8049, 4.9, true, "Come forth, my servants! Defend your master!" }, { 8050, 11.4, true, "YOU CANNOT DEFEAT THE LIVING FLAME! COME YOU MINIONS OF FIRE! COME FORTH, YOU CREATURES OF HATE! YOUR MASTER CALLS!" }, { 8046, 3.9, true, "By fire be purged!" }, { 8047, 4.8, true, "TASTE THE FLAMES OF SULFURON!" }, { 8051, 2.8, true, "Die, insect!" }, { 8048, 7.1, true, "MY PATIENCE IS DWINDLING! COME, GNATS, TO YOUR DEATH!" } }, title = "The Firelord" },
    { id = "onyxia", entry = 10184, name = "Onyxia", label = "Onyxia", level = 83, display = 8570, height = 28.1, span = 53.2, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\Achievement_Boss_Onyxia", profile = "bruiser", kit = { 18435, 68867, 18500, 18392, 18431, 68958, 261 }, passives = {}, talentInfo = { { name = "Breath of the Broodmother", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire damage is increased by 10%." }, { name = "Onyxian Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Your armor is increased by 20%." }, { name = "Daughter of Deathwing", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", text = "Your maximum health is increased by 10%." }, { name = "Claws of the Broodmother", icon = "Interface\\Icons\\INV_Misc_MonsterClaw_03", text = "Increases your chance to get a critical strike with melee attacks by 5%." }, { name = "Many Whelps", icon = "Interface\\Icons\\Ability_Hunter_Pet_DragonHawk", text = "Reduces the cooldown of your Onyxian Whelps by 30 sec.\n\nMany whelps! Handle it! The eggs of the Broodmother's lair hatch faster than any raid can burn them." }, { name = "No Safe Flank", icon = "Interface\\Icons\\INV_Misc_MonsterTail_03", text = "When you are struck, you have a 10% chance to answer with a Tail Sweep. Once every 30 sec.\n\nMany whelps? Handle it. A tail behind you? That one the Broodmother handles herself." } }, tips = { [261] = "Call your brood from the eggs of your lair: three Onyxian Whelps swarm out to fight at your side for 20 sec." }, visualKit = 286, soundTransform = 7274, soundDeath = 0, flies = true, wave = 1, instance = "Onyxia's Lair", expansion = 0, order = 319, summons = { [261] = true }, box = { -8.45, 0.22, 11.36 }, view = { -17.7487, -0.5675, 28.3087 }, title = "Daughter of Deathwing", visages = { "lady_katrana_prestor" }, shape = "Dragon" },
    { id = "nefarian", entry = 11583, name = "Nefarian", label = "Nefarian", level = 63, display = 11380, height = 28.1, span = 53.2, school = "shadow", pool = "classic_raid", icon = "Interface\\Icons\\Achievement_Boss_Nefarion", profile = "caster", kit = { 22539, 22677, 22686, 23364, 22687, 261 }, passives = {}, talentInfo = { { name = "Shadowflame of Blackwing Lair", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 10%." }, { name = "Deathwing's Heir", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", text = "Your maximum health is increased by 10%." }, { name = "Black Dragonscale Hide", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "All damage you take is reduced by 5%." }, { name = "Master of Blackrock Spire", icon = "Interface\\Icons\\Spell_Shadow_Possession", text = "Your Shadow spells cost 8% less." }, { name = "Bolts of the Black Flight", icon = "Interface\\Icons\\Spell_Shadow_GatherShadows", text = "Your damaging spells have a 10% chance to hurl a Shadow Bolt at the target as well. Once every 20 sec.\n\nMan or dragon, Deathwing's son never casts one spell of shadow where two will do." }, { name = "Lord of Blackrock Spire", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "Reduces the cooldown of your Bellowing Roar by 15 sec.\n\nNow the mortals will see the true Lord of Blackrock Spire, and they will not move until he allows it." } }, tips = { [261] = "Raise the bones of your fallen drakonids: three Bone Constructs rise to fight at your side for 20 sec." }, visualKit = 7775, soundTransform = 8288, soundDeath = 8292, flies = true, wave = 1, instance = "Blackwing Lair", expansion = 0, order = 295, summons = { [261] = true }, box = { -8.45, 0.22, 11.36 }, view = { -17.7487, -0.2270, 22.5205 }, voices = { { 8288, 10.2, true, "Well done, my minions. The mortals' courage begins to wane! Now, let's see how they contend with the true Lord of Blackrock Spire!!!" }, { 8291, 6.8, true, "Impossible! Rise my minions! Serve your master once more!" }, { 8292, 8.2, true, "This cannot be! I am the master here! You mortals are nothing to my kind! Do you hear me? Nothing!" }, { 8289, 7.8, true, "Enough! Now you vermin shall feel the force of my birthright, the fury of the earth itself." } }, title = "Lord of Blackrock Spire", visages = { "lord_victor_nefarius" }, shape = "Dragon" },
    { id = "kelthuzad", entry = 15990, name = "Kel'Thuzad", label = "Kel'Thuzad", level = 83, display = 15945, height = 16.1, span = 16.1, school = "frost", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_KelThuzad_01", profile = "caster", kit = { 28478, 28479, 31249, 22936, 61112, 261 }, passives = {}, talentInfo = { { name = "Archlich", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "Master of Naxxramas", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Phylactery", icon = "Interface\\Icons\\INV_Misc_Gem_Sapphire_02", text = "Your maximum health is increased by 8%." }, { name = "Chill of the Grave", icon = "Interface\\Icons\\Spell_Frost_FrostWard", text = "Your Frost resistance is increased by 50." }, { name = "Scream Your Dying Breath", icon = "Interface\\Icons\\Spell_Frost_IceShock", text = "Your damaging spells have an 8% chance to loose a free Frostbolt at the target. Once every 20 sec.\n\nScream your dying breath! The archlich casts faster than any mortal mage; his frost never waits." }, { name = "I Will Freeze the Blood in Your Veins", icon = "Interface\\Icons\\Spell_Frost_FreezingBreath", text = "Reduces the cooldown of Frostbolt Volley by 5 sec.\n\nKel'Thuzad's volleys sweep Naxxramas's highest chamber without pause." } }, tips = { [261] = "Minions, servants, soldiers of the cold dark! Obey the call of Kel'Thuzad! Call a Patchwork Golem to fight for you for 20 sec." }, visualKit = 4991, soundTransform = 14475, soundDeath = 14480, flies = false, wave = 1, instance = "Naxxramas", expansion = 2, order = 530, summons = { [261] = true }, box = { 0.21, 0.18, 7.47 }, view = { -1.7493, -0.0000, 4.1737 }, voices = { { 14467, 6.8, true, "Your forces are nearly marshaled to strike back against your enemies, my liege." }, { 14468, 9.3, true, "Yes, master. The time of their ultimate demise draws close.... What is this?" }, { 14469, 3.3, true, "As you command, master!" }, { 14484, 10.4, true, "No!!! A curse upon you, interlopers! The armies of the Lich King will hunt you down. You will not escape your fate..." }, { 14463, 13.0, true, "Who dares violate the sanctity of my domain? Be warned, all who trespass here are doomed." }, { 14464, 8.9, true, "Fools! You think yourselves triumphant? You have only taken one step closer to the abyss!" }, { 14465, 8.3, true, "I grow tired of these games. Proceed, and I will banish your souls to oblivion!" }, { 14466, 11.9, true, "You have no idea what horrors lie ahead. You have seen nothing! The frozen heart of Naxxramas awaits you!" }, { 14475, 2.1, true, "Pray for mercy!" }, { 14476, 2.4, true, "Scream your dying breath!" }, { 14477, 3.1, true, "The end is upon you!" }, { 14478, 3.2, true, "The dark void awaits you!" } }, title = "Archlich" },
    { id = "hakkar", entry = 14834, name = "Hakkar", label = "Hakkar", level = 63, display = 15295, height = 23.1, span = 30.3, school = "nature", pool = "classic_raid", icon = "Interface\\Icons\\Achievement_Boss_Hakkar", profile = "caster", kit = { 24328, 33915, 24688, 24687, 24686, 12888 }, passives = {}, talentInfo = { { name = "Blood of the Soulflayer", icon = "Interface\\Icons\\Achievement_Boss_Hakkar", text = "The Blood God's corruption runs through you: your Shadow damage is increased by 10%." }, { name = "Avatar of the Blood God", icon = "Interface\\Icons\\Spell_Shadow_BloodBoil", text = "Your maximum health is increased by 10%." }, { name = "Aspects of the Primal Loa", icon = "Interface\\Icons\\INV_ZulGurubTrinket", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Corrupted Blood", icon = "Interface\\Icons\\Spell_Shadow_CorpseExplode", text = "Your damaging spells have a 10% chance to infect the target with Corrupted Blood. Once every 15 sec.\n\nOne drop of the Soulflayer's blood once emptied the cities of Azeroth. It has lost none of its hunger." }, { name = "Drinker of the Faithful", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain", text = "Increases the damage of your Blood Siphon by 15%.\n\nHakkar grows stronger with every drop of Gurubashi blood spilled on his altar." } }, tips = { [33915] = "Siphon the blood of the faithful, stealing 75 health from every enemy near you.", [24686] = "Take the aspect of Mar'li, stunning an enemy in melee range for 2 sec." }, visualKit = 282, soundTransform = 8414, soundDeath = 8468, flies = false, wave = 1, instance = "Zul'Gurub", expansion = 0, order = 252, box = { -4.73, -0.11, 10.47 }, view = { 2.6569, -3.2320, 3.8667 }, voices = { { 8414, 10.5, true, "PRIDE HERALDS THE END OF YOUR WORLD. COME, MORTALS! FACE THE WRATH OF THE SOULFLAYER!" } }, title = "The Soulflayer" },
