    { id = "illidan", entry = 22917, name = "Illidan Stormrage", label = "Illidan Stormrage", level = 73, display = 21135, height = 14.1, span = 19.8, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Achievement_Boss_Illidan", profile = "bruiser", kit = { 40932, 40631, 41917, 40904, 40841, 50582 }, passives = {}, talentInfo = { { name = "Twin Blades of Azzinoth", icon = "Interface\\Icons\\INV_Weapon_Glave_01", text = "Your attack speed is increased by 10%." }, { name = "The Demon Within", icon = "Interface\\Icons\\Spell_Shadow_Metamorphosis", text = "Your Shadow damage is increased by 8%." }, { name = "Flames of Azzinoth", icon = "Interface\\Icons\\Spell_Fire_FelFlameRing", text = "Your Fire damage is increased by 8%." }, { name = "Evasion of the Betrayer", icon = "Interface\\Icons\\Spell_Shadow_ShadowWard", text = "Your chance to dodge is increased by 5%." }, { name = "You Are Not Prepared", icon = "Interface\\Icons\\Spell_Fire_FelFlameStrike", text = "Your melee attacks have an 8% chance to loose a Flame Blast. Once every 20 sec.\n\nYou are not prepared! Every stroke of the Warglaives drags a little of Azzinoth's fire with it." }, { name = "Who Shall Be Next", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_3", text = "Reduces the cooldown of Draw Soul by 5 sec.\n\nWho shall be next to taste my blades? The Betrayer drinks souls faster the longer he fights." } }, tips = {}, visualKit = 7775, soundTransform = 11475, soundDeath = 0, flies = true, wave = 1, instance = "Black Temple", expansion = 1, order = 385, box = { -4.26, 1.40, 7.02 }, voices = { { 11465, 8.7, true, "Come, my minions. Deal with this traitor as he deserves!" }, { 11473, 6.6, true, "Who shall be next to taste my blades?" }, { 11472, 3.8, true, "This is too easy!" }, { 11479, 6.4, true, "I will not be touched by rabble such as you!" }, { 11480, 6.1, true, "Behold the Flames of Azzinoth!" }, { 11481, 5.8, true, "Stare into the eyes of the Betrayer!" }, { 11475, 8.2, true, "Behold the power... of the demon within!" }, { 11474, 9.5, true, "You've wasted too much time, mortals. Now you shall fall." }, { 11467, 4.9, true, "I can feel your hatred." }, { 11468, 4.8, true, "Give in to your fear!" }, { 11469, 5.2, true, "You know nothing of power!" }, { 11471, 4.5, true, "Such... arrogance!" } }, title = "The Betrayer", visages = { "illidan_demon" }, shape = "Night elf" },
    { id = "kaelthas", entry = 19622, name = "Kael'thas Sunstrider", label = "Kael'thas Sunstrider", level = 73, display = 20023, height = 9.8, span = 9.8, school = "fire", pool = "tbc", icon = "Interface\\Icons\\Achievement_Boss_Kael'thasSunstrider_01", profile = "caster", kit = { 36805, 38535, 36731, 30225, 36834, 55019, 36533, 261 }, passives = {}, talentInfo = { { name = "Fire of Al'ar", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "Your Fire damage is increased by 10%." }, { name = "Power of the Verdant Spheres", icon = "Interface\\Icons\\Spell_Arcane_ArcanePotency", text = "Your casting speed is increased by 8%." }, { name = "Resolve of the Sunstriders", icon = "Interface\\Icons\\Spell_Arcane_ArcaneResilience", text = "Damage you take is reduced by 5%." }, { name = "Fel Addiction", icon = "Interface\\Icons\\Spell_Fire_FelFire", text = "Your Intellect is increased by 8%." }, { name = "Flames of the Sunwell", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "Your damaging spells have an 8% chance to call down a Flame Strike. Once every 20 sec.\n\nThe Sun King's fire spills over wherever he points; the floor of the Eye still burns." }, { name = "Magister's Discipline", icon = "Interface\\Icons\\Spell_Arcane_MindMastery", text = "Your Flame Strike covers a 30% larger area.\n\nKael'thas learned in Dalaran that a pillar of flame is only as good as the ground it covers." } }, tips = { [261] = "Anar'anel belore! Call a phoenix of Al'ar's brood to fight beside you for 20 sec." }, visualKit = 286, soundTransform = 11263, soundDeath = 11274, flies = false, wave = 1, instance = "Tempest Keep", expansion = 1, order = 401, summons = { [261] = true }, box = { -0.44, -0.31, 4.88 }, voices = { { 11257, 4.7, true, "Capernian will see to it that your stay here is a short one." }, { 11258, 8.0, true, "Well done, you have proven worthy to test your skills against my master engineer, Telonicus." }, { 11259, 5.0, true, "Let us see how your nerves hold up against the Darkener, Thaladred!" }, { 11260, 12.1, true, "You have persevered against some of my best advisors... but none can withstand the might of the Blood Hammer. Behold, Lord Sanguinar!" }, { 11261, 4.9, true, "As you see, I have many weapons in my arsenal...." }, { 11262, 12.6, true, "Perhaps I underestimated you. It would be unfair to make you fight all four advisors at once, but... fair treatment was never shown to my people. I'm just returning the favor." }, { 11263, 8.1, true, "Alas, sometimes one must take matters into one's own hands. Balamore shanal!" }, { 11273, 8.7, true, "I have not come this far to be stopped! The future I have planned will not be jeopardized! Now you will taste true power!!" }, { 11270, 3.1, true, "You will not prevail!" }, { 11271, 3.4, true, "You gambled. And lost." }, { 11272, 2.5, true, "This was child's play." }, { 11268, 2.3, true, "Obey me!" } }, title = "Lord of the Blood Elves" },
    { id = "vashj", entry = 21212, name = "Lady Vashj", label = "Lady Vashj", level = 73, display = 20748, height = 9.5, span = 9.8, school = "nature", pool = "tbc", icon = "Interface\\Icons\\Achievement_Boss_LadyVashj", profile = "caster", kit = { 38280, 40088, 38509, 38316, 38575, 28527, 261 }, passives = {}, talentInfo = { { name = "Coilfang Lightning", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 10%." }, { name = "Barrier of the Highborne", icon = "Interface\\Icons\\Spell_Nature_LightningShield", text = "Damage you take is reduced by 6%." }, { name = "Highborne Sorcery", icon = "Interface\\Icons\\Spell_Arcane_StarFire", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Mistress of the Tides", icon = "Interface\\Icons\\Spell_Frost_SummonWaterElemental", text = "The mana cost of your Nature spells is reduced by 8%." }, { name = "You May Want to Take Cover", icon = "Interface\\Icons\\Spell_Shaman_StaticShock", text = "Your damaging spells have a 10% chance to lay Static Charge on the target. Once every 15 sec.\n\nVashj's lightning clings; whoever it touches carries the storm to their friends." }, { name = "I'll Split You", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", text = "Your Forked Lightning deals 15% more damage.\n\nI'll split you from stem to stern! The Matron's lightning forks wider each time." } }, tips = { [261] = "Death to the outsiders! Call two Coilfang Elites from the depths to fight for you for 20 sec." }, visualKit = 282, soundTransform = 11532, soundDeath = 11544, flies = false, wave = 1, instance = "Coilfang: Serpentshrine Cavern", expansion = 1, order = 373, summons = { [261] = true }, box = { -2.32, -0.09, 4.67 }, voices = { { 11532, 3.9, true, "I'll split you from stem to stern!" }, { 11533, 3.3, true, "Victory to Lord Illidan!" }, { 11534, 3.6, true, "I spit on you, surface filth!" }, { 11535, 2.7, true, "Death to the outsiders!" }, { 11538, 8.7, true, "I did not wish to lower myself by engaging your kind, but you leave me little choice..." }, { 11539, 4.5, true, "The time is now! Leave none standing!" }, { 11540, 2.8, true, "You may want to take cover." }, { 11536, 2.9, true, "Straight to the heart!" }, { 11537, 3.4, true, "Seek your mark!" }, { 11541, 3.2, true, "Your time ends now!" }, { 11542, 2.2, true, "You have failed!" }, { 11543, 3.1, true, "Be'lemer an-delei!" } }, title = "Coilfang Matron" },
    { id = "malchezaar", entry = 15690, name = "Prince Malchezaar", label = "Prince Malchezaar", level = 73, display = 19274, height = 10.1, span = 10.1, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Achievement_Boss_PrinceMalchezaar_02", profile = "bruiser", kit = { 30854, 30131, 261 }, passives = {}, talentInfo = { { name = "Eredar Shadowcraft", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 10%." }, { name = "Prince of the Nether", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Damage you take is reduced by 6%." }, { name = "Strength of the Legion", icon = "Interface\\Icons\\Spell_Shadow_UnholyStrength", text = "Your Strength is increased by 8%." }, { name = "Word of Darkness", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your melee attacks have a 10% chance to lay Shadow Word: Pain on the target. Once every 15 sec.\n\nWho knows what secrets hide in the dark. Every blow the prince lands whispers one of them." }, { name = "All Realities Open", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your Cleave strikes 1 more target.\n\nAll realities, all dimensions are open to me! There is always one more victim in reach." } }, tips = { [261] = "You face not Malchezaar alone, but the legions I command! Call an Infernal down from the Nether to burn your foes for 20 sec." }, visualKit = 7775, soundTransform = 9218, soundDeath = 9221, flies = false, wave = 1, instance = "Karazhan", expansion = 1, order = 351, summons = { [261] = true }, box = { -0.94, -0.25, 5.05 }, voices = { { 9218, 10.8, true, "Madness has brought you here to me. I shall be your undoing!" }, { 9220, 7.7, true, "Simple fools! Time is the fire in which you'll burn!" }, { 9317, 8.7, true, "I see the subtlety of conception is beyond primitives such as you." }, { 9223, 11.0, true, "Who knows what secrets hide in the dark." }, { 9320, 7.5, true, "The cerestial forces are mine to manipulate." }, { 9321, 8.7, true, "How can you hope to stand against such overwhelming power?" }, { 9222, 7.1, true, "Surely you did not think you could win." }, { 9318, 8.6, true, "Your greed, your foolishness has brought you to this end." }, { 9319, 9.9, true, "You are but a plaything. Unfit even to amuse." }, { 9224, 8.9, true, "All realities, all dimensions are open to me!" }, { 9322, 8.1, true, "You face not Malchezaar alone, but the legions I command!" }, { 9221, 13.0, true, "I refuse to concede defeat! I am a prince of the Eredar! I... am..." } }, title = "Master of Karazhan" },
    { id = "gruul", entry = 19044, name = "Gruul the Dragonkiller", label = "Gruul the Dragonkiller", level = 73, display = 18698, height = 19.6, span = 20.0, school = "physical", pool = "tbc", icon = "Interface\\Icons\\Achievement_Boss_GruulTheDragonkiller", profile = "tank", kit = { 33813, 36240, 36297, 37764, 36300, 37548 }, passives = {}, talentInfo = { { name = "Gronn Hide", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", text = "Your armor is increased by 20%." }, { name = "Dragonkiller's Bulk", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Lord of the Gronn", icon = "Interface\\Icons\\Ability_Druid_ChallangingRoar", text = "The threat you cause is increased by 30%." }, { name = "Swelling Might", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your Strength is increased by 8%." }, { name = "Growth", icon = "Interface\\Icons\\Ability_Racial_BloodRage", text = "Reduces the cooldown of Growth by 10 sec.\n\nGruul grows the longer a fight goes on; nobody has ever seen him stop." }, { name = "No Escape", icon = "Interface\\Icons\\Spell_Nature_Earthquake", text = "Reduces the cooldown of Ground Slam by 10 sec.\n\nNo escape. The Dragonkiller's slams come quicker once he has the taste of it." } }, tips = {}, visualKit = 437, soundTransform = 11355, soundDeath = 11363, flies = false, wave = 1, instance = "Gruul's Lair", expansion = 1, order = 395, box = { -0.79, 0.50, 9.61 }, voices = { { 11355, 4.8, true, "Come.... and die." }, { 11356, 3.8, true, "Scurry." }, { 11357, 4.5, true, "No escape." }, { 11358, 3.5, true, "Stay." }, { 11359, 4.8, true, "Beg for life." }, { 11360, 3.7, true, "No more." }, { 11361, 3.1, true, "Unworthy." }, { 11362, 3.0, true, "Die." }, { 11363, 5.1, true, "Aaargh..." } }, title = "Overlord of the Ogres of Outland" },
    { id = "lichking", entry = 36597, name = "The Lich King", label = "The Lich King", level = 83, display = 30721, height = 6.2, span = 6.2, school = "frost", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_LichKing", profile = "bruiser", kit = { 69409, 72149, 69242, 72133, 16608, 73791 }, passives = {}, talentInfo = { { name = "Lord of the Scourge", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your Shadow damage is increased by 10%." }, { name = "The Frozen Throne", icon = "Interface\\Icons\\INV_Chest_Plate16", text = "Your armor is increased by 15%." }, { name = "Remorseless Winter", icon = "Interface\\Icons\\Spell_Frost_FrostShock", text = "Your Frost resistance is increased by 60." }, { name = "Harvest Soul", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "Frostmourne Hungers", icon = "Interface\\Icons\\Spell_DeathKnight_EmpowerRuneBlade", text = "Your melee attacks have an 8% chance to unleash Pain and Suffering. Once every 20 sec.\n\nFrostmourne hungers..." }, { name = "Soul Reaper", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_2", text = "Reduces the cooldown of Soul Reaper by 10 sec.\n\nThe Lich King reaps souls faster as the blade feeds." } }, tips = {}, visualKit = 4991, soundTransform = 17366, soundDeath = 17358, flies = false, wave = 1, instance = "Icecrown Citadel", expansion = 2, order = 568, box = { -0.50, -0.93, 2.87 }, voices = { { 17349, 14.2, true, "So the Light's vaunted justice has finally arrived? Shall I lay down Frostmourne and throw myself at your mercy, Fordring?" }, { 17350, 22.6, true, "You'll learn of that first hand. When my work is complete, you will beg for mercy -- and I will deny you. Your anguished cries will be testament to my unbridled power..." }, { 17351, 18.4, true, "I'll keep you alive to witness the end, Fordring. I would not want the Light's greatest champion to miss seeing this wretched world remade in my image." }, { 17369, 9.7, true, "I will freeze you from within until all that remains is an icy husk." }, { 17370, 7.7, true, "Watch as the world around you collapses!" }, { 17373, 7.3, true, "Val'kyr, your master calls!" }, { 17366, 6.6, true, "Frostmourne hungers..." }, { 17367, 7.1, true, "Frostmourne, OBEY ME!" }, { 17368, 6.7, true, "Frostmourne feeds on the soul of your fallen ally!" }, { 17363, 5.1, true, "Hope wanes..." }, { 17364, 4.4, true, "The end has come!" }, { 17365, 5.4, true, "Face now your tragic end." } }, title = "Lord of the Scourge" },
    { id = "sindragosa", entry = 36853, name = "Sindragosa", label = "Sindragosa", level = 83, display = 30362, height = 36.4, span = 83.8, school = "frost", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Sindragosa", profile = "caster", kit = { 71386, 70123, 71077, 69762, 69845, 36922 }, passives = {}, talentInfo = { { name = "Queen of the Frostbrood", icon = "Interface\\Icons\\Spell_Frost_FreezingBreath", text = "Your Frost damage is increased by 10%." }, { name = "Permeating Chill", icon = "Interface\\Icons\\Spell_Frost_FrostShock", text = "Your Frost resistance is increased by 60." }, { name = "Frozen Bones", icon = "Interface\\Icons\\INV_Misc_Bone_HumanSkull_01", text = "Your armor is increased by 20%." }, { name = "Icy Grip", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Suffer, Mortals", icon = "Interface\\Icons\\Spell_Frost_ArcticWinds", text = "When you are struck, you have a 10% chance to breathe Frost Breath. Once every 20 sec.\n\nSuffer, mortals, as your pathetic magic betrays you!" }, { name = "Frost Bomb", icon = "Interface\\Icons\\Spell_Frost_FrozenCore", text = "Reduces the cooldown of Frost Bomb by 8 sec.\n\nThe Queen of the Frostbrood rains bombs of ice on the Frost Queen's Lair without pause." } }, tips = {}, visualKit = 4991, soundTransform = 17007, soundDeath = 17010, flies = true, wave = 1, instance = "Icecrown Citadel", expansion = 2, order = 567, box = { -16.14, -0.10, 17.00 }, voices = { { 17007, 9.6, true, "You are fools to have come to this place. The icy winds of Northrend will consume your souls!" }, { 17014, 8.0, true, "Suffer, mortals, as your pathetic magic betrays you!" }, { 17013, 6.2, true, "Can you feel the cold hand of death upon your heart?" }, { 17015, 6.0, true, "Aaagh! It burns! What sorcery is this!?" }, { 17012, 6.6, true, "Your incursion ends here! None shall survive!" }, { 17016, 7.7, true, "Now, feel my master's limitless power and despair!" }, { 17008, 2.8, true, "Perish!" }, { 17009, 3.9, true, "The flaw of mortality...." }, { 17011, 4.7, true, "Enough! I tire of these games!" }, { 17010, 5.2, true, "Free... at last...." } }, title = "Queen of the Frostbrood" },
    { id = "anubarak", entry = 29120, name = "Anub'arak", label = "Anub'arak", level = 74, display = 27856, height = 12.5, span = 15.6, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Anubarak", profile = "bruiser", kit = { 53472, 53467, 53454, 66012, 53521, 261 }, passives = {}, talentInfo = { { name = "Carapace of the Crypt Lord", icon = "Interface\\Icons\\INV_Misc_MonsterSpiderCarapace_01", text = "Your armor is increased by 20%." }, { name = "A Pestilence Upon You", icon = "Interface\\Icons\\Spell_Nature_InsectSwarm", text = "Your Nature damage is increased by 8%." }, { name = "King of Azjol-Nerub", icon = "Interface\\Icons\\achievement_boss_anubarak", text = "Your attack power is increased by 10%." }, { name = "Traitor King's Shell", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Your maximum health is increased by 10%." }, { name = "Burrow and Strike", icon = "Interface\\Icons\\Ability_Hunter_Pet_Silithid", text = "When you are struck, you have an 8% chance to Impale the attacker. Once every 20 sec.\n\nThe Traitor King never fights on the surface alone; the floor itself bites back." }, { name = "Leeching Swarm", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain", text = "Your Leeching Swarm lasts 5 sec longer.\n\nAnub'arak's locusts are slow to leave a feast." } }, tips = { [261] = "Call an Anub'ar Guardian up from Azjol-Nerub to fight beside you for 20 sec." }, visualKit = 282, soundTransform = 14054, soundDeath = 14069, flies = false, wave = 1, instance = "Azjol-Nerub", expansion = 2, order = 464, summons = { [53521] = true, [261] = true }, box = { 0.43, 0.12, 6.02 }, voices = { { 14054, 2.7, true, "Eternal agony awaits you!" }, { 14057, 4.1, true, "Soon the master's voice will call to you." }, { 14056, 2.2, true, "You have made your choice." }, { 14055, 4.1, true, "You shall experience my torment first hand!" }, { 14069, 7.8, true, "Ahhh... RAAAAAGH! Never thought... I would be free of him...." }, { 14060, 3.8, true, "Your armor is useless against my locusts!" }, { 14067, 4.5, true, "Uunak-hissss tik-k-k-k-k!" }, { 14068, 2.5, true, "A pestilence upon you!" }, { 14058, 3.2, true, "Auum na-l ak-k-k-k, isshhh." }, { 14059, 5.7, true, "Come forth, my brethren! Feast on their flesh!" }, { 14053, 18.0, true, "I was king of this empire once, long ago. In life I stood as champion. In death I returned as conqueror. Now I protect the kingdom once more. Ironic, yes?" } }, title = "The Traitor King" },
    { id = "ingvar", entry = 23954, name = "Ingvar the Plunderer", label = "Ingvar the Plunderer", level = 72, display = 21953, height = 7.8, span = 7.8, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Dungeon_UtgardeKeep_Normal", profile = "bruiser", kit = { 42669, 42724, 72539, 42708, 48193 }, passives = {}, talentInfo = { { name = "Warrior Born", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your Strength is increased by 8%." }, { name = "Raised by Annhylde", icon = "Interface\\Icons\\Spell_Shadow_AnimateDead", text = "Your maximum health is increased by 8%." }, { name = "Plunderer's Fury", icon = "Interface\\Icons\\Ability_Warrior_BloodFrenzy", text = "Your attack speed is increased by 8%." }, { name = "Dragonflayer Resolve", icon = "Interface\\Icons\\achievement_dungeon_utgardekeep", text = "Damage you take is reduced by 5%." }, { name = "I'll Paint My Face", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your melee attacks have an 8% chance to Smash the enemies before you. Once every 20 sec.\n\nI'll paint my face with your blood! Ingvar's blows land hard enough to shake the hall." }, { name = "Staggering", icon = "Interface\\Icons\\Ability_Warrior_WarCry", text = "Reduces the cooldown of Staggering Roar by 8 sec.\n\nThe Plunderer's roar shook Utgarde's halls, and it comes back around fast." } }, tips = {}, visualKit = 7775, soundTransform = 13207, soundDeath = 13213, flies = false, wave = 1, instance = "Utgarde Keep", expansion = 2, order = 443, charModel = true, box = { -0.47, -0.04, 3.72 }, voices = { { 13207, 2.6, true, "I'll paint my face with your blood!" }, { 13212, 3.1, true, "Mjul orm agn gjor!" }, { 13213, 3.8, true, "My life for the... death god!" }, { 13209, 5.0, true, "I return! A second chance to carve your skull!" }, { 13214, 2.4, true, "I am a warrior born!" }, { 13211, 5.0, true, "No! I can do... better! I can..." } }, title = "Commander of the Dragon Riders", visages = { "ingvar_undead" }, shape = "Vrykul" },
    { id = "malygos", entry = 28859, name = "Malygos", label = "Malygos", level = 83, display = 26752, height = 29.3, span = 62.7, school = "arcane", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Malygos_01", profile = "caster", kit = { 56272, 57432, 61693, 50804, 15847, 56548 }, passives = {}, talentInfo = { { name = "The Spell-Weaver", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", text = "Your Arcane damage is increased by 10%." }, { name = "Aspect of Magic", icon = "Interface\\Icons\\Spell_Holy_MagicalSentry", text = "Your Intellect is increased by 8%." }, { name = "Blue Dragonscale", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Blue", text = "Your armor is increased by 20%." }, { name = "Nexus War", icon = "Interface\\Icons\\Spell_Arcane_ArcanePotency", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Submit!", icon = "Interface\\Icons\\Spell_Arcane_Blast", text = "Your damaging spells have an 8% chance to release an Arcane Pulse. Once every 20 sec.\n\nSubmit! Malygos's power spills out around every spell he throws." }, { name = "I Am Unstoppable", icon = "Interface\\Icons\\Spell_Arcane_Arcane01", text = "Your Arcane Breath deals 15% more damage.\n\nThe Aspect of Magic breathes the Nexus itself." } }, tips = {}, visualKit = 1005, soundTransform = 14517, soundDeath = 14540, flies = true, wave = 1, instance = "The Eye of Eternity", expansion = 2, order = 544, box = { -8.95, -0.07, 13.51 }, voices = { { 14512, 9.5, true, "Lesser beings, intruding here! A shame that your excess courage does not compensate for your stupidity!" }, { 14513, 10.8, true, "None but the blue dragonflight are welcome here. Perhaps this is the work of Alexstrasza? Well, then, she has sent you to your deaths!" }, { 14514, 12.2, true, "What could you hope to accomplish? To storm brazenly into my domain... to employ magic... against ME?" }, { 14515, 9.7, true, "I am without limits here. The rules of your cherished reality do not apply. In this realm, I am in control!" }, { 14516, 6.6, true, "I give you one chance. Pledge fealty to me, and perhaps I will not slaughter you for your insolence." }, { 14517, 3.7, true, "My patience has reached its limit. I will be rid of you!" }, { 14518, 3.0, true, "You will not succeed while I draw breath!" }, { 14519, 3.4, true, "Your stupidity has finally caught up with you!" }, { 14520, 2.6, true, "More artifacts to confiscate." }, { 14521, 5.5, true, "How very naive." }, { 14523, 5.4, true, "Few have experienced the pain I will now inflict upon you!" }, { 14524, 6.4, true, "I will teach you ignorant children just how little you know of magic." } }, title = "The Spell-Weaver" },
    { id = "kobold", entry = 40, name = "Kobold Miner", label = "Kobold", level = 7, display = 373, height = 1.4, span = 2.2, school = "fire", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Head_Kobold_01", profile = "glass_cannon", kit = { 6257, 6016, 11976, 48594, 261 }, passives = {}, talentInfo = { { name = "Candlelit Fury", icon = "Interface\\Icons\\Spell_Fire_Flare", text = "Your candle burns hot: your Fire damage is increased by 8%." }, { name = "Thick Kobold Skull", icon = "Interface\\Icons\\INV_Misc_Bone_01", text = "Damage you take is reduced by 5%." }, { name = "Tunnel Rat Cunning", icon = "Interface\\Icons\\Trade_Mining", text = "Your Intellect is increased by 6%." }, { name = "You No Take Candle", icon = "Interface\\Icons\\Spell_Fire_SealOfFire", text = "When you are struck, you have a 10% chance to fling a burning candle stub at your attacker. Once every 20 sec.\n\nHands off the candle! A kobold will fight a whole guard patrol over a stub of wax, and set a few of them alight." }, { name = "Yiieee! Me Run!", icon = "Interface\\Icons\\Ability_Rogue_Sprint", text = "Reduces the cooldown of your Sprint by 20 sec.\n\nNo kobold has ever been too proud to run. The ones who were are not around to tell it." } }, tips = { [6257] = "Fling a lit candle stub at an enemy, dealing 30 Fire damage and setting it alight for 15 Fire damage every 3 sec. for 30 sec.", [261] = "You no take candle! Two Kobold Vermin scurry out of the tunnels to fight beside you for 20 sec." }, visualKit = 286, soundTransform = 694, soundDeath = 314, flies = false, wave = 1, zone = "Elwynn Forest", expansion = 0, order = 6, summons = { [261] = true }, box = { -0.02, -0.04, 0.71 }, skins = { { entry = 79, name = "Albino", creature = "Narg the Taskmaster", display = 774, height = 1.6, span = 2.5, box = { -0.02, -0.05, 0.80 } } }, title = "Kobold of the Elwynn Mines" },
    { id = "murloc", entry = 127, name = "Murloc Tidehunter", label = "Murloc", level = 19, display = 1995, height = 1.9, span = 1.9, school = "frost", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Head_Murloc_01", profile = "glass_cannon", kit = { 11831, 9672, 744, 12024, 11986, 261 }, passives = {}, talentInfo = { { name = "Tidehunter's Chill", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "Your Frost damage is increased by 8%." }, { name = "Slippery Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your chance to dodge is increased by 5%." }, { name = "Gift of the Tides", icon = "Interface\\Icons\\Spell_Nature_HealingWaveLesser", text = "Your healing is increased by 10%." }, { name = "Tangled in the Nets", icon = "Interface\\Icons\\Ability_Ensnare", text = "When you are struck, you have a 10% chance to throw a Net over your attacker. Once every 20 sec.\n\nEvery tidehunter drags its nets up the beach. Swing at one and you will likely end up in them." }, { name = "There Are Always More", icon = "Interface\\Icons\\inv_pet_babymurlocs_blue", text = "Reduces the cooldown of your Mrglglglgl! by 30 sec.\n\nKill one murloc and three more come up the shore. Nobody on the Westfall coast has ever counted to the last one." } }, tips = { [261] = "Let out the murloc war cry. Two Murloc Coastrunners come splashing up the beach to fight beside you for 20 sec." }, visualKit = 4991, soundTransform = 416, soundDeath = 420, flies = false, wave = 1, zone = "Westfall", expansion = 0, order = 20, summons = { [261] = true }, box = { -0.13, -0.00, 0.96 }, title = "Murloc of the Westfall Coast" },
    { id = "gnoll", entry = 125, name = "Riverpaw Brute", label = "Gnoll", level = 16, display = 10790, height = 2.3, span = 2.3, school = "physical", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Head_Gnoll_01", profile = "bruiser", kit = { 13730, 19820, 3391, 12461, 6268 }, passives = {}, talentInfo = { { name = "Riverpaw Savagery", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your Physical damage is increased by 8%." }, { name = "Mangy Hide", icon = "Interface\\Icons\\INV_Misc_Pelt_Wolf_01", text = "Your armor is increased by 15%." }, { name = "Gnoll Brawn", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your Strength is increased by 8%." }, { name = "Cornered Gnoll", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "When you are struck, you have a 10% chance to Gnaw your attacker. Once every 30 sec.\n\nBack a Riverpaw into a corner and it stops snarling and starts biting. The bones it gnaws on were somebody's once." }, { name = "Riverpaw Howl", icon = "Interface\\Icons\\Ability_Warrior_WarCry", text = "Your Demoralizing Shout reaches 30% farther.\n\nThe pack howls together. From one hill to the next the Riverpaw call carries, and every farmhand hears it." } }, tips = {}, visualKit = 437, soundTransform = 1015, soundDeath = 308, flies = false, wave = 1, zone = "Westfall", expansion = 0, order = 21, as = 124, box = { -0.03, 0.04, 1.14 }, view = { 0.2998, 0.0000, 0.0110 }, variants = { "gnoll_mystic" }, skins = { { entry = 518, name = "Redridge", creature = "Yowler", display = 488, height = 2.3, span = 2.3, box = { -0.03, 0.04, 1.14 } }, { entry = 433, name = "Shadow", creature = "Shadowhide Gnoll", display = 275, height = 1.8, span = 1.8, box = { -0.02, 0.03, 0.88 } } }, title = "Gnoll of the Riverpaw Pack" },
    { id = "felguard", entry = 18977, name = "Felguard Destroyer", label = "Felguard", level = 60, display = 18251, height = 11.0, span = 11.0, school = "shadow", pool = "archetype", icon = "Interface\\Icons\\Spell_Shadow_SummonFelGuard", profile = "bruiser", kit = { 33971, 40505, 13737, 15615, 40219, 40221 }, passives = {}, talentInfo = { { name = "Legion Weaponmaster", icon = "Interface\\Icons\\Spell_Shadow_SummonFelGuard", text = "Your Physical damage is increased by 10%." }, { name = "Fel-Forged Plate", icon = "Interface\\Icons\\Spell_Shadow_FelArmour", text = "Your armor is increased by 20%." }, { name = "Demonic Might", icon = "Interface\\Icons\\Spell_Shadow_UnholyStrength", text = "Your Strength is increased by 8%." }, { name = "Shadow-Tempered Hide", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Your Shadow resistance is increased by 40." }, { name = "Destroyer's Rhythm", icon = "Interface\\Icons\\Ability_Warrior_SavageBlow", text = "Your melee hits have an 8% chance to follow up with a Mortal Strike. Once every 10 sec.\n\nDrilled in the Twisting Nether until the killing blow comes without thought." }, { name = "The March Unhalted", icon = "Interface\\Icons\\Ability_Warrior_Charge", text = "Reduces the cooldown of Sweeping Charge by 5 sec.\n\nThe Legion's march will not be halted! A Destroyer is back in the enemy line before it has reformed." } }, tips = {}, visualKit = 7775, soundTransform = 53133, soundDeath = 7314, flies = false, wave = 1, zone = "Hellfire Peninsula", expansion = 1, order = 324, box = { 0.52, -0.23, 5.46 }, skins = { { entry = 4677, name = "Yellow", creature = "Doomwarder", display = 5049, height = 3.7, span = 3.7, box = { 0.17, -0.08, 1.82 } }, { entry = 17400, name = "Red", creature = "Felguard Annihilator", display = 18287, height = 8.2, span = 8.2, box = { 0.39, -0.17, 4.09 } }, { entry = 16952, name = "White", creature = "Anger Guard", display = 18193, height = 7.3, span = 7.3, box = { 0.35, -0.15, 3.64 } } }, title = "Soldier of the Burning Legion" },
    { id = "fire_elemental", entry = 15438, name = "Greater Fire Elemental", label = "Fire Elemental", level = 80, display = 1204, height = 5.0, span = 5.0, school = "fire", pool = "archetype", icon = "Interface\\Icons\\Spell_Fire_Elemental_Totem", profile = "caster", kit = { 57984, 12470, 32720, 17883, 10733, 38064 }, passives = { 13377 }, talentInfo = { { name = "Heart of Living Flame", icon = "Interface\\Icons\\INV_Elemental_Primal_Fire", text = "Your Fire damage is increased by 10%." }, { name = "Flameborn Body", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Your Fire resistance is increased by 80." }, { name = "Wildfire Surge", icon = "Interface\\Icons\\Spell_Fire_Flare", text = "Your chance to land a critical spell is increased by 4%." }, { name = "Everburning Core", icon = "Interface\\Icons\\Spell_Fire_MasterOfElements", text = "Your Fire abilities cost 8% less." }, { name = "Spreading Flames", icon = "Interface\\Icons\\Spell_Fire_Immolation", text = "Your damaging spells have a 12% chance to set the target alight with Immolate. Once every 10 sec.\n\nA fire elemental does not choose what burns. Anything it touches simply catches." }, { name = "Living Inferno", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "Your Fire Nova reaches 30% farther.\n\nLoosed from the totem's leash, the flame swells to fill the room around it." } }, tips = { [32720] = "Flare into a racing wildfire, increasing your movement speed by 120% for 10 sec." }, visualKit = 286, soundTransform = 1288, soundDeath = 1286, flies = false, wave = 1, expansion = 0, order = 310, box = { 0.08, -0.05, 2.65 }, title = "Guardian of the Fire Totem" },
    { id = "thrall", entry = 4949, name = "Thrall", label = "Thrall", level = 83, display = 4527, height = 2.8, span = 2.8, school = "nature", pool = "leader", icon = "Interface\\Icons\\Achievement_Leader_Thrall", profile = "caster", kit = { 59517, 59519, 59717, 59507, 13728, 11986, 16609, 261 }, passives = {}, talentInfo = { { name = "Fury of the Storm", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 10%." }, { name = "Wisdom of the Far Seer", icon = "Interface\\Icons\\Spell_Nature_Sentinal", text = "Your Intellect is increased by 8%." }, { name = "Ancestral Guidance", icon = "Interface\\Icons\\Spell_Nature_HealingWaveGreater", text = "Your healing is increased by 10%." }, { name = "Frostwolf Resolve", icon = "Interface\\Icons\\Spell_Nature_SpiritWolf", text = "Damage you take is reduced by 5%." }, { name = "Doomhammer's Thunder", icon = "Interface\\Icons\\Spell_Shaman_ThunderStorm", text = "When you are struck, you have a 10% chance to call down Thunder around you. Once every 20 sec.\n\nThose who crowd the Warchief learn what the Doomhammer's storm sounds like from up close." }, { name = "The Storm Answers", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", text = "Your Chain Lightning deals 15% more damage.\n\nThe spirits of air answer the son of Durotan first, and they strike harder for him than for any other." } }, tips = { [261] = "Call on the spirits of the wolf: two spirit wolves fight at your side for 20 sec." }, visualKit = 282, soundTransform = 5880, soundDeath = 0, flies = false, wave = 1, zone = "Orgrimmar", expansion = 0, order = 14, summons = { [261] = true }, charModel = true, box = { 0.01, -0.01, 1.41 }, title = "Warchief" },
    { id = "sylvanas", entry = 10181, name = "Lady Sylvanas Windrunner", label = "Lady Sylvanas Windrunner", level = 83, display = 28213, height = 2.4, span = 2.4, school = "shadow", pool = "leader", icon = "Interface\\Icons\\Achievement_Leader_Sylvanas", profile = "glass_cannon", kit = { 59712, 59710, 59713, 59514, 17238, 29211, 59711, 22884 }, passives = {}, talentInfo = { { name = "Wail of the Banshee", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_3", text = "Your Shadow damage is increased by 10%." }, { name = "Dark Ranger's Mark", icon = "Interface\\Icons\\Ability_Hunter_MarkedForDeath", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Undying Will of the Forsaken", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", text = "Damage you take is reduced by 5%." }, { name = "Windrunner's Stride", icon = "Interface\\Icons\\Ability_Hunter_RunningShot", text = "You move 10% faster." }, { name = "Rise Again to Serve", icon = "Interface\\Icons\\Ability_TheBlackArrow", text = "Your damaging spells and shots have a 10% chance to strike the target with a Black Arrow. Once every 20 sec.\n\nEvery foe the Banshee Queen marks is a recruit for the Forsaken who has not been told yet." }, { name = "The Dark Lady's Legion", icon = "Interface\\Icons\\Spell_Shadow_AnimateDead", text = "Reduces the cooldown of Summon Skeleton by 20 sec.\n\nThe Forsaken were raised to serve a king. Now they rise for their queen, and faster." } }, tips = {}, visualKit = 7775, soundTransform = 5886, soundDeath = 16320, flies = false, wave = 1, zone = "Undercity", expansion = 0, order = 317, summons = { [59711] = true }, box = { -0.08, -0.02, 1.19 }, title = "Banshee Queen" },
    { id = "varian", entry = 29611, name = "King Varian Wrynn", label = "King Varian Wrynn", level = 83, display = 28127, height = 2.7, span = 2.7, school = "physical", pool = "leader", icon = "Interface\\Icons\\Achievement_Leader_King_Varian_Wrynn", profile = "bruiser", kit = { 41056, 59688, 15708, 15752, 22857, 23600, 60509 }, passives = {}, talentInfo = { { name = "Fury of Lo'Gosh", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "Gladiator's Instinct", icon = "Interface\\Icons\\Ability_Warrior_Riposte", text = "Your chance to critically strike with melee attacks is increased by 5%." }, { name = "Lion of Stormwind", icon = "Interface\\Icons\\INV_BannerPVP_02", text = "Your maximum health is increased by 8%." }, { name = "Resolve of the King", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Damage you take is reduced by 5%." }, { name = "Spirit of the Wolf", icon = "Interface\\Icons\\Ability_Warrior_SavageBlow", text = "Your melee hits have an 8% chance to let loose a Piercing Howl. Once every 20 sec.\n\nLo'Gosh, the ghost wolf of the arena, never let a wounded foe walk away. The king still howls when he smells blood." }, { name = "The Lion Leaps", icon = "Interface\\Icons\\Ability_HeroicLeap", text = "Reduces the cooldown of your Heroic Leap by 5 sec.\n\nThe gladiator learned to cross a pit in a single bound. The king crosses a battlefield." } }, tips = {}, visualKit = 437, soundTransform = 16100, soundDeath = 0, flies = false, wave = 1, zone = "Stormwind City", expansion = 0, order = 315, box = { -0.10, -0.05, 1.34 }, title = "King of Stormwind" },
    { id = "jaina", entry = 4968, name = "Lady Jaina Proudmoore", label = "Lady Jaina Proudmoore", level = 83, display = 30863, height = 2.3, span = 2.3, school = "frost", pool = "leader", icon = "Interface\\Icons\\Spell_Arcane_TeleportTheramore", profile = "caster", kit = { 72166, 20692, 20679, 20680, 11831, 29211, 20681 }, passives = {}, talentInfo = { { name = "Daughter of the Sea", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "Kirin Tor Training", icon = "Interface\\Icons\\Spell_Holy_MagicalSentry", text = "Your casting speed is increased by 8%." }, { name = "Archmage's Insight", icon = "Interface\\Icons\\Spell_Arcane_ArcaneResilience", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Brilliance Aura", icon = "Interface\\Icons\\Spell_Holy_ArcaneIntellect", text = "Your Spirit is increased by 8%." }, { name = "Cold of the North", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "When you are struck, you have a 10% chance to answer with a Frostbolt. Once every 20 sec.\n\nWhoever closes on the Lady of Theramore finds the frost there first." }, { name = "Proudmoore's Tempest", icon = "Interface\\Icons\\Spell_Frost_IceStorm", text = "Your Blizzard covers a 20% larger area.\n\nThe admiral's daughter learned her storms at sea, where there is room for them to grow." } }, tips = {}, visualKit = 4991, soundTransform = 5882, soundDeath = 11010, flies = false, wave = 1, zone = "Dustwallow Marsh", expansion = 0, order = 313, summons = { [20681] = true }, box = { 0.02, 0.01, 1.14 }, title = "Ruler of Theramore" },
    { id = "grom", entry = 17026, name = "Grom Hellscream", label = "Grom Hellscream", level = 70, display = 21575, height = 5.4, span = 5.4, school = "physical", pool = "leader", icon = "Interface\\Icons\\Achievement_Character_Orc_Male", profile = "bruiser", kit = { 65947, 15708, 15284, 22911, 13730, 11329 }, passives = {}, talentInfo = { { name = "Blood of Mannoroth", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "Your attack power is increased by 10%." }, { name = "Warsong Frenzy", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", text = "Your attack speed is increased by 8%." }, { name = "Warsong Ferocity", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your chance to critically strike with melee attacks is increased by 5%." }, { name = "Hellscream's Endurance", icon = "Interface\\Icons\\Spell_Nature_BloodLust", text = "Your maximum health is increased by 8%." }, { name = "Critical Strike", icon = "Interface\\Icons\\Ability_CriticalStrike", text = "Your melee hits have a 10% chance to follow up with a Mortal Strike. Once every 15 sec.\n\nThe Blademaster's edge finds the gap in any guard. Lok'tar ogar!" }, { name = "Gorehowl's Song", icon = "Interface\\Icons\\INV_Axe_04", text = "Reduces the cooldown of your Bladestorm by 15 sec.\n\nThe wind through Gorehowl's notches howls louder with every turn, and Grom never waits long to hear it again." } }, tips = { [11329] = "Walk with the wind: vanish from sight into stealth for 10 sec. Attacking or casting ends it." }, visualKit = 437, soundTransform = 10629, soundDeath = 0, flies = false, wave = 1, expansion = 0, order = 306, charModel = true, box = { 0.02, -0.02, 2.71 }, title = "Chieftain of the Warsong Clan" },
    { id = "spike_fireball", entry = 4275, name = "Archmage Arugal", label = "Spike: name collision", level = 21, display = 2353, height = 2.6, span = 2.6, school = "arcane", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Fire_FlameBolt", profile = "caster", kit = { 9053 }, passives = {}, talentInfo = {}, tips = {}, visualKit = 1005, soundTransform = 0, soundDeath = 0, flies = false, wave = 0, instance = "Shadowfang Keep", expansion = 0, order = 49, charModel = true, box = { -0.13, -0.01, 1.28 }, title = "Master of Shadowfang Keep" },
    { id = "spike_onyxia", entry = 10184, name = "Onyxia", label = "Spike: flight", level = 83, display = 8570, height = 28.1, span = 53.2, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\Achievement_Boss_Onyxia", profile = "bruiser", kit = { 18435, 18500 }, passives = {}, talentInfo = {}, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = true, wave = 0, instance = "Onyxia's Lair", expansion = 0, order = 320, box = { -8.45, 0.22, 11.36 }, title = "Daughter of Deathwing" },
    { id = "majordomo", entry = 12018, name = "Majordomo Executus", label = "Majordomo Executus", level = 63, display = 12029, height = 12.2, span = 12.2, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Holy_Excorcism_02", profile = "caster", kit = { 20229, 20619, 21075, 33245, 261 }, passives = {}, talentInfo = { { name = "Son of the Living Flame", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire damage is increased by 8%." }, { name = "Runes of Warding", icon = "Interface\\Icons\\Spell_Holy_SealOfProtection", text = "Damage you take is reduced by 6%." }, { name = "Aegis of the Molten Core", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Your maximum health is increased by 10%." }, { name = "Command of the Flamewakers", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", text = "Your casting speed is increased by 5%." }, { name = "Ashes to Ashes", icon = "Interface\\Icons\\Spell_Holy_Excorcism_02", text = "When you are struck, you have a 10% chance to unleash a Blast Wave. Once every 20 sec.\n\nBurn, mortals! Burn for this transgression! Whoever lays a hand on the Firelord's steward feels the Core answer." }, { name = "Sworn to the Firelord", icon = "Interface\\Icons\\Ability_Warrior_RallyingCry", text = "Reduces the cooldown of Call the Flamewaker Guard by 30 sec.\n\nThe Flamewakers are sworn to their master's steward. When Executus calls, they do not keep him waiting." } }, tips = { [261] = "Reckless mortals! Call two Flamewaker Elites to your side for 20 sec. None may challenge the Sons of the Living Flame!" }, visualKit = 286, soundTransform = 8035, soundDeath = 8042, flies = false, wave = 2, instance = "Molten Core", expansion = 0, order = 279, summons = { [261] = true }, box = { -1.76, -0.05, 5.93 }, view = { -5.8422, 0.0000, 1.1000 }, voices = { { 8035, 5.8, true, "Reckless mortals! None may challenge the Sons of the Living flame!" }, { 8039, 7.3, true, "The runes of warding have been destroyed! Hunt down the infidels, my brethren!" }, { 8037, 2.1, true, "Ashes to ashes!" }, { 8036, 5.1, true, "Burn mortals! Burn for this transgression!" }, { 8038, 32.0, true, "Impossible! Stay your attack, mortals... I submit! I submit!" }, { 8040, 12.9, true, "Behold Ragnaros - the Firelord! He who was ancient when this world was young! Bow before him, mortals! Bow before your ending!" }, { 8041, 7.1, true, "These mortal infidels, my lord! They have invaded your sanctum and seek to steal your secrets!" }, { 8042, 8.3, true, "My flame... Please, don't take away my flame..." } }, title = "Steward of the Firelord" },
    { id = "geddon", entry = 12056, name = "Baron Geddon", label = "Baron Geddon", level = 63, display = 12129, height = 13.5, span = 13.5, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", profile = "caster", kit = { 20475, 19659, 19695, 23462 }, passives = {}, talentInfo = { { name = "Heart of the Inferno", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "You burn hotter than the Core itself: your Fire damage is increased by 10%." }, { name = "Body of Living Flame", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Your Fire resistance is increased by 80." }, { name = "Baron of the Molten Core", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Take Your Friends With You", icon = "Interface\\Icons\\INV_Enchant_EssenceAstralSmall", text = "Your damaging spells have an 8% chance to turn the target into a Living Bomb. Once every 20 sec.\n\nEvery raid that reaches the Baron learns to run from its own. Burn for the Firelord, and take your friends with you." }, { name = "Take the Hall With You", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "Increases the radius of Fire Nova by 30%.\n\nBeaten, the Baron gave the Firelord one last service: he tried to take the whole hall with him." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Molten Core", expansion = 0, order = 273, box = { 0.22, -0.14, 7.05 }, title = "Right Hand of Ragnaros" },
    { id = "vaelastrasz", entry = 13020, name = "Vaelastrasz the Corrupt", label = "Vaelastrasz the Corrupt", level = 63, display = 13992, height = 14.7, span = 29.9, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Fire_Fire", profile = "bruiser", kit = { 23461, 15847, 23128, 23462 }, passives = {}, talentInfo = { { name = "Flame of the Red Flight", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire damage is increased by 10%." }, { name = "Heart of the Red", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Red", text = "Your maximum health is increased by 8%." }, { name = "Dragonscale of Grim Batol", icon = "Interface\\Icons\\INV_Misc_MonsterScales_15", text = "Your armor is increased by 20%." }, { name = "Blackwing Torment", icon = "Interface\\Icons\\INV_Gauntlets_03", text = "Your melee attack speed is increased by 8%." }, { name = "I Cannot Control Myself", icon = "Interface\\Icons\\Spell_Fire_SealOfFire", text = "Your melee hits have a 10% chance to set off a Fire Nova around you. Once every 15 sec.\n\nFLAME! DEATH! DESTRUCTION! Nefarius' fire rages inside him, and it bursts out whether he wills it or not." }, { name = "Nefarius' Hate", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Reduces the cooldown of your Tail Sweep by 5 sec.\n\nNefarius' hate has made him stronger than ever before. You should have fled while you could." } }, tips = {}, visualKit = 286, soundTransform = 8283, soundDeath = 0, flies = true, wave = 2, instance = "Blackwing Lair", expansion = 0, order = 297, box = { -5.20, -0.03, 6.75 }, view = { -16.4944, -0.0638, 2.1540 }, voices = { { 8281, 8.4, true, "Too late, friends! Nefarius' corruption has taken hold...I cannot...control myself." }, { 8282, 11.1, true, "I beg you, mortals - FLEE! Flee before I lose all sense of control! The black fire rages within my heart! I MUST- release it!" }, { 8283, 16.8, true, "FLAME! DEATH! DESTRUCTION! Cower, mortals before the wrath of Lord...NO - I MUST fight this! Alexstrasza help me, I MUST fight it!" }, { 8285, 13.1, true, "Nefarius' hate has made me stronger than ever before! You should have fled while you could, mortals! The fury of Blackrock courses through my veins!" } }, title = "Ward of the Red Dragonflight", visages = { "vaelastrasz_red" }, shape = "Dragon" },
    { id = "chromaggus", entry = 14020, name = "Chromaggus", label = "Chromaggus", level = 63, display = 14367, height = 18.2, span = 21.6, school = "arcane", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Fire_Fire", profile = "bruiser", kit = { 23308, 23187, 23313, 23310, 57570, 23128 }, passives = { 22283, 22285 }, talentInfo = { { name = "Brood Affliction", icon = "Interface\\Icons\\Spell_Shadow_UnholyStrength", text = "All damage you deal is increased by 6%." }, { name = "Shimmering Hide", icon = "Interface\\Icons\\Spell_Holy_PowerWordShield", text = "All damage you take is reduced by 6%." }, { name = "Bred for Blackwing Lair", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", text = "Your maximum health is increased by 10%." }, { name = "Frenzied Hound", icon = "Interface\\Icons\\Ability_Druid_ChallangingRoar", text = "When you are struck, you have a 10% chance to breathe Incinerate at the enemies before you. Once every 30 sec.\n\nEvery wound drives the hound wilder, and a wild hound breathes fire at whatever hurt it." }, { name = "Sands of Time", icon = "Interface\\Icons\\Spell_Nature_TimeStop", text = "Increases the damage of your Time Lapse by 15%.\n\nBronze blood runs deepest in Nefarian's hound; its breath of stopped time returns before the others." } }, tips = {}, visualKit = 1005, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Blackwing Lair", expansion = 0, order = 290, box = { -1.77, -0.02, 9.01 }, view = { -4.5873, 0.4608, 1.9497 }, title = "Creation of Nefarian" },
    { id = "jindo", entry = 11380, name = "Jin'do the Hexxer", label = "Jin'do the Hexxer", level = 63, display = 11311, height = 5.3, span = 5.3, school = "shadow", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", profile = "caster", kit = { 19460, 17172, 24212, 24261, 11986, 261 }, passives = {}, talentInfo = { { name = "Hexxer's Malice", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your Shadow damage is increased by 10%." }, { name = "Powerful Healing Ward", icon = "Interface\\Icons\\Spell_Nature_HealingWaveGreater", text = "Healing you do is increased by 15%." }, { name = "High Priest of Hakkar", icon = "Interface\\Icons\\Achievement_Boss_Hakkar", text = "Your Intellect is increased by 8%." }, { name = "Step Right Up", icon = "Interface\\Icons\\Spell_Nature_Polymorph", text = "Reduces the cooldown of your Hex by 10 sec.\n\nWelcome to the great show, friends! Jin'do has turned more fools into frogs than any witch doctor of the Gurubashi." }, { name = "Delusions of Jin'do", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "Your damaging spells have a 10% chance to fill the target with the Delusions of Jin'do. Once every 20 sec.\n\nThose the Hexxer touches start seeing shades at the edge of their sight. They are right to be afraid." } }, tips = { [261] = "Call a Shade of Jin'do out of the spirit world to fight at your side for 20 sec." }, visualKit = 7775, soundTransform = 8425, soundDeath = 0, flies = false, wave = 2, instance = "Zul'Gurub", expansion = 0, order = 258, summons = { [261] = true }, charModel = true, box = { -0.06, 0.07, 2.64 }, voices = { { 8425, 6.0, true, "Welcome to the great show, friends. Step right up to die!" } }, title = "Witch Doctor of Zul'Gurub" },
    { id = "marli", entry = 14510, name = "High Priestess Mar'li", label = "High Priestess Mar'li", level = 63, display = 15220, height = 3.7, span = 3.7, school = "nature", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", profile = "caster", kit = { 24099, 25424, 17620, 745, 261 }, passives = {}, talentInfo = { { name = "Venom of Shadra", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "Your Nature damage is increased by 10%." }, { name = "Drain of the High Priestess", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Increases your Shadow damage by 5%." }, { name = "Swiftness of the Web", icon = "Interface\\Icons\\Spell_Nature_Web", text = "Your spells are cast 6% faster." }, { name = "Zulian Wards", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Damage you take is reduced by 4%." }, { name = "Shadra's Venom", icon = "Interface\\Icons\\Ability_Creature_Poison_05", text = "Your damaging spells have an 8% chance to loose a Poison Bolt at the target. Once every 15 sec.\n\nDraw me to your web mistress Shadra. Unleash your venom! The spider loa's venom never runs dry." }, { name = "Shadra's Bounty", icon = "Interface\\Icons\\Spell_Nature_NatureTouchDecay", text = "Your Poison Bolt Volley costs 20% less.\n\nThe temple of Shadra is full of venom sacs, and its high priestess wastes none of them." } }, tips = { [261] = "Aid me, my brood! Two Spawn of Mar'li hatch and skitter to your side to fight for 20 sec." }, visualKit = 282, soundTransform = 8418, soundDeath = 8423, flies = false, wave = 2, instance = "Zul'Gurub", expansion = 0, order = 257, summons = { [261] = true }, charModel = true, box = { -0.31, -0.09, 1.87 }, voices = { { 8418, 5.3, true, "Draw me to your web mistress Shadra. Unleash your venom!" }, { 8423, 7.7, true, "Bless you, mortals, for this release...Hakkar controls me no longer!" } }, title = "Priestess of Shadra", visages = { "marli_spider" }, shape = "Troll" },
    { id = "skeram", entry = 15263, name = "The Prophet Skeram", label = "The Prophet Skeram", level = 63, display = 15345, height = 27.0, span = 27.0, school = "arcane", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Nature_WispSplode", profile = "caster", kit = { 26192, 26194, 785, 29211, 261 }, passives = {}, talentInfo = { { name = "Prophecy of Doom", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", text = "Your prophecies come true: your Arcane damage is increased by 10%." }, { name = "The Age of Darkness", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Illusions of the Prophet", icon = "Interface\\Icons\\INV_Qiraj_JewelEncased", text = "Damage you take is reduced by 6%." }, { name = "Tremble, Mortals", icon = "Interface\\Icons\\Spell_Nature_EarthShock", text = "Your damaging spells have a 10% chance to loose an Arcane Explosion around you. Once every 15 sec.\n\nTremble, mortals! Skeram's power spills over whether he wills it or not; no one near the Prophet stands easy." }, { name = "The Ancient Ones Return", icon = "Interface\\Icons\\Spell_Nature_WispSplode", text = "Increases the damage of your Arcane Explosion by 15%.\n\nPrepare for the return of the ancient ones! Every wave of the Prophet's power is a little closer to their waking." } }, tips = { [261] = "Split yourself: two images of the Prophet step out of you and fight beside you for 20 sec." }, visualKit = 1005, soundTransform = 8615, soundDeath = 8622, flies = false, wave = 2, instance = "Ahn'Qiraj Temple", expansion = 0, order = 270, summons = { [261] = true }, box = { 0.14, 0.07, 13.03 }, view = { -6.1091, -0.2880, 2.4976 }, voices = { { 8615, 4.3, true, "Are you so eager to die? I will be happy to accommodate you..." }, { 8616, 5.5, true, "Cower mortals! The age of darkness is at hand." }, { 8621, 3.2, true, "Tremble! The end is upon you." }, { 8617, 2.7, true, "Let your death serve as an example!" }, { 8619, 4.8, true, "Spineless wretches! You will drown in rivers of blood!" }, { 8620, 8.1, true, "The screams of the dying will fill the air. A symphony of terror is about to begin!" }, { 8618, 4.5, true, "Prepare for the return of the ancient ones!" }, { 8622, 3.2, true, "You only delay the inevitable!" } }, title = "Prophet of Ahn'Qiraj" },
    { id = "huhuran", entry = 15509, name = "Princess Huhuran", label = "Princess Huhuran", level = 63, display = 15739, height = 25.9, span = 25.9, school = "nature", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", profile = "bruiser", kit = { 26050, 26053, 24335, 26051 }, passives = {}, talentInfo = { { name = "Acid of the Hive", icon = "Interface\\Icons\\Ability_Creature_Poison_03", text = "Your acid eats through armor and flesh: your Nature damage is increased by 10%." }, { name = "Wasp Chitin", icon = "Interface\\Icons\\INV_Qiraj_SkinSandworm", text = "Your armor is increased by 20%." }, { name = "Poison-Hardened Carapace", icon = "Interface\\Icons\\Spell_Nature_ResistNature", text = "Your Nature resistance is increased by 50." }, { name = "Dripping Mandibles", icon = "Interface\\Icons\\Spell_Nature_Acid_01", text = "Your melee hits have a 15% chance to Acid Spit the target. Once every 5 sec.\n\nEvery bite the Princess takes leaves acid behind, and the acid keeps on working long after." }, { name = "Killing Frenzy", icon = "Interface\\Icons\\Ability_Hunter_Pet_Wasp", text = "Reduces the cooldown of your Frenzy by 10 sec.\n\nPrincess Huhuran goes into a killing frenzy, and the frenzy does not end until the hive is fed." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = true, wave = 2, instance = "Ahn'Qiraj Temple", expansion = 0, order = 269, box = { 1.70, -0.62, 14.37 }, view = { -14.0871, -0.1658, 1.9440 }, title = "Silithid Wasp of Ahn'Qiraj" },
    { id = "ossirian", entry = 15339, name = "Ossirian the Unscarred", label = "Ossirian the Unscarred", level = 63, display = 15432, height = 22.1, span = 22.1, school = "physical", pool = "classic_raid", icon = "Interface\\Icons\\Ability_BullRush", profile = "bruiser", kit = { 25188, 25189, 25195, 80303, 43317, 261 }, passives = {}, talentInfo = { { name = "Strength of the Unscarred", icon = "Interface\\Icons\\Achievement_Boss_OssirianTheUnscarred", text = "No blade has ever scarred you: your attack power is increased by 10%." }, { name = "Unscarred Hide", icon = "Interface\\Icons\\INV_Misc_QirajiCrystal_01", text = "Damage you take is reduced by 8%." }, { name = "General of the Qiraji", icon = "Interface\\Icons\\INV_QirajIdol_War", text = "Your Strength is increased by 8%." }, { name = "My Powers Are Renewed", icon = "Interface\\Icons\\Spell_Shadow_CurseOfTounges", text = "Reduces the cooldown of your Frenzy by 20 sec.\n\nOnly the crystals of the Ruins ever weakened the Unscarred, and never for long." }, { name = "Rise and Block Out the Sun", icon = "Interface\\Icons\\Ability_BullRush", text = "Your melee hits have an 8% chance to set off a War Stomp. Once every 20 sec.\n\nThe Ruins shake under Ossirian's every step. Stand beside him too long and the sand throws you off your feet." } }, tips = { [261] = "Sands of the desert, rise! Two sand vortices spin up at your side and fight for you for 15 sec." }, visualKit = 437, soundTransform = 8598, soundDeath = 8594, flies = false, wave = 2, instance = "Ruins of Ahn'Qiraj", expansion = 0, order = 304, summons = { [261] = true }, box = { -0.39, -0.56, 11.02 }, voices = { { 8593, 1.9, true, "I am rejuvinated!" }, { 8595, 2.5, true, "My powers are renewed!" }, { 8596, 2.0, true, "My powers return!" }, { 8597, 2.8, true, "Protect the city at all costs!" }, { 8600, 2.8, true, "To your posts. Defend the city." }, { 8601, 2.2, true, "Tresspassers will be terminated." }, { 8598, 4.2, true, "Sands of the desert, rise and block out the sun!" }, { 8602, 1.9, true, "You are terminated." }, { 8594, 3.1, true, "I...have...failed." }, { 8599, 1.7, true, "The walls have been breached!" } }, title = "Hand of C'Thun" },
    { id = "cthun", entry = 15727, name = "C'Thun", label = "C'Thun", level = 63, display = 15787, height = 8.4, span = 31.8, school = "shadow", pool = "classic_raid", icon = "Interface\\Icons\\Achievement_Boss_CThun", profile = "caster", kit = { 26143, 26476, 26139, 261 }, passives = {}, talentInfo = { { name = "Gaze of the Old God", icon = "Interface\\Icons\\Achievement_Boss_CThun", text = "Nothing escapes your eye: your Shadow damage is increased by 10%." }, { name = "Carapace of C'Thun", icon = "Interface\\Icons\\INV_Qiraj_CarapaceOldGod", text = "Damage you take is reduced by 8%." }, { name = "Countless Eyes", icon = "Interface\\Icons\\INV_Misc_Eye_01", text = "Your casting speed is increased by 6%." }, { name = "Whispers in the Dark", icon = "Interface\\Icons\\Spell_Shadow_MindFlay", text = "Your damaging spells have a 10% chance to set an eye tentacle's Mind Flay on the target. Once every 10 sec.\n\nYou will die. Your friends will abandon you. Wherever C'Thun's will falls, another eye opens." }, { name = "The Ground Splits", icon = "Interface\\Icons\\Spell_Nature_Earthquake", text = "Reduces the cooldown of your Ground Rupture by 5 sec.\n\nBeneath the temple the god's tentacles are everywhere; the floor never stays whole for long." } }, tips = { [261] = "The ground splits: two Claw Tentacles burst up beside you and rake your enemies for 20 sec." }, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Ahn'Qiraj Temple", expansion = 0, order = 261, summons = { [261] = true }, box = { -0.01, -0.02, 3.41 }, view = { -27.8138, 0.6106, -0.5430 }, title = "Old God of Madness and Chaos", visages = { "cthun_awakened", "cthun_eye" }, shape = "Emerging" },
    { id = "anubrekhan", entry = 15956, name = "Anub'Rekhan", label = "Anub'Rekhan", level = 83, display = 15931, height = 12.5, span = 15.6, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Ability_BackStab", profile = "tank", kit = { 28783, 28969, 28785, 37548, 261 }, passives = {}, talentInfo = { { name = "Crypt Lord's Carapace", icon = "Interface\\Icons\\INV_Misc_MonsterSpiderCarapace_01", text = "Your armor is increased by 20%." }, { name = "Spider Lord", icon = "Interface\\Icons\\achievement_boss_anubarak", text = "The threat you cause is increased by 30%." }, { name = "Undying Chitin", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Your maximum health is increased by 10%." }, { name = "Locust Swarm", icon = "Interface\\Icons\\Spell_Nature_InsectSwarm", text = "Your Nature damage is increased by 8%." }, { name = "Just a Little Taste", icon = "Interface\\Icons\\Spell_Nature_Acid_01", text = "When you are struck, you have a 10% chance to spit Acid Spit at the attacker. Once every 20 sec.\n\nJust a little taste... The spider lord answers every blow with acid." }, { name = "There Is No Way Out", icon = "Interface\\Icons\\Ability_Hunter_Pet_Wasp", text = "Reduces the cooldown of Locust Swarm by 15 sec.\n\nWhere to go? What to do? The swarm is never far away." } }, tips = { [261] = "Loose three corpse scarabs from the dead around you to fight for 20 sec." }, visualKit = 282, soundTransform = 8785, soundDeath = 8789, flies = false, wave = 2, instance = "Naxxramas", expansion = 2, order = 523, summons = { [261] = true }, box = { 0.43, 0.12, 6.02 }, view = { -2.8964, 0.0000, 1.4740 }, voices = { { 8785, 2.3, true, "Just a little taste..." }, { 8786, 2.7, true, "There is no way out." }, { 8787, 4.2, true, "Yes, run! It makes the blood pump faster!" }, { 8788, 5.6, true, "Ahh... welcome to my parlor." }, { 8790, 12.5, true, "I hear little hearts beating. Yes... beating faster now... soon the beating will stop." }, { 8791, 10.4, true, "Where to go? What to do? So many choices that all end in pain, end in death." }, { 8792, 9.6, true, "Which one shall I eat first? So difficult to choose. They all smell so delicious..." }, { 8793, 11.5, true, "Closer now. Tasty morsels. I've been too long without food, without blood to drink." }, { 8789, 4.7, true, "Shhh... it will all be over soon." } }, title = "Spider Lord of Azjol-Nerub" },
    { id = "faerlina", entry = 15953, name = "Grand Widow Faerlina", label = "Grand Widow Faerlina", level = 83, display = 15940, height = 3.3, span = 3.3, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", profile = "caster", kit = { 28796, 28794, 54096, 54093, 261 }, passives = {}, talentInfo = { { name = "Cult of the Damned", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "Your Nature damage is increased by 10%." }, { name = "Rain of the Widow", icon = "Interface\\Icons\\Spell_Shadow_RainOfFire", text = "Your Fire damage is increased by 6%." }, { name = "Acolyte's Devotion", icon = "Interface\\Icons\\Spell_Holy_MindVision", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Widow's Resolve", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Damage you take is reduced by 5%." }, { name = "You Cannot Hide From Me", icon = "Interface\\Icons\\Ability_Creature_Poison_03", text = "Your damaging spells have an 8% chance to loose a Poison Bolt Volley. Once every 20 sec.\n\nThe Grand Widow's poison finds everyone in the room eventually." }, { name = "Run While You Still Can", icon = "Interface\\Icons\\Spell_Fire_MeteorStorm", text = "Your Rain of Fire lasts 2 sec longer.\n\nRun while you still can! Faerlina's fire keeps falling after you flee." } }, tips = { [261] = "Slay them in the master's name! Call two Naxxramas Worshippers to fight for you for 20 sec." }, visualKit = 282, soundTransform = 8794, soundDeath = 8798, flies = false, wave = 2, instance = "Naxxramas", expansion = 2, order = 526, summons = { [261] = true }, charModel = true, box = { -0.18, 0.01, 1.63 }, voices = { { 8799, 18.3, true, "Your old lives, your mortal desires mean nothing... you are acolytes of the master now, and you will serve the cause without question! The greatest glory is to die in the master's service!" }, { 8794, 2.2, true, "Slay them in the master's name!" }, { 8800, 1.6, true, "You have failed!" }, { 8801, 1.4, true, "Pathetic wretch!" }, { 8798, 2.9, true, "The master will avenge me!!" }, { 8795, 2.7, true, "You cannot hide from me!" }, { 8796, 2.2, true, "Kneel before me, worm!" }, { 8797, 2.2, true, "Run while you still can!" } }, title = "Cult of the Damned" },
    { id = "maexxna", entry = 15952, name = "Maexxna", label = "Maexxna", level = 83, display = 15928, height = 20.2, span = 42.4, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Maexxna", profile = "bruiser", kit = { 29484, 54453, 28741, 54121, 54123, 261 }, passives = {}, talentInfo = { { name = "Spider of the Arachnid Quarter", icon = "Interface\\Icons\\Ability_Hunter_Pet_Spider", text = "Your attack power is increased by 10%." }, { name = "Chitin Carapace", icon = "Interface\\Icons\\INV_Misc_MonsterSpiderCarapace_01", text = "Your armor is increased by 15%." }, { name = "Venom Glands", icon = "Interface\\Icons\\Ability_Creature_Poison_06", text = "Your Nature damage is increased by 8%." }, { name = "Eight Legs", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Your movement speed is increased by 10%." }, { name = "Wrapped", icon = "Interface\\Icons\\Spell_Nature_Web", text = "Your melee attacks have an 8% chance to Web Wrap the target. Once every 20 sec.\n\nMaexxna wraps whatever she bites, to eat later." }, { name = "Broodmother's Venom", icon = "Interface\\Icons\\Ability_Creature_Poison_04", text = "Your Poison Shock deals 15% more damage.\n\nThe broodmother of Naxxramas has venom enough for the whole quarter." } }, tips = { [261] = "Hatch three Maexxna Spiderlings from your egg sacs to fight for you for 20 sec." }, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Naxxramas", expansion = 2, order = 533, summons = { [261] = true }, box = { 4.65, -0.00, 8.15 }, view = { -24.0171, 0.0904, 5.2361 }, title = "Spider of the Arachnid Quarter" },
    { id = "gothik", entry = 16060, name = "Gothik the Harvester", label = "Gothik the Harvester", level = 83, display = 16279, height = 7.0, span = 7.0, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", profile = "caster", kit = { 29317, 27831, 16608, 50267, 58541, 261 }, passives = {}, talentInfo = { { name = "Master of Necromancy", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", text = "Your Shadow damage is increased by 10%." }, { name = "Harvester of Souls", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_3", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Living and Dead", icon = "Interface\\Icons\\Spell_Shadow_AnimateDead", text = "Your maximum health is increased by 8%." }, { name = "Necromantic Focus", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "The mana cost of your Shadow spells is reduced by 8%." }, { name = "Foolishly You Have Sought", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Your damaging spells have an 8% chance to Drain Life. Once every 20 sec.\n\nThe harvester takes a little of every life he ends." }, { name = "I Have Waited Long Enough", icon = "Interface\\Icons\\Spell_Shadow_Shadowfury", text = "Reduces the cooldown of Shadow Bolt Volley by 4 sec.\n\nGothik's patience ran out long ago; his volleys come fast." } }, tips = { [261] = "Death is the only escape! Raise a Death Knight from the harvest to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 8808, soundDeath = 8805, flies = false, wave = 2, instance = "Naxxramas", expansion = 2, order = 525, summons = { [261] = true }, box = { -0.21, -0.02, 3.51 }, view = { -2.1527, 0.0000, 0.5280 }, voices = { { 8807, 24.4, true, "Foolishly you have sought your own demise." }, { 8808, 6.9, true, "I have waited long enough. Now you face the harvester of souls." }, { 8805, 7.7, true, "I... am... undone." }, { 8806, 3.0, true, "Death is the only escape!" } }, title = "Master of Necromancy" },
    { id = "patchwerk", entry = 16028, name = "Patchwerk", label = "Patchwerk", level = 83, display = 16174, height = 14.2, span = 14.9, school = "physical", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Patchwerk", profile = "tank", kit = { 41926, 32309, 37548, 28131 }, passives = {}, talentInfo = { { name = "Avatar of War", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "The threat you cause is increased by 30%." }, { name = "Stitched Bulk", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 12%." }, { name = "Patchwork Hide", icon = "Interface\\Icons\\INV_Misc_Bandage_15", text = "Your armor is increased by 20%." }, { name = "Hateful", icon = "Interface\\Icons\\Ability_Warrior_InnerRage", text = "Your attack power is increased by 10%." }, { name = "Patchwerk Want to Play", icon = "Interface\\Icons\\Ability_Warrior_PunishingBlow", text = "Your melee attacks have an 8% chance to add a Hateful Strike. Once every 15 sec.\n\nPatchwerk hits whoever is biggest, and then whoever is next biggest." }, { name = "Slime Glands", icon = "Interface\\Icons\\Spell_Nature_Acid_01", text = "Reduces the cooldown of Slime Bolt by 5 sec.\n\nWhen Patchwerk gets angry, the slime flies faster." } }, tips = {}, visualKit = 437, soundTransform = 8909, soundDeath = 8911, flies = false, wave = 2, instance = "Naxxramas", expansion = 2, order = 535, box = { -1.00, 0.09, 6.47 }, view = { -7.4671, 0.0000, 1.3970 }, voices = { { 8909, 3.3, true, "Patchwerk want to play!" }, { 8910, 3.4, true, "Kel'thuzad make Patchwerk his avatar of war!" }, { 8912, 1.6, true, "No more play?" }, { 8911, 4.0, true, "What... happen to-" } }, title = "Abomination of Naxxramas" },
    { id = "loatheb", entry = 16011, name = "Loatheb", label = "Loatheb", level = 83, display = 16110, height = 11.9, span = 18.4, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Loatheb", profile = "caster", kit = { 29865, 29204, 69633, 261 }, passives = {}, talentInfo = { { name = "Bog Beast of Naxxramas", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "Your Nature damage is increased by 10%." }, { name = "Fungal Bulk", icon = "Interface\\Icons\\INV_Mushroom_11", text = "Your maximum health is increased by 10%." }, { name = "Spore Cloud", icon = "Interface\\Icons\\Spell_Nature_AbolishMagic", text = "Your Nature resistance is increased by 60." }, { name = "Necrotic Flesh", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Damage you take is reduced by 5%." }, { name = "Inevitable", icon = "Interface\\Icons\\Spell_Shadow_NightOfTheDead", text = "When you are struck, you have an 8% chance to spread Deathbloom. Once every 30 sec.\n\nStrike the bog beast and its spores burst over everyone near it." }, { name = "Necrotic Aura", icon = "Interface\\Icons\\Spell_Shadow_AuraOfDarkness", text = "Reduces the cooldown of Inevitable Doom by 8 sec.\n\nLoatheb's doom comes sooner every time it is called." } }, tips = { [261] = "Call a Plague Beast out of the Plague Quarter to fight for you for 20 sec." }, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Naxxramas", expansion = 2, order = 532, summons = { [261] = true }, box = { 1.67, -0.59, 5.44 }, view = { -11.0455, 0.3140, 1.7035 }, title = "Bog Beast of Naxxramas" },
    { id = "azuregos", entry = 6109, name = "Azuregos", label = "Azuregos", level = 63, display = 11460, height = 25.3, span = 53.6, school = "frost", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Blue", profile = "caster", kit = { 21097, 9672, 21098, 21099, 19983, 22067, 21150 }, passives = {}, talentInfo = { { name = "Storm of the Nexus", icon = "Interface\\Icons\\Spell_Frost_IceStorm", text = "The storm you call never falters: your Frost damage is increased by 10%." }, { name = "Reflective Scales", icon = "Interface\\Icons\\Spell_Frost_FrostWard", text = "Damage you take is reduced by 6%." }, { name = "Mind of the Blue Flight", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Blue", text = "Your Intellect is increased by 8%." }, { name = "Keeper of Azshara's Secrets", icon = "Interface\\Icons\\Spell_Frost_FrostBolt", text = "Your Frost spells cost 8% less." }, { name = "Mark of Frost", icon = "Interface\\Icons\\Spell_Frost_ChainsOfIce", text = "When you are struck, you have a 10% chance to Chill the enemies around you. Once every 20 sec.\n\nThose who raise a hand against Azuregos carry his frost away with them, and it remembers them when they return." }, { name = "The Arcane Shall Remain Inviolate", icon = "Interface\\Icons\\Spell_Arcane_Blink", text = "Reduces the cooldown of Arcane Vacuum by 10 sec.\n\nThis place is under my protection. No thief of Azshara's secrets gets far enough away to matter." } }, tips = { [21150] = "Tear an enemy through the air to your side with a vacuum of arcane force." }, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = true, wave = 2, zone = "Azshara", expansion = 0, order = 175, box = { -8.48, 0.00, 11.43 }, view = { -17.8935, 0.5717, 15.9452 }, title = "Safekeeper of the Nexus" },
    { id = "kazzak", entry = 18728, name = "Doom Lord Kazzak", label = "Doom Lord Kazzak", level = 73, display = 17887, height = 51.5, span = 88.5, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", profile = "bruiser", kit = { 19983, 21066, 22665, 23931, 21056, 16608 }, passives = {}, talentInfo = { { name = "Supreme Lord's Wrath", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 10%." }, { name = "Hide of the Doom Lord", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Damage you take is reduced by 6%." }, { name = "Harvest of Mortal Souls", icon = "Interface\\Icons\\Spell_Shadow_SoulGem", text = "Your maximum health is increased by 8%." }, { name = "Felblood Might", icon = "Interface\\Icons\\Spell_Shadow_UnholyStrength", text = "Your Strength is increased by 6%." }, { name = "Tear in the Void", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "Your melee attacks have an 8% chance to loose a Void Bolt at the target. Once every 30 sec.\n\nKazzak's greatblade leaves a tear in the air behind each swing, and the void answers through it." }, { name = "Endless Volley", icon = "Interface\\Icons\\Spell_Shadow_Shadowfury", text = "Reduces the cooldown of Shadow Bolt Volley by 3 sec.\n\nWhen the Doomlord tires of waiting, his volleys fall like rain across Hellfire." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Hellfire Peninsula", expansion = 1, order = 327, box = { -5.78, 0.34, 25.75 }, view = { -11.5336, 1.4475, 7.6601 }, voices = { { 11333, 3.8, true, "The legion will conquer all!" }, { 11334, 3.4, true, "All mortals will perish!" }, { 11335, 4.5, true, "All life must be eradicated!" }, { 11336, 5.5, true, "I'll rip the flesh from your bones!" }, { 11337, 2.9, true, "Kirel narak!" }, { 11338, 2.5, true, "Contemptible wretch!" }, { 11339, 4.3, true, "The universe will be remade." }, { 11340, 6.3, true, "The Legion... will never... fall." } }, title = "Doomlord of the Burning Legion" },
    { id = "ysondre", entry = 14887, name = "Ysondre", label = "Ysondre", level = 63, display = 15364, height = 21.7, span = 44.9, school = "nature", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Green", profile = "caster", kit = { 24819, 20824, 24818, 15847, 12098, 261 }, passives = {}, talentInfo = { { name = "Lightning of the Nightmare", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", text = "Your Nature damage is increased by 10%." }, { name = "Scales of the Dreamer", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Damage you take is reduced by 5%." }, { name = "Storm of the Dreamer", icon = "Interface\\Icons\\Spell_Nature_Sleep", text = "Your casting speed is increased by 6%." }, { name = "Aspect of the Emerald Dream", icon = "Interface\\Icons\\Spell_Nature_Tranquility", text = "Your Intellect is increased by 8%." }, { name = "The Dream's Storm", icon = "Interface\\Icons\\Spell_Nature_CallStorm", text = "When you are struck, you have a 10% chance to call the Dream's storm down on your attacker. Once every 20 sec.\n\nWherever Ysondre lands, the Dream's storm gathers over her, and it answers whoever strikes her." }, { name = "Feel the Storm", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Reduces the cooldown of Lightning Wave by 3 sec.\n\nFeel the storm of the Dream, defilers! Ysondre's lightning comes back around faster than they can scatter." } }, tips = { [261] = "Call two Demented Druid Spirits, druids lost to the Nightmare, to fight at your side for 20 sec." }, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = true, wave = 2, zone = "Ashenvale", expansion = 0, order = 88, summons = { [261] = true }, box = { -7.75, 0.04, 9.80 }, view = { -25.5216, 0.0000, 4.6970 }, title = "Dragon of Nightmare" },
    { id = "princess", entry = 330, name = "Princess", label = "Princess", level = 9, display = 8871, height = 1.6, span = 2.2, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\Ability_Hunter_Pet_Boar", profile = "bruiser", kit = { 40772, 32019, 6605, 5568, 261 }, passives = {}, talentInfo = { { name = "Prize Sow's Tusks", icon = "Interface\\Icons\\Ability_Hunter_Pet_Boar", text = "Your Physical damage is increased by 8%." }, { name = "Thick Pig Hide", icon = "Interface\\Icons\\Ability_Druid_Bash", text = "Your armor is increased by 15%." }, { name = "Pumpkin-Fed Bulk", icon = "Interface\\Icons\\INV_Misc_Food_59", text = "Your maximum health is increased by 8%." }, { name = "Pumpkin Patch Rampage", icon = "Interface\\Icons\\Spell_Nature_NaturesWrath", text = "Your melee hits have a 10% chance to set off a Trample around you. Once every 8 sec.\n\nNobody touches her pumpkins. When Princess gets going, the whole patch gets flattened." }, { name = "Farmyard Stampede", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Reduces the cooldown of your Boar Charge by 5 sec.\n\nOnce a prize pig gets up to speed, it takes a whole fence line to stop her." } }, tips = { [261] = "Squeal for your entourage: two Porcine Entourage boars trot to your side and fight for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Elwynn Forest", expansion = 0, order = 7, summons = { [261] = true }, box = { 0.24, 0.00, 0.77 }, title = "Prize Pig of the Brackwell Family" },
    { id = "gamon", entry = 6466, name = "Gamon", label = "Gamon", level = 12, display = 5205, height = 2.3, span = 2.3, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\Achievement_Character_Orc_Male", profile = "bruiser", kit = { 14872, 5164, 10966, 3391, 11876, 9741 }, passives = { 5021 }, talentInfo = { { name = "Ragefire Grudge", icon = "Interface\\Icons\\Ability_Warrior_InnerRage", text = "All damage you deal is increased by 5%." }, { name = "Bar Brawler", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack speed is increased by 8%." }, { name = "Tauren Hide", icon = "Interface\\Icons\\Ability_Warrior_EndlessRage", text = "Your Stamina is increased by 8%." }, { name = "Liquid Courage", icon = "Interface\\Icons\\INV_Drink_05", text = "When you are hit, you have an 8% chance to Thrash back, gaining extra attacks. Once every 20 sec.\n\nEvery hero who picks on Gamon learns the same lesson: hitting him only makes him thirstier." }, { name = "Gamon Fight Everybody", icon = "Interface\\Icons\\Ability_BullRush", text = "Reduces the cooldown of your Arantir's Rage by 20 sec.\n\nGamon don't need no help. Gamon don't need no rest either. Gamon just want the next fight." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Orgrimmar", expansion = 0, order = 13, charModel = true, box = { -0.04, -0.00, 1.12 }, title = "Hero of Orgrimmar" },
    { id = "murkeye", entry = 391, name = "Old Murk-Eye", label = "Old Murk-Eye", level = 20, display = 5243, height = 2.6, span = 2.6, school = "nature", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Misc_Head_Murloc_01", profile = "glass_cannon", kit = { 3584, 12024, 12167, 15860, 261 }, passives = {}, talentInfo = { { name = "Coastal Plague", icon = "Interface\\Icons\\Ability_Creature_Disease_02", text = "Your Nature damage is increased by 10%." }, { name = "Old One's Cunning", icon = "Interface\\Icons\\Spell_Nature_NullifyDisease", text = "Your chance to critically strike with spells is increased by 4%." }, { name = "Hundred-Tide Hide", icon = "Interface\\Icons\\Ability_Hunter_Pet_Crocolisk", text = "Your chance to dodge is increased by 5%." }, { name = "Tidewalker's Stride", icon = "Interface\\Icons\\Spell_Frost_Wisp", text = "Your movement speed is increased by 8%." }, { name = "Venom-Slick Harpoon", icon = "Interface\\Icons\\Ability_Creature_Poison_03", text = "Your damaging spells have a 10% chance to Impale the target with your harpoon. Once every 10 sec.\n\nA hundred tides of rust, brine and murloc spit. Nobody pulls Murk-Eye's harpoon out clean." }, { name = "Lamp of the Lighthouse", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Increases the damage of your Lighthouse Lightning by 15%.\n\nOld Murk-Eye stole the Westfall lighthouse lamp a hundred tides ago. Mrrgl. It still sparks." } }, tips = { [261] = "Gurgle for help: two Murloc Coastrunners splash out of the shallows and fight for you for 20 sec." }, visualKit = 282, soundTransform = 416, soundDeath = 420, flies = false, wave = 2, zone = "Westfall", expansion = 0, order = 22, summons = { [261] = true }, box = { -0.17, -0.00, 1.28 }, title = "Murloc of the Westfall Lighthouse" },
    { id = "smite", entry = 646, name = "Mr. Smite", label = "Mr. Smite", level = 20, display = 2026, height = 2.7, span = 2.7, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Misc_Head_Tauren_01", profile = "bruiser", kit = { 6432, 24438, 9080 }, passives = {}, talentInfo = { { name = "First Mate's Grit", icon = "Interface\\Icons\\Ability_Parry", text = "Your chance to parry is increased by 5%." }, { name = "Tauren Brawn", icon = "Interface\\Icons\\Ability_Warrior_WarCry", text = "Your Strength is increased by 6%." }, { name = "Juggernaut Discipline", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Damage you take is reduced by 5%." }, { name = "Plundered Muscle", icon = "Interface\\Icons\\Ability_Warrior_PunishingBlow", text = "Your Physical damage is increased by 6%." }, { name = "Time to Improvise", icon = "Interface\\Icons\\Ability_Warrior_WeaponMastery", text = "Reduces the cooldown of your Smite Stomp by 15 sec.\n\nYou landlubbers are tougher than I thought! Every time the First Mate reaches for new steel, the deck shakes first." } }, tips = {}, visualKit = 437, soundTransform = 5777, soundDeath = 0, flies = false, wave = 2, instance = "Deadmines", expansion = 0, order = 37, charModel = true, box = { -0.05, -0.01, 1.34 }, voices = { { 5775, 2.6, true, "You there, check out that noise!" }, { 5777, 5.9, true, "We're under attack! Avast, ye swabs! Repel the invaders!" }, { 5778, 5.1, false, "You landlubbers are tougher than I thought, I'll have to Improvise!" }, { 5779, 3.4, false, "D'ah! Now you're making me angry!" } }, title = "The Ship's First Mate" },
    { id = "cookie", entry = 645, name = "Cookie", label = "Cookie", level = 20, display = 1305, height = 1.7, span = 1.7, school = "nature", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Misc_Food_15", profile = "caster", kit = { 5174, 6306, 25058, 29676 }, passives = {}, talentInfo = { { name = "Secret Recipe", icon = "Interface\\Icons\\INV_Misc_Food_15", text = "Your healing is increased by 12%." }, { name = "Acidic Seasoning", icon = "Interface\\Icons\\Spell_Nature_Acid_01", text = "Your Nature damage is increased by 8%." }, { name = "Hearty Appetite", icon = "Interface\\Icons\\INV_Misc_Food_14", text = "Your maximum health is increased by 8%." }, { name = "Spilled Stew", icon = "Interface\\Icons\\INV_Drink_06", text = "When you are hit, you have an 8% chance to slosh Acid Splash over everyone nearby. Once every 20 sec.\n\nJostle the cook and the pot goes everywhere. Mrgl! Nobody jostles Cookie twice." }, { name = "Second Helping", icon = "Interface\\Icons\\Spell_Holy_Heal", text = "Reduces the cooldown of Cookie's Cooking by 6 sec.\n\nThere is always more stew in the pot. Nobody on the Juggernaut dares ask what is in it." } }, tips = {}, visualKit = 282, soundTransform = 416, soundDeath = 420, flies = false, wave = 2, instance = "Deadmines", expansion = 0, order = 33, box = { -0.11, -0.00, 0.83 }, title = "The Ship's Cook" },
    { id = "greenskin", entry = 647, name = "Captain Greenskin", label = "Captain Greenskin", level = 20, display = 7113, height = 2.1, span = 2.1, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Misc_Head_Orc_01", profile = "bruiser", kit = { 5208, 40505, 7395, 14030 }, passives = {}, talentInfo = { { name = "Poison-Tipped Barbs", icon = "Interface\\Icons\\Ability_Creature_Poison_05", text = "Your Nature damage is increased by 10%." }, { name = "Sea Legs", icon = "Interface\\Icons\\Ability_Rogue_Feint", text = "Your chance to dodge is increased by 5%." }, { name = "Goblin Cutthroat", icon = "Interface\\Icons\\Ability_CriticalStrike", text = "Your chance to critically strike with melee attacks is increased by 4%." }, { name = "Captain's Swagger", icon = "Interface\\Icons\\Ability_Warrior_BloodFrenzy", text = "Your attack power is increased by 6%." }, { name = "Feed the Sharks", icon = "Interface\\Icons\\Ability_Poisons", text = "Your melee hits have a 6% chance to drive in a Poisoned Harpoon. Once every 20 sec.\n\nYarr! A goblin captain never swings without a little something extra on the barbs." }, { name = "Powder Monkeys", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "Increases the damage of your Deadmines Dynamite by 15%.\n\nThe Defias blasted the Deadmines out of the rock. Their captain never sails without a crate of the leftovers." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Deadmines", expansion = 0, order = 32, charModel = true, box = { 0.01, -0.04, 1.04 }, title = "The Ship's Captain" },
    { id = "mutanus", entry = 3654, name = "Mutanus the Devourer", label = "Mutanus the Devourer", level = 20, display = 4088, height = 5.1, span = 5.1, school = "nature", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Misc_Head_Murloc_01", profile = "caster", kit = { 8150, 7399, 7967, 12693, 21807 }, passives = {}, talentInfo = { { name = "Devourer's Storm", icon = "Interface\\Icons\\Spell_Nature_ThunderClap", text = "Your Nature damage is increased by 10%." }, { name = "Heart of the Nightmare", icon = "Interface\\Icons\\Spell_Shadow_Possession", text = "Your Shadow damage is increased by 6%." }, { name = "Mutated Hide", icon = "Interface\\Icons\\Ability_Creature_Disease_05", text = "Your maximum health is increased by 8%." }, { name = "Deviate Resilience", icon = "Interface\\Icons\\Spell_Nature_ResistNature", text = "Your Nature resistance is increased by 40." }, { name = "The Devourer's Hunger", icon = "Interface\\Icons\\Spell_Shadow_VampiricAura", text = "Your melee attacks have a 10% chance to Devour Flesh from the target. Once every 20 sec.\n\nIt was a murloc once. The Nightmare grew it huge and left it only one thought: eat." }, { name = "Cavern Echo", icon = "Interface\\Icons\\Ability_ThunderClap", text = "Increases the damage of Thundercrack by 15%.\n\nThunder in the Wailing Caverns does not fade; it rolls on down every tunnel." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Wailing Caverns", expansion = 0, order = 57, box = { -0.34, -0.01, 2.57 }, title = "Murloc of the Emerald Nightmare" },
    { id = "cobrahn", entry = 3669, name = "Lord Cobrahn", label = "Lord Cobrahn", level = 20, display = 4213, height = 3.1, span = 3.1, school = "nature", pool = "classic_dungeon", icon = "Interface\\Icons\\Ability_Hunter_Pet_WindSerpent", profile = "caster", kit = { 9739, 12747, 8040, 11431, 12160 }, passives = { 3616 }, talentInfo = { { name = "Fang of the Serpent", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 10%." }, { name = "Druid of the Fang", icon = "Interface\\Icons\\Spell_Nature_HealingTouch", text = "Your healing is increased by 8%." }, { name = "Venomous Insight", icon = "Interface\\Icons\\Ability_Creature_Poison_02", text = "Your chance to critically strike with spells is increased by 4%." }, { name = "Dreamer's Thrift", icon = "Interface\\Icons\\Spell_Nature_Sleep", text = "The cost of your Nature spells is reduced by 8%." }, { name = "The Dreamer's Grip", icon = "Interface\\Icons\\Spell_Nature_StrangleVines", text = "Reduces the cooldown of your Entangling Roots by 5 sec.\n\nYou will never wake the dreamer! Naralex's dream grows roots through every cavern the Fanglord walks." } }, tips = {}, visualKit = 282, soundTransform = 5785, soundDeath = 0, flies = false, wave = 2, instance = "Wailing Caverns", expansion = 0, order = 53, charModel = true, box = { -0.24, 0.01, 1.55 }, voices = { { 5785, 1.8, true, "You will never wake the dreamer!" } }, title = "Fanglord", visages = { "cobrahn_serpent" }, shape = "Night elf" },
    { id = "serpentis", entry = 3673, name = "Lord Serpentis", label = "Lord Serpentis", level = 20, display = 4215, height = 3.1, span = 3.1, school = "nature", pool = "classic_dungeon", icon = "Interface\\Icons\\Ability_Hunter_Pet_WindSerpent", profile = "caster", kit = { 9532, 8147, 19514, 16561 }, passives = { 22351 }, talentInfo = { { name = "Serpent King's Storm", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 10%." }, { name = "Crown of the Caverns", icon = "Interface\\Icons\\Spell_Nature_WispSplode", text = "Your Intellect is increased by 6%." }, { name = "Coils of the Serpent", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", text = "Damage you take is reduced by 5%." }, { name = "Serpent's Renewal", icon = "Interface\\Icons\\Spell_Nature_HealingTouch", text = "Your healing is increased by 8%." }, { name = "I Can Do Anything", icon = "Interface\\Icons\\Spell_Lightning_LightningBolt01", text = "Your damaging spells have a 10% chance to call a Lightning Bolt down on the target. Once every 8 sec.\n\nThe self-crowned serpent king believes the storm answers to him. Some days it does." } }, tips = {}, visualKit = 282, soundTransform = 5788, soundDeath = 0, flies = false, wave = 2, instance = "Wailing Caverns", expansion = 0, order = 56, charModel = true, box = { -0.24, 0.01, 1.55 }, voices = { { 5788, 5.1, true, "I am the serpent king! I can do anything!" } }, title = "Fanglord" },
    { id = "stitches", entry = 412, name = "Stitches", label = "Stitches", level = 35, display = 1693, height = 5.1, span = 5.4, school = "nature", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Misc_Head_Undead_01", profile = "tank", kit = { 3106, 54794, 15496, 31705, 4280 }, passives = {}, talentInfo = { { name = "Stitched Flesh", icon = "Interface\\Icons\\Spell_Shadow_AbominationExplosion", text = "Your maximum health is increased by 12%." }, { name = "Abomination's Hide", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 20%." }, { name = "Hunger for Darkshire", icon = "Interface\\Icons\\Ability_Racial_Cannibalize", text = "The threat you cause is increased by 30%." }, { name = "Shambling Bulk", icon = "Interface\\Icons\\Ability_Warrior_ShieldWall", text = "Damage you take is reduced by 6%." }, { name = "Festering Rot", icon = "Interface\\Icons\\Spell_Nature_NatureTouchDecay", text = "When you are struck, you have a 15% chance to exude Aura of Rot. Once every 6 sec.\n\nCut Abercrombie's stitches and the rot comes spilling out over whoever held the blade." }, { name = "Darkshire, I Hunger", icon = "Interface\\Icons\\INV_Misc_Food_14", text = "Increases the damage of Consume Flesh by 20%.\n\nThe Night Watch rings the bell when Stitches comes down the road. He is hungry every time." } }, tips = { [4280] = "Tear a mouthful from an enemy, draining 50 health to hold your stitches together." }, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Duskwood", expansion = 0, order = 92, box = { -0.36, 0.03, 2.35 }, view = { -0.8858, 0.1498, 0.7322 }, title = "Gift from the Embalmer" },
    { id = "morladim", entry = 522, name = "Mor'Ladim", label = "Mor'Ladim", level = 30, display = 21691, height = 2.5, span = 2.5, school = "shadow", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Misc_Bone_HumanSkull_01", profile = "bruiser", kit = { 3547, 38461, 13737, 19369, 5164 }, passives = {}, talentInfo = { { name = "Ladimore's Betrayal", icon = "Interface\\Icons\\Ability_Warrior_Trauma", text = "Your Physical damage is increased by 8%." }, { name = "Undying Knight", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", text = "Damage you take is reduced by 6%." }, { name = "Stormwind Training", icon = "Interface\\Icons\\Ability_Parry", text = "Your chance to parry is increased by 5%." }, { name = "Chill of the Grave", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Your Shadow resistance is increased by 40." }, { name = "Sarah's Memory", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "When struck, you have a 10% chance to answer with a Mortal Strike. Once every 30 sec.\n\nSarah... what have I done? Every wound brings Raven Hill back, and the knight fights all the harder." }, { name = "Knight of Stormwind", icon = "Interface\\Icons\\Ability_Warrior_Charge", text = "Reduces the cooldown of Charge by 5 sec.\n\nDeath took his reason, not his training: Morgan Ladimore still charges the enemy's line." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Duskwood", expansion = 0, order = 91, box = { -0.05, -0.05, 1.23 }, title = "Fallen Soldier of Grand Hamlet" },
    { id = "thalnos", entry = 4543, name = "Bloodmage Thalnos", label = "Bloodmage Thalnos", level = 32, display = 11396, height = 3.1, span = 3.1, school = "fire", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", profile = "caster", kit = { 13729, 9613, 8814, 11445, 17173 }, passives = {}, talentInfo = { { name = "Bloodmage's Pyre", icon = "Interface\\Icons\\Spell_Fire_FlameShock", text = "Your Fire damage is increased by 10%." }, { name = "The Angry Dead", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 6%." }, { name = "Unquiet Bones", icon = "Interface\\Icons\\Spell_Shadow_Twilight", text = "Damage you take is reduced by 5%." }, { name = "Graveyard Channeling", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "The cost of your Fire spells is reduced by 8%." }, { name = "More Souls", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Your damaging spells have a 10% chance to siphon the target's soul as well. Once every 20 sec.\n\nMore... more souls! The Bloodmage's hunger outlived his flesh and will outlive his bones." }, { name = "Bloodmage's Brand", icon = "Interface\\Icons\\Spell_Fire_Immolation", text = "Increases the damage of Flame Shock by 15%.\n\nNo rest for the angry dead: Thalnos burns his mark into every living thing in his graveyard." } }, tips = {}, visualKit = 286, soundTransform = 5844, soundDeath = 0, flies = false, wave = 2, instance = "Scarlet Monastery", expansion = 0, order = 99, box = { -0.70, -0.20, 1.36 }, view = { 1.3704, 0.0463, 1.1505 }, voices = { { 5844, 2.5, true, "We hunger for vengeance." }, { 5846, 3.2, true, "No rest... for the angry dead!" }, { 5845, 3.2, true, "More... More souls!" } }, title = "Once of the Scarlet Crusade" },
    { id = "herod", entry = 3975, name = "Herod", label = "Herod", level = 37, display = 2041, height = 2.8, span = 2.8, school = "holy", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Misc_Head_Human_01", profile = "bruiser", kit = { 8989, 15496, 6268, 8599, 261 }, passives = {}, talentInfo = { { name = "Scarlet Champion", icon = "Interface\\Icons\\Ability_Warrior_SavageBlow", text = "Your Physical damage is increased by 8%." }, { name = "Armory Plate", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Light, Give Me Strength", icon = "Interface\\Icons\\Spell_Holy_FistOfJustice", text = "Your Strength is increased by 6%." }, { name = "A Real Challenge", icon = "Interface\\Icons\\Ability_Warrior_Challange", text = "Your attack speed is increased by 6%." }, { name = "Blades of Light", icon = "Interface\\Icons\\Ability_Whirlwind", text = "Reduces the cooldown of Whirlwind by 10 sec.\n\nBlades of light! The Scarlet Champion has spun that axe through a thousand challengers in the Armory." }, { name = "Ravager's Edge", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Increases the damage of Cleave by 15%.\n\nAh, I've been waiting for a real challenge! The Ravager bites deepest in its master's hands." } }, tips = { [261] = "Call the Armory's trainees: three Scarlet Trainees rush to fight at your side for 20 sec." }, visualKit = 154, soundTransform = 5830, soundDeath = 0, flies = false, wave = 2, instance = "Scarlet Monastery", expansion = 0, order = 103, summons = { [261] = true }, charModel = true, box = { -0.14, -0.01, 1.38 }, voices = { { 5830, 3.0, true, "Ah - I've been waiting for a real challenge!" }, { 5832, 1.5, true, "Blades of light!" }, { 5833, 2.0, true, "Light, give me strength!" }, { 5831, 1.5, true, "Is that all?" } }, title = "The Scarlet Champion" },
    { id = "mograine", entry = 3976, name = "Scarlet Commander Mograine", label = "Scarlet Commander Mograine", level = 40, display = 2042, height = 2.6, span = 2.6, school = "holy", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Holy_SealOfMight", profile = "tank", kit = { 14518, 37548, 13005, 32773, 13874, 17233 }, passives = { 8990 }, talentInfo = { { name = "Commander's Resolve", icon = "Interface\\Icons\\Ability_Warrior_ShieldWall", text = "Damage you take is reduced by 8%." }, { name = "Lightforged Plate", icon = "Interface\\Icons\\Spell_Holy_DevotionAura", text = "Your armor is increased by 20%." }, { name = "Righteous Presence", icon = "Interface\\Icons\\Spell_Holy_SealOfFury", text = "The threat you cause is increased by 30%." }, { name = "Crusader's Wrath", icon = "Interface\\Icons\\Spell_Holy_CrusaderStrike", text = "Your Holy damage is increased by 8%." }, { name = "Unworthy", icon = "Interface\\Icons\\Spell_Holy_SealOfMight", text = "When you are struck, you have a 10% chance to answer with a Crusader Strike. Once every 20 sec.\n\nUnworthy. The Commander's one-word answer to every blade that finds him." }, { name = "Infidels Must Be Purified", icon = "Interface\\Icons\\Spell_Holy_RighteousFury", text = "Crusader Strike deals 20% more damage.\n\nSworn to the Crusade and to his High Inquisitor, he strikes with a zealot's certainty." } }, tips = {}, visualKit = 154, soundTransform = 5835, soundDeath = 0, flies = false, wave = 2, instance = "Scarlet Monastery", expansion = 0, order = 106, charModel = true, box = { -0.13, -0.01, 1.28 }, voices = { { 5835, 3.8, true, "Infidels! They must be purified!" }, { 5836, 1.4, true, "Unworthy." }, { 5837, 1.7, true, "At your side, milady!" } }, title = "Commander of the Monastery" },
    { id = "thermaplugg", entry = 7800, name = "Mekgineer Thermaplugg", label = "Mekgineer Thermaplugg", level = 28, display = 6980, height = 4.9, span = 6.0, school = "fire", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Misc_Head_Gnome_01", profile = "caster", kit = { 22334, 10346, 10101, 11820, 10341, 3720 }, passives = {}, talentInfo = { { name = "MORE Explosions", icon = "Interface\\Icons\\INV_Misc_Bomb_05", text = "Your Fire damage is increased by 12%." }, { name = "Irradiated Genius", icon = "Interface\\Icons\\INV_Gizmo_02", text = "Your Intellect is increased by 6%." }, { name = "Mech Plating", icon = "Interface\\Icons\\INV_Gizmo_01", text = "Your armor is increased by 20%." }, { name = "Salvaged Blasting Powder", icon = "Interface\\Icons\\INV_Gizmo_FelIronBomb", text = "The cost of your Fire spells is reduced by 8%." }, { name = "Bigger Bombs", icon = "Interface\\Icons\\INV_Misc_Bomb_08", text = "Increases the radius of Bomb by 30%.\n\nExplosions! MORE explosions! Thermaplugg packs every bomb with twice the powder it needs." }, { name = "Security Protocol", icon = "Interface\\Icons\\Ability_Ensnare", text = "Your damaging abilities have a 15% chance to fire an Electrified Net at the target. Once every 15 sec.\n\nUsurpers! Gnomeregan's defences still answer to its self-styled king, and they net first." } }, tips = {}, visualKit = 286, soundTransform = 5807, soundDeath = 5810, flies = false, wave = 2, instance = "Gnomeregan", expansion = 0, order = 96, summons = { [3720] = true }, box = { 1.28, 0.19, 2.28 }, view = { -4.5109, 0.6656, 2.5300 }, voices = { { 5807, 3.6, true, "Usurpers! Gnomeregan is mine!" }, { 5808, 4.2, true, "My machines are the future! They'll destroy you all!" }, { 5809, 5.3, true, "Explosions! MORE explosions! I've got to have more explosions!" }, { 5810, 1.0, true, "And STAY dead!" } }, title = "Self-Styled King of Gnomeregan" },
    { id = "gahzrilla", entry = 7273, name = "Gahz'rilla", label = "Gahz'rilla", level = 46, display = 7271, height = 14.8, span = 25.8, school = "frost", pool = "classic_dungeon", icon = "Interface\\Icons\\Ability_Hunter_Pet_Crocolisk", profile = "bruiser", kit = { 11131, 11836, 11902, 16099 }, passives = {}, talentInfo = { { name = "Breath of the Sacred Pool", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "Hydra Scales", icon = "Interface\\Icons\\Ability_Hunter_Pet_Turtle", text = "Your armor is increased by 15%." }, { name = "Many-Headed Fury", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your attack speed is increased by 8%." }, { name = "Blood of Zul'Farrak", icon = "Interface\\Icons\\Spell_Nature_Regenerate", text = "Your maximum health is increased by 8%." }, { name = "Another Head Spits", icon = "Interface\\Icons\\Spell_Frost_IceShard", text = "Your melee attacks have an 8% chance to spit an Icicle at the target. Once every 10 sec.\n\nWhile one head bites, another is already taking aim." }, { name = "Weight of the Hydra", icon = "Interface\\Icons\\Spell_Nature_EarthQuake", text = "Increases the damage of Gahz'rilla Slam by 15%.\n\nWhen the demigod of the sacred pool comes down on the steps of Zul'Farrak, the whole court shakes." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Zul'Farrak", expansion = 0, order = 138, box = { -5.30, 1.75, 6.82 }, title = "Hydra Demigod" },
    { id = "theradras", entry = 12201, name = "Princess Theradras", label = "Princess Theradras", level = 48, display = 12292, height = 8.7, span = 8.7, school = "nature", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Nature_EarthQuake", profile = "tank", kit = { 21832, 37548, 21869, 21909, 5568, 22693 }, passives = {}, talentInfo = { { name = "Heart of Maraudon", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", text = "Your armor is increased by 25%." }, { name = "Weight of the Mountain", icon = "Interface\\Icons\\Spell_Nature_EarthBindTotem", text = "Your maximum health is increased by 10%." }, { name = "Wrath of Maraudon", icon = "Interface\\Icons\\Spell_Nature_Earthquake", text = "The threat you cause is increased by 30%." }, { name = "Stoneskin", icon = "Interface\\Icons\\Spell_Nature_StoneClawTotem", text = "Damage you take is reduced by 6%." }, { name = "The Earth Answers", icon = "Interface\\Icons\\Ability_ThunderClap", text = "Your melee attacks have a 10% chance to Trample every enemy around you. Once every 15 sec.\n\nEvery step the daughter of the earth takes is felt from Maraudon to the Valley of Spears." }, { name = "Daughter of the Earth", icon = "Interface\\Icons\\Spell_Nature_Cyclone", text = "Reduces the cooldown of Dust Field by 5 sec.\n\nThe ground of Maraudon remembers its princess and rises to shake again at her word." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Maraudon", expansion = 0, order = 128, box = { -1.06, -0.03, 4.36 }, title = "Mother of the Centaur" },
    { id = "thaurissan", entry = 9019, name = "Emperor Dagran Thaurissan", label = "Emperor Thaurissan", level = 56, display = 8807, height = 1.9, span = 1.9, school = "fire", pool = "classic_dungeon", icon = "Interface\\Icons\\Achievement_Boss_EmperorDagranThaurissan", profile = "caster", kit = { 17492, 12470, 15636, 9574, 261 }, passives = {}, talentInfo = { { name = "Hand of Ragnaros", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Your Fire damage is increased by 12%." }, { name = "Emperor's Majesty", icon = "Interface\\Icons\\INV_Crown_01", text = "Your Intellect is increased by 6%." }, { name = "Shadowforge Command", icon = "Interface\\Icons\\Spell_Fire_SealOfFire", text = "Your chance to critically strike with spells is increased by 4%." }, { name = "Royal Treasury", icon = "Interface\\Icons\\INV_Misc_Coin_02", text = "The cost of your Fire spells is reduced by 8%." }, { name = "Chosen of the Firelord", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Reduces the cooldown of Avatar of Flame by 10 sec.\n\nThe sorcerer-thane who called Ragnaros into this world never waits long for his master's fire." }, { name = "Molten Majesty", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "When you are struck, you have a 12% chance to erupt in a Fire Nova. Once every 15 sec.\n\nNone may lay hands on the Emperor of the Shadowforge throne and walk away unburnt." } }, tips = { [261] = "Guards! Two Anvilrage Guardsmen of the Shadowforge march to your side and fight for 20 sec." }, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Blackrock Depths", expansion = 0, order = 168, summons = { [261] = true }, charModel = true, box = { -0.12, -0.02, 0.95 }, title = "Emperor of Blackrock" },
    { id = "gordok", entry = 11501, name = "King Gordok", label = "King Gordok", level = 62, display = 11583, height = 8.0, span = 8.0, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\Ability_Warrior_Charge", profile = "bruiser", kit = { 22886, 15708, 15572, 16727, 261 }, passives = {}, talentInfo = { { name = "King of the Gordok", icon = "Interface\\Icons\\INV_Crown_02", text = "All damage you deal is increased by 5%." }, { name = "Ogre Brawn", icon = "Interface\\Icons\\Ability_Warrior_WarCry", text = "Your Strength is increased by 8%." }, { name = "Da King's Hard Head", icon = "Interface\\Icons\\Ability_Warrior_ShieldWall", text = "Damage you take is reduced by 6%." }, { name = "Tribute of Might", icon = "Interface\\Icons\\Ability_Warrior_BloodFrenzy", text = "Your attack power is increased by 8%." }, { name = "Da King Stomps", icon = "Interface\\Icons\\Ability_WarStomp", text = "Increases the damage of War Stomp by 15%.\n\nMe big king now. When me stomp, whole courtyard fall down!" }, { name = "Crusher of Scrubs", icon = "Interface\\Icons\\Ability_Warrior_Sunder", text = "Your melee attacks have a 12% chance to Sunder the target's armor. Once every 4 sec.\n\nEvery swing of da king's claymore leaves a dent. Scrubs is soft." } }, tips = { [261] = "Bellow for Cho'Rush the Observer, your ogre-mage advisor, who fights at your side for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Dire Maul", expansion = 0, order = 217, summons = { [261] = true }, box = { 0.04, -0.27, 3.97 }, title = "King of the Gordunni Ogres" },
    { id = "rend", entry = 10429, name = "Warchief Rend Blackhand", label = "Rend Blackhand", level = 62, display = 9778, height = 2.8, span = 2.8, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Misc_Head_Orc_01", profile = "bruiser", kit = { 261, 16856, 13736, 15284, 5164, 8269, 13049 }, passives = {}, talentInfo = { { name = "Blackhand's Legacy", icon = "Interface\\Icons\\Ability_Warrior_SavageBlow", text = "Your Physical damage is increased by 10%." }, { name = "Warchief's Command", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", text = "Your attack power is increased by 6%." }, { name = "Rider of the Black Drake", icon = "Interface\\Icons\\Ability_Mount_Drake_Proto", text = "Your movement speed is increased by 8%." }, { name = "Bloodlust of the Horde", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack speed is increased by 6%." }, { name = "Glaive of the Warchief", icon = "Interface\\Icons\\Ability_Whirlwind", text = "Reduces the cooldown of your Whirlwind by 15 sec.\n\nKnocked from Gyth's back, Rend does not stop swinging until the ring is clear." } }, tips = { [261] = "Call down a black drake of the Spire's rookery, kin of your mount Gyth, to fight at your side for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Blackrock Spire", expansion = 0, order = 187, summons = { [261] = true, [13049] = true }, charModel = true, box = { 0.01, -0.01, 1.41 }, title = "Warchief of the Dark Horde" },
    { id = "drakkisath", entry = 10363, name = "General Drakkisath", label = "General Drakkisath", level = 62, display = 10115, height = 9.8, span = 14.8, school = "fire", pool = "classic_dungeon", icon = "Interface\\Icons\\Achievement_Boss_GeneralDrakkisath", profile = "bruiser", kit = { 23023, 16419, 15548, 20691, 12097, 16789, 6487 }, passives = {}, talentInfo = { { name = "Flames of the Black Flight", icon = "Interface\\Icons\\Spell_Fire_Immolation", text = "Your Fire damage is increased by 10%." }, { name = "Dragonkin Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Your armor is increased by 15%." }, { name = "General of the Spire", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", text = "Your Strength is increased by 6%." }, { name = "Draconic Fury", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your chance to critically strike with melee attacks is increased by 4%." }, { name = "Pillar of the Black Flight", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "Increases the radius of Flamestrike by 30%.\n\nFrom the heights of the Spire, Drakkisath's fire falls on the whole hall at once." }, { name = "Nefarian's Chosen", icon = "Interface\\Icons\\Ability_Racial_BloodRage", text = "Reduces the cooldown of your Rage by 15 sec.\n\nThe Black Prince's general does not tire while his master watches." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Blackrock Spire", expansion = 0, order = 186, summons = { [6487] = true }, box = { -1.30, -1.14, 4.84 }, title = "Hand of Nefarian" },
    { id = "attumen", entry = 16152, name = "Attumen the Huntsman", label = "Attumen the Huntsman", level = 73, display = 16040, height = 5.1, span = 5.4, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Ability_Warrior_Cleave", profile = "bruiser", kit = { 29832, 29847, 29711, 29833, 261 }, passives = {}, talentInfo = { { name = "Spectral Cleave", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your Shadow damage is increased by 8%." }, { name = "Midnight's Gallop", icon = "Interface\\Icons\\Ability_Mount_Dreadsteed", text = "Your movement speed is increased by 10%." }, { name = "Huntsman's Eye", icon = "Interface\\Icons\\Ability_Hunter_SniperShot", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "I Kill for a Living", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "Midnight's Hooves", icon = "Interface\\Icons\\Ability_Warrior_Trauma", text = "Your melee attacks have an 8% chance to Shadow Cleave the target and its nearest allies. Once every 20 sec.\n\nMidnight fights as hard as her rider; now and then she rears and brings a victim down." }, { name = "The Hunt Begins", icon = "Interface\\Icons\\Ability_Warrior_Charge", text = "Reduces the cooldown of Charge by 5 sec.\n\nAmateurs! Do not think you can best me! I kill for a living." } }, tips = { [261] = "Come Midnight, let's disperse this petty rabble! Call two Spectral Chargers from the stables of Karazhan to trample your foes for 20 sec." }, visualKit = 7775, soundTransform = 0, soundDeath = 9165, flies = false, wave = 2, instance = "Karazhan", expansion = 1, order = 347, summons = { [261] = true }, box = { 0.61, -0.03, 2.54 }, voices = { { 9169, 2.5, true, "It was... inevitable." }, { 9300, 3.0, true, "Another trophy to add to my collection!" }, { 9170, 3.2, true, "Such easy sport." }, { 9304, 5.7, true, "Amateurs! Do not think you can best me! I kill for a living." }, { 9166, 4.5, true, "Weapons are merely a convenience for a warrior of my skill!" }, { 9165, 7.0, true, "Always knew... someday I would become... the hunted." } }, title = "Master of Midnight", visages = { "attumen_unmounted" }, shape = "Mounted" },
    { id = "moroes", entry = 15687, name = "Moroes", label = "Moroes", level = 73, display = 16540, height = 3.8, span = 3.8, school = "physical", pool = "tbc", icon = "Interface\\Icons\\Ability_Gouge", profile = "glass_cannon", kit = { 29425, 34694, 29448, 8818, 37023, 261 }, passives = {}, talentInfo = { { name = "Steward's Garrote", icon = "Interface\\Icons\\Ability_Rogue_Garrote", text = "Your Physical damage is increased by 8%." }, { name = "Never Enough Time", icon = "Interface\\Icons\\INV_Misc_PocketWatch_01", text = "Your attack speed is increased by 10%." }, { name = "Blinding Etiquette", icon = "Interface\\Icons\\Spell_Shadow_MindSteal", text = "Your chance to critically hit with melee attacks is increased by 6%." }, { name = "Nimble Carving Hands", icon = "Interface\\Icons\\Ability_Rogue_Eviscerate", text = "Your Agility is increased by 8%." }, { name = "How Terribly Clumsy", icon = "Interface\\Icons\\Ability_Rogue_Rupture", text = "Your melee attacks have a 10% chance to Garrote the target. Once every 20 sec.\n\nOh, I've gone and made a mess... Moroes's carving knife slips, always in the worst possible place." }, { name = "Now, Where Was I?", icon = "Interface\\Icons\\Ability_Vanish", text = "Reduces the cooldown of Vanish by 15 sec.\n\nNow, where was I? Oh, yes... The steward knows every servants' passage in the tower." } }, tips = { [261] = "One more for dinner this evening. Call Lady Catriona Von'Indi from the banquet hall to fight at your side for 20 sec." }, visualKit = 437, soundTransform = 9211, soundDeath = 9213, flies = false, wave = 2, instance = "Karazhan", expansion = 1, order = 349, summons = { [261] = true }, charModel = true, box = { -0.40, -0.11, 1.88 }, voices = { { 9211, 6.2, true, "Hm, unannounced visitors. Preparations must be made..." }, { 9215, 4.7, true, "Now, where was I? Oh, yes..." }, { 9316, 2.2, true, "You rang?" }, { 9214, 3.2, true, "One more for dinner this evening." }, { 9314, 3.7, true, "Time... never enough time." }, { 9315, 3.0, true, "Oh, I've gone and made a mess..." }, { 9213, 4.1, true, "How terribly clumsy of me." } }, title = "Tower Steward" },
    { id = "bigbadwolf", entry = 26829, name = "The Big Bad Wolf", label = "The Big Bad Wolf", level = 73, display = 26789, height = 3.5, span = 3.8, school = "physical", pool = "tbc", icon = "Interface\\Icons\\Ability_Hunter_Pet_Wolf", profile = "bruiser", kit = { 30752, 30761, 3604, 31041, 43317 }, passives = {}, talentInfo = { { name = "The Better to Eat You With", icon = "Interface\\Icons\\Ability_Hunter_Pet_Wolf", text = "Your chance to critically hit with melee attacks is increased by 6%." }, { name = "Insatiable Hunger", icon = "Interface\\Icons\\Ability_Racial_Cannibalize", text = "Your attack power is increased by 10%." }, { name = "Thick Wolf Pelt", icon = "Interface\\Icons\\INV_Misc_Pelt_Wolf_01", text = "Your armor is increased by 15%." }, { name = "After Little Red", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Your movement speed is increased by 12%." }, { name = "Mmmm... Delicious", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your melee attacks have a 10% chance to Mangle the target. Once every 15 sec.\n\nMmmm... delicious. Once the wolf has a taste, he keeps coming back for more." }, { name = "Huff and Puff", icon = "Interface\\Icons\\Spell_Shadow_DeathScream", text = "Reduces the cooldown of Terrifying Howl by 15 sec.\n\nThe Opera's wolf never learned a new song; he just howls the old one more often." } }, tips = {}, visualKit = 437, soundTransform = 9276, soundDeath = 0, flies = false, wave = 2, instance = "Karazhan", expansion = 1, order = 354, as = 17521, box = { 0.25, -0.25, 1.75 }, voices = { { 9276, 6.0, true, "The better to own you with!" }, { 9277, 5.5, true, "Mmmm... delicious." }, { 9278, 5.5, true, "Run away little girl, run away!" } }, title = "Worgen of the Opera House", visages = { "grandmother" }, shape = "Wolf" },
    { id = "curator", entry = 15691, name = "The Curator", label = "The Curator", level = 73, display = 16958, height = 14.3, span = 15.4, school = "arcane", pool = "tbc", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", profile = "caster", kit = { 30383, 30235, 10101, 52869, 261 }, passives = {}, talentInfo = { { name = "Hateful Arcana", icon = "Interface\\Icons\\Spell_Arcane_Blast", text = "Your Arcane damage is increased by 10%." }, { name = "Menagerie Plating", icon = "Interface\\Icons\\INV_Misc_Gear_01", text = "Your armor is increased by 20%." }, { name = "Arcane Conduits", icon = "Interface\\Icons\\Spell_Holy_MagicalSentry", text = "Your Arcane resistance is increased by 50." }, { name = "Gallery Protection", icon = "Interface\\Icons\\Spell_Holy_PowerWordShield", text = "Your maximum health is increased by 8%." }, { name = "You Are Not a Guest", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", text = "When you are struck, you have a 10% chance to discharge an Arcing Sear. Once every 20 sec.\n\nYou are not a guest. The Curator's conduits spark at anyone who strikes the exhibit." }, { name = "Evocation Protocol", icon = "Interface\\Icons\\Spell_Nature_Purge", text = "Reduces the cooldown of Evocation by 30 sec.\n\nThe golem was built to drain itself dry and refill on schedule; the schedule has only grown tighter." } }, tips = { [261] = "This Curator is equipped for gallery protection. Release two Astral Flares to hurl themselves at your foes for 20 sec." }, visualKit = 1005, soundTransform = 9183, soundDeath = 9184, flies = false, wave = 2, instance = "Karazhan", expansion = 1, order = 353, summons = { [261] = true }, box = { 2.37, -0.47, 7.16 }, voices = { { 9183, 3.1, true, "The Menagerie is for guests only." }, { 9188, 3.7, true, "Gallery rules will be strictly enforced." }, { 9309, 3.9, true, "This Curator is equipped for gallery protection." }, { 9186, 3.0, true, "Your request cannot be processed." }, { 9185, 4.6, true, "Failure to comply will result in offensive action." }, { 9187, 2.5, true, "Do not touch the displays." }, { 9308, 2.2, true, "You are not a guest." }, { 9184, 4.4, true, "Curator is no longer operation-a-l." } }, title = "Arcane Golem of Karazhan" },
    { id = "aran", entry = 16524, name = "Shade of Aran", label = "Shade of Aran", level = 73, display = 16621, height = 3.8, span = 3.8, school = "arcane", pool = "tbc", icon = "Interface\\Icons\\Spell_Fire_FlameBolt", profile = "caster", kit = { 29953, 29954, 29955, 8364, 29964, 29961, 29973, 30024, 29962 }, passives = {}, talentInfo = { { name = "Magus of Tirisfal", icon = "Interface\\Icons\\Spell_Nature_WispSplode", text = "Your Arcane damage is increased by 10%." }, { name = "I'll Freeze You All", icon = "Interface\\Icons\\Spell_Frost_IceStorm", text = "Your Frost damage is increased by 6%." }, { name = "Replenishing Drink", icon = "Interface\\Icons\\Spell_Frost_ManaRecharge", text = "The mana cost of your Arcane spells is reduced by 10%." }, { name = "A Shade's Resilience", icon = "Interface\\Icons\\Spell_Arcane_Blink", text = "Damage you take is reduced by 5%." }, { name = "Flame Wreath", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "When you are struck, you have a 10% chance to hurl a Fireball at the attacker. Once every 45 sec.\n\nAran's wreath of flame punished anyone who stepped wrong; the shade still burns whoever lays a hand on him." }, { name = "A Few More Tricks", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", text = "Reduces the cooldown of Ultimate Arcane Explosion by 30 sec.\n\nI'm not finished yet! No, I have a few more tricks up my sleeve..." } }, tips = {}, visualKit = 1005, soundTransform = 9241, soundDeath = 9244, flies = false, wave = 2, instance = "Karazhan", expansion = 1, order = 352, summons = { [29962] = true }, charModel = true, box = { -0.19, -0.01, 1.92 }, voices = { { 9241, 5.8, true, "Please, no more! My son... he's gone mad!" }, { 9323, 2.8, true, "I'll not be tortured again!" }, { 9324, 5.7, true, "Who are you? What do you want? Stay away from me!" }, { 9245, 5.3, true, "I'll show you: this beaten dog still has some teeth!" }, { 9326, 3.3, true, "Burn, you hellish fiends!" }, { 9246, 3.0, true, "I'll freeze you all!" }, { 9327, 2.6, true, "Back to the cold dark with you!" }, { 9242, 6.9, true, "Yes, yes my son is quite powerful... but I have powers of my own!" }, { 9325, 6.4, true, "I am not some simple jester! I am Nielas Aran!" }, { 9248, 7.3, true, "Surely you wouldn't deny an old man a replenishing drink? No, no, I thought not." }, { 9251, 7.5, false, "I'm not finished yet! No, I have a few more tricks up my sleeve..." }, { 9250, 3.4, true, "I want this nightmare to be over!" } }, title = "Father of Medivh" },
    { id = "nightbane", entry = 17225, name = "Nightbane", label = "Nightbane", level = 73, display = 18062, height = 21.2, span = 43.2, school = "fire", pool = "tbc", icon = "Interface\\Icons\\Spell_Fire_Fire", profile = "bruiser", kit = { 39263, 25653, 30131, 30128, 30130, 36922, 261 }, passives = {}, talentInfo = { { name = "Medivh's Undying Fire", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire damage is increased by 10%." }, { name = "Bones of Arcanagos", icon = "Interface\\Icons\\INV_Misc_Bone_ElfSkull_01", text = "Your armor is increased by 20%." }, { name = "Charred Hide", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Your Fire resistance is increased by 60." }, { name = "Talons of Arcanagos", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Swatting Tail", icon = "Interface\\Icons\\INV_Misc_MonsterTail_03", text = "When you are struck, you have a 10% chance to Tail Sweep the enemies behind you. Once every 20 sec.\n\nWhoever creeps up behind Nightbane learns what is left of Arcanagos's tail." }, { name = "Medivh's Burning", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Your Smoldering Breath deals 15% more damage.\n\nThe fire Medivh poured into Arcanagos never went out; it smoulders in every breath the bones still take." } }, tips = { [261] = "Bombard the ground with bone fragments that pull themselves together into three Restless Skeletons, fighting for you for 20 sec." }, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = true, wave = 2, instance = "Karazhan", expansion = 1, order = 350, summons = { [261] = true }, box = { -6.53, 0.05, 10.01 }, title = "Once the Blue Dragon Arcanagos" },
    { id = "magtheridon", entry = 17257, name = "Magtheridon", label = "Magtheridon", level = 73, display = 18527, height = 23.3, span = 39.6, school = "fire", pool = "tbc", icon = "Interface\\Icons\\Achievement_Boss_Magtheridon", profile = "tank", kit = { 30616, 30619, 63821, 37548, 33707, 261 }, passives = {}, talentInfo = { { name = "Hide of the Pit Lord", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 20%." }, { name = "Blood of Magtheridon", icon = "Interface\\Icons\\Spell_Shadow_BloodBoil", text = "Your maximum health is increased by 10%." }, { name = "Lord of Outland", icon = "Interface\\Icons\\Ability_Warrior_InnerRage", text = "The threat you cause is increased by 30%." }, { name = "Blast Nova", icon = "Interface\\Icons\\Spell_Fire_SealOfFire", text = "Your Fire damage is increased by 8%." }, { name = "The Cubes Shatter", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "When you are struck, you have an 8% chance to bring Falling Rubble down around you. Once every 30 sec.\n\nEvery blow Magtheridon takes shakes the Citadel's ceiling a little looser." }, { name = "Unbroken by the Cubes", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Reduces the cooldown of Blast Nova by 15 sec.\n\nWithout the channelers' cubes to hold him, the pit lord's novas come far more often." } }, tips = { [261] = "Call a Burning Abyssal out of Hellfire Citadel's pit to fight for you for 20 sec." }, visualKit = 286, soundTransform = 0, soundDeath = 10258, flies = false, wave = 2, instance = "Magtheridon's Lair", expansion = 1, order = 397, summons = { [261] = true }, box = { -13.00, 0.32, 11.38 }, voices = { { 10247, 9.0, true, "Wretched, meddling insects! Release me, and perhaps I will grant you a merciful death!" }, { 10248, 6.2, true, "Vermin! Leeches! Take my blood and choke on it!" }, { 10249, 7.9, true, "Illidan is an arrogant fool! I will crush him and reclaim Outland as my own!" }, { 10250, 7.0, true, "Away, you mindless parasites! My blood is my own!" }, { 10251, 7.4, true, "How long do you believe your pathetic sorcery can hold me?" }, { 10252, 4.4, true, "My blood will be the end of you!" }, { 10253, 7.2, true, "I... am... unleashed!" }, { 10255, 6.1, true, "Did you think me weak? Soft? Who is the weak one now?" }, { 10256, 5.0, true, "Not again! Not again..." }, { 10257, 9.5, true, "I will not be taken so easily! Let the walls of this prison tremble... and fall!" }, { 10258, 5.7, true, "The Legion will consume you all!" } }, title = "Lord of Outland" },
    { id = "doomwalker", entry = 17711, name = "Doomwalker", label = "Doomwalker", level = 73, display = 21435, height = 32.2, span = 32.2, school = "nature", pool = "tbc", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Bronze", profile = "tank", kit = { 33665, 39050, 32636, 33661, 52022, 37548 }, passives = {}, talentInfo = { { name = "Titanic War Plating", icon = "Interface\\Icons\\INV_Chest_Plate16", text = "Your armor is increased by 25%." }, { name = "Lightning Wrath", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", text = "Your Nature damage is increased by 8%." }, { name = "Threat Level Zero", icon = "Interface\\Icons\\Ability_Warrior_Defensivestance", text = "The threat you cause is increased by 30%." }, { name = "Directive: Endure", icon = "Interface\\Icons\\Spell_Holy_Devotion", text = "Your maximum health is increased by 10%." }, { name = "Trajectory Locked", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "When you are struck, you have a 10% chance to answer with Lightning Wrath. Once every 20 sec.\n\nTrajectory locked. Whatever strikes Doomwalker is marked, measured and answered with lightning." }, { name = "Magnitude Set", icon = "Interface\\Icons\\Spell_Nature_Earthquake", text = "Reduces the cooldown of Earthquake by 8 sec.\n\nMagnitude set. Release. The fel reaver's quake engines recharge faster with every tremor." } }, tips = {}, visualKit = 282, soundTransform = 11344, soundDeath = 11352, flies = false, wave = 2, zone = "Shadowmoon Valley", expansion = 1, order = 342, box = { -3.27, -0.00, 16.05 }, voices = { { 11344, 4.7, true, "Do not proceed. You will be eliminated." }, { 11345, 3.1, true, "Tectonic disruption commencing." }, { 11346, 3.2, true, "Magnitude set. Release." }, { 11347, 1.8, true, "Trajectory locked." }, { 11348, 2.7, true, "Engage maximum speed." }, { 11349, 2.4, true, "Threat level zero." }, { 11350, 2.2, true, "Directive accomplished." }, { 11351, 2.2, true, "Target exterminated." }, { 11352, 5.1, true, "System failure in five, f-o-u-r..." } }, title = "Fel Reaver of Kil'jaeden" },
    { id = "steamrigger", entry = 25794, name = "Mekgineer Steamrigger", label = "Mekgineer Steamrigger", level = 72, display = 23383, height = 7.4, span = 9.1, school = "physical", pool = "tbc", icon = "Interface\\Icons\\INV_Misc_Head_Gnome_01", profile = "caster", kit = { 31486, 31485, 35107, 11983, 261 }, passives = {}, talentInfo = { { name = "Sharpened Saw Blades", icon = "Interface\\Icons\\INV_Misc_Gear_01", text = "Your Physical damage is increased by 8%." }, { name = "Steam-Powered Rig", icon = "Interface\\Icons\\Trade_Engineering", text = "Your casting speed is increased by 8%." }, { name = "Riveted Plating", icon = "Interface\\Icons\\INV_Misc_Wrench_01", text = "Your armor is increased by 15%." }, { name = "Electrified Netting", icon = "Interface\\Icons\\Spell_Nature_LightningShield", text = "Your Nature damage is increased by 6%." }, { name = "You Just Got Served", icon = "Interface\\Icons\\INV_Misc_Gear_08", text = "When you are struck, you have a 10% chance to fling a Saw Blade back. Once every 15 sec.\n\nYou just got served, punk! The pounder's blade launchers fire on anything that dents the paint." }, { name = "Extra Wiring", icon = "Interface\\Icons\\Ability_Ensnare", text = "Your Electrified Net lasts 2 sec longer.\n\nSteamrigger wires every net twice. You never know when a cupcake will try to wriggle out." } }, tips = { [31485] = "Fire the Super Shrink Ray at the enemies before you, shrinking them and cutting their damage by 35% for 15 sec.", [261] = "Mommy! Call two Steamrigger Mechanics down from the gantries to fight for you for 20 sec." }, visualKit = 437, soundTransform = 10368, soundDeath = 10375, flies = false, wave = 2, instance = "Coilfang: The Steamvault", expansion = 1, order = 364, as = 17796, summons = { [261] = true }, box = { 1.92, 0.29, 3.42 }, voices = { { 10367, 2.0, true, "I'm bringin' the pain!" }, { 10368, 2.2, true, "You're in for a world o' hurt!" }, { 10369, 2.0, true, "Eat hot metal, scumbag!" }, { 10370, 1.6, true, "I'll come over there!" }, { 10372, 2.1, true, "You just got served, punk!" }, { 10373, 1.1, true, "I own you!" }, { 10374, 1.9, true, "Have fun dyin', cupcake!" }, { 10375, 0.6, true, "Mommy!" } }, title = "Technician of the Steamvault" },
    { id = "hydross", entry = 21216, name = "Hydross the Unstable", label = "Hydross the Unstable", level = 73, display = 20162, height = 13.4, span = 16.8, school = "frost", pool = "tbc", icon = "Interface\\Icons\\Spell_Frost_ManaRecharge", profile = "caster", kit = { 38235, 54237, 38215, 261 }, passives = {}, talentInfo = { { name = "Waters of Purity", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "Unstable Waters", icon = "Interface\\Icons\\Spell_Frost_FrostWard", text = "Your Frost resistance is increased by 60." }, { name = "Flowing Form", icon = "Interface\\Icons\\Spell_Frost_Wisp", text = "Damage you take is reduced by 5%." }, { name = "Purified Mana", icon = "Interface\\Icons\\Spell_Frost_ManaRecharge", text = "The mana cost of your Frost spells is reduced by 8%." }, { name = "I Will Purge You", icon = "Interface\\Icons\\Spell_Frost_SummonWaterElemental", text = "Your damaging spells have a 10% chance to loose a Water Blast at the target. Once every 20 sec.\n\nI will purge you from this place! Every wave Hydross throws carries another behind it." }, { name = "Deeper Tomb", icon = "Interface\\Icons\\Spell_Frost_Glacier", text = "Your Water Tomb deals 15% more damage.\n\nThe Duke of Currents presses the water tighter around whoever he entombs." } }, tips = { [261] = "Better, much better. Split off two Pure Spawn of Hydross to fight for you for 20 sec." }, visualKit = 4991, soundTransform = 11289, soundDeath = 11293, flies = false, wave = 2, instance = "Coilfang: Serpentshrine Cavern", expansion = 1, order = 372, summons = { [261] = true }, box = { 0.02, 0.01, 8.52 }, voices = { { 11289, 3.5, true, "I cannot allow you to interfere!" }, { 11290, 4.6, true, "Better, much better." }, { 11291, 3.0, true, "They have forced me to this...." }, { 11292, 2.6, true, "I had no choice." }, { 11293, 4.4, true, "I am... released." } }, title = "Duke of Currents", visages = { "hydross_corrupt" }, shape = "Pure" },
    { id = "lurker", entry = 21217, name = "The Lurker Below", label = "The Lurker Below", level = 73, display = 20216, height = 86.2, span = 86.2, school = "frost", pool = "tbc", icon = "Interface\\Icons\\Spell_Ice_MagicDamage", profile = "caster", kit = { 37138, 37478, 37660, 30930, 29309, 261 }, passives = {}, talentInfo = { { name = "Scalding Geyser", icon = "Interface\\Icons\\Spell_Frost_SummonWaterElemental", text = "Your Frost damage is increased by 10%." }, { name = "Deep-Water Hide", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Your armor is increased by 20%." }, { name = "Leviathan's Bulk", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 8%." }, { name = "Cold of the Depths", icon = "Interface\\Icons\\Spell_Frost_FrostWard", text = "Your Frost resistance is increased by 50." }, { name = "Thrashing Tentacles", icon = "Interface\\Icons\\Spell_Frost_Wisp", text = "When you are struck, you have a 10% chance to Whirl. Once every 20 sec.\n\nFishing for the Lurker is easy. Surviving what bites is not." }, { name = "Long Breath", icon = "Interface\\Icons\\Spell_Shaman_TidalWaves", text = "Reduces the cooldown of Spout by 10 sec.\n\nThe Lurker surfaces, draws one long breath, and sweeps the whole pool with it." } }, tips = { [30930] = "Spout a torrent of freezing water over the enemies before you for 64 Frost damage.", [29309] = "Sink beneath the water for 3 sec: nothing can reach you, and you can do nothing.", [261] = "Sink below the surface and call two Coilfang Ambushers to fight for you for 20 sec." }, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Coilfang: Serpentshrine Cavern", expansion = 1, order = 377, summons = { [261] = true }, box = { -6.12, -0.16, -17.99 }, title = "Kraken of Serpentshrine Cavern" },
    { id = "leotheras", entry = 21215, name = "Leotheras the Blind", label = "Leotheras the Blind", level = 73, display = 20514, height = 6.7, span = 6.7, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Ability_Whirlwind", profile = "bruiser", kit = { 37640, 39135, 37683, 37511, 261 }, passives = {}, talentInfo = { { name = "Whirling Steel", icon = "Interface\\Icons\\Ability_Whirlwind", text = "Your attack speed is increased by 10%." }, { name = "Sightless Precision", icon = "Interface\\Icons\\Ability_Rogue_Eviscerate", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Blind Instinct", icon = "Interface\\Icons\\Spell_Shadow_DemonicTactics", text = "Your chance to dodge is increased by 5%." }, { name = "Twin Glaives of Leotheras", icon = "Interface\\Icons\\Ability_Rogue_DualWeild", text = "Your Agility is increased by 8%." }, { name = "Finally, My Banishment Ends", icon = "Interface\\Icons\\Ability_Warrior_Riposte", text = "Your melee attacks have a 10% chance to add a Debilitating Strike. Once every 15 sec.\n\nLeotheras fights blind; he does not need to see a gap to find it." }, { name = "The Whirlwind Returns", icon = "Interface\\Icons\\Ability_Warrior_Bladestorm", text = "Reduces the cooldown of Whirlwind by 8 sec.\n\nThe elf's steel barely stops spinning before it starts again." } }, tips = { [261] = "We all have our demons... Let your inner demon step out as the Shadow of Leotheras and fight for you for 20 sec." }, visualKit = 7775, soundTransform = 11312, soundDeath = 11317, flies = false, wave = 2, instance = "Coilfang: Serpentshrine Cavern", expansion = 1, order = 374, summons = { [261] = true }, charModel = true, box = { -0.40, -0.06, 3.34 }, voices = { { 11312, 4.9, true, "Finally, my banishment ends!" }, { 11314, 3.3, true, "Kill, kill!" }, { 11315, 4.0, true, "That's right, yes!" }, { 11316, 2.9, true, "Who's the master now?" }, { 11313, 11.8, true, "No... no! What have you done? I am the master! Do you hear me? I am... aaggh! Can't... contain him." }, { 11317, 10.3, true, "You cannot kill me, fools! I'll be back, I'll...." } }, title = "Blood Elf Demon Hunter", visages = { "leotheras_demon" }, shape = "Blood elf" },
    { id = "voidreaver", entry = 19516, name = "Void Reaver", label = "Void Reaver", level = 73, display = 18951, height = 32.2, span = 32.2, school = "arcane", pool = "tbc", icon = "Interface\\Icons\\Ability_ThunderClap", profile = "tank", kit = { 34162, 34172, 25778, 37548, 55019 }, passives = {}, talentInfo = { { name = "Fel Reaver Plating", icon = "Interface\\Icons\\INV_Gizmo_02", text = "Your armor is increased by 25%." }, { name = "Arcane Orb Targeting", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", text = "Your Arcane damage is increased by 8%." }, { name = "Marked for Extermination", icon = "Interface\\Icons\\Ability_Warrior_Challange", text = "The threat you cause is increased by 30%." }, { name = "Reinforced Frame", icon = "Interface\\Icons\\INV_Misc_Gear_01", text = "Your maximum health is increased by 10%." }, { name = "Targets Acquired", icon = "Interface\\Icons\\Spell_Arcane_Blast", text = "When you are struck, you have a 10% chance to launch an Arcane Orb. Once every 15 sec.\n\nAlert. The Tempest Keep's guardian answers every hit with a targeting solution." }, { name = "Overclocked Pistons", icon = "Interface\\Icons\\Ability_GolemThunderClap", text = "Reduces the cooldown of Pounding by 5 sec.\n\nVoid Reaver's pistons were built for sieges; they cycle faster the hotter they run." } }, tips = {}, visualKit = 1005, soundTransform = 11213, soundDeath = 11214, flies = false, wave = 2, instance = "Tempest Keep", expansion = 1, order = 402, box = { -3.27, -0.00, 16.05 }, voices = { { 11213, 4.8, true, "Alert! You are marked for extermination." }, { 11215, 4.0, true, "Extermination successful." }, { 11216, 4.3, true, "Invasive lifeform no longer functional." }, { 11217, 2.5, true, "Threat neutralized." }, { 11214, 5.6, true, "Systems... shutting... d-o-w-n..." }, { 11218, 2.9, true, "Alternative measure commencing..." }, { 11219, 3.2, true, "Calculating force parameters..." } }, title = "Guardian of the Eye" },
    { id = "solarian", entry = 18805, name = "High Astromancer Solarian", label = "High Astromancer Solarian", level = 73, display = 18239, height = 8.1, span = 8.1, school = "arcane", pool = "tbc", icon = "Interface\\Icons\\Spell_Nature_StarFall", profile = "caster", kit = { 33031, 33045, 33009, 34322, 261 }, passives = {}, talentInfo = { { name = "Wrath of the Astromancer", icon = "Interface\\Icons\\Spell_Arcane_StarFire", text = "Your Arcane damage is increased by 10%." }, { name = "Astromancer's Focus", icon = "Interface\\Icons\\Spell_Nature_StarFall", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Solarium Wardings", icon = "Interface\\Icons\\Spell_Holy_PowerWordShield", text = "Damage you take is reduced by 5%." }, { name = "Starlit Channeling", icon = "Interface\\Icons\\Spell_Arcane_ManaTap", text = "The mana cost of your Arcane spells is reduced by 8%." }, { name = "Tal anu'men no sin'dorei", icon = "Interface\\Icons\\Spell_Arcane_Arcane02", text = "Your damaging spells have a 10% chance to lay Wrath of the Astromancer. Once every 20 sec.\n\nThe astromancer reads a fate in the stars for every target, and none of them end well." }, { name = "Split the Heavens", icon = "Interface\\Icons\\Spell_Holy_SearingLight", text = "Reduces the cooldown of Blinding Light by 5 sec.\n\nSolarian draws starlight down into the Solarium faster than eyes can adjust." } }, tips = { [33045] = "Lay the wrath of the astromancer on an enemy, dealing 500 Arcane damage every 2 sec for 8 sec.", [261] = "Call two Solarium Agents through a split in the stars to fight for you for 20 sec." }, visualKit = 1005, soundTransform = 11134, soundDeath = 11135, flies = false, wave = 2, instance = "Tempest Keep", expansion = 1, order = 400, summons = { [261] = true }, charModel = true, box = { -0.30, -0.12, 4.03 }, voices = { { 11134, 3.9, true, "Tal anu'men no sin'dorei!" }, { 11139, 4.1, true, "You are hopelessly outmatched!" }, { 11140, 4.3, true, "I will crush your delusions of grandeur!" }, { 11136, 3.5, true, "Your soul belongs to the abyss!" }, { 11137, 3.2, true, "By the blood of the Highborne!" }, { 11138, 2.6, true, "For the Sunwell!" }, { 11135, 4.0, true, "The warmth of the sun... awaits." } }, title = "Astromancer of the Sunfury", visages = { "solarian_void" }, shape = "Blood elf" },
    { id = "najentus", entry = 22887, name = "High Warlord Naj'entus", label = "High Warlord Naj'entus", level = 73, display = 21174, height = 27.6, span = 27.6, school = "frost", pool = "tbc", icon = "Interface\\Icons\\Spell_Frost_IceShard", profile = "bruiser", kit = { 39837, 39835, 39836, 39872, 39878 }, passives = {}, talentInfo = { { name = "Serrated Spines", icon = "Interface\\Icons\\Ability_Warrior_SavageBlow", text = "Your attack power is increased by 10%." }, { name = "Warlord's Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Your armor is increased by 15%." }, { name = "Crashing Tides", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 8%." }, { name = "Blood Will Flow", icon = "Interface\\Icons\\Ability_Warrior_BloodFrenzy", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Needle Spines", icon = "Interface\\Icons\\INV_Weapon_ShortBlade_14", text = "When you are struck, you have a 10% chance to fire a Needle Spine back. Once every 15 sec.\n\nNaj'entus bristles; whoever strikes him catches a spine for the trouble." }, { name = "In the Name of Lady Vashj", icon = "Interface\\Icons\\Spell_Frost_FrostArmor02", text = "Your Tidal Burst deals 15% more damage.\n\nYou will die in the name of Lady Vashj! The warlord's shield bursts harder the longer it held." } }, tips = {}, visualKit = 4991, soundTransform = 11450, soundDeath = 11459, flies = false, wave = 2, instance = "Black Temple", expansion = 1, order = 384, box = { -3.69, -0.32, 12.64 }, voices = { { 11450, 5.7, true, "You will die in the name of Lady Vashj!" }, { 11451, 3.4, true, "Stick around..." }, { 11452, 3.5, true, "I'll deal with you later." }, { 11455, 5.1, true, "Your success was short-lived!" }, { 11456, 4.1, true, "Time for you to go." }, { 11453, 4.0, true, "Be'lanen dalorai!" }, { 11454, 4.3, true, "Blood... will... flow!" }, { 11457, 4.5, true, "Bal, lamer zhita!" }, { 11458, 6.1, true, "My patience has run out! Die! Die!" }, { 11459, 5.6, true, "Lord Illidan will... crush you!" } }, title = "Champion of Lady Vashj" },
    { id = "supremus", entry = 22898, name = "Supremus", label = "Supremus", level = 73, display = 21145, height = 66.4, span = 82.1, school = "fire", pool = "tbc", icon = "Interface\\Icons\\Trade_Engineering", profile = "tank", kit = { 41926, 41272, 42055, 40253, 37548 }, passives = {}, talentInfo = { { name = "Molten Punch", icon = "Interface\\Icons\\Spell_Fire_Volcano", text = "Your Fire damage is increased by 8%." }, { name = "Abyssal Hide", icon = "Interface\\Icons\\Spell_Shadow_SummonInfernal", text = "Your armor is increased by 25%." }, { name = "Acquires a New Target", icon = "Interface\\Icons\\Ability_Warrior_Challange", text = "The threat you cause is increased by 30%." }, { name = "Colossal Frame", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Molten Wake", icon = "Interface\\Icons\\Spell_Fire_LavaSpawn", text = "When you are struck, you have an 8% chance to trail Molten Flame. Once every 30 sec.\n\nSupremus leaks magma when he is hit; the floor of the Black Temple still bears the scars." }, { name = "Unstoppable Charge", icon = "Interface\\Icons\\Ability_Warrior_Charge", text = "Reduces the cooldown of Behemoth Charge by 5 sec.\n\nNothing slows the abyssal once it has chosen a new target." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Black Temple", expansion = 1, order = 390, box = { -4.04, -0.50, 34.08 }, title = "Abyssal of the Black Temple" },
    { id = "teron", entry = 22871, name = "Teron Gorefiend", label = "Teron Gorefiend", level = 73, display = 21254, height = 5.9, span = 5.9, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Spell_Fire_Burnout", profile = "caster", kit = { 40239, 40157, 40876, 40243, 261 }, passives = {}, talentInfo = { { name = "Vengeance Is Mine", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Your Fire damage is increased by 8%." }, { name = "Shadow of Death", icon = "Interface\\Icons\\Spell_Shadow_DeathCoil", text = "Your Shadow damage is increased by 10%." }, { name = "Turning of the Wheel", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", text = "Damage you take is reduced by 6%." }, { name = "First of the Death Knights", icon = "Interface\\Icons\\Spell_Shadow_AnimateDead", text = "Your maximum health is increased by 8%." }, { name = "The Wheel Spins Again", icon = "Interface\\Icons\\Spell_Fire_Immolation", text = "Your damaging spells have a 10% chance to add an Incinerate. Once every 15 sec.\n\nFor me the wheel of death has spun many times. Teron's fire always comes around once more." }, { name = "Give In", icon = "Interface\\Icons\\Spell_Shadow_Requiem", text = "Reduces the cooldown of Spirit Lance by 3 sec.\n\nGive in. The first death knight throws spirit faster than the living can dodge it." } }, tips = { [261] = "Death really isn't so bad. Raise two Shadowy Constructs to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 11513, soundDeath = 11521, flies = false, wave = 2, instance = "Black Temple", expansion = 1, order = 391, summons = { [261] = true }, charModel = true, box = { 0.02, -0.03, 2.94 }, voices = { { 11512, 21.1, true, "I was the first you know. For me the wheel of death has spun many times. So much time has passed... I have a lot of catching up to do." }, { 11513, 4.4, true, "Vengeance is mine!" }, { 11514, 5.1, true, "I have use for you..." }, { 11515, 3.7, true, "It gets worse." }, { 11517, 4.4, true, "What are you afraid of?" }, { 11520, 4.6, true, "You will show the proper respect!" }, { 11516, 7.2, true, "Death really isn't so bad." }, { 11519, 5.0, true, "I have something for you..." }, { 11518, 2.6, true, "Give in." }, { 11521, 7.5, true, "The wheel... spins... again." } }, title = "First of the Horde's Death Knights" },
    { id = "gurtogg", entry = 22948, name = "Gurtogg Bloodboil", label = "Gurtogg Bloodboil", level = 73, display = 21443, height = 12.9, span = 17.0, school = "nature", pool = "tbc", icon = "Interface\\Icons\\Ability_Warrior_Cleave", profile = "tank", kit = { 40457, 42005, 40508, 40491, 40602, 40486, 37548 }, passives = {}, talentInfo = { { name = "Bloodboil", icon = "Interface\\Icons\\Spell_Shadow_BloodBoil", text = "Your Physical damage is increased by 8%." }, { name = "Fel-Fed Vigor", icon = "Interface\\Icons\\Spell_Fire_FelFire", text = "Your maximum health is increased by 12%." }, { name = "Time to Feast", icon = "Interface\\Icons\\Ability_Racial_Cannibalize", text = "The threat you cause is increased by 30%." }, { name = "Fel Orc Hide", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 20%." }, { name = "Acidic Wound", icon = "Interface\\Icons\\Spell_Nature_Acid_01", text = "Your melee attacks have a 10% chance to breathe Fel-Acid Breath. Once every 20 sec.\n\nI hunger. Gurtogg's wounds weep acid, and so does his breath." }, { name = "Horde Will Crush You", icon = "Interface\\Icons\\Spell_DeathKnight_BloodBoil", text = "Your Bloodboil deals 15% more damage.\n\nHorde will... crush you. The Bonechewer's rage makes every boil run hotter." } }, tips = {}, visualKit = 282, soundTransform = 11432, soundDeath = 11439, flies = false, wave = 2, instance = "Black Temple", expansion = 1, order = 382, box = { 1.64, -0.41, 6.47 }, voices = { { 11432, 5.1, true, "Horde will... crush you." }, { 11433, 3.3, true, "Time to feast." }, { 11434, 5.8, true, "More! I want more!" }, { 11435, 7.1, true, "Drink your blood. Eat your flesh." }, { 11436, 3.3, true, "I hunger." }, { 11438, 7.3, true, "I'll rip the meat from your bones!" }, { 11439, 5.6, true, "Aaaahrg..." } }, title = "Dire Orc of the Bonechewer Clan" },
    { id = "shahraz", entry = 22947, name = "Mother Shahraz", label = "Mother Shahraz", level = 73, display = 21252, height = 15.2, span = 15.9, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\INV-Sword_53", profile = "glass_cannon", kit = { 40810, 40827, 40859, 40823, 52634 }, passives = {}, talentInfo = { { name = "Six Blades of the Mother", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "All damage you deal is increased by 6%." }, { name = "Fatal Attraction", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordDominate", text = "Your Shadow damage is increased by 8%." }, { name = "Prismatic Aura", icon = "Interface\\Icons\\Spell_Arcane_PrismaticCloak", text = "Damage you take is reduced by 6%." }, { name = "Shivarra Grace", icon = "Interface\\Icons\\Spell_Shadow_Possession", text = "Your casting speed is increased by 8%." }, { name = "Business or Pleasure", icon = "Interface\\Icons\\Spell_Shadow_SiphonMana", text = "Your damaging spells have a 10% chance to add a Sinful Beam. Once every 15 sec.\n\nSo... business or pleasure? With the Mother, one beam always leads to another." }, { name = "Easy Come, Easy Go", icon = "Interface\\Icons\\Spell_Shadow_ImpPhaseShift", text = "Reduces the cooldown of Silencing Shriek by 10 sec.\n\nEasy come, easy go. Shahraz shrieks whenever the room grows too loud for her liking." } }, tips = {}, visualKit = 7775, soundTransform = 11504, soundDeath = 11511, flies = false, wave = 2, instance = "Black Temple", expansion = 1, order = 388, box = { 1.45, 0.16, 7.56 }, voices = { { 11501, 3.5, true, "You play, you pay." }, { 11502, 2.5, true, "I'm not impressed." }, { 11503, 2.6, true, "Enjoying yourselves?" }, { 11504, 5.7, true, "So... business or pleasure?" }, { 11505, 3.0, true, "You seem a little tense..." }, { 11506, 2.7, true, "Don't be shy." }, { 11507, 3.6, true, "I'm all... yours." }, { 11508, 4.0, true, "Easy come, easy go." }, { 11509, 3.6, true, "So much for a happy ending." }, { 11510, 3.6, true, "Stop toying with my emotions!" }, { 11511, 3.7, true, "I wasn't finished." } }, title = "Shivarra of the Black Temple" },
    { id = "archimonde", entry = 17968, name = "Archimonde", label = "Archimonde", level = 73, display = 20939, height = 31.9, span = 31.9, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Achievement_Boss_Archimonde", profile = "caster", kit = { 42023, 31984, 31972, 32014, 31970, 32053 }, passives = {}, talentInfo = { { name = "Doomfire", icon = "Interface\\Icons\\Spell_Fire_FelFlameRing", text = "Your Fire damage is increased by 10%." }, { name = "Finger of Death", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 8%." }, { name = "Might of the Eredar", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_3", text = "Your Intellect is increased by 8%." }, { name = "Lord of the Legion", icon = "Interface\\Icons\\Spell_Shadow_DemonicTactics", text = "Damage you take is reduced by 8%." }, { name = "Your Resistance Is Insignificant", icon = "Interface\\Icons\\Spell_Nature_Cyclone", text = "When you are struck, you have an 8% chance to lay Grip of the Legion on the attacker. Once every 45 sec.\n\nThose who crowd the Defiler feel the Legion's fist close around them." }, { name = "I Am the Coming of the End", icon = "Interface\\Icons\\Spell_Shadow_DeathCoil", text = "Reduces the cooldown of Finger of Death by 10 sec.\n\nAll creation will be devoured. Archimonde points, and the end arrives sooner." } }, tips = {}, visualKit = 7775, soundTransform = 10987, soundDeath = 10992, flies = false, wave = 2, instance = "The Battle for Mount Hyjal", expansion = 1, order = 360, box = { -2.76, -0.75, 15.98 }, voices = { { 10987, 4.8, true, "Your resistance is insignificant." }, { 10990, 4.2, true, "This world will burn!" }, { 11041, 3.3, true, "Manach sheek-thrish!" }, { 10989, 2.0, true, "Away, vermin!" }, { 11044, 3.7, true, "All creation will be devoured." }, { 10991, 4.8, true, "Your soul will languish for eternity." }, { 11045, 3.4, true, "I am the coming of the end!" }, { 10993, 12.0, true, "At last it is here! Mourn and lament the passing of all you have ever known, and all that would have been! Hach min corai!" }, { 10992, 7.7, true, "No, it cannot be! Nooo!" }, { 10988, 3.7, true, "You are mine now." }, { 11042, 3.8, true, "Bow to my will." }, { 10986, 14.9, true, "All of your efforts have been in vain, for the draining of the World Tree has already begun! Soon the heart of your world will beat no more!" } }, title = "The Defiler" },
    { id = "malacrass", entry = 24239, name = "Hex Lord Malacrass", label = "Hex Lord Malacrass", level = 73, display = 22332, height = 8.5, span = 8.5, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", profile = "caster", kit = { 43383, 35195, 41374, 41375, 41383, 43426, 43429, 43421 }, passives = {}, talentInfo = { { name = "Spirit Bolts", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 10%." }, { name = "Drained Souls", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Your healing is increased by 10%." }, { name = "Stolen Wards", icon = "Interface\\Icons\\Spell_Holy_PowerWordShield", text = "Damage you take is reduced by 5%." }, { name = "Amani Voodoo", icon = "Interface\\Icons\\Spell_Shaman_Hex", text = "Your casting speed is increased by 6%." }, { name = "Your Will Belongs to Me", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "Your damaging spells have an 8% chance to add a Mind Blast. Once every 20 sec.\n\nYour will belong to me now. Malacrass keeps a little of every mind he has emptied." }, { name = "Da Spirits Gonna Feast", icon = "Interface\\Icons\\Spell_Shadow_Haunting", text = "Your Spirit Bolts last 3 sec longer.\n\nDa spirits gonna feast today! The Hex Lord lets the barrage run as long as they're hungry." } }, tips = { [43421] = "Lay a stolen lifebloom on yourself, healing 4713 every 1 sec for 7 sec." }, visualKit = 7775, soundTransform = 12041, soundDeath = 12051, flies = false, wave = 2, instance = "Zul'Aman", expansion = 1, order = 411, charModel = true, box = { -0.12, 0.10, 4.11 }, voices = { { 12041, 4.7, true, "Da shadow gonna fall on you...." }, { 12043, 4.4, true, "Dis a nightmare ya don' wake up from!" }, { 12044, 3.4, true, "Azzaga choogo zinn!" }, { 12046, 3.8, true, "Darkness comin' for you...." }, { 12047, 4.2, true, "Your soul gonna bleed!" }, { 12051, 4.7, true, "Dis not... da end for me!" } }, title = "Advisor to Zul'jin" },
    { id = "zuljin", entry = 23863, name = "Zul'jin", label = "Zul'jin", level = 73, display = 21899, height = 7.1, span = 7.1, school = "physical", pool = "tbc", icon = "Interface\\Icons\\Achievement_Boss_Zuljin", profile = "bruiser", kit = { 17207, 43093, 40563, 38262, 48193, 261 }, passives = {}, talentInfo = { { name = "Spirit of the Bear", icon = "Interface\\Icons\\Ability_Racial_BearForm", text = "Your armor is increased by 15%." }, { name = "Spirit of the Eagle", icon = "Interface\\Icons\\Ability_Hunter_EagleEye", text = "Your Physical damage is increased by 6%." }, { name = "Spirit of the Lynx", icon = "Interface\\Icons\\Ability_Hunter_Pet_Cat", text = "Your attack speed is increased by 10%." }, { name = "Grievous Wounds", icon = "Interface\\Icons\\Ability_Warrior_BloodFrenzy", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "You Too Slow", icon = "Interface\\Icons\\Ability_Whirlwind", text = "Your melee attacks have an 8% chance to start a Whirlwind. Once every 20 sec.\n\nYou too slow! Me too strong! The warlord's axes never stop moving." }, { name = "Everybody Always Wanna Take", icon = "Interface\\Icons\\INV_ThrowingAxe_03", text = "Reduces the cooldown of Grievous Throw by 15 sec.\n\nNow we gonna start takin' back. Zul'jin throws again the moment the last wound closes." } }, tips = { [261] = "Lot more going to fall like you. Call two Amani'shi Berserkers to fight at your side for 20 sec." }, visualKit = 437, soundTransform = 12091, soundDeath = 12100, flies = false, wave = 2, instance = "Zul'Aman", expansion = 1, order = 414, summons = { [261] = true }, box = { 0.16, -0.17, 3.53 }, voices = { { 12091, 2.8, true, "Nobody badduh dan me!" }, { 12092, 4.9, true, "Got me some new tricks... like me brudda bear...." }, { 12093, 3.8, true, "Dere be no hidin' from da eagle!" }, { 12094, 6.5, true, "Let me introduce you to me new bruddas: fang and claw!" }, { 12095, 5.1, true, "Ya don' have to look to da sky to see da dragonhawk!" }, { 12096, 3.7, true, "Fire kill you just as quick!" }, { 12097, 4.1, true, "You too slow! Me too strong!" }, { 12098, 2.8, true, "Da Amani di chuka!" }, { 12099, 2.8, true, "Lot more going to fall like you." }, { 12100, 8.6, true, "Mebbe me fall... but da Amani empire... never going to die." } }, title = "Warlord of Zul'Aman", visages = { "zuljin_bear", "zuljin_eagle", "zuljin_lynx", "zuljin_hawk" }, shape = "Troll" },
    { id = "brutallus", entry = 24882, name = "Brutallus", label = "Brutallus", level = 73, display = 22711, height = 27.3, span = 61.7, school = "fire", pool = "tbc", icon = "Interface\\Icons\\Spell_Fire_FelHellfire", profile = "tank", kit = { 19630, 45185, 37548, 45246 }, passives = {}, talentInfo = { { name = "Meteor Slash", icon = "Interface\\Icons\\Spell_Fire_MeteorStorm", text = "Your Fire damage is increased by 8%." }, { name = "Pit Lord's Bulk", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 12%." }, { name = "Lambs to the Slaughter", icon = "Interface\\Icons\\Ability_Warrior_Challange", text = "The threat you cause is increased by 30%." }, { name = "Felfury Plate", icon = "Interface\\Icons\\Spell_Fire_FelFireward", text = "Your armor is increased by 20%." }, { name = "Burn", icon = "Interface\\Icons\\Spell_Fire_Immolation", text = "When you are struck, you have an 8% chance to Burn the enemies around you. Once every 30 sec.\n\nAnother day, another glorious battle! Brutallus answers every blow with a heavier one." }, { name = "Too Easy", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Reduces the cooldown of Meteor Slash by 10 sec.\n\nToo easy! The pit lord's slashes come sooner once he senses weakness." } }, tips = { [45246] = "I live for this! Burn: set the air around you alight for 2700 Fire damage to every enemy within 8 yards." }, visualKit = 286, soundTransform = 12463, soundDeath = 12471, flies = false, wave = 2, instance = "The Sunwell", expansion = 1, order = 415, box = { -18.34, 1.05, 13.23 }, voices = { { 12458, 6.8, true, "Puny lizard! Death is the only answer you'll find here!" }, { 12459, 4.6, true, "Bagh! Your magic is weak!" }, { 12460, 3.3, true, "I will crush you!" }, { 12461, 6.9, true, "That was fun." }, { 12462, 3.8, true, "Come try your luck!" }, { 12463, 5.3, true, "Ah, more lambs to the slaughter!" }, { 12464, 2.8, true, "Perish, insect!" }, { 12465, 2.7, true, "You are meat!" }, { 12466, 2.9, true, "Too easy!" }, { 12467, 4.0, true, "Bring the fight to me!" }, { 12468, 5.7, true, "Another day, another glorious battle!" }, { 12469, 3.6, true, "I live for this!" } }, title = "Pit Lord of the Burning Legion" },
    { id = "felmyst", entry = 25038, name = "Felmyst", label = "Felmyst", level = 73, display = 22838, height = 23.2, span = 47.8, school = "nature", pool = "tbc", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_1", profile = "caster", kit = { 45402, 45855, 19983, 31475, 261 }, passives = {}, talentInfo = { { name = "Breath of Corruption", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "Your Nature damage is increased by 10%." }, { name = "Scales of Madrigosa", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Blue", text = "Damage you take is reduced by 5%." }, { name = "Gift of the Deceiver", icon = "Interface\\Icons\\Spell_Shadow_DemonicTactics", text = "Your casting speed is increased by 6%." }, { name = "Undying Wyrm", icon = "Interface\\Icons\\Spell_Shadow_AuraOfDarkness", text = "Your maximum health is increased by 6%." }, { name = "Fog of Corruption", icon = "Interface\\Icons\\Spell_Shadow_DemonBreath", text = "When you are struck, you have a 10% chance to release Demonic Vapor. Once every 20 sec.\n\nMadrigosa's corpse still breathes; the fel mist leaks out wherever she is struck." }, { name = "Death to All", icon = "Interface\\Icons\\Spell_Nature_AbolishMagic", text = "Reduces the cooldown of Gas Nova by 8 sec.\n\nDeath to all who oppose! Felmyst vents her gas more often each pass over the Sunwell." } }, tips = { [261] = "Raise two of the Unyielding Dead from the fog of corruption to fight for you for 20 sec." }, visualKit = 282, soundTransform = 0, soundDeath = 12483, flies = true, wave = 2, instance = "The Sunwell", expansion = 1, order = 416, summons = { [261] = true }, box = { -8.32, -0.05, 10.66 }, voices = { { 12477, 5.8, true, "Glory to Kil'jaeden! Death to all who oppose!" }, { 12480, 2.8, true, "I kill for the master!" }, { 12481, 2.6, true, "The end has come!" }, { 12478, 2.5, true, "Choke on your final breath!" }, { 12479, 3.8, true, "I am stronger than ever before!" }, { 12482, 4.6, true, "No more hesitation! Your fates are written!" }, { 12483, 4.1, true, "Kil'jaeden will... prevail!" } }, title = "Once the Blue Dragon Madrigosa", visages = { "madrigosa" }, shape = "Undead" },
    { id = "muru", entry = 25741, name = "M'uru", label = "M'uru", level = 73, display = 23404, height = 14.5, span = 14.5, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Spell_Shadow_ConeOfSilence", profile = "caster", kit = { 46008, 45944, 46161, 261, 17204 }, passives = {}, talentInfo = { { name = "Heart of Entropius", icon = "Interface\\Icons\\Spell_Shadow_Twilight", text = "Your Shadow damage is increased by 10%." }, { name = "Hollow Light", icon = "Interface\\Icons\\Spell_Holy_PowerWordShield", text = "Damage you take is reduced by 6%." }, { name = "Drained Naaru", icon = "Interface\\Icons\\Spell_Shadow_SiphonMana", text = "The mana cost of your Shadow spells is reduced by 8%." }, { name = "Remnant of the Light", icon = "Interface\\Icons\\Spell_Holy_AuraMastery", text = "Your Holy resistance is increased by 50." }, { name = "Void Sentinel's Gaze", icon = "Interface\\Icons\\Spell_Shadow_ShadeTrueSight", text = "When you are struck, you have a 10% chance to answer with a Void Blast. Once every 20 sec.\n\nM'uru's light is gone; what is left pushes back at anything that touches it." }, { name = "Negative Energy", icon = "Interface\\Icons\\Spell_Shadow_Shadowfiend", text = "Reduces the cooldown of Dark Fiend by 5 sec.\n\nThe fallen naaru bleeds darkness faster the longer the Sunwell feeds on it." } }, tips = { [261] = "Open the portals of the Sunwell and let two Shadowsword Berserkers through to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "The Sunwell", expansion = 1, order = 424, summons = { [261] = true, [17204] = true }, box = { 0.06, 0.02, 8.87 }, title = "Guardian of Tempest Keep", visages = { "entropius" }, shape = "Naaru" },
    { id = "kiljaeden", entry = 25315, name = "Kil'jaeden", label = "Kil'jaeden", level = 73, display = 23200, height = 53.8, span = 53.8, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Achievement_Boss_Kiljaedan", profile = "caster", kit = { 45442, 45664, 45737, 45641, 45909, 45657, 261 }, passives = {}, talentInfo = { { name = "Soul Harvest of Argus", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_3", text = "Your Shadow damage is increased by 10%." }, { name = "Blue Flame of the Sunwell", icon = "Interface\\Icons\\Spell_Fire_Felflamering", text = "Your Fire damage is increased by 6%." }, { name = "Heir of Sargeras", icon = "Interface\\Icons\\Spell_Shadow_Metamorphosis", text = "Your Intellect is increased by 8%." }, { name = "Unbowed Before Velen", icon = "Interface\\Icons\\Spell_Shadow_NetherProtection", text = "Damage you take is reduced by 6%." }, { name = "Who Can You Trust", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "Your damaging spells have an 8% chance to add Legion Lightning. Once every 20 sec.\n\nWho can you trust! The Deceiver's lightning leaps between friends as easily as lies do." }, { name = "I Will Not Be Denied", icon = "Interface\\Icons\\Spell_Shadow_Twilight", text = "Reduces the cooldown of Darkness of a Thousand Souls by 30 sec.\n\nI will not be denied! This world shall fall! Kil'jaeden gathers the souls faster each time." } }, tips = { [45909] = "Call Armageddon down around you: a falling star scorches every enemy near you with fire.", [261] = "The enemy is among you! Call two Hands of the Deceiver to fight at your side for 20 sec." }, visualKit = 7775, soundTransform = 0, soundDeath = 12527, flies = false, wave = 2, instance = "The Sunwell", expansion = 1, order = 421, summons = { [261] = true }, box = { -0.38, 1.25, 2.18 }, voices = { { 12501, 3.0, true, "Another step toward destruction!" }, { 12502, 2.3, true, "Anakh Kyree!" }, { 12503, 2.3, true, "Who can you trust!" }, { 12504, 2.8, true, "The enemy is among you!" }, { 12505, 1.8, true, "CHAOS!" }, { 12506, 2.0, true, "DESTRUCTION!" }, { 12507, 1.9, true, "OBLIVION!" }, { 12508, 5.0, true, "I will not be denied! This world shall fall!" }, { 12509, 4.5, true, "Do not harbor false hope! You cannot win!" }, { 12510, 11.5, true, "Aggghh! The powers of the Sunwell... turn... against me! What have you done? What have you done???" } }, title = "The Deceiver" },
    { id = "keristrasza", entry = 26723, name = "Keristrasza", label = "Keristrasza", level = 73, display = 24307, height = 1.5, span = 1.5, school = "frost", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Keristrasza", profile = "caster", kit = { 48096, 50997, 48179, 50155, 52117 }, passives = {}, talentInfo = { { name = "Crystalfire", icon = "Interface\\Icons\\Spell_Fire_BlueFlameBreath", text = "Your Frost damage is increased by 8%." }, { name = "Frozen Consort", icon = "Interface\\Icons\\Spell_Frost_ChainsOfIce", text = "Your Frost resistance is increased by 50." }, { name = "Blood of the Red Flight", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Red", text = "Your maximum health is increased by 8%." }, { name = "Nexus Crystal Focus", icon = "Interface\\Icons\\Spell_Nature_CrystalBall", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Intense Cold", icon = "Interface\\Icons\\Spell_Frost_Glacier", text = "When you are struck, you have a 10% chance to release Intense Cold around you. Once every 30 sec.\n\nThe cold of the Nexus clings to Keristrasza and seeps into whatever reaches her." }, { name = "Preserve Me", icon = "Interface\\Icons\\Spell_Frost_FreezingBreath", text = "Your Crystalfire Breath deals 15% more damage.\n\nDragonqueen... Life-Binder... The red consort's fire burns through the blue's crystal." } }, tips = {}, visualKit = 4991, soundTransform = 13450, soundDeath = 13454, flies = true, wave = 2, instance = "The Nexus", expansion = 2, order = 447, box = { 0.00, 0.00, 0.76 }, voices = { { 13450, 16.8, true, "Preserve? Why? There's no truth in it. No no no... only in the taking! I see that now!" }, { 13453, 5.2, true, "Now we've come to the truth!" }, { 13452, 9.6, true, "Finish it! Finish it! Kill me, or I swear by the Dragonqueen you'll never see daylight again!" }, { 13454, 9.2, true, "Dragonqueen... Life-Binder... preserve... me." }, { 13451, 6.5, true, "Stay. Enjoy your final moments." } }, title = "Unwilling Consort of Malygos", visages = { "keristrasza_visage" }, shape = "Dragon" },
    { id = "loken", entry = 28923, name = "Loken", label = "Loken", level = 81, display = 27485, height = 15.5, span = 15.5, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Spell_Nature_StormReach", profile = "caster", kit = { 52921, 52960, 33665, 50100 }, passives = {}, talentInfo = { { name = "Storm of Ulduar", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 10%." }, { name = "Titanic Frame", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Prime Designate", icon = "Interface\\Icons\\Spell_Holy_MindVision", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Watcher's Hide", icon = "Interface\\Icons\\INV_Misc_Gem_Stone_01", text = "Your armor is increased by 20%." }, { name = "Current of Ulduar", icon = "Interface\\Icons\\Spell_Nature_ThunderClap", text = "When you are struck, you have a 10% chance to Arc Lightning back. Once every 20 sec.\n\nThe Halls of Lightning hum around Loken; strike him and the current answers." }, { name = "Forever", icon = "Interface\\Icons\\Spell_Shaman_ThunderStorm", text = "Reduces the cooldown of Lightning Nova by 5 sec.\n\nThe titan's jailer builds charge faster than any keeper he replaced." } }, tips = {}, visualKit = 282, soundTransform = 14162, soundDeath = 14172, flies = false, wave = 2, instance = "Halls of Lightning", expansion = 2, order = 512, box = { -0.10, -0.49, 7.76 }, voices = { { 14161, 18.0, true, "My master has shown me the future, and you have no place in it. Azeroth will be reborn in darkness. Yogg-Saron shall be released! The Pantheon shall fall!" }, { 14162, 2.8, true, "What hope is there for you? None!" }, { 14163, 2.1, true, "You cannot hide from fate!" }, { 14164, 3.4, true, "Come closer. I will make it quick." }, { 14165, 3.0, true, "Your flesh cannot hold out for long." }, { 14166, 1.4, true, "Only mortal..." }, { 14167, 3.6, true, "I... am... FOREVER!" }, { 14168, 3.1, true, "What little time you had, you wasted!" }, { 14169, 3.2, true, "You stare blindly into the abyss!" }, { 14170, 5.5, true, "Your ignorance is profound. Can you not see where this path leads?" }, { 14171, 3.7, true, "You cross the precipice of oblivion!" }, { 14172, 5.9, true, "My death... heralds the end of this world." } }, title = "Prime Designate" },
    { id = "ymiron", entry = 26861, name = "King Ymiron", label = "King Ymiron", level = 82, display = 28019, height = 7.9, span = 7.9, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_KingYmiron_01", profile = "bruiser", kit = { 48294, 48291, 42724, 51750, 261 }, passives = {}, talentInfo = { { name = "The Fallen King", icon = "Interface\\Icons\\Spell_Shadow_DeathScream", text = "Your Shadow damage is increased by 8%." }, { name = "King of Utgarde", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "Vrykul Endurance", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 8%." }, { name = "Ancestral Fury", icon = "Interface\\Icons\\Ability_Warrior_BloodFrenzy", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Fetid Rot", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "Your melee attacks have a 10% chance to add Fetid Rot. Once every 15 sec.\n\nWhat the Lich King promised Ymiron was not glory, but rot." }, { name = "Bane of the Living", icon = "Interface\\Icons\\Spell_Shadow_CurseOfSargeras", text = "Your Bane lasts 3 sec longer.\n\nThe fallen king's bane lingers as long as his grudge." } }, tips = { [261] = "Your ancestors will aid you! Call two Avenging Spirits to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 13609, soundDeath = 13618, flies = false, wave = 2, instance = "Utgarde Pinnacle", expansion = 2, order = 481, summons = { [261] = true }, box = { -0.11, -0.00, 3.96 }, voices = { { 13609, 14.0, true, "You invade my home and then dare to challenge me? I will tear the hearts from your chests and offer them as gifts to the death god! Rualg nja gaborr!" }, { 13614, 3.6, true, "Your death is only the beginning." }, { 13615, 2.8, true, "You have failed your people!" }, { 13616, 4.3, true, "There is a reason I am king!" }, { 13617, 2.2, true, "Breathe no more!" }, { 13618, 5.7, true, "What... awaits me... now?" }, { 13610, 5.3, true, "Bjorn of the Black Storm! Honor me now with your presence!" }, { 13611, 5.0, true, "Haldor of the Rocky Cliffs! Grant me your strength!" }, { 13612, 6.5, true, "Ranulf of the Screaming Abyss! Snuff these maggots with darkest night!" }, { 13613, 5.4, true, "Tor of the Brutal Siege, bestow your might upon me!" } }, title = "The Fallen King" },
    { id = "sartharion", entry = 28860, name = "Sartharion", label = "Sartharion", level = 83, display = 27035, height = 14.7, span = 29.9, school = "fire", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Sartharion_01", profile = "bruiser", kit = { 56908, 56909, 56910, 57757, 261, 17204 }, passives = {}, talentInfo = { { name = "Onyx Guardian", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", text = "Your armor is increased by 20%." }, { name = "Flame of the Sanctum", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire damage is increased by 10%." }, { name = "Black Dragonflight", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "Will of Sartharion", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 8%." }, { name = "Flame Tsunami", icon = "Interface\\Icons\\Spell_Fire_Volcano", text = "When you are struck, you have an 8% chance to rain lava around you. Once every 30 sec.\n\nThe Obsidian Sanctum's lava rises whenever its guardian is pressed." }, { name = "Twilight Revenge", icon = "Interface\\Icons\\spell_fire_twilightflamebreath", text = "Your Flame Breath deals 15% more damage.\n\nSartharion burns hotter for every drake the intruders slay." } }, tips = { [261] = "Call two Twilight Whelps from the Obsidian Sanctum to fight for you for 20 sec." }, visualKit = 286, soundTransform = 14093, soundDeath = 14107, flies = true, wave = 2, instance = "The Obsidian Sanctum", expansion = 2, order = 540, summons = { [261] = true, [17204] = true }, box = { -5.20, -0.03, 6.75 }, voices = { { 14093, 6.7, true, "It is my charge to watch over these eggs. I will see you burn before any harm comes to them!" }, { 14103, 3.0, true, "This pathetic siege ends NOW!" }, { 14098, 2.5, true, "Burn, you miserable wretches!" }, { 14105, 3.1, true, "Shadron! Come to me! All is at risk!" }, { 14106, 3.3, true, "Tenebron! The eggs are yours to protect as well!" }, { 14104, 3.3, true, "Vesperon, the clutch is in danger! Assist me!" }, { 14107, 4.3, true, "Such is the price... of failure...." }, { 14099, 2.7, true, "Such flammable little insects...." }, { 14100, 2.8, true, "Your charred bones will litter the floor!" }, { 14101, 2.2, true, "How much heat can you take?" }, { 14094, 3.2, true, "You will make a fine meal for the hatchlings." }, { 14096, 2.3, true, "You are at a grave disadvantage." } }, title = "The Onyx Guardian" },
    { id = "razorscale", entry = 33186, name = "Razorscale", label = "Razorscale", level = 83, display = 28787, height = 15.8, span = 48.0, school = "fire", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Razorscale", profile = "bruiser", kit = { 47251, 62666, 64733, 64771 }, passives = {}, talentInfo = { { name = "Broodmother of the Proto-Drakes", icon = "Interface\\Icons\\Ability_Mount_Drake_Proto", text = "Your attack power is increased by 10%." }, { name = "Razor Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your armor is increased by 20%." }, { name = "Devouring Flame", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire damage is increased by 10%." }, { name = "Unchained", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Your movement speed is increased by 10%." }, { name = "Harpoon Rage", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "When you are struck, you have a 10% chance to spit Devouring Flame. Once every 15 sec.\n\nRazorscale remembers every harpoon, and burns whoever threw it." }, { name = "Broodmother's Fire", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Increases the damage of Flame Breath by 15%.\n\nThe broodmother's breath melts dwarven iron." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = true, wave = 2, instance = "Ulduar", expansion = 2, order = 495, box = { -6.75, 0.35, 7.13 }, title = "Broodmother of the Proto-Drakes" },
    { id = "ignis", entry = 33118, name = "Ignis the Furnace Master", label = "Ignis the Furnace Master", level = 83, display = 29185, height = 28.5, span = 28.5, school = "fire", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Ignis_01", profile = "caster", kit = { 62553, 65722, 62680, 261 }, passives = {}, talentInfo = { { name = "Furnace Master", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire damage is increased by 10%." }, { name = "Molten Hide", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Your Fire resistance is increased by 60." }, { name = "Iron Frame", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your maximum health is increased by 10%." }, { name = "Slag Imbued", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Heat", icon = "Interface\\Icons\\Spell_Fire_SoulBurn", text = "When you are struck, you have a 10% chance to Scorch the enemies before you. Once every 20 sec.\n\nThe furnace master breathes fire on anyone who stands too close to the forge." }, { name = "Stoke the Furnace", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "Reduces the cooldown of Flame Jets by 8 sec.\n\nIgnis's forge never cools; the flame jets come quicker as it heats." } }, tips = { [261] = "Heat a construct in your forge and wake it to fight for you for 20 sec." }, visualKit = 286, soundTransform = 15564, soundDeath = 15572, flies = false, wave = 2, instance = "Ulduar", expansion = 2, order = 492, summons = { [261] = true }, box = { -0.39, 0.04, 14.25 }, voices = { { 15564, 7.1, true, "Insolent whelps! Your blood will temper the weapons used to reclaim this world!" }, { 15565, 7.3, true, "Arise, soldiers of the iron crucible! The Maker's will be done!" }, { 15566, 3.6, true, "I will burn away your impurities!" }, { 15567, 3.1, true, "Let the inferno consume you!" }, { 15568, 5.7, true, "BURN! Burn in the Maker's fire!" }, { 15569, 2.8, true, "More scraps for the scrap heap." }, { 15570, 3.7, true, "Your bones will serve as kindling." }, { 15571, 3.9, true, "LET IT BE FINISHED!" }, { 15572, 4.2, true, "I. Have. Failed." } }, title = "Eternal Flame" },
    { id = "hodir", entry = 32845, name = "Hodir", label = "Hodir", level = 83, display = 28743, height = 19.0, span = 19.0, school = "frost", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Hodir_01", profile = "caster", kit = { 62469, 62478, 62457, 65370 }, passives = {}, talentInfo = { { name = "Titanic Watcher", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "Biting Cold", icon = "Interface\\Icons\\Spell_Frost_FrostWard", text = "Your Frost resistance is increased by 60." }, { name = "Frost Giant", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Winter's Keeper", icon = "Interface\\Icons\\Spell_Frost_Glacier", text = "Your armor is increased by 20%." }, { name = "Shattering Ice", icon = "Interface\\Icons\\Spell_Frost_IceShard", text = "When you are struck, you have a 10% chance to drop Ice Shards. Once every 15 sec.\n\nIcicles fall from Hodir's hall whenever the keeper is struck." }, { name = "Flash Freeze", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "Reduces the cooldown of Freeze by 8 sec.\n\nWinds of the north consume you! Hodir freezes the hall over and over." } }, tips = {}, visualKit = 4991, soundTransform = 15552, soundDeath = 15557, flies = false, wave = 2, instance = "Ulduar", expansion = 2, order = 491, box = { -0.28, -0.32, 9.50 }, voices = { { 15552, 4.5, true, "You will suffer for this trespass!" }, { 15553, 6.1, true, "Tragic. To come so far, only to fail." }, { 15554, 4.4, true, "Welcome to the endless winter." }, { 15555, 3.7, true, "Winds of the north consume you!" }, { 15557, 9.1, true, "I... I am released from his grasp... at last." }, { 15558, 4.4, true, "ENOUGH! This ends now!" } }, title = "Titanic Watcher" },
    { id = "thorim", entry = 32865, name = "Thorim", label = "Thorim", level = 83, display = 28977, height = 18.9, span = 18.9, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Thorim", profile = "bruiser", kit = { 62130, 62042, 62131, 62605, 62279 }, passives = {}, talentInfo = { { name = "The Stormlord", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 10%." }, { name = "Storm Giant", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Titanic Might", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your Strength is increased by 8%." }, { name = "Unbalancing", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Stormcaller", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", text = "Your melee attacks have an 8% chance to add a Chain Lightning. Once every 15 sec.\n\nInterlopers! Thorim's blows carry the storm with them." }, { name = "Sif", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "Reduces the cooldown of Frost Nova by 8 sec.\n\nSif's cold still answers her husband's call." } }, tips = {}, visualKit = 282, soundTransform = 15733, soundDeath = 15743, flies = false, wave = 2, instance = "Ulduar", expansion = 2, order = 499, box = { -0.36, -0.46, 9.36 }, voices = { { 15733, 8.9, true, "Interlopers! You mortals who dare to interfere with my sport will pay... Wait--you..." }, { 15734, 8.3, true, "I remember you... In the mountains... But you... what is this? Where am--" }, { 15735, 4.0, true, "Behold the power of the storms and despair!" }, { 15736, 2.8, true, "Do not hold back! Destroy them!" }, { 15737, 3.1, true, "Have you begun to regret your intrusion?" }, { 15738, 7.8, true, "Impertinent whelps, you dare challenge me atop my pedestal? I will crush you myself!" }, { 15739, 2.3, true, "Can't you at least put up a fight!?" }, { 15740, 1.1, true, "Pathetic." }, { 15741, 2.6, true, "My patience has reached its limit!" }, { 15742, 2.3, true, "Failures! Weaklings!" }, { 15743, 3.2, true, "Stay your arms! I yield!" }, { 15744, 7.7, true, "I feel as though I am awakening from a nightmare, but the shadows in this place yet linger." } }, title = "The Stormlord" },
    { id = "mimiron", entry = 33350, name = "Mimiron", label = "Mimiron", level = 83, display = 28578, height = 3.2, span = 3.2, school = "fire", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Mimiron_01", profile = "caster", kit = { 62997, 63677, 261 }, passives = {}, talentInfo = { { name = "The Grand Architect", icon = "Interface\\Icons\\Trade_Engineering", text = "Your Fire damage is increased by 10%." }, { name = "Self Repair", icon = "Interface\\Icons\\INV_Misc_Wrench_01", text = "Your maximum health is increased by 8%." }, { name = "Overclocked", icon = "Interface\\Icons\\INV_Gizmo_08", text = "Your casting speed is increased by 6%." }, { name = "Medic!", icon = "Interface\\Icons\\INV_Misc_Bomb_02", text = "When you are struck, you have a 10% chance to vent a Heat Wave. Once every 20 sec.\n\nOutplayed! Mimiron's machines vent heat whenever something dents them." }, { name = "Prognosis: Negative", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "Your Plasma Blast lasts 2 sec longer.\n\nThe Grand Architect never builds a cannon that stops early." } }, tips = { [261] = "Drop two Bomb Bots that trundle at your foes and fight for you for 20 sec." }, visualKit = 286, soundTransform = 15611, soundDeath = 15615, flies = false, wave = 2, instance = "Ulduar", expansion = 2, order = 494, summons = { [261] = true }, box = { -0.10, 0.01, 1.57 }, voices = { { 15611, 9.1, true, "Oh, my! I wasn't expecting company! The workshop is such a mess. How embarrassing." }, { 15629, 13.4, true, "Now, why would you go and do something like that? Didn't you see the sign that said, \"DO NOT PUSH THIS BUTTON!\"? How will we finish testing with the self-destruct mechanism active?" }, { 15613, 1.8, true, "MEDIC!" }, { 15614, 6.7, true, "I can fix that... or maybe not! Sheesh, what a mess..." }, { 15615, 11.1, true, "WONDERFUL! Positively marvelous results! Hull integrity at 98.9 percent! Barely a dent! Moving right along." }, { 15616, 8.8, true, "Behold the VX-001 Anti-personnel Assault Cannon! You might want to take cover." }, { 15617, 4.4, true, "Fascinating. I think they call that a \"clean kill\"." }, { 15618, 5.6, true, "Note to self: Cannon highly effective against flesh." }, { 15619, 8.8, true, "Thank you, friends! Your efforts have yielded some fantastic data! Now, where did I put-- oh, there it is." }, { 15620, 7.7, true, "Isn't it beautiful? I call it the magnificent aerial command unit!" }, { 15621, 2.5, true, "Outplayed!" }, { 15622, 2.1, true, "You can do better than that!" } }, title = "The Grand Architect" },
    { id = "algalon", entry = 32871, name = "Algalon the Observer", label = "Algalon the Observer", level = 83, display = 28641, height = 25.3, span = 25.3, school = "arcane", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Algalon_01", profile = "caster", kit = { 64395, 6304, 64599, 64596, 56969 }, passives = {}, talentInfo = { { name = "Herald of the Titans", icon = "Interface\\Icons\\Spell_Arcane_StarFire", text = "Your Arcane damage is increased by 10%." }, { name = "Observer", icon = "Interface\\Icons\\Spell_Holy_MindVision", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Titanic Frame", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Starfall", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", text = "Your casting speed is increased by 6%." }, { name = "I Do What I Must", icon = "Interface\\Icons\\Spell_Arcane_Blast", text = "Your damaging spells have an 8% chance to loose an Arcane Barrage. Once every 20 sec.\n\nAlgalon's calculations never end at one star." }, { name = "Reorigination", icon = "Interface\\Icons\\Spell_Fire_Meteorstorm", text = "Reduces the cooldown of Cosmic Smash by 8 sec.\n\nAlgalon has watched worlds end; one more boulder is nothing." } }, tips = {}, visualKit = 1005, soundTransform = 15390, soundDeath = 15400, flies = false, wave = 2, instance = "Ulduar", expansion = 2, order = 487, box = { -0.77, 0.18, 8.04 }, voices = { { 15405, 8.0, false, "Translocation complete. Commencing planetary analysis of Azeroth." }, { 15406, 6.1, false, "Stand back, mortals. I'm not here to fight you." }, { 15407, 11.0, false, "It is in the universe's best interest to re-originate this planet should my analysis find systemic corruption. Do not interfere." }, { 15386, 13.8, true, "Your actions are illogical. All possible results for this encounter have been calculated. The Pantheon will receive the Observer's message regardless of outcome." }, { 15390, 11.7, true, "See your world through my eyes: A universe so vast as to be immeasurable - incomprehensible even to your greatest minds." }, { 15392, 4.4, true, "The stars come to my aid!" }, { 15396, 4.7, true, "Witness the fury of the cosmos!" }, { 15394, 5.3, true, "You are out of time." }, { 15397, 5.2, true, "Behold the tools of creation!" }, { 15402, 10.1, true, "I've rearranged the reply code - your planet will be spared. I cannot be certain of my own calculations anymore." }, { 15403, 10.8, true, "I lack the strength to transmit the signal. You must... hurry... find a place of power... close to the skies." }, { 15404, 13.8, true, "Do not worry about my fate, Bronzen. If the signal is not transmitted in time, re-origination will proceed regardless. Save... your world..." } }, title = "Herald of the Titans" },
    { id = "yoggsaron", entry = 33288, name = "Yogg-Saron", label = "Yogg-Saron", level = 83, display = 28817, height = 29.1, span = 39.1, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_YoggSaron_01", profile = "caster", kit = { 63830, 63038, 64164, 16608 }, passives = {}, talentInfo = { { name = "The Beast With a Thousand Maws", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your Shadow damage is increased by 10%." }, { name = "Old God", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "Your maximum health is increased by 10%." }, { name = "Sanity's End", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Shadowy Barrier", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Damage you take is reduced by 5%." }, { name = "Induce Madness", icon = "Interface\\Icons\\Spell_Shadow_MindRot", text = "Your damaging spells have an 8% chance to open a Lunatic Gaze. Once every 20 sec.\n\nLook upon the true face of death and despair! Yogg-Saron's gaze follows every spell he casts." }, { name = "The Lucid Dream", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordDominate", text = "Reduces the cooldown of Malady of the Mind by 10 sec.\n\nThe Old God's whispers find the next mind sooner every time." } }, tips = {}, visualKit = 7775, soundTransform = 15755, soundDeath = 15761, flies = false, wave = 2, instance = "Ulduar", expansion = 2, order = 501, box = { -1.85, 0.03, 2.30 }, voices = { { 15756, 4.0, true, "MADNESS WILL CONSUME YOU!" }, { 15755, 7.1, true, "Look upon the true face of death, and know that your end comes soon!" }, { 15758, 3.2, true, "Eternal suffering awaits!" }, { 15761, 16.2, true, "Your fate is sealed. The end of days is finally upon you and ALL who inhabit this miserable little seedling. Uulwi ifis halahs gag erh'ongg w'ssh." } }, title = "The Beast With a Thousand Maws", visages = { "yoggsaron_awakened" }, shape = "Dormant" },
    { id = "marrowgar", entry = 36612, name = "Lord Marrowgar", label = "Lord Marrowgar", level = 83, display = 31119, height = 42.5, span = 51.9, school = "frost", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_LordMarrowgar", profile = "tank", kit = { 46270, 69055, 5703, 69146, 37548 }, passives = {}, talentInfo = { { name = "Guardian of the Frozen Throne", icon = "Interface\\Icons\\INV_Misc_Bone_HumanSkull_01", text = "Your armor is increased by 25%." }, { name = "Bone Colossus", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 12%." }, { name = "The Only Escape", icon = "Interface\\Icons\\Ability_Warrior_Challange", text = "The threat you cause is increased by 30%." }, { name = "Coldflame", icon = "Interface\\Icons\\Spell_Frost_FrostShock", text = "Your Frost damage is increased by 10%." }, { name = "Chilled Marrow", icon = "Interface\\Icons\\Spell_Fire_BlueFire", text = "When you are struck, you have a 10% chance to send out Coldflame. Once every 15 sec.\n\nThe Scourge will wash over this world as a swarm of death and destruction!" }, { name = "Bone Storm", icon = "Interface\\Icons\\Ability_Whirlwind", text = "Reduces the cooldown of Bone Storm by 8 sec.\n\nMarrowgar never stays still for long." } }, tips = {}, visualKit = 4991, soundTransform = 16941, soundDeath = 16944, flies = false, wave = 2, instance = "Icecrown Citadel", expansion = 2, order = 561, box = { 2.12, -0.20, 17.62 }, voices = { { 16950, 10.9, true, "This is the beginning AND the end, mortals. None may enter the master's sanctum!" }, { 16941, 10.9, true, "The Scourge will wash over this world as a swarm of death and destruction!" }, { 16946, 3.8, true, "BONE STORM!" }, { 16947, 3.9, true, "Bound by bone!" }, { 16948, 3.0, true, "Stick around!" }, { 16949, 4.9, true, "The only escape is death!" }, { 16942, 4.5, true, "More bones for the offering!" }, { 16943, 4.5, true, "Languish in damnation!" }, { 16944, 6.8, true, "I see... Only darkness." }, { 16945, 5.9, true, "THE MASTER'S RAGE COURSES THROUGH ME!" } }, title = "Guardian of the Frozen Throne" },
    { id = "saurfang", entry = 37813, name = "Deathbringer Saurfang", label = "Deathbringer Saurfang", level = 83, display = 30790, height = 2.7, span = 2.7, school = "physical", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Saurfang", profile = "bruiser", kit = { 72380, 55974, 15496, 72737, 261 }, passives = {}, talentInfo = { { name = "Son of the High Overlord", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "Blood Power", icon = "Interface\\Icons\\Spell_DeathKnight_BloodBoil", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Resistant Skin", icon = "Interface\\Icons\\INV_Chest_Plate16", text = "Your armor is increased by 15%." }, { name = "Deathbringer", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 8%." }, { name = "Mark of the Fallen Champion", icon = "Interface\\Icons\\Ability_Rogue_FeignDeath", text = "Your melee attacks have an 8% chance to burst in a Blood Nova. Once every 20 sec.\n\nThe fallen champion's mark splashes blood on everyone near it." }, { name = "Deathbringer's Rage", icon = "Interface\\Icons\\Spell_DeathKnight_BloodPlague", text = "Reduces the cooldown of Boiling Blood by 4 sec.\n\nSaurfang's blood power boils over faster the longer he fights." } }, tips = { [261] = "Call two Vampiric Fiends out of the Citadel's blood to fight for you for 20 sec." }, visualKit = 437, soundTransform = 16694, soundDeath = 16701, flies = false, wave = 2, instance = "Icecrown Citadel", expansion = 2, order = 557, summons = { [261] = true }, charModel = true, box = { 0.01, -0.01, 1.35 }, voices = { { 16701, 17.5, true, "For every Horde soldier that you killed -- for every Alliance dog that fell, the Lich King's armies grew. Even now the val'kyr work to raise your fallen as Scourge." }, { 16702, 9.8, true, "Things are about to get much worse. Come, taste the power that the Lich King has bestowed upon me!" }, { 16703, 4.3, true, "Dwarves..." }, { 16704, 13.8, true, "Join me, father. Join me and we will crush this world in the name of the Scourge -- for the glory of the Lich King!" }, { 16705, 9.5, true, "Stubborn and old. What chance do you have? I am stronger, and more powerful than you ever were." }, { 16706, 8.9, true, "Pathetic old orc! Come then, heroes. Come and face the might of the Scourge!" }, { 16694, 3.2, true, "BY THE MIGHT OF THE LICH KING!" }, { 16699, 3.4, true, "The ground runs red with your blood!" }, { 16700, 2.3, true, "Feast, my minions!" }, { 16695, 1.6, true, "You are nothing!" }, { 16696, 3.0, true, "Your soul will find no redemption here!" }, { 16698, 3.2, true, "I have become... DEATH!" } }, title = "Son of the High Overlord" },
    { id = "festergut", entry = 36626, name = "Festergut", label = "Festergut", level = 83, display = 31006, height = 13.7, span = 13.7, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Ability_Creature_Cursed_01", profile = "tank", kit = { 69240, 70138, 69651, 37548 }, passives = {}, talentInfo = { { name = "Gaseous Bloat", icon = "Interface\\Icons\\Spell_Shadow_PlagueCloud", text = "Your maximum health is increased by 12%." }, { name = "Bloated", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", text = "Damage you take is reduced by 5%." }, { name = "Gas Spore", icon = "Interface\\Icons\\Ability_Warrior_Challange", text = "The threat you cause is increased by 30%." }, { name = "Plague Stench", icon = "Interface\\Icons\\Spell_Shadow_CreepingPlague", text = "Your Shadow damage is increased by 10%." }, { name = "Gastric Bloat", icon = "Interface\\Icons\\Ability_Creature_Disease_02", text = "When you are struck, you have a 10% chance to release Gaseous Blight. Once every 20 sec.\n\nHit Festergut and the gas comes out." }, { name = "Inhale Blight", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "Reduces the cooldown of Vile Gas by 5 sec.\n\nFestergut breathes deep and gives it all back." } }, tips = {}, visualKit = 282, soundTransform = 16901, soundDeath = 16904, flies = false, wave = 2, instance = "Icecrown Citadel", expansion = 2, order = 558, box = { 1.60, -0.97, 6.63 }, voices = { { 16907, 6.3, true, "No! You killed Stinky! You Pay!" }, { 16901, 1.6, true, "Fun time?" }, { 16906, 5.7, true, "I not feel so good..." }, { 16902, 3.3, true, "Daddy, I did it!" }, { 16903, 4.5, true, "Dead, dead, dead!" }, { 16905, 3.0, true, "Fun time over!" }, { 16904, 4.5, true, "Da ... Ddy..." } }, title = "Glutton of the Plagueworks" },
    { id = "rotface", entry = 36627, name = "Rotface", label = "Rotface", level = 83, display = 31005, height = 13.7, span = 13.7, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Spell_Fire_Felcano", profile = "tank", kit = { 69507, 70671, 69778, 37548 }, passives = {}, talentInfo = { { name = "Creation of Professor Putricide", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 12%." }, { name = "Rotting Hide", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", text = "Your armor is increased by 25%." }, { name = "Icky Sticky", icon = "Interface\\Icons\\Ability_Warrior_Challange", text = "The threat you cause is increased by 30%." }, { name = "Ooze Flood", icon = "Interface\\Icons\\Spell_Nature_Acid_01", text = "Your Nature damage is increased by 10%." }, { name = "Unstable Ooze", icon = "Interface\\Icons\\INV_Misc_Slime_01", text = "When you are struck, you have a 10% chance to splash Sticky Ooze. Once every 15 sec.\n\nHit Rotface and something sticky comes off." }, { name = "Daddy Make Toys", icon = "Interface\\Icons\\Spell_Shadow_PlagueCloud", text = "Reduces the cooldown of Mutated Infection by 8 sec.\n\nDaddy make toys out of you! Rotface spreads his infection faster with every ooze he swallows." } }, tips = {}, visualKit = 282, soundTransform = 16986, soundDeath = 16989, flies = false, wave = 2, instance = "Icecrown Citadel", expansion = 2, order = 566, box = { 1.60, -0.97, 6.63 }, voices = { { 16993, 7.4, true, "What? Precious? Noooooooooo!!!" }, { 16986, 3.3, true, "Weeeeee!" }, { 16991, 2.4, true, "Icky sticky!" }, { 16992, 5.3, true, "I tink I made an angry poo-poo. It gonna blow!" }, { 16988, 4.0, true, "Daddy make new toys out of you!" }, { 16987, 2.7, true, "I brokes-ded it..." }, { 16990, 3.4, true, "SLEEPY TIME!" }, { 16989, 3.6, true, "Bad news, daddy..." } }, title = "Creation of Professor Putricide" },
    { id = "putricide", entry = 36678, name = "Professor Putricide", label = "Professor Putricide", level = 83, display = 30881, height = 7.2, span = 7.2, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\inv_misc_herb_evergreenmoss", profile = "caster", kit = { 70853, 70346, 70492, 7961 }, passives = {}, talentInfo = { { name = "Mad Scientist of the Scourge", icon = "Interface\\Icons\\Spell_Shadow_PlagueCloud", text = "Your Nature damage is increased by 10%." }, { name = "Good News, Everyone", icon = "Interface\\Icons\\INV_Potion_27", text = "Your casting speed is increased by 6%." }, { name = "Unstable Experiment", icon = "Interface\\Icons\\INV_Potion_25", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Plague Sickness", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 8%." }, { name = "Malleable Goo", icon = "Interface\\Icons\\INV_Misc_Slime_02", text = "Your damaging spells have an 8% chance to spill Mutated Slime. Once every 20 sec.\n\nSomething always spills in the professor's laboratory." }, { name = "Ooze Eruption", icon = "Interface\\Icons\\Spell_Nature_Acid_01", text = "Reduces the cooldown of Ooze Eruption by 8 sec.\n\nThe professor's oozes grow more volatile with every batch." } }, tips = { [7961] = "Throw a vial of tear gas: every enemy near you is dazed and stunned for 5 sec." }, visualKit = 282, soundTransform = 17114, soundDeath = 17124, flies = false, wave = 2, instance = "Icecrown Citadel", expansion = 2, order = 564, box = { -0.38, -0.34, 3.58 }, voices = { { 17119, 8.6, true, "Just an ordinary gas cloud, but watch out because that's no ordinary gas cloud!" }, { 17124, 13.3, true, "Oh Festergut, you were always my favorite -- next to Rotface. The good news is that you left behind so much gas. I can practically taste it!" }, { 17126, 5.3, true, "Great news, everyone! The slime is flowing again!" }, { 17123, 5.7, true, "Good news, everyone! I've fixed the poison slime pipes!" }, { 17146, 16.5, true, "Terrible news, everyone. Rotface is dead, but great news everyone! He left behind plenty of ooze for me to use! What? I'm a poet and I didn't know it... Astounding!" }, { 17114, 8.4, true, "Good news, everyone! I think I've perfected a plague that will destroy all life on Azeroth!" }, { 17122, 6.5, true, "Two oozes, one room. So many delightful possibilities!" }, { 17120, 6.7, true, "Hrm, I don't feel a thing. Wha?! Where'd those come from?" }, { 17121, 5.5, true, "Tastes like... Cherry! OH! Excuse me!" }, { 17115, 3.3, true, "Hrm, interesting..." }, { 17116, 2.3, true, "That was unexpected!" }, { 17118, 4.6, true, "Great news, everyone!" } }, title = "Mad Scientist of the Scourge", visages = { "putricide_mutated" }, shape = "Scientist" },
    { id = "keleseth", entry = 37972, name = "Prince Keleseth", label = "Prince Keleseth", level = 83, display = 30857, height = 4.1, span = 4.1, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_PrinceKeleseth", profile = "caster", kit = { 71405, 71815, 55850, 37729 }, passives = {}, talentInfo = { { name = "The San'layn", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 10%." }, { name = "Invocation of Blood", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Darkfallen Orb", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Your Shadow resistance is increased by 60." }, { name = "Blood Prince", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 8%." }, { name = "Orb Resonance", icon = "Interface\\Icons\\Spell_Shadow_Shadowfury", text = "Your damaging spells have an 8% chance to loose a Shadow Bolt Volley. Once every 20 sec.\n\nThe Darkfallen Orb resonates with every lance Keleseth throws." }, { name = "Such Wondrous Power", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "Reduces the cooldown of Empowered Shadow Lance by 5 sec.\n\nThe Darkfallen Orb has made me INVINCIBLE!" } }, tips = {}, visualKit = 7775, soundTransform = 16728, soundDeath = 16725, flies = false, wave = 2, instance = "Icecrown Citadel", expansion = 2, order = 563, box = { -0.46, -0.23, 1.98 }, voices = { { 16727, 5.7, true, "Such wondrous power! The Darkfallen Orb has made me INVINCIBLE!" }, { 16728, 2.2, true, "Blood will flow." }, { 16723, 2.3, true, "Were you ever a threat?" }, { 16724, 2.3, true, "Truth is found in death." }, { 16725, 4.0, true, "My queen, they... come." } }, title = "The San'layn" },
    { id = "lanathel", entry = 37955, name = "Blood-Queen Lana'thel", label = "Blood-Queen Lana'thel", level = 83, display = 31165, height = 8.9, span = 15.4, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Lanathel", profile = "glass_cannon", kit = { 70985, 71446, 71623, 73070, 8602 }, passives = {}, talentInfo = { { name = "The San'layn", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your Shadow damage is increased by 10%." }, { name = "Presence of the Darkfallen", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Blood Queen's Grace", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Your movement speed is increased by 10%." }, { name = "Thirst of the Blood Queen", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Your casting speed is increased by 6%." }, { name = "Just a Taste", icon = "Interface\\Icons\\Spell_Shadow_BloodBoil", text = "Your damaging spells have an 8% chance to add a Twilight Bloodbolt. Once every 15 sec.\n\nJust a taste... the Blood Queen's bolts come in pairs when she is thirsty." }, { name = "Delirious", icon = "Interface\\Icons\\Ability_Rogue_Rupture", text = "Your Delirious Slash deals 15% more damage.\n\nThe Blood Queen's blade cuts deeper as the frenzy takes her." } }, tips = { [8602] = "Drink deep of the Blood Queen's essence: your damage is raised by 100% and you cannot be feared for 10 sec." }, visualKit = 7775, soundTransform = 16782, soundDeath = 16794, flies = true, wave = 2, instance = "Icecrown Citadel", expansion = 2, order = 556, box = { -2.97, -1.24, 4.28 }, voices = { { 16782, 4.6, true, "You have made an... unwise... decision." }, { 16783, 1.7, true, "Just a taste..." }, { 16784, 1.9, true, "Know my hunger!" }, { 16790, 5.4, true, "Yes! Feed, my precious one! You are mine now!" }, { 16786, 0.9, true, "SUFFER!" }, { 16787, 1.9, true, "Can you handle this?" }, { 16788, 3.2, true, "Here it comes..." }, { 16791, 3.0, true, "Really...? Is that all you've got?" }, { 16792, 2.0, true, "Such a pity." }, { 16789, 8.2, true, "How... unfortunate." }, { 16793, 3.1, true, "This ends NOW!" }, { 16794, 6.6, true, "But... we were getting along... so... well..." } }, title = "The San'layn" },
    { id = "defias", entry = 589, name = "Defias Pillager", label = "Defias Pillager", level = 15, display = 2338, height = 2.1, span = 2.1, school = "fire", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Bandana_03", profile = "caster", kit = { 20793, 7978, 11831, 7964, 14514 }, passives = {}, talentInfo = { { name = "Brotherhood Pyromancy", icon = "Interface\\Icons\\Spell_Fire_FlameBolt", text = "Your Fire damage is increased by 8%." }, { name = "Pillager's Studies", icon = "Interface\\Icons\\Spell_Arcane_StudentOfMagic", text = "Your Intellect is increased by 8%." }, { name = "Masked Raider", icon = "Interface\\Icons\\Ability_Rogue_Disguise", text = "Your chance to land a critical spell is increased by 4%." }, { name = "Stonemason's Grudge", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "When you are struck, you have a 10% chance to cast Frost Nova. Once every 25 sec.\n\nThey built Stormwind and were never paid. Every Defias carries that debt, and collects it from whoever comes close." }, { name = "Burn the Farmsteads", icon = "Interface\\Icons\\Spell_Fire_Fireball", text = "Reduces the cooldown of your Throw Dynamite by 3 sec.\n\nThe pillagers of Westfall light a barn a night. Practice makes the flame come quicker to the hand." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Westfall", expansion = 0, order = 18, charModel = true, box = { -0.10, -0.00, 1.06 }, skinName = "Pillager", variants = { "defias_footpad", "defias_pirate", "defias_overseer" }, skins = { { entry = 4417, name = "Black", creature = "Defias Taskmaster", display = 2440, height = 2.1, span = 2.1, box = { -0.10, -0.00, 1.06 }, charModel = true } }, title = "Member of the Defias Brotherhood" },
    { id = "harpy", entry = 2962, name = "Windfury Harpy", label = "Harpy", level = 8, display = 10877, height = 3.1, span = 3.1, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bat", profile = "caster", kit = { 9532, 3589, 38110, 6982, 13443, 6950 }, passives = {}, talentInfo = { { name = "Windfury Storm", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 8%." }, { name = "Feathered Evasion", icon = "Interface\\Icons\\INV_Feather_01", text = "Your chance to dodge is increased by 5%." }, { name = "Shrieking Tempo", icon = "Interface\\Icons\\Spell_Shadow_DeathScream", text = "Your casting speed is increased by 6%." }, { name = "Windfury", icon = "Interface\\Icons\\Spell_Nature_Cyclone", text = "Your harmful spells have a 10% chance to call down a second Lightning Bolt. Once every 15 sec.\n\nThe Windfury name is earned in storms: where one bolt falls on the plains below, a second follows on the wind." }, { name = "Roost Mother's Shriek", icon = "Interface\\Icons\\Spell_Shadow_AuraOfDarkness", text = "Reduces the cooldown of your Deafening Screech by 5 sec.\n\nThe matriarchs of the roost screech the loudest and the most often. No shaman in Mulgore finishes a chant near them." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = true, wave = 2, zone = "Mulgore", expansion = 0, order = 9, box = { 0.02, 0.01, 2.29 }, view = { -1.3576, 0.0000, 0.0990 }, skins = { { entry = 2040, name = "Black", creature = "Haggatha the Crone", display = 2163, height = 4.8, span = 4.8, box = { 0.03, 0.02, 3.51 } }, { entry = 2021, name = "Crimson", creature = "Bloodfeather Matriarch", display = 6813, height = 4.8, span = 4.8, box = { 0.03, 0.02, 3.51 } }, { entry = 5362, name = "Purple", creature = "Northspring Harpy", display = 10872, height = 4.2, span = 4.2, box = { 0.03, 0.02, 3.10 } }, { entry = 3452, name = "Yellow", creature = "Serena Bloodfeather", display = 2295, height = 4.8, span = 4.8, box = { 0.03, 0.02, 3.51 } }, { entry = 5830, name = "Green", creature = "Sister Rathtalon", display = 10876, height = 4.8, span = 4.8, box = { 0.03, 0.02, 3.51 } } }, title = "Harpy of Mulgore" },
    { id = "wendigo", entry = 1135, name = "Wendigo", label = "Wendigo", level = 7, display = 950, height = 2.5, span = 2.5, school = "frost", pool = "archetype", icon = "Interface\\Icons\\Spell_Frost_FrostShock", profile = "bruiser", kit = { 3131, 3130, 56402, 16727, 32918, 31256 }, passives = {}, talentInfo = { { name = "Frostmaw Fury", icon = "Interface\\Icons\\Spell_Frost_FreezingBreath", text = "Your Frost damage is increased by 10%." }, { name = "Thick Winter Pelt", icon = "Interface\\Icons\\INV_Misc_Pelt_Bear_01", text = "Your armor is increased by 15%." }, { name = "Cave Brute Brawn", icon = "Interface\\Icons\\Ability_Druid_Maul", text = "Your Strength is increased by 8%." }, { name = "Breath of the Deep Cave", icon = "Interface\\Icons\\Spell_Frost_ArcticWinds", text = "Your melee attacks have an 8% chance to loose a Frost Breath at your target. Once every 15 sec.\n\nA wendigo does not stop to breathe. Every snarl in close quarters comes out as a gust of cave frost." }, { name = "Avalanche Stomp", icon = "Interface\\Icons\\Ability_BullRush", text = "Your War Stomp reaches 30% farther.\n\nHeavy feet on thin ice: the mountain shakes loose every time a wendigo comes down hard." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Dun Morogh", expansion = 0, order = 4, box = { 0.03, -0.00, 1.23 }, view = { 5.7955, 0.0480, 0.7583 }, skins = { { entry = 2248, name = "Brown", creature = "Cave Yeti", display = 3206, height = 3.6, span = 3.6, box = { 0.04, -0.00, 1.76 } }, { entry = 13602, name = "Gray", creature = "The Abominable Greench", display = 13644, height = 7.2, span = 7.2, box = { 0.07, -0.00, 3.51 } }, { entry = 2452, name = "Black", creature = "Skhowl", display = 1078, height = 4.1, span = 4.1, box = { 0.04, -0.00, 2.02 } } }, title = "Yeti of Dun Morogh" },
    { id = "furbolg", entry = 31, name = "Furbolg", label = "Furbolg", level = 2, display = 145, height = 2.0, span = 2.0, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_Regeneration", profile = "caster", kit = { 9532, 11986, 13585, 13583, 12747, 26066 }, passives = {}, talentInfo = { { name = "Spirits of the Forest", icon = "Interface\\Icons\\Spell_Nature_LightningBolt", text = "Your Nature damage is increased by 8%." }, { name = "Thick Furbolg Hide", icon = "Interface\\Icons\\INV_Misc_Pelt_Bear_03", text = "Your armor is increased by 15%." }, { name = "Shaman's Mending", icon = "Interface\\Icons\\Spell_Nature_HealingWaveGreater", text = "Your healing is increased by 10%." }, { name = "Spirits Stir", icon = "Interface\\Icons\\Spell_Nature_LightningShield", text = "When you are struck, you have a 12% chance to wrap yourself in a Lightning Shield. Once every 30 sec.\n\nThe forest spirits never forgot the furbolgs. Lay a hand on one and the air around it starts to crackle." }, { name = "Timbermaw Remedies", icon = "Interface\\Icons\\Spell_Nature_MagicImmunity", text = "Your Healing Wave costs 20% less.\n\nThe Timbermaw keep the old cures: moss, honey and a word to the spirits, and a hurt furbolg is soon up and growling." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, expansion = 0, order = 1, summons = { [26066] = true }, box = { 0.25, 0.00, 0.98 }, skins = { { entry = 10738, name = "White", creature = "High Chief Winterfall", display = 9491, height = 3.4, span = 3.4, box = { 0.43, 0.00, 1.72 } }, { entry = 2186, name = "Black", creature = "Carnivous the Breaker", display = 5773, height = 2.4, span = 2.4, box = { 0.30, 0.00, 1.18 } }, { entry = 2039, name = "Gray", creature = "Ursal the Mauler", display = 6818, height = 2.6, span = 2.6, box = { 0.32, 0.00, 1.28 } }, { entry = 1993, name = "Blue", creature = "Greenpaw", display = 6819, height = 2.4, span = 2.4, box = { 0.30, 0.00, 1.18 } }, { entry = 6185, name = "Timbermaw", creature = "Timbermaw Warrior", display = 6825, height = 2.6, span = 2.6, box = { 0.32, 0.00, 1.28 } } }, title = "Bear-Man Tribesman" },
    { id = "worgen", entry = 27020, name = "Bloodmoon Worgen", label = "Worgen", level = 74, display = 26787, height = 2.7, span = 2.9, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Mount_WhiteDireWolf", profile = "bruiser", kit = { 53094, 3604, 8715, 32714, 36589, 261 }, passives = {}, talentInfo = { { name = "Bloodmoon Frenzy", icon = "Interface\\Icons\\Ability_Hunter_Pet_Wolf", text = "All damage you deal is increased by 8%." }, { name = "Cursed Resilience", icon = "Interface\\Icons\\Ability_Creature_Cursed_02", text = "Damage you take is reduced by 6%." }, { name = "Rending Claws", icon = "Interface\\Icons\\INV_Misc_MonsterClaw_04", text = "Your chance to land a critical strike is increased by 5%." }, { name = "The Curse Spreads", icon = "Interface\\Icons\\Spell_Shadow_CurseOfMannoroth", text = "Your melee attacks have an 8% chance to deliver an Infected Worgen Bite. Once every 15 sec.\n\nThe moon rises, and the curse runs in your blood. Every scratch of a Bloodmoon worgen carries it a little further." }, { name = "Call the Bloodmoon", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Reduces the cooldown of your Call the Bloodmoon by 30 sec.\n\nOne howl under the full moon and the whole Bloodmoon pack comes loping out of the Grizzly Hills pines." } }, tips = { [261] = "Howl for the pack: two Bloodmoon Worgen answer and fight at your side for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Grizzly Hills", expansion = 2, order = 463, summons = { [261] = true }, box = { 0.20, -0.19, 1.34 }, title = "Worgen of the Grizzly Hills" },
    { id = "satyr", entry = 3758, name = "Felmusk Satyr", label = "Satyr", level = 26, display = 2010, height = 2.8, span = 2.8, school = "shadow", pool = "archetype", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", profile = "glass_cannon", kit = { 6942, 14873, 41176, 11981, 12098, 15087 }, passives = {}, talentInfo = { { name = "Felmusk Claws", icon = "Interface\\Icons\\Ability_Rogue_Eviscerate", text = "Your Physical damage is increased by 8%." }, { name = "Satyr's Cunning", icon = "Interface\\Icons\\Ability_Rogue_SinisterCalling", text = "Your Agility is increased by 8%." }, { name = "Trickster's Edge", icon = "Interface\\Icons\\Ability_Rogue_FindWeakness", text = "Your chance to land a critical strike is increased by 5%." }, { name = "Nightmare Revelry", icon = "Interface\\Icons\\Ability_Rogue_SliceDice", text = "Your attack speed is increased by 6%." }, { name = "Cloud of Musk", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "When you are struck, you have an 8% chance to burn your attacker's mana with a fel bolt. Once every 30 sec.\n\nStrike a satyr and the felmusk bites back: the fel stench sours the magic in your veins." }, { name = "Tricks of Xavius", icon = "Interface\\Icons\\Spell_Nature_Sleep", text = "Reduces the cooldown of Sleep by 15 sec.\n\nThe satyrs learned their tricks from Xavius himself, and a nightmare is always the first trick they reach for." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Ashenvale", expansion = 0, order = 86, box = { -0.78, -0.00, 1.38 }, view = { 1.6069, 0.0000, 0.0660 }, skins = { { entry = 2150, name = "Brown", creature = "Zenn Foulhoof", display = 10035, height = 2.8, span = 2.8, box = { -0.78, -0.00, 1.38 } }, { entry = 4673, name = "Magenta", creature = "Hatefury Betrayer", display = 11331, height = 3.6, span = 3.6, box = { -1.01, -0.00, 1.80 } }, { entry = 14225, name = "Teal", creature = "Prince Kellen", display = 6743, height = 4.2, span = 4.2, box = { -1.17, -0.00, 2.07 } } }, title = "Satyr of Ashenvale" },
    { id = "raptor", entry = 3633, name = "Deviate Stalker", label = "Raptor", level = 15, display = 949, height = 2.8, span = 5.4, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Hunter_Pet_Raptor", profile = "glass_cannon", kit = { 22766, 22120, 11977, 3604, 6605, 8040 }, passives = {}, talentInfo = { { name = "Deviate Ferocity", icon = "Interface\\Icons\\Ability_Hunter_Pet_Raptor", text = "Your Physical damage is increased by 8%." }, { name = "Stalker's Reflexes", icon = "Interface\\Icons\\Ability_Hunter_CatlikeReflexes", text = "Your Agility is increased by 8%." }, { name = "Killing Claws", icon = "Interface\\Icons\\INV_Misc_MonsterClaw_03", text = "Your chance to land a critical strike is increased by 6%." }, { name = "Deviate Frenzy", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "When you are struck, you have a 10% chance to tear into your attacker with Rend. Once every 30 sec.\n\nThe Nightmare twisted the stalkers of the caverns: wound one and it turns on you in a spray of teeth." }, { name = "Pack Hunter's Lunge", icon = "Interface\\Icons\\Ability_Warrior_Charge", text = "Reduces the cooldown of your Charge by 5 sec.\n\nRaptors hunt in relays: one lunges, the next is already running. Alone, a stalker simply lunges twice." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "The Barrens", expansion = 0, order = 26, as = 3634, box = { -0.99, 0.40, 1.34 }, view = { 3.4342, 0.0576, 0.3981 }, skins = { { entry = 1015, name = "Orange", creature = "Highland Raptor", display = 670, height = 1.8, span = 3.5, box = { -0.64, 0.26, 0.87 } }, { entry = 3257, name = "Red", creature = "Ishamuhale", display = 2571, height = 3.3, span = 6.3, box = { -1.17, 0.47, 1.57 } }, { entry = 687, name = "Violet", creature = "Jungle Stalker", display = 11317, height = 4.3, span = 8.2, box = { -1.52, 0.61, 2.05 } }, { entry = 23873, name = "Obsidian", creature = "Goreclaw the Ravenous", display =