    { id = "ogre_mage", entry = 5473, name = "Dunemaul Ogre Mage", label = "Ogre Mage", level = 47, display = 12003, height = 7.7, span = 7.7, school = "fire", pool = "archetype", icon = "Interface\\Icons\\Spell_Fire_FireBolt02", profile = "caster", kit = { 9053, 11436, 6742, 2602, 12748, 261 }, passives = {}, talentInfo = { { name = "Two Heads, Twice the Fire", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "Your Fire damage is increased by 8%." }, { name = "Thick Ogre Skull", icon = "Interface\\Icons\\INV_Misc_Bone_OrcSkull_01", text = "Your maximum health is increased by 8%." }, { name = "Dunemaul Mojo", icon = "Interface\\Icons\\Spell_Arcane_ArcanePotency", text = "Your Intellect is increased by 6%." }, { name = "Ogre Magi Discipline", icon = "Interface\\Icons\\Spell_Arcane_MindMastery", text = "Your Fire spells cost 8% less." }, { name = "Other Head Casts Too", icon = "Interface\\Icons\\Spell_Fire_FlameBolt", text = "Your damaging spells have a 10% chance to loose a second Fireball. Once every 10 sec.\n\nAn ogre mage has two heads and they never agree on anything, except that the fireball was a good idea." }, { name = "Bloodlust Mastery", icon = "Interface\\Icons\\Spell_Nature_BloodLust", text = "Reduces the cooldown of Bloodlust by 20 sec.\n\nMe cast Bloodlust! Now you smash! A Dunemaul mage's whole job is shouting that, so it gets a lot of practice." } }, tips = { [261] = "Me cast, you smash! Bellow for a Dunemaul Brute, who stomps in to fight at your side for 20 sec." }, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Tanaris", expansion = 0, order = 133, summons = { [261] = true }, box = { -0.08, -0.01, 3.80 }, skins = { { entry = 7034, name = "Red", creature = "Firegut Ogre Mage", display = 11550, height = 6.4, span = 6.4, box = { -0.06, -0.00, 3.16 } }, { entry = 818, name = "Gray", creature = "Mai'Zoth", display = 11546, height = 5.9, span = 5.9, box = { -0.06, -0.00, 2.94 } }, { entry = 2453, name = "Tan",