    { id = "giant", entry = 5358, name = "Cliff Giant", label = "Giant", level = 50, display = 12813, height = 11.2, span = 11.8, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_EarthQuake", profile = "tank", kit = { 21071, 45, 5568, 10101, 6524, 22693, 21008 }, passives = {}, talentInfo = { { name = "Mountain's Endurance", icon = "Interface\\Icons\\Spell_Nature_EnchantArmor", text = "Your maximum health is increased by 12%." }, { name = "Hide Like Stone", icon = "Interface\\Icons\\INV_Elemental_Primal_Earth", text = "Your armor is increased by 25%." }, { name = "Earthen Bulwark", icon = "Interface\\Icons\\Spell_Nature_SkinofEarth", text = "Damage you take is reduced by 6%." }, { name = "Looming Colossus", icon = "Interface\\Icons\\Ability_Warrior_Challange", text = "The threat you cause is increased by 30%." }, { name = "Avalanche Arms", icon = "Interface\\Icons\\Spell_Nature_Earthquake", text = "Your melee attacks have a 6% chance to hurl a Boulder at the enemies before you. Once every 15 sec.\n\nA cliff giant is never short of ammunition. Every swing of its maul shakes loose another boulder." }, { name = "The Mountain Falls", icon = "Interface\\Icons\\Ability_WarStomp", text = "Your Ground Tremor reaches 25% farther.\n\nThe mountain falls upon you! When a giant shakes the cliffs of Feralas, the whole slope comes down with it." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Feralas", expansion = 0, order = 150, box = { 0.13, -0.10, 5.55 }, skinName = "Stone", variants = { "giant_frost" }, skins = { { entry = 12206, name = "Crystal", creature = "Primordial Behemoth", display = 12309, height = 10.0, span = 10.6, box = { 0.12, -0.09, 4.98 } } }, title = "Mountain Giant of Feralas" },
    { id = "voidwalker", entry = 1860, name = "Voidwalker", label = "Voidwalker", level = 24, display = 1132, height = 2.7, span = 2.7, school = "shadow", pool = "archetype", icon = "Interface\\Icons\\Spell_Shadow_SummonVoidWalker", profile = "tank", kit = { 37486, 33914, 24614, 33916, 12040, 36472 }, passives = {}, talentInfo = { { name = "Hunger of the Void", icon = "Interface\\Icons\\Spell_Shadow_SummonVoidWalker", text = "Your Shadow damage is increased by 8%." }, { name = "Voidbound Resilience", icon = "Interface\\Icons\\Spell_Shadow_AntiMagicShell", text = "Damage you take is reduced by 8%." }, { name = "Endless Emptiness", icon = "Interface\\Icons\\Spell_Shadow_DemonicFortitude", text = "Your maximum health is increased by 10%." }, { name = "Tormentor", icon = "Interface\\Icons\\Spell_Shadow_GatherShadows", text = "The threat you cause is increased by 40%." }, { name = "Nether Shroud", icon = "Interface\\Icons\\Spell_Shadow_NetherCloak", text = "When you are struck, you have a 6% chance to wrap yourself in Shadow Shield. Once every 45 sec.\n\nA voidwalker is sworn to stand between its master and harm, and the void closes around it when the blows land." }, { name = "Bottomless Hunger", icon = "Interface\\Icons\\Spell_Shadow_Twilight", text = "Reduces the cooldown of Consume Shadows by 10 sec.\n\nThe void hungers. It feeds on the shade of every fight it stands in, and it is never full." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, expansion = 0, order = 74, box = { 0.04, -0.15, 1.41 }, title = "Servant of the Warlock" },
    { id = "infernal", entry = 89, name = "Infernal", label = "Infernal", level = 70, display = 169, height = 4.1, span = 5.5, school = "fire", pool = "archetype", icon = "Interface\\Icons\\Spell_Shadow_SummonInfernal", profile = "tank", kit = { 22703, 70428, 5568, 15062, 261 }, passives = { 37059 }, talentInfo = { { name = "Meteor-Forged Shell", icon = "Interface\\Icons\\Spell_Fire_Volcano", text = "Your armor is increased by 25%." }, { name = "Felfire Heart", icon = "Interface\\Icons\\Spell_Fire_FelFireward", text = "Your Fire resistance is increased by 80." }, { name = "Legion Siege Engine", icon = "Interface\\Icons\\Spell_Fire_MoltenBlood", text = "Your maximum health is increased by 10%." }, { name = "Beacon of Destruction", icon = "Interface\\Icons\\Spell_Fire_Felcano", text = "The threat you cause is increased by 30%." }, { name = "Burning Wake", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "When you are struck, you have an 8% chance to Trample everything around you. Once every 30 sec.\n\nAn Infernal does not notice who strikes it; it only keeps walking, and whatever is underfoot burns." }, { name = "Crater", icon = "Interface\\Icons\\Ability_WarStomp", text = "Increases the radius of your Inferno by 30%.\n\nWhere a Legion comet lands, the crater is always wider than the survivors remember." } }, tips = { [261] = "The sky burns again: a second Infernal crashes down to fight at your side for 20 sec." }, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, expansion = 2, order = 440, summons = { [261] = true }, box = { -0.19, -0.01, 2.08 }, title = "Demon of the Burning Legion" },
    { id = "doomguard", entry = 11859, name = "Doomguard", label = "Doomguard", level = 73, display = 1912, height = 4.9, span = 4.9, school = "shadow", pool = "archetype", icon = "Interface\\Icons\\Spell_Shadow_AntiMagicShell", profile = "bruiser", kit = { 19474, 40876, 21949, 89, 19482, 15090 }, passives = {}, talentInfo = { { name = "Doomlord's Wrath", icon = "Interface\\Icons\\Spell_Shadow_RainOfFire", text = "All damage you deal is increased by 8%." }, { name = "Pact-Bound Hide", icon = "Interface\\Icons\\Spell_Shadow_DemonicPact", text = "Damage you take is reduced by 5%." }, { name = "Strength of the Doomlord", icon = "Interface\\Icons\\Spell_Shadow_UnholyStrength", text = "Your Strength is increased by 8%." }, { name = "Soul Forfeit", icon = "Interface\\Icons\\Spell_Shadow_ScourgeBuild", text = "Your melee attacks have an 8% chance to hurl a Doom Bolt at the target. Once every 20 sec.\n\nYour soul is forfeit to the Legion! A doomguard collects its debts between one swing and the next." }, { name = "Legion's Rain", icon = "Interface\\Icons\\Spell_Fire_MeteorStorm", text = "Increases the radius of your Rain of Fire by 20%.\n\nBound by the Ritual of Doom, a doomguard burns everything within reach of its summoners, and a little more." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = true, wave = 2, expansion = 2, order = 450, box = { -0.81, 0.10, 2.45 }, skins = { { entry = 14535, name = "Blue", creature = "Artorius the Doombringer", display = 2727, height = 4.5, span = 4.5, box = { -0.74, 0.09, 2.25 } } }, title = "Ered'ruin of the Burning Legion" },
    { id = "water_elemental", entry = 510, name = "Water Elemental", label = "Water Elemental", level = 70, display = 525, height = 2.3, span = 2.9, school = "frost", pool = "archetype", icon = "Interface\\Icons\\Spell_Frost_SummonWaterElemental", profile = "caster", kit = { 31707, 33395, 34449, 37250, 34827 }, passives = {}, talentInfo = { { name = "Heart of the Tide", icon = "Interface\\Icons\\Spell_Frost_SummonWaterElemental_2", text = "Your Frost damage is increased by 10%." }, { name = "Fluid Form", icon = "Interface\\Icons\\INV_Elemental_Primal_Water", text = "Damage you take is reduced by 5%." }, { name = "Flowing Current", icon = "Interface\\Icons\\Spell_Frost_IceFloes", text = "Your casting speed is increased by 6%." }, { name = "Dalaran Binding", icon = "Interface\\Icons\\Spell_Frost_WizardMark", text = "Your Frost abilities cost 8% less." }, { name = "Riptide", icon = "Interface\\Icons\\Spell_Frost_IceShard", text = "Your damaging spells have a 10% chance to hurl a Waterbolt at the target. Once every 8 sec.\n\nWater never strikes once. Where one wave breaks, the next is already rolling in behind it." }, { name = "Deep Freeze", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "Your Freeze holds enemies 2 sec. longer.\n\nThe magi of Dalaran bound it from the coldest currents of the sea; its grip is slow to thaw." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, expansion = 0, order = 307, box = { 0.00, 0.00, 1.45 }, skinName = "Tide", variants = { "water_elemental_fouled", "water_elemental_mojo" }, title = "Servant of the Frost Mage" },
