    { id = "air_elemental", entry = 28384, name = "Lesser Air Elemental", label = "Air Elemental", level = 77, display = 21130, height = 1.5, span = 1.5, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_Cyclone", profile = "caster", kit = { 15801, 39587, 32014, 6982, 6728, 12550 }, passives = {}, talentInfo = { { name = "Eye of the Storm", icon = "Interface\\Icons\\Spell_Nature_EyeOfTheStorm", text = "Your Nature damage is increased by 10%." }, { name = "Formless Wind", icon = "Interface\\Icons\\Ability_Druid_GaleWinds", text = "Your chance to dodge is increased by 6%." }, { name = "Howling Gale", icon = "Interface\\Icons\\Spell_Nature_UnrelentingStorm", text = "Your casting speed is increased by 8%." }, { name = "Eye of the Cyclone", icon = "Interface\\Icons\\Spell_Nature_Cyclone", text = "When you are struck, you have a 10% chance to lash your attacker with Wind Shock. Once every 30 sec.\n\nThe storm has no body to strike. Swing at it and the wind answers, slowing the hand that swung." }, { name = "Gathering Gale", icon = "Interface\\Icons\\Spell_Nature_EarthBind", text = "Reduces the cooldown of your Air Burst by 5 sec.\n\nThe winds carry you away! Over the Storm Peaks the next gust is never far behind the last." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, expansion = 2, order = 473, box = { -0.06, -0.01, 0.95 }, skinName = "Gale", variants = { "air_elemental_storm", "air_elemental_dust" }, skins = { { entry = 14454, name = "Cyan", creature = "The Windreaver", display = 14515, height = 8.1, span = 8.4, box = { -0.32, -0.06, 5.20 } } }, title = "Elemental of the Halls of Stone" },
    { id = "core_hound", entry = 11671, name = "Core Hound", label = "Core Hound", level = 61, display = 12168, height = 4.4, span = 7.8, school = "fire", pool = "archetype", icon = "Interface\\Icons\\Ability_Hunter_Pet_CoreHound", profile = "bruiser", kit = { 19272, 19771, 19319, 19391, 7948 }, passives = {}, talentInfo = { { name = "Magmadar's Brood", icon = "Interface\\Icons\\Spell_Fire_LavaSpawn", text = "Your Fire damage is increased by 10%." }, { name = "Molten Hide", icon = "Interface\\Icons\\Spell_Fire_MoltenBlood", text = "Your Fire resistance is increased by 60." }, { name = "Rock-Hard Hide", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Your armor is increased by 15%." }, { name = "Hound's Ferocity", icon = "Interface\\Icons\\Ability_Druid_FerociousBite", text = "Your attack power is increased by 6%." }, { name = "Magma Spittle", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Your melee attacks have an 8% chance to spit a Fireball at the target. Once every 12 sec.\n\nLava runs in a core hound's throat, and a little of it always comes up with the bite." }, { name = "Smouldering Remains", icon = "Interface\\Icons\\Ability_Hunter_Pet_CoreHound", text = "Reduces the cooldown of Smouldering Remains by 30 sec.\n\nKill a Core Hound and it lies still; turn your back and it rises again, unless its whole pack dies together." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Molten Core", expansion = 0, order = 272, box = { -0.29, -0.01, 2.16 }, title = "Servant of the Firelord" },
    { id = "bog_lord", entry = 18127, name = "Bog Lord", label = "Bog Lord", level = 64, display = 18229, height = 12.0, span = 12.0, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_Regeneration", profile = "tank", kit = { 32077, 32065, 5100, 35235, 35238, 54794 }, passives = {}, talentInfo = { { name = "Creeping Rot", icon = "Interface\\Icons\\INV_Mushroom_11", text = "Your Nature damage is increased by 8%." }, { name = "Spongy Hide", icon = "Interface\\Icons\\Spell_Nature_SpiritArmor", text = "Damage you take is reduced by 8%." }, { name = "Rooted Bulk", icon = "Interface\\Icons\\Spell_Nature_StrangleVines", text = "Your maximum health is increased by 12%." }, { name = "Spore Cloud Menace", icon = "Interface\\Icons\\Ability_Hunter_Pet_Sporebat", text = "The threat you cause is increased by 30%." }, { name = "Spreading Spores", icon = "Interface\\Icons\\INV_Mushroom_02", text = "Your melee hits have a 10% chance to coat the target in Fungal Decay. Once every 8 sec.\n\nEvery blow from a Bog Lord leaves spores behind. By morning they have taken root." }, { name = "Deep Roots", icon = "Interface\\Icons\\Spell_Nature_AbolishMagic", text = "Your Osmosis drains 2 sec. longer.\n\nRot and root. The bog reclaims all, and it is in no hurry." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Zangarmarsh", expansion = 1, order = 330, box = { 0.63, 0.06, 5.98 }, skins = { { entry = 17877, name = "Purple", creature = "Fhwoor", display = 18228, height = 6.0, span = 6.0, box = { 0.31, 0.03, 2.99 } }, { entry = 17942, name = "Yellow", creature = "Quagmirran", display = 18224, height = 21.0, span = 21.0, box = { 1.10, 0.10, 10.47 } } }, title = "Fungal Giant of Zangarmarsh" },
    { id = "naga", entry = 17800, name = "Coilfang Myrmidon", label = "Naga", level = 70, display = 18389, height = 5.7, span = 5.7, school = "frost", pool = "archetype", icon = "Interface\\Icons\\Spell_Frost_SummonWaterElemental", profile = "bruiser", kit = { 38358, 15496, 35105, 26141, 22911, 7160 }, passives = {}, talentInfo = { { name = "Coilfang Warcraft", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your Physical damage is increased by 8%." }, { name = "Scales of the Deep", icon = "Interface\\Icons\\INV_Misc_MonsterScales_09", text = "Your armor is increased by 15%." }, { name = "Serpent's Strength", icon = "Interface\\Icons\\Ability_Warrior_StrengthOfArms", text = "Your Strength is increased by 8%." }, { name = "Blood Like Venom", icon = "Interface\\Icons\\Ability_Creature_Poison_03", text = "Your Nature resistance is increased by 40." }, { name = "Myrmidon's Sweep", icon = "Interface\\Icons\\Ability_Rogue_SliceDice", text = "Your melee hits have a 5% chance to sweep into a free Cleave. Once every 30 sec.\n\nMyrmidons fight in the press of the Steamvault's pools, where every swing that misses one warmblood finds another." }, { name = "Tide's Rush", icon = "Interface\\Icons\\Ability_Warrior_Charge", text = "Your Charge's cooldown is 5 sec. shorter.\n\nIn water the naga are faster than anything with legs, and the Coilfang keep their halls flooded for it." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "Coilfang: The Steamvault", expansion = 1, order = 365, charModel = true, box = { -0.85, 0.01, 2.77 }, skins = { { entry = 17798, name = "Warlord", creature = "Warlord Kalithresh", display = 20235, height = 7.2, span = 7.2, box = { -1.06, 0.01, 3.46 }, charModel = true }, { entry = 17957, name = "Champion", creature = "Coilfang Champion", display = 18384, height = 5.7, span = 5.7, box = { -0.85, 0.01, 2.77 }, charModel = true }, { entry = 17735, name = "Wrathfin", creature = "Wrathfin Warrior", display = 18401, height = 4.0, span = 4.0, box = { -0.59, 0.01, 1.94 }, charModel = true }, { entry = 21966, name = "Sharkkis", creature = "Fathom-Guard Sharkkis", display = 20671, height = 8.6, span = 8.6, box = { -1.27, 0.02, 4.16 }, charModel = true }, { entry = 22873, name = "Coilskar", creature = "Coilskar General", display = 21159, height = 5.7, span = 5.7, box = { -0.85, 0.01, 2.77 }, charModel = true } }, title = "Naga of the Steamvault" },
