    { id = "fel_reaver", entry = 18733, name = "Fel Reaver", label = "Fel Reaver", level = 70, display = 18671, height = 42.9, span = 42.9, school = "fire", pool = "archetype", icon = "Interface\\Icons\\Spell_Fire_FelFlameRing", profile = "tank", kit = { 36835, 22911, 19798, 11130, 54794, 43713 }, passives = {}, talentInfo = { { name = "Fel-Iron Hull", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 30%." }, { name = "Relentless Engine", icon = "Interface\\Icons\\Spell_Fire_FelHellfire", text = "Your maximum health is increased by 12%." }, { name = "Unstoppable Machine", icon = "Interface\\Icons\\Ability_Warrior_StalwartProtector", text = "Damage you take is reduced by 6%." }, { name = "Hellfire Juggernaut", icon = "Interface\\Icons\\Spell_Fire_FelFlameRing", text = "The threat you cause is increased by 40%." }, { name = "Pressure Valve", icon = "Interface\\Icons\\Ability_Warrior_Revenge", text = "Hits against you have a 10% chance to set off a Knock Away around you. Once every 12 sec.\n\nCrowd a Fel Reaver and its engine vents the pressure the only way it knows: through you." }, { name = "Reinforced Plating", icon = "Interface\\Icons\\Ability_Warrior_ShieldWall", text = "Your Hardened Skin lasts 5 sec. longer.\n\nBuilt by the Legion to walk through Hellfire's artillery; the plating was never meant to come off." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Hellfire Peninsula", expansion = 1, order = 325, box = { -4.36, -0.00, 21.40 }, title = "Construct of the Burning Legion" },
