    { id = "ghoul", entry = 25393, name = "Ghoul", label = "Ghoul", level = 70, display = 24992, height = 2.3, span = 3.0, school = "shadow", pool = "archetype", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", profile = "glass_cannon", kit = { 12538, 30478, 22911, 36472, 31540, 16458 }, passives = {}, talentInfo = { { name = "Ravenous Hunger", icon = "Interface\\Icons\\Ability_GhoulFrenzy", text = "Your Physical damage is increased by 8%." }, { name = "Rotting Resilience", icon = "Interface\\Icons\\Ability_Creature_Disease_02", text = "Damage you take is reduced by 5%." }, { name = "Frenzied Scavenger", icon = "Interface\\Icons\\Ability_Rogue_SliceDice", text = "Your attack speed is increased by 8%." }, { name = "Grave-Dirt Claws", icon = "Interface\\Icons\\Spell_DeathKnight_Gnaw_Ghoul", text = "Your melee critical strike chance is increased by 5%." }, { name = "The Hunger", icon = "Interface\\Icons\\INV_Misc_MonsterClaw_02", text = "Your melee hits have an 8% chance to set off a Ravenous Claw. Once every 12 sec.\n\nA ghoul does not fight to win. It fights to eat, and every bite makes it hungrier." }, { name = "Pack of the Dead", icon = "Interface\\Icons\\Ability_Druid_ChallangingRoar", text = "Reduces the cooldown of your Frenzy by 15 sec.\n\nAt Hyjal the ghouls came in waves; once one smelled blood, the whole pack fed until it was gone." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Borean Tundra", expansion = 2, order = 433, as = 17895, box = { 0.30, 0.13, 1.10 }, skinName = "Ghoul", variants = { "ghoul_frigid", "ghoul_volatile" }, skins = { { entry = 26621, name = "Gray", creature = "Ghoul Tormentor", display = 24994, height = 2.3, span = 3.0, box = { 0.30, 0.13, 1.10 } } }, title = "Foot Soldier of the Scourge" },
    { id = "gargoyle", entry = 17906, name = "Gargoyle", label = "Gargoyle", level = 70, display = 17311, height = 4.8, span = 10.1, school = "shadow", pool = "archetype", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bat", profile = "bruiser", kit = { 31664, 29903, 13444, 29325, 54722 }, passives = {}, talentInfo = { { name = "Foul Bolt Mastery", icon = "Interface\\Icons\\Spell_Nature_Acid_01", text = "Your Nature damage is increased by 8%." }, { name = "Living Stone Hide", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", text = "Your armor is increased by 20%." }, { name = "Wings of the Necropolis", icon = "Interface\\Icons\\ability_deathknight_summongargoyle", text = "Your movement speed is increased by 10%." }, { name = "Stone-Carved Talons", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your melee critical strike chance is increased by 4%." }, { name = "Corrosive Spittle", icon = "Interface\\Icons\\Spell_Nature_EnchantArmor", text = "Your Acid Volley deals 15% more damage.\n\nGargoyles digest nothing; what they swallow comes back up as acid, and they aim it." }, { name = "Hunter of the Skies", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bat", text = "Your melee hits have a 6% chance to loose a Gargoyle Strike. Once every 20 sec.\n\nBetween dives the gargoyle spits foul bolts; the Scourge made them to hunt from above, not to brawl." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = true, wave = 2, instance = "The Battle for Mount Hyjal", expansion = 1, order = 357, box = { -0.24, -0.00, 3.28 }, skins = { { entry = 10506, name = "Black", creature = "Kirtonos the Herald", display = 7534, height = 3.2, span = 6.7, box = { -0.16, -0.00, 2.19 } }, { entry = 10809, name = "Blue", creature = "Stonespine", display = 7856, height = 4.2, span = 8.7, box = { -0.21, -0.00, 2.85 } }, { entry = 30482, name = "Onyx", creature = "Wrathstrike Gargoyle", display = 26801, height = 4.8, span = 10.1, box = { -0.24, -0.00, 3.28 } }, { entry = 32472, name = "Azure", creature = "Ebon Blade Gargoyle", display = 26802, height = 4.8, span = 10.1, box = { -0.24, -0.00, 3.28 } }, { entry = 32292, name = "Ivory", creature = "Aldur'thar Sentry", display = 26800, height = 4.8, span = 10.1, box = { -0.24, -0.00, 3.28 } } }, title = "Winged Servant of the Scourge" },
    { id = "frost_wyrm", entry = 26841, name = "Frost Wyrm", label = "Frost Wyrm", level = 72, display = 24166, height = 10.8, span = 21.6, school = "frost", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Blue", profile = "caster", kit = { 31688, 60542, 21098, 62666, 15063 }, passives = {}, talentInfo = { { name = "Breath of the Frostbrood", icon = "Interface\\Icons\\Spell_Frost_FreezingBreath", text = "Your Frost damage is increased by 10%." }, { name = "Frostbrood Bones", icon = "Interface\\Icons\\Spell_Frost_FrostWard", text = "Your Frost resistance is increased by 60." }, { name = "Icecrown Chill", icon = "Interface\\Icons\\Spell_Frost_FrostShock", text = "Your spell critical strike chance is increased by 5%." }, { name = "Wyrmbone Frame", icon = "Interface\\Icons\\Spell_Frost_FrostArmor02", text = "Damage you take is reduced by 5%." }, { name = "Killing Cold", icon = "Interface\\Icons\\Spell_Frost_Glacier", text = "When you are struck, you have a 10% chance to set off a Chill around you. Once every 20 sec.\n\nNo blood runs in a frost wyrm; only the cold of Icecrown, and it bites whoever comes close." }, { name = "Deep Breath", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Increases the damage of Frost Breath by 15%.\n\nRaised by the Lich King from the bones of the fallen blue flight, the Frostbrood still breathe like dragons." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = true, wave = 2, zone = "Dragonblight", expansion = 2, order = 453, as = 17907, box = { -3.26, -0.03, 5.03 }, title = "Undead Dragon of the Scourge" },
    { id = "vrykul", entry = 23652, name = "Dragonflayer Vrykul", label = "Vrykul", level = 69, display = 21917, height = 5.2, span = 5.2, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Achievement_Dungeon_UtgardeKeep_Normal", profile = "bruiser", kit = { 43410, 42724, 38557, 24193, 42708, 32714 }, passives = {}, talentInfo = { { name = "Dragonflayer Savagery", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your Physical damage is increased by 8%." }, { name = "Blood of Ymir", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 8%." }, { name = "Utgarde Berserker", icon = "Interface\\Icons\\Ability_Racial_BloodRage", text = "Your attack speed is increased by 8%." }, { name = "Fury of the Fjord", icon = "Interface\\Icons\\INV_Axe_09", text = "Your melee attacks have an 8% chance to Chop the target. Once every 20 sec.\n\nFor Ymir! A Dragonflayer does not swing once when twice will do." }, { name = "Ymir's Endless Rage", icon = "Interface\\Icons\\Ability_Druid_Enrage", text = "Reduces the cooldown of your Enrage by 15 sec.\n\nThe rage of the first vrykul burns long in the blood of Utgarde's sons." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Howling Fjord", expansion = 2, order = 439, charModel = true, box = { -0.31, -0.02, 2.48 }, skinName = "Berserker", variants = { "vrykul_runeseer", "vrykul_ymirjar", "vrykul_harpooner" }, skins = { { entry = 23961, name = "Ironhelm", creature = "Dragonflayer Ironhelm", display = 22281, height = 5.2, span = 5.2, box = { -0.31, -0.02, 2.48 }, charModel = true }, { entry = 24238, name = "Skorn", creature = "Bjorn Halgurdsson", display = 22232, height = 7.8, span = 7.8, box = { -0.47, -0.04, 3.72 }, charModel = true } }, title = "Vrykul of Wyrmskull Village" },
