    { id = "garrosh", entry = 25237, name = "Garrosh Hellscream", label = "Garrosh Hellscream", level = 70, display = 23006, height = 2.8, span = 2.8, school = "physical", pool = "leader", icon = "Interface\\Icons\\INV_Misc_Head_Orc_01", profile = "bruiser", kit = { 62444, 22911, 65931, 9128, 28371, 261, 42332 }, passives = {}, talentInfo = { { name = "Son of Hellscream", icon = "Interface\\Icons\\Ability_Warrior_Bladestorm", text = "Your attack power is increased by 10%." }, { name = "Mag'har Ferocity", icon = "Interface\\Icons\\Ability_Warrior_OffensiveStance", text = "Your chance to land a critical strike is increased by 5%." }, { name = "Twin Axes of the Warsong", icon = "Interface\\Icons\\Ability_DualWield", text = "Your attack speed is increased by 8%." }, { name = "Kor'kron Warplate", icon = "Interface\\Icons\\Ability_Warrior_ShieldWall", text = "Your armor is increased by 15%." }, { name = "Blood of Hellscream", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "When you are struck, you have a 10% chance to fly into the Hellscream fury. Once every 30 sec.\n\nGrom's blood runs hot in his son. Wound Garrosh and you only feed the fury." }, { name = "Warsong Muster", icon = "Interface\\Icons\\inv_misc_tournaments_banner_orc", text = "Reduces the cooldown of your Warsong Honor Guard by 15 sec.\n\nThe Overlord of the Warsong Offensive never has to call twice. His guard is already running." } }, tips = { [261] = "Propose? I will show you what I propose! Two Warsong Honor Guards take the field at your side for 30 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, zone = "Borean Tundra", expansion = 2, order = 432, summons = { [261] = true }, charModel = true, box = { 0.01, -0.01, 1.41 }, title = "Overlord of the Warsong Offensive" },
    { id = "bolvar", entry = 1748, name = "Highlord Bolvar Fordragon", label = "Highlord Bolvar Fordragon", level = 73, display = 5566, height = 2.1, span = 2.1, school = "holy", pool = "leader", icon = "Interface\\Icons\\Spell_Holy_AvengersShield", profile = "tank", kit = { 32674, 66007, 15493, 66010, 17143, 37486, 41104 }, passives = {}, talentInfo = { { name = "Bulwark of Stormwind", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Damage you take is reduced by 8%." }, { name = "Highlord's Shield", icon = "Interface\\Icons\\Ability_Defend", text = "Your chance to block is increased by 8%." }, { name = "Righteous Fury of Fordragon", icon = "Interface\\Icons\\Spell_Holy_SealOfFury", text = "The threat you cause is increased by 30%." }, { name = "Fordragon's Fortitude", icon = "Interface\\Icons\\Spell_Holy_WordFortitude", text = "Your maximum health is increased by 10%." }, { name = "Stormwind Stands Firm", icon = "Interface\\Icons\\Spell_Holy_InnerFire", text = "Your melee hits have a 10% chance to follow with a Holy Strike. Once every 15 sec.\n\nWhere the Highlord plants his feet, the Light comes down on the enemies of Stormwind twice." }, { name = "Shield of the Highlord", icon = "Interface\\Icons\\Spell_Holy_AvengersShield", text = "Your Avenger's Shield leaps to 1 more target.\n\nThe Light will not abandon us! Bolvar's shield finds one more foe before it returns to his arm." } }, tips = {}, visualKit = 154, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, expansion = 0, order = 308, charModel = true, box = { -0.10, -0.00, 1.06 }, title = "Regent of Stormwind" },
    { id = "arthas", entry = 26499, name = "Arthas", label = "Prince Arthas", level = 80, display = 24949, height = 2.4, span = 2.4, school = "holy", pool = "leader", icon = "Interface\\Icons\\Spell_Holy_SealOfMight", profile = "bruiser", kit = { 14518, 52445, 43429, 32772, 52444, 261, 33625 }, passives = {}, talentInfo = { { name = "Purge of Stratholme", icon = "Interface\\Icons\\Spell_Holy_Excorcism_02", text = "Your Holy damage is increased by 10%." }, { name = "Vigor of the Crown Prince", icon = "Interface\\Icons\\Spell_Holy_FistOfJustice", text = "Your Strength is increased by 8%." }, { name = "Crusader's Zeal", icon = "Interface\\Icons\\Spell_Holy_CrusaderStrike", text = "Your attack speed is increased by 8%." }, { name = "Unwavering Command", icon = "Interface\\Icons\\Spell_Holy_SealOfMight", text = "Damage you take is reduced by 5%." }, { name = "This City Must Be Purged", icon = "Interface\\Icons\\Spell_Holy_SealOfWrath", text = "Reduces the cooldown of The Culling by 15 sec.\n\nUther called it treason. Arthas called it mercy, and the men who followed him into Stratholme never had long to wait for the order." }, { name = "A Clean Death", icon = "Interface\\Icons\\Ability_ThunderClap", text = "Increases the damage of Hammer of Wrath by 20%.\n\nI can only help you with a clean death. The prince never hesitates at the last blow." } }, tips = { [261] = "Those of you who have the will to save this land, follow me! Two Lordaeron Footmen march with you for 30 sec." }, visualKit = 154, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, instance = "The Culling of Stratholme", expansion = 2, order = 507, summons = { [261] = true }, box = { -0.17, -0.00, 1.19 }, voices = { { 12828, 1.8, false, "Glad you could make it, Uther." }, { 12829, 5.0, false, "As if I could forget. Listen, Uther, there's something about the plague you should know..." }, { 12830, 9.9, false, "Oh, no. We're too late. These people have all been infected! They may look fine now, but it's just a matter of time before they turn into the undead!" }, { 12831, 2.3, false, "This entire city must be purged." }, { 12832, 4.4, false, "Damn it, Uther! As your future king, I order you to purge this city!" }, { 12833, 3.7, false, "Then I must consider this an act of treason." }, { 12834, 10.9, false, "Have I? Lord Uther, by my right of succession and the sovereignty of my crown, I hereby relieve you of your command and suspend your paladins from service." }, { 12835, 8.6, false, "It's done! Those of you who have the will to save this land, follow me! The rest of you... get out of my sight!" }, { 12836, 0.6, false, "Jaina?" }, { 14327, 9.8, true, "Take position here, and I will lead a small force inside Stratholme to begin the culling. We must contain and purge the infected for the sake of all of Lordaeron!" }, { 14293, 11.7, false, "Everyone looks ready. Remember, these people are all infected with the plague and will die soon. We must purge Stratholme to protect the remainder of Lordaeron from the Scourge. Let's go." }, { 14294, 2.3, false, "I can only help you with a clean death." } }, title = "Prince of Lordaeron" },
    { id = "uther", entry = 26528, name = "Uther the Lightbringer", label = "Uther the Lightbringer", level = 80, display = 23889, height = 2.6, span = 2.6, school = "holy", pool = "leader", icon = "Interface\\Icons\\Spell_Holy_LayOnHands", profile = "tank", kit = { 66005, 43429, 15493, 17233, 66010, 261, 37486 }, passives = { 52442 }, talentInfo = { { name = "The Lightbringer", icon = "Interface\\Icons\\Spell_Holy_FlashHeal", text = "Your healing is increased by 15%." }, { name = "Shield of the Silver Hand", icon = "Interface\\Icons\\Spell_Holy_DivineIntervention", text = "Damage you take is reduced by 10%." }, { name = "Righteous Fury of the Order", icon = "Interface\\Icons\\Spell_Holy_SealOfFury", text = "You generate 30% more threat." }, { name = "Devotion of the First Paladin", icon = "Interface\\Icons\\Spell_Holy_DevotionAura", text = "Your armor is increased by 15%." }, { name = "Judgement of the Silver Hand", icon = "Interface\\Icons\\Spell_Holy_RighteousnessAura", text = "Your melee hits have a 10% chance to pass Judgement on the target. Once every 10 sec.\n\nUther taught every paladin of the order to judge before striking. He never stopped doing both at once." }, { name = "Hands of the Lightbringer", icon = "Interface\\Icons\\Spell_Holy_LayOnHands", text = "Reduces the cooldown of your Lay on Hands by 60 sec.\n\nThe Light shall mend what darkness breaks, and the first paladin is never long without it." } }, tips = { [261] = "Watch your tone with me, boy. Two Knights of the Silver Hand answer their order's first paladin and fight at your side for 30 sec." }, visualKit = 154, soundTransform = 0, soundDeath = 0, flies = false, wave = 2, expansion = 2, order = 484, summons = { [261] = true }, charModel = true, box = { -0.13, -0.01, 1.28 }, voices = { { 12839, 6.3, false, "Watch your tone with me, boy. You may be the prince, but I'm still your superior as a paladin!" }, { 12840, 0.5, false, "What?" }, { 12841, 3.7, false, "How can you even consider that? There's got to be some other way." }, { 12842, 5.5, false, "You are not my king yet, boy! Nor would I obey that command even if you were!" }, { 12843, 3.9, false, "Treason? Have you lost your mind, Arthas?" }, { 12844, 3.5, false, "You've just crossed a terrible threshold, Arthas." } }, title = "Knight of the Silver Hand" },
    { id = "lucifron", entry = 12118, name = "Lucifron", label = "Lucifron", level = 63, display = 13031, height = 9.2, span = 9.2, school = "shadow", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Shadow_NightOfTheDead", profile = "caster", kit = { 19702, 20603, 19703, 30002, 261 }, passives = {}, talentInfo = { { name = "Herald of Impending Doom", icon = "Interface\\Icons\\Spell_Shadow_CurseOfMannoroth", text = "Your Shadow damage is increased by 10%." }, { name = "Flamewaker Hide", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Damage you take is reduced by 5%." }, { name = "Accursed Tongue", icon = "Interface\\Icons\\Spell_Shadow_CurseOfTounges", text = "Your casting speed is increased by 5%." }, { name = "Doom Spreads", icon = "Interface\\Icons\\Spell_Shadow_BlackPlague", text = "Your damaging spells have a 10% chance to loose a Shadow Shock at the enemies around you. Once every 30 sec.\n\nEvery raid that comes to Lucifron brings its decursers. It is never enough: his doom finds whoever they missed." }, { name = "Doom Comes Sooner", icon = "Interface\\Icons\\Spell_Shadow_NightOfTheDead", text = "Reduces the cooldown of Impending Doom by 5 sec.\n\nYour doom is already upon you, mortal. Lucifron only decides when it lands." } }, tips = { [261] = "Call the two Flamewaker Protectors who guard the first gate of the Core to fight beside you for 20 sec." }, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Molten Core", expansion = 0, order = 277, summons = { [261] = true }, box = { -1.32, -0.04, 4.45 }, title = "Flamewaker Captain of Ragnaros" },
    { id = "magmadar", entry = 11982, name = "Magmadar", label = "Magmadar", level = 63, display = 10193, height = 13.1, span = 23.4, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\Ability_Hunter_Pet_CoreHound", profile = "bruiser", kit = { 19272, 19408, 19451, 16419 }, passives = { 19449 }, talentInfo = { { name = "Molten Maw", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Your Fire damage is increased by 10%." }, { name = "Core Hound Hide", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your armor is increased by 15%." }, { name = "Killing Frenzy", icon = "Interface\\Icons\\Ability_Racial_BloodRage", text = "Your attack speed is increased by 6%." }, { name = "Breath of the Core", icon = "Interface\\Icons\\Spell_Fire_WindsofWoe", text = "Your melee attacks have an 8% chance to loose a Lava Breath. Once every 15 sec.\n\nMagmadar's jaws are never empty; every bite spills the lava that rises in his throat." }, { name = "Father of the Core Hounds", icon = "Interface\\Icons\\Spell_Shadow_DeathScream", text = "Increases the damage of your Lava Breath by 15%.\n\nEvery Core Hound in the depths learned to breathe fire from its father, and none of them breathes it as hot." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Molten Core", expansion = 0, order = 278, box = { -0.86, -0.02, 6.49 }, view = { -10.7105, 0.1997, 3.2805 }, title = "Father of the Core Hounds" },
    { id = "gehennas", entry = 12259, name = "Gehennas", label = "Gehennas", level = 63, display = 13030, height = 9.2, span = 9.2, school = "shadow", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", profile = "caster", kit = { 19728, 19717, 36917, 20277, 261 }, passives = {}, talentInfo = { { name = "Rain of the Firelord", icon = "Interface\\Icons\\Spell_Fire_MeteorStorm", text = "Your Fire damage is increased by 10%." }, { name = "Gehennas' Malice", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 5%." }, { name = "Brimstone Ward", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Damage you take is reduced by 5%." }, { name = "Malice of the Flamewaker", icon = "Interface\\Icons\\Spell_Shadow_Shadowfury", text = "Your damaging spells have a 10% chance to hurl a Shadow Bolt at the target. Once every 12 sec.\n\nGehennas never throws one bolt when two will do: the second always goes to whoever the healers were saving." }, { name = "Burn Beneath the Rain", icon = "Interface\\Icons\\Spell_Shadow_RainOfFire", text = "Increases the radius of Rain of Fire by 30%.\n\nThe Firelord's rain falls wide. There is no dry ground in Gehennas' chamber." } }, tips = { [261] = "Call two Flamewakers from Gehennas' guard to fight beside you for 20 sec." }, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Molten Core", expansion = 0, order = 275, summons = { [261] = true }, box = { -1.32, -0.04, 4.45 }, title = "Flamewaker of the Firelord" },
    { id = "garr", entry = 12057, name = "Garr", label = "Garr", level = 63, display = 12110, height = 10.4, span = 13.4, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Nature_EarthBind", profile = "tank", kit = { 19492, 19496, 19497, 19953, 261, 37548 }, passives = {}, talentInfo = { { name = "Obsidian Hide", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", text = "Your armor is increased by 15%." }, { name = "Living Fortress", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Fury of the Fallen", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", text = "Your attack speed is increased by 5%." }, { name = "Firesworn Eruption", icon = "Interface\\Icons\\Spell_Fire_Volcano", text = "When you are struck, you have a 10% chance to Erupt. Once every 20 sec.\n\nGarr's Firesworn burst when they fall. Something of that fire lives in the stone lieutenant himself." }, { name = "Bound Elementals", icon = "Interface\\Icons\\Spell_Fire_LavaSpawn", text = "Reduces the cooldown of Call the Firesworn by 30 sec.\n\nThe Firesworn are bound to Garr; stray too far and they rage, so they never stray. They come the moment he calls." } }, tips = { [19953] = "The fire of your fallen Firesworn becomes yours: your physical damage rises by 500 and your attack speed by 50% for 10 sec.", [261] = "Call two Firesworn, the elementals bound to you, to fight at your side for 20 sec." }, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Molten Core", expansion = 0, order = 274, summons = { [261] = true }, box = { -0.06, -0.18, 4.79 }, view = { -5.4924, 0.0000, 1.2320 }, title = "Lieutenant of Ragnaros" },
    { id = "shazzrah", entry = 12264, name = "Shazzrah", label = "Shazzrah", level = 63, display = 13032, height = 9.2, span = 9.2, school = "arcane", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Nature_WispSplode", profile = "caster", kit = { 19712, 19715, 12738, 19714, 29211 }, passives = {}, talentInfo = { { name = "Arcane Inferno", icon = "Interface\\Icons\\Spell_Arcane_StarFire", text = "Your Arcane damage is increased by 10%." }, { name = "Grounded in Flame", icon = "Interface\\Icons\\Spell_Nature_AbolishMagic", text = "Damage you take is reduced by 5%." }, { name = "Sorcerer of the Core", icon = "Interface\\Icons\\Spell_Arcane_ArcanePotency", text = "Your casting speed is increased by 5%." }, { name = "Arcane Overflow", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Your damaging spells have a 10% chance to loose an Arcane Explosion around you. Once every 30 sec.\n\nShazzrah's magic does not only burn; it spills over, and whoever stands near the arcanist feels it." }, { name = "The Blinking Sorcerer", icon = "Interface\\Icons\\Spell_Arcane_PortalIronForge", text = "Reduces the cooldown of Gate of Shazzrah by 5 sec.\n\nRaids that tanked Shazzrah learned to stand spread: he was never where they left him for long." } }, tips = {}, visualKit = 1005, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Molten Core", expansion = 0, order = 281, box = { -1.32, -0.04, 4.45 }, view = { -4.0367, 0.0000, 0.7700 }, title = "Arcanist of the Flamewakers" },
    { id = "golemagg", entry = 11988, name = "Golemagg the Incinerator", label = "Golemagg the Incinerator", level = 63, display = 11986, height = 23.1, span = 24.5, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Nature_EarthQuake", profile = "tank", kit = { 20228, 19798, 18945, 8269, 261, 37548 }, passives = { 13879 }, talentInfo = { { name = "Bulk of the Molten Giant", icon = "Interface\\Icons\\Spell_Nature_EarthBindTotem", text = "Your maximum health is increased by 10%." }, { name = "Magma Skin", icon = "Interface\\Icons\\Spell_Fire_LavaSpawn", text = "Your armor is increased by 15%." }, { name = "Incinerator's Fury", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "Your Fire damage is increased by 8%." }, { name = "The Incinerator", icon = "Interface\\Icons\\Spell_Fire_FlameBolt", text = "Your melee attacks have an 8% chance to hurl a Pyroblast at the target. Once every 15 sec.\n\nGolemagg does not need to stop swinging to set you alight; the fire simply leaves his fist." }, { name = "Golemagg's Trust", icon = "Interface\\Icons\\Ability_Hunter_Pet_Wolf", text = "Reduces the cooldown of Call the Core Ragers by 30 sec.\n\nThe Core Ragers draw strength from their master and cannot die while he lives. They come the moment he stirs." } }, tips = { [261] = "Call two of your Core Ragers, the hounds that never leave the Incinerator's side, to fight for you for 20 sec." }, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Molten Core", expansion = 0, order = 276, summons = { [261] = true }, box = { 0.27, -0.21, 11.49 }, title = "Molten Giant of Ragnaros" },
    { id = "sulfuron", entry = 12098, name = "Sulfuron Harbinger", label = "Sulfuron Harbinger", level = 63, display = 13030, height = 9.2, span = 9.2, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\INV_Hammer_Unique_Sulfuras", profile = "caster", kit = { 19781, 19780, 19778, 19779, 261 }, passives = {}, talentInfo = { { name = "Herald of the Flame", icon = "Interface\\Icons\\Spell_Fire_SealOfFire", text = "Your Fire damage is increased by 10%." }, { name = "Harbinger's Hide", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Damage you take is reduced by 5%." }, { name = "Voice of Ragnaros", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire spells and abilities cost 8% less." }, { name = "Harbinger's Spear", icon = "Interface\\Icons\\Ability_Throw", text = "Your damaging spells have a 10% chance to hurl a Flame Spear at the target. Once every 12 sec.\n\nThe Harbinger always has another spear, and every one of them is on fire." }, { name = "Rite of the Flamewakers", icon = "Interface\\Icons\\Spell_Shadow_ChillTouch", text = "Reduces the cooldown of Flamewaker Priests by 30 sec.\n\nSulfuron's priests keep the Harbinger standing; while one lives he will not fall, and they come quickly when he calls." } }, tips = { [261] = "Call two of the Flamewaker Priests who serve the Harbinger to fight beside you for 20 sec." }, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Molten Core", expansion = 0, order = 282, summons = { [261] = true }, box = { -1.32, -0.04, 4.45 }, view = { -4.0367, 0.0000, 0.7700 }, title = "Herald of Ragnaros" },
    { id = "razorgore", entry = 12435, name = "Razorgore the Untamed", label = "Razorgore the Untamed", level = 63, display = 10115, height = 9.8, span = 14.8, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", profile = "bruiser", kit = { 19632, 22425, 24375, 23023, 261 }, passives = {}, talentInfo = { { name = "Brood Guardian's Fire", icon = "Interface\\Icons\\Spell_Fire_FlameBolt", text = "Your Fire damage is increased by 10%." }, { name = "Untamed Hide", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Your armor is increased by 15%." }, { name = "Warden of the Eggs", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", text = "Your maximum health is increased by 8%." }, { name = "Precious Eggs", icon = "Interface\\Icons\\Ability_WarStomp", text = "When you are struck, you have a 10% chance to loose a Fireball Volley at the enemies around you. Once every 30 sec.\n\nFools! These eggs are more precious than you know. Come near the brood and the brood's guardian answers in fire." }, { name = "Untamed Fury", icon = "Interface\\Icons\\Spell_Fire_FlameShock", text = "Reduces the cooldown of your Fireball Volley by 4 sec.\n\nFreed of Grethok's orb, Razorgore pays back every moment of his captivity in fire." } }, tips = { [261] = "Roar for the brood's guardians: two Death Talon Dragonspawn charge in to fight at your side for 20 sec." }, visualKit = 286, soundTransform = 8275, soundDeath = 8278, flies = false, wave = 3, instance = "Blackwing Lair", expansion = 0, order = 296, summons = { [261] = true }, box = { -1.30, -1.14, 4.84 }, view = { -6.2229, 0.0000, 0.8808 }, voices = { { 8275, 2.8, true, "You'll pay for forcing me to do this!" }, { 8276, 4.2, true, "Fools! These eggs are more precious than you know!" }, { 8277, 4.6, true, "No - not another one! I'll have your heads for this atrocity!" }, { 8278, 5.3, true, "If I fall into the abyss, I'll take all of you mortals with me!" } }, title = "Guardian of the Black Dragon Eggs" },
    { id = "broodlord", entry = 12017, name = "Broodlord Lashlayer", label = "Broodlord Lashlayer", level = 63, display = 14308, height = 8.7, span = 9.7, school = "physical", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", profile = "bruiser", kit = { 24573, 261, 23331, 25778 }, passives = {}, talentInfo = { { name = "Lashlayer's Halberd", icon = "Interface\\Icons\\Ability_Warrior_SavageBlow", text = "Your Physical damage is increased by 10%." }, { name = "Dragonspawn Plate", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Warden of the Sanctum", icon = "Interface\\Icons\\Ability_Warrior_Riposte", text = "Your chance to parry is increased by 5%." }, { name = "Broodlord's Onslaught", icon = "Interface\\Icons\\Ability_Warrior_Decisivestrike", text = "Your chance to land a critical strike in melee is increased by 5%." }, { name = "Blast of the Black Flight", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "When you are struck, you have a 10% chance to answer with a Blast Wave. Once every 20 sec.\n\nCrowd the Broodlord in his sanctum and the black flight's fire throws you back out, burned and slowed." }, { name = "Not So Easily Lured", icon = "Interface\\Icons\\Ability_Warrior_PunishingBlow", text = "Reduces the cooldown of your Knock Away by 4 sec.\n\nClever mortals keep trying to drag him from his sanctum. He keeps knocking them back into it." } }, tips = { [261] = "Summon the guards of your sanctum: two Death Talon Wyrmguards fight at your side for 20 sec." }, visualKit = 437, soundTransform = 8286, soundDeath = 0, flies = false, wave = 3, instance = "Blackwing Lair", expansion = 0, order = 289, summons = { [261] = true }, box = { -1.02, 1.63, 4.37 }, voices = { { 8286, 5.3, true, "None of your kind should be here! You've doomed only yourselves!" }, { 8287, 6.4, true, "Clever, mortals - but I am not so easily lured away from my sanctum!" } }, title = "Drakonid Servant of Nefarian" },
    { id = "firemaw", entry = 11983, name = "Firemaw", label = "Firemaw", level = 63, display = 6377, height = 15.7, span = 26.5, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", profile = "bruiser", kit = { 22539, 23341, 23339, 11350 }, passives = {}, talentInfo = { { name = "Firemaw's Breath", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire damage is increased by 10%." }, { name = "Black Drake Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "All damage you take is reduced by 6%." }, { name = "Fireproof Hide", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Your Fire resistance is increased by 50." }, { name = "Ceaseless Buffet", icon = "Interface\\Icons\\Spell_Fire_Fireball", text = "Your melee hits have a 10% chance to set off a Flame Buffet. Once every 20 sec.\n\nFiremaw never stops burning. Stand near him long enough and the fire finds a way through any cloak." }, { name = "Wings of the Black Flight", icon = "Interface\\Icons\\Ability_Hunter_Pet_DragonHawk", text = "Reduces the cooldown of your Wing Buffet by 5 sec.\n\nA beat of Firemaw's wings clears the ledge before the tank has found his feet." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = true, wave = 3, instance = "Blackwing Lair", expansion = 0, order = 292, box = { -2.41, -0.00, 7.12 }, view = { -10.2082, 0.0000, 2.6730 }, title = "Black Drake of Blackwing Lair" },
    { id = "ebonroc", entry = 14601, name = "Ebonroc", label = "Ebonroc", level = 63, display = 6377, height = 15.7, span = 26.5, school = "shadow", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", profile = "bruiser", kit = { 22539, 24585, 23339 }, passives = { 20809 }, talentInfo = { { name = "Ebon Shadowflame", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 10%." }, { name = "Shadowed Hide", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "All damage you take is reduced by 6%." }, { name = "Shadow of the Black Flight", icon = "Interface\\Icons\\Spell_Shadow_ShadowWard", text = "Your Shadow resistance is increased by 50." }, { name = "Your Wounds Will Mend Me", icon = "Interface\\Icons\\Spell_Shadow_GatherShadows", text = "Your melee hits have a 10% chance to Drain Life from the target. Once every 15 sec.\n\nYour wounds will mend my shadowed hide. Every claw Ebonroc sinks in feeds him." }, { name = "Thrashing Hunger", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain", text = "Reduces the cooldown of your Drain Life by 3 sec.\n\nThe hungrier the drake, the sooner it feeds again; Ebonroc is always hungry." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = true, wave = 3, instance = "Blackwing Lair", expansion = 0, order = 291, box = { -2.41, -0.00, 7.12 }, view = { -8.0882, 0.0000, 2.6730 }, title = "Black Drake of Blackwing Lair" },
    { id = "flamegor", entry = 11981, name = "Flamegor", label = "Flamegor", level = 63, display = 6377, height = 15.7, span = 26.5, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", profile = "bruiser", kit = { 22539, 23342, 23339, 23462 }, passives = {}, talentInfo = { { name = "Blood of the Black Brood", icon = "Interface\\Icons\\Spell_Shadow_UnholyStrength", text = "Your attack power is increased by 8%." }, { name = "Seared Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "All damage you take is reduced by 6%." }, { name = "Ember Hide", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Your Fire resistance is increased by 40." }, { name = "Frenzy Unchecked", icon = "Interface\\Icons\\Ability_Druid_ChallangingRoar", text = "Reduces the cooldown of your Enrage by 10 sec.\n\nHunters took turns calming Flamegor with their darts. When they missed, the next frenzy came all the sooner." }, { name = "Scorching Wings", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "When you are struck, you have a 10% chance to answer with a Wing Buffet. Once every 30 sec.\n\nCrowd a frenzied drake and the wings come first; the fire follows." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = true, wave = 3, instance = "Blackwing Lair", expansion = 0, order = 293, box = { -2.41, -0.00, 7.12 }, view = { -10.2082, -0.2261, 2.6165 }, title = "Black Drake of Blackwing Lair" },
    { id = "mandokir", entry = 11382, name = "Bloodlord Mandokir", label = "Bloodlord Mandokir", level = 63, display = 11288, height = 5.3, span = 5.3, school = "physical", pool = "classic_raid", icon = "Interface\\Icons\\Ability_Mount_Raptor", profile = "bruiser", kit = { 16856, 13736, 24408, 19134, 48193, 261 }, passives = {}, talentInfo = { { name = "Bloodlord's Edge", icon = "Interface\\Icons\\INV_Sword_48", text = "Your Physical damage is increased by 10%." }, { name = "Raptor Rider's Plate", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Champion of Hakkar", icon = "Interface\\Icons\\Ability_Warrior_BloodFrenzy", text = "Your chance to land a critical strike in melee is increased by 5%." }, { name = "Threatening Gaze", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "When you are struck, you have a 10% chance to answer with a Mortal Strike. Once every 20 sec.\n\nThe Bloodlord is watching. Whoever raises a hand against him had better not blink, because Mandokir already has." }, { name = "Ohgan's Loyalty", icon = "Interface\\Icons\\Ability_Mount_Raptor", text = "Reduces the cooldown of Ohgan, to Me! by 30 sec.\n\nMandokir rode Ohgan into every battle of the Gurubashi. One whistle, and the raptor is back at his side." } }, tips = { [261] = "Whistle for Ohgan: your raptor bounds to your side and fights for 20 sec." }, visualKit = 437, soundTransform = 8413, soundDeath = 0, flies = false, wave = 3, instance = "Zul'Gurub", expansion = 0, order = 251, summons = { [261] = true }, charModel = true, box = { -0.06, 0.07, 2.64 }, voices = { { 8413, 3.3, true, "I'll feed your souls to Hakkar himself!" } }, title = "Leader of the Gurubashi Tribe" },
    { id = "thekal", entry = 14509, name = "High Priest Thekal", label = "High Priest Thekal", level = 63, display = 15216, height = 3.7, span = 3.7, school = "physical", pool = "classic_raid", icon = "Interface\\Icons\\Ability_Mount_JungleTiger", profile = "bruiser", kit = { 22859, 22666, 24185, 6713, 261 }, passives = {}, talentInfo = { { name = "Blessing of Thekal", icon = "Interface\\Icons\\Ability_Mount_JungleTiger", text = "Your attack power is increased by 8%." }, { name = "Gurubashi Steel", icon = "Interface\\Icons\\Ability_Parry", text = "Your chance to parry is increased by 5%." }, { name = "Zealot's Resolve", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Damage you take is reduced by 4%." }, { name = "Zulian Vigor", icon = "Interface\\Icons\\Spell_Nature_BloodLust", text = "Your maximum health is increased by 6%." }, { name = "Shirvallah's Fury", icon = "Interface\\Icons\\Ability_Warrior_SavageBlow", text = "Your melee hits have an 8% chance to follow through with a Mortal Cleave. Once every 15 sec.\n\nShirvallah, fill me with your RAGE! The tiger god's priest never strikes once when he can cleave." }, { name = "Lor'Khan's Blessing", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Increases the damage of your Mortal Cleave by 15%.\n\nZealot Lor'Khan keeps his master's blood running hot, and every cleave of the high priest's axe bites deeper for it." } }, tips = { [261] = "Call Zealot Zath, the blade of your temple, to fight at your side for 20 sec." }, visualKit = 437, soundTransform = 8419, soundDeath = 8424, flies = false, wave = 3, instance = "Zul'Gurub", expansion = 0, order = 253, summons = { [261] = true }, charModel = true, box = { -0.04, 0.05, 1.85 }, voices = { { 8419, 3.8, true, "Shirvallah, fill me with your RAGE!" }, { 8424, 5.3, true, "Hakkar binds me no more! Peace at last!" } }, title = "Priest of Shirvallah", visages = { "thekal_tiger" }, shape = "Troll" },
    { id = "arlokk", entry = 14515, name = "High Priestess Arlokk", label = "High Priestess Arlokk", level = 63, display = 15218, height = 3.7, span = 3.7, school = "shadow", pool = "classic_raid", icon = "Interface\\Icons\\Ability_Mount_BlackPanther", profile = "bruiser", kit = { 29306, 15581, 24212, 12540, 34189, 261 }, passives = {}, talentInfo = { { name = "Priestess of Shadow", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your Shadow damage is increased by 8%." }, { name = "Gurubashi Blades", icon = "Interface\\Icons\\Ability_Parry", text = "Your chance to parry is increased by 5%." }, { name = "Call of Bethekk", icon = "Interface\\Icons\\Ability_Mount_BlackPanther", text = "Your attack power is increased by 8%." }, { name = "Zulian Discipline", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Damage you take is reduced by 4%." }, { name = "Whispers of Bethekk", icon = "Interface\\Icons\\Spell_Shadow_Possession", text = "Your melee hits have an 8% chance to lay Shadow Word: Pain on the target. Once every 12 sec.\n\nEvery cut from the priestess's daggers carries a whisper of the panther loa, and the whisper festers." }, { name = "Jungle Shadows", icon = "Interface\\Icons\\Ability_Stealth", text = "Reduces the cooldown of your Vanish by 10 sec.\n\nArlokk was never truly there. One moment the priestess stands at her altar; the next, only the gong still rings." } }, tips = { [261] = "Feast on them, my pretties! Two Zulian Prowlers slink out of the jungle and hunt with you for 20 sec." }, visualKit = 7775, soundTransform = 8416, soundDeath = 8412, flies = false, wave = 3, instance = "Zul'Gurub", expansion = 0, order = 255, summons = { [261] = true }, charModel = true, box = { -0.31, -0.09, 1.87 }, view = { -0.7267, 0.0000, 0.1650 }, voices = { { 8416, 3.6, true, "Bethekk, your priestess calls upon your might!" }, { 8412, 4.3, true, "At last, I am free of the Soulflayer!" } }, title = "Priestess of Bethekk", visages = { "arlokk_panther" }, shape = "Troll" },
    { id = "venoxis", entry = 14507, name = "High Priest Venoxis", label = "High Priest Venoxis", level = 63, display = 15217, height = 3.7, span = 3.7, school = "holy", pool = "classic_raid", icon = "Interface\\Icons\\Ability_Hunter_Pet_WindSerpent", profile = "caster", kit = { 23979, 23860, 23858, 23895, 23859, 261 }, passives = {}, talentInfo = { { name = "Light of the Serpent Priest", icon = "Interface\\Icons\\Spell_Holy_HolyBolt", text = "Your Holy damage is increased by 10%." }, { name = "Blessing of Hethiss", icon = "Interface\\Icons\\Spell_Holy_Renew", text = "Healing you do is increased by 10%." }, { name = "High Priest's Devotion", icon = "Interface\\Icons\\Spell_Holy_DispelMagic", text = "Your Holy spells cost 8% less." }, { name = "Serpent Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Damage you take is reduced by 5%." }, { name = "Wrath of the Snake Cult", icon = "Interface\\Icons\\Spell_Shadow_SiphonMana", text = "Your Holy Wrath leaps to 1 more enemy.\n\nVenoxis still speaks Hethiss's prayers, but every bolt he calls now coils from one heretic to the next." }, { name = "Hakkar's Leash", icon = "Interface\\Icons\\Spell_Holy_HolyNova", text = "Blows against you have a 10% chance to set off a Holy Nova. Once every 20 sec.\n\nBound to Hakkar, the high priest's light lashes out at whoever strikes him, whether he wills it or not." } }, tips = { [261] = "Call the cobras of the Temple of Hethiss: two Razzashi Cobras slither out and fight at your side for 20 sec." }, visualKit = 154, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Zul'Gurub", expansion = 0, order = 254, summons = { [261] = true }, charModel = true, box = { -0.04, 0.05, 1.85 }, voices = { { 8421, 3.5, true, "Let the coils of hate unfurl!" } }, title = "Priest of Hethiss", visages = { "venoxis_serpent" }, shape = "Troll" },
    { id = "jeklik", entry = 14517, name = "High Priestess Jeklik", label = "High Priestess Jeklik", level = 63, display = 15219, height = 3.7, span = 3.7, school = "shadow", pool = "classic_raid", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bat", profile = "caster", kit = { 23953, 23952, 24674, 22884, 23954, 261 }, passives = {}, talentInfo = { { name = "Shadow of Hir'eek", icon = "Interface\\Icons\\Spell_Shadow_SiphonMana", text = "Your Shadow damage is increased by 10%." }, { name = "Mending of the Bat Priestess", icon = "Interface\\Icons\\Spell_Holy_Heal", text = "Healing you do is increased by 10%." }, { name = "Leathery Wings", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bat", text = "Damage you take is reduced by 5%." }, { name = "Voice of Hir'eek", icon = "Interface\\Icons\\Spell_Shadow_PsychicScream", text = "Your spells are cast 6% faster." }, { name = "The Great Heal", icon = "Interface\\Icons\\Spell_Holy_GreaterHeal", text = "Reduces the cooldown of your Great Heal by 10 sec.\n\nEvery raid learns to interrupt the bat priestess's heal. You are the one casting it now." }, { name = "Hir'eek's Whisper", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your damaging spells have an 8% chance to lay Shadow Word: Pain on the target. Once every 15 sec.\n\nThe bat god speaks through his priestess in whispers, and the whispers leave wounds." } }, tips = { [261] = "Come to me, my children! A Gurubashi Bat Rider swoops in to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 8417, soundDeath = 8422, flies = false, wave = 3, instance = "Zul'Gurub", expansion = 0, order = 256, summons = { [261] = true }, charModel = true, box = { -0.31, -0.09, 1.87 }, voices = { { 8417, 3.8, true, "Lord Hir'eek, grant me wings of vengeance!" }, { 8422, 5.3, true, "Finally...death! Curse you, Hakkar! Curse you!" } }, title = "Priestess of Hir'eek", visages = { "jeklik_bat" }, shape = "Troll" },
    { id = "kurinnaxx", entry = 15348, name = "Kurinnaxx", label = "Kurinnaxx", level = 63, display = 15742, height = 6.7, span = 20.4, school = "physical", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_AhnQirajTrinket_01", profile = "bruiser", kit = { 25814, 25646, 25648, 3391, 18501 }, passives = {}, talentInfo = { { name = "Sand Reaver's Claws", icon = "Interface\\Icons\\Ability_Druid_Swipe", text = "Your Physical damage is increased by 10%." }, { name = "Silithid Carapace", icon = "Interface\\Icons\\Ability_Hunter_Pet_Silithid", text = "Your armor is increased by 20%." }, { name = "Burrower's Bulk", icon = "Interface\\Icons\\INV_Qiraj_OuroHide", text = "Your maximum health is increased by 8%." }, { name = "The Sands Claim the Wounded", icon = "Interface\\Icons\\Ability_CriticalStrike", text = "Your melee attacks have a 10% chance to rake the enemies in front of you with a Wide Slash. Once every 10 sec.\n\nKurinnaxx never strikes only one; every swing of the sand reaver's claws catches whoever stands too close." }, { name = "Cornered Reaver", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "Reduces the cooldown of your Enrage by 10 sec.\n\nWounded, the sand reaver does not flee back under the sand. It only grows more savage." } }, tips = { [25648] = "Bury a sand trap in the ground at your feet. It lies in wait for 1 min for the first enemy to blunder into it." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Ruins of Ahn'Qiraj", expansion = 0, order = 302, box = { -3.19, 0.25, 0.98 }, title = "Sand Reaver of Ahn'Qiraj" },
    { id = "rajaxx", entry = 15341, name = "General Rajaxx", label = "General Rajaxx", level = 63, display = 15376, height = 19.4, span = 19.4, school = "physical", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_AhnQirajTrinket_03", profile = "tank", kit = { 15588, 22591, 25515, 6713, 25516, 261, 37548 }, passives = {}, talentInfo = { { name = "Qiraji Carapace", icon = "Interface\\Icons\\INV_Qiraj_CarapaceOldGod", text = "Your armor is increased by 20%." }, { name = "General's Resolve", icon = "Interface\\Icons\\INV_QirajIdol_War", text = "Damage you take is reduced by 8%." }, { name = "Commander of the Swarm", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", text = "The threat you cause is increased by 30%." }, { name = "Swarmguard's Parry", icon = "Interface\\Icons\\Ability_Warrior_Riposte", text = "Your chance to parry is increased by 5%." }, { name = "A Thousand Years of Vengeance", icon = "Interface\\Icons\\Spell_Nature_ThunderClap", text = "When you are struck, you have a 10% chance to bring down a Thunderclap. Once every 15 sec.\n\nOne thousand years Rajaxx waited behind the Scarab Wall. Every blow against him brings the thunder closer." }, { name = "Endless Waves", icon = "Interface\\Icons\\INV_Misc_AhnQirajTrinket_04", text = "Reduces the cooldown of Continue the Fight! by 30 sec.\n\nRajaxx never fights alone. Behind every wave of the Qiraji army there is always another." } }, tips = { [25516] = "Command nearby allies for 30 sec, healing them for 200 every 3 sec and quickening their attacks by 10% and casts by 11%.", [261] = "Warriors, captains, continue the fight! Two Qiraji Warriors march to your side for 20 sec." }, visualKit = 437, soundTransform = 8614, soundDeath = 0, flies = false, wave = 3, instance = "Ruins of Ahn'Qiraj", expansion = 0, order = 301, summons = { [261] = true }, box = { 1.21, -1.09, 8.83 }, view = { -2.4153, -0.7863, 1.3126 }, voices = { { 8612, 7.8, true, "The time of our retribution is at hand! Let darkness reign in the hearts of our enemies!" }, { 8610, 13.9, true, "No longer will we wait behind barred doors and walls of stone! No longer will our vengeance be denied! The dragons themselves will tremble before our wrath!" }, { 8608, 4.8, true, "Fear is for the enemy! Fear and death!" }, { 8611, 11.8, true, "Staghelm will whimper and beg for his life, just as his whelp of a son did! One thousand years of injustice will end this day!" }, { 8607, 9.5, true, "Fandral! Your time has come! Go and hide in the Emerald Dream and pray we never find you!" }, { 8609, 3.6, true, "Impudent fool! I will kill you myself!" }, { 8603, 3.8, true, "Attack and make them pay dearly!" }, { 8605, 3.3, true, "Crush them! Drive them out!" }, { 8606, 3.9, true, "Do not hesitate! Destroy them!" }, { 8613, 6.1, true, "Warriors, Captains, continue the fight!" }, { 8604, 2.6, true, "Breathe your last!" } }, title = "Commander of the Qiraji" },
    { id = "moam", entry = 15340, name = "Moam", label = "Moam", level = 63, display = 15392, height = 18.8, span = 27.6, school = "arcane", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", profile = "caster", kit = { 25672, 25671, 15550, 22693, 25681 }, passives = {}, talentInfo = { { name = "Obsidian Mana Core", icon = "Interface\\Icons\\Spell_Arcane_ArcanePotency", text = "Hoarded mana burns hotter: your Arcane damage is increased by 8%." }, { name = "Petrified Hide", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", text = "Your obsidian body raises your armor by 20%." }, { name = "Hoarded Mana", icon = "Interface\\Icons\\Spell_Arcane_ManaTap", text = "Your Intellect is increased by 8%." }, { name = "Hoarder of Magic", icon = "Interface\\Icons\\Spell_Arcane_ArcaneTorrent", text = "Reduces the mana cost of your Arcane spells by 8%." }, { name = "Feet of Stone", icon = "Interface\\Icons\\Spell_Shadow_ManaBurn", text = "When you are struck, you have a 10% chance to Trample the enemies around you. Once every 20 sec.\n\nMoam was made of the ruins' own stone. Whoever comes close enough to strike him learns how heavy that stone is." }, { name = "Overflowing Core", icon = "Interface\\Icons\\Spell_Nature_WispSplode", text = "Arcane Eruption reaches 20% farther.\n\nWhen Moam's core is full the stored mana does not trickle out. It erupts, and the Ruins shake." } }, tips = { [25672] = "Release the mana stored in your stone body in one burst, dealing 3063 Arcane damage to nearby enemies and hurling them away.", [25681] = "Call on the magic you have hoarded: two Mana Fiends rise from the ruins and fight at your side for 20 sec." }, visualKit = 1005, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Ruins of Ahn'Qiraj", expansion = 0, order = 303, summons = { [25681] = true }, box = { -0.37, -1.85, 9.14 }, title = "Creation of Emperor Vek'lor" },
    { id = "buru", entry = 15370, name = "Buru the Gorger", label = "Buru the Gorger", level = 63, display = 15654, height = 11.4, span = 15.0, school = "physical", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_AhnQirajTrinket_02", profile = "bruiser", kit = { 96, 20512, 43420, 2379, 37548, 261 }, passives = {}, talentInfo = { { name = "Gorger's Appetite", icon = "Interface\\Icons\\Ability_Racial_Cannibalize", text = "Your Physical damage is increased by 8%." }, { name = "Chitin of the Gorger", icon = "Interface\\Icons\\INV_Misc_AhnQirajTrinket_05", text = "Your armor is increased by 15%." }, { name = "Egg-Swollen Bulk", icon = "Interface\\Icons\\Ability_Hunter_Pet_Worm", text = "Your maximum health is increased by 10%." }, { name = "Thorned Carapace", icon = "Interface\\Icons\\Spell_Nature_Thorns", text = "Your Nature resistance is increased by 40." }, { name = "Gorger's Hunger", icon = "Interface\\Icons\\Ability_Rogue_Rupture", text = "Your melee hits have a 10% chance to Dismember the target. Once every 10 sec.\n\nBuru eats everything in his path: eggs, silithid, adventurers. He has never once been full." }, { name = "Gathering Momentum", icon = "Interface\\Icons\\Ability_Rogue_Sprint", text = "Your Speed lasts 5 sec longer.\n\nThe Gorger starts slow. The longer he chases you across the ruins, the faster he comes." } }, tips = { [20512] = "Breathe the creeping plague of the hive over nearby enemies, dealing 70 Nature damage every 2 sec for 20 sec.", [261] = "Crack open the eggs of the hive: two Hive'Zara Hatchlings swarm out and fight at your side for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Ruins of Ahn'Qiraj", expansion = 0, order = 299, summons = { [261] = true }, box = { 0.87, 0.23, 5.72 }, view = { -5.1273, 2.6240, 2.9440 }, title = "Silithid Colossus", visages = { "buru_cracked" }, shape = "Armored" },
    { id = "ayamiss", entry = 15369, name = "Ayamiss the Hunter", label = "Ayamiss the Hunter", level = 63, display = 15431, height = 25.9, span = 25.9, school = "nature", pool = "classic_raid", icon = "Interface\\Icons\\Ability_Hunter_Pet_Wasp", profile = "bruiser", kit = { 25748, 25749, 25852, 13902, 8269, 261 }, passives = {}, talentInfo = { { name = "Venom of the Hive Hunter", icon = "Interface\\Icons\\Ability_Hunter_Pet_Wasp", text = "Your Nature damage is increased by 8%." }, { name = "Wings of the Swarm", icon = "Interface\\Icons\\Spell_Nature_InsectSwarm", text = "You move 12% faster on beating wings." }, { name = "Darting Flight", icon = "Interface\\Icons\\Ability_Rogue_Feint", text = "Your chance to dodge is increased by 5%." }, { name = "From the High Perch", icon = "Interface\\Icons\\INV_Misc_MonsterTail_03", text = "Your melee hits have a 15% chance to drive a Poison Stinger into the target. Once every 6 sec.\n\nFrom her perch above the ruins the Hunter picks one target, and her stinger finds it again and again." }, { name = "Call of the Hive", icon = "Interface\\Icons\\Ability_Hunter_Pet_Silithid", text = "Reduces the cooldown of Call the Swarm by 30 sec.\n\nThe Hive'Zara answer their Hunter faster than any other voice in the Ruins of Ahn'Qiraj." } }, tips = { [25749] = "Spray barbed stingers at every enemy around you, dealing 875 Nature damage.", [261] = "Call the hive: three Hive'Zara Swarmers dive to your side and fight for 20 sec." }, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = true, wave = 3, instance = "Ruins of Ahn'Qiraj", expansion = 0, order = 298, summons = { [261] = true }, box = { 1.70, -0.62, 14.37 }, view = { -16.1591, -0.0552, 1.5572 }, title = "Silithid Wasp of Ahn'Qiraj" },
    { id = "sartura", entry = 15516, name = "Battleguard Sartura", label = "Battleguard Sartura", level = 63, display = 15583, height = 12.7, span = 12.7, school = "physical", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_AhnQirajTrinket_04", profile = "bruiser", kit = { 26083, 25174, 22911, 26027, 28371, 261 }, passives = {}, talentInfo = { { name = "Whirlwind of Steel", icon = "Interface\\Icons\\Ability_Whirlwind", text = "Your Physical damage is increased by 8%." }, { name = "Battleguard's Parry", icon = "Interface\\Icons\\Ability_Parry", text = "Your chance to parry is increased by 6%." }, { name = "Plate of the Sacred Grounds", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Laws of the Ancients", icon = "Interface\\Icons\\Ability_Warrior_Sunder", text = "Your melee hits have a 10% chance to set off a Sundering Cleave. Once every 6 sec.\n\nYou will be judged for defiling these sacred grounds, and the judgement falls on everyone standing near the accused." }, { name = "I Serve to the Last", icon = "Interface\\Icons\\INV_Misc_AhnQirajTrinket_04", text = "Increases the damage of your Whirlwind by 15%.\n\nSartura's whirlwind cuts deeper the longer the Battleguards hold the sacred grounds." } }, tips = { [261] = "Guards, defend your mistress! Two of Sartura's Royal Guards whirl to your side and fight for 20 sec." }, visualKit = 437, soundTransform = 8646, soundDeath = 8648, flies = false, wave = 3, instance = "Ahn'Qiraj Temple", expansion = 0, order = 260, summons = { [261] = true }, box = { -2.12, -0.24, 6.62 }, view = { -0.0471, 0.2709, 1.6156 }, voices = { { 8646, 3.9, true, "You will be judged for defiling these sacred grounds! The laws of the Ancients will not be challenged! Trespassers will be annihilated!" }, { 8647, 2.9, true, "I sentence you to death!" }, { 8648, 3.0, true, "I serve to the last!" } }, title = "Leader of the Qiraji Battleguards" },
    { id = "fankriss", entry = 15510, name = "Fankriss the Unyielding", label = "Fankriss the Unyielding", level = 63, display = 15743, height = 8.9, span = 27.2, school = "physical", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_AhnQirajTrinket_06", profile = "bruiser", kit = { 25646, 3391, 22994, 17204, 261 }, passives = {}, talentInfo = { { name = "Punishing Mandibles", icon = "Interface\\Icons\\Ability_Warrior_SavageBlow", text = "Your Physical damage is increased by 8%." }, { name = "The Unyielding", icon = "Interface\\Icons\\Ability_Warrior_ShieldWall", text = "Damage you take is reduced by 6%." }, { name = "Mother of the Spawn", icon = "Interface\\Icons\\Ability_Hunter_Pet_Worm", text = "Your maximum health is increased by 8%." }, { name = "The Unrelenting", icon = "Interface\\Icons\\Ability_Warrior_PunishingBlow", text = "Your melee attacks have a 10% chance to send you into a Thrash, gaining extra attacks. Once every 10 sec.\n\nFankriss does not tire and does not relent; when one blow lands, more follow before the wound can close." }, { name = "Lair of the Unyielding", icon = "Interface\\Icons\\Spell_Nature_StrangleVines", text = "Reduces the cooldown of Entangle by 10 sec.\n\nThe tunnels themselves reach for anyone who tries to run from the hatchlings." } }, tips = { [261] = "Three Vekniss Hatchlings scuttle out of the hive tunnels and swarm your enemies for 15 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Ahn'Qiraj Temple", expansion = 0, order = 267, summons = { [17204] = true, [261] = true }, box = { -4.26, 0.33, 1.31 }, view = { -19.2215, 0.0000, 2.7500 }, title = "Sand Reaver of Ahn'Qiraj" },
    { id = "viscidus", entry = 15299, name = "Viscidus", label = "Viscidus", level = 63, display = 15686, height = 19.6, span = 31.7, school = "nature", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Nature_Acid_01", profile = "caster", kit = { 24099, 25993, 25989, 10577, 261 }, passives = {}, talentInfo = { { name = "Venom of the Deep Hive", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "Your Nature damage is increased by 10%." }, { name = "Viscous Mass", icon = "Interface\\Icons\\INV_Misc_Slime_01", text = "Blows sink into your ooze: damage you take is reduced by 6%." }, { name = "Toxic Globules", icon = "Interface\\Icons\\Spell_Nature_NatureResistanceTotem", text = "Your Nature resistance is increased by 60." }, { name = "Toxic Splash", icon = "Interface\\Icons\\Spell_Nature_NullifyPoison", text = "When you are struck, you have a 10% chance to exude a cloud of Toxin. Once every 15 sec.\n\nStrike the ooze and it splashes; the splash is poison, and it lingers where it lands." }, { name = "Rejoin", icon = "Interface\\Icons\\Spell_Nature_Acid_01", text = "Reduces the cooldown of your healing Rejoin by 15 sec.\n\nShatter Viscidus and the globs crawl home. Given a moment, the ooze is always whole again." } }, tips = { [261] = "Shatter a piece of yourself loose: three Globs of Viscidus ooze out and fight at your side for 20 sec." }, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Ahn'Qiraj Temple", expansion = 0, order = 271, summons = { [261] = true }, box = { -5.31, -0.14, 9.49 }, view = { -25.1856, 0.0000, 3.2450 }, title = "Ooze of Ahn'Qiraj" },
    { id = "veklor", entry = 15276, name = "Emperor Vek'lor", label = "Emperor Vek'lor", level = 63, display = 15778, height = 20.0, span = 20.0, school = "arcane", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_AhnQirajTrinket_01", profile = "caster", kit = { 26006, 568, 26607, 29211, 10577, 261 }, passives = {}, talentInfo = { { name = "Arcane Might of the Emperor", icon = "Interface\\Icons\\Spell_Arcane_Blast", text = "Your Arcane damage is increased by 10%." }, { name = "Shadow of the Old God", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 5%." }, { name = "Twin Emperors' Bond", icon = "Interface\\Icons\\Spell_Shadow_GatherShadows", text = "Your brother shares your pain: damage you take is reduced by 5%." }, { name = "Emperors Do Not Brawl", icon = "Interface\\Icons\\Spell_Arcane_ArcaneTorrent", text = "When you are struck, you have a 10% chance to answer with an Arcane Burst. Once every 20 sec.\n\nVek'lor leaves the melee to his brother; anyone who closes on him is thrown back out of it." }, { name = "Brothers in Step", icon = "Interface\\Icons\\Spell_Arcane_Blink", text = "Reduces the cooldown of your blink by 8 sec.\n\nThe twins trade places so often that their enemies never know which brother they face." } }, tips = { [261] = "The bugs of the temple answer the emperor: two Qiraji Scarabs scuttle to your side and fight for 20 sec." }, visualKit = 1005, soundTransform = 0, soundDeath = 8625, flies = false, wave = 3, instance = "Ahn'Qiraj Temple", expansion = 0, order = 265, summons = { [261] = true }, box = { -0.38, -0.01, 9.98 }, view = { -5.7364, 0.3840, 1.4887 }, voices = { { 8629, 2.1, true, "You will not escape death!" }, { 8625, 2.4, true, "My brother, no!" } }, title = "Twin Emperor of Ahn'Qiraj" },
    { id = "veknilash", entry = 15275, name = "Emperor Vek'nilash", label = "Emperor Vek'nilash", level = 63, display = 15761, height = 20.0, span = 20.0, school = "physical", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_AhnQirajTrinket_03", profile = "bruiser", kit = { 26007, 26613, 8269, 29211, 10577, 261 }, passives = {}, talentInfo = { { name = "Kalimdor's Revenge", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your Physical damage is increased by 8%." }, { name = "Imperial Carapace", icon = "Interface\\Icons\\INV_Misc_AhnQirajTrinket_05", text = "Your armor is increased by 20%." }, { name = "Twin Emperors' Bond", icon = "Interface\\Icons\\Spell_Shadow_GatherShadows", text = "Your brother shares your pain: damage you take is reduced by 5%." }, { name = "Your Fate Is Sealed", icon = "Interface\\Icons\\Ability_MeleeDamage", text = "Your melee hits have a 10% chance to set off an Uppercut. Once every 10 sec.\n\nYour fate is sealed! Vek'nilash does not let anyone stand in front of him for long." }, { name = "I Feel Your Pain", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain", text = "Your Bruising Blow deals 15% more damage.\n\nVek'lor, I feel your pain! Every wound his brother suffers comes back through Vek'nilash's blade." } }, tips = { [261] = "The scorpions of the temple answer the emperor: two Qiraji Scorpions scuttle to your side and fight for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 8636, flies = false, wave = 3, instance = "Ahn'Qiraj Temple", expansion = 0, order = 266, summons = { [261] = true }, box = { -0.38, -0.01, 9.98 }, view = { -5.7364, 0.2133, 1.2327 }, voices = { { 8635, 2.1, true, "Your fate is sealed!" }, { 8636, 3.2, true, "Vek'lor, I feel your pain!" } }, title = "Twin Emperor of Ahn'Qiraj" },
    { id = "ouro", entry = 15517, name = "Ouro", label = "Ouro", level = 63, display = 15509, height = 40.5, span = 40.5, school = "nature", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_AhnQirajTrinket_02", profile = "bruiser", kit = { 9931152, 26103, 26093, 29211, 261 }, passives = {}, talentInfo = { { name = "Sands of Ahn'Qiraj", icon = "Interface\\Icons\\Spell_Nature_Cyclone", text = "Your Nature damage is increased by 8%." }, { name = "Wormscale Hide", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Your armor is increased by 25%." }, { name = "Colossal Bulk", icon = "Interface\\Icons\\Ability_Hunter_Pet_Worm", text = "Your maximum health is increased by 12%." }, { name = "Too Close to the Maw", icon = "Interface\\Icons\\Spell_Nature_Earthquake", text = "When you are struck, you have a 10% chance to Sweep the enemies around you. Once every 15 sec.\n\nThose who crowd the Great Worm are the first to learn how far its bulk can throw them." }, { name = "Tunnels Beneath the Hive", icon = "Interface\\Icons\\Ability_Rogue_Sprint", text = "Reduces the cooldown of your burrow by 8 sec.\n\nOuro's tunnels run everywhere beneath Ahn'Qiraj; the ground itself is his road." } }, tips = { [261] = "The mounds of your passing split open: two Ouro Scarabs swarm your enemies for 15 sec." }, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Ahn'Qiraj Temple", expansion = 0, order = 268, summons = { [261] = true }, box = { -0.94, -0.37, 11.81 }, view = { -26.1136, -0.0864, 5.2498 }, title = "Ancient Sand Worm" },
    { id = "noth", entry = 15954, name = "Noth the Plaguebringer", label = "Noth the Plaguebringer", level = 83, display = 16590, height = 4.3, span = 4.3, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Spell_Shadow_CurseOfMannoroth", profile = "caster", kit = { 29213, 20812, 56038, 29208, 261 }, passives = {}, talentInfo = { { name = "Former Mage of Dalaran", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 10%." }, { name = "Plaguebringer", icon = "Interface\\Icons\\Spell_Shadow_CurseOfMannoroth", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Glory to the Master", icon = "Interface\\Icons\\Spell_Shadow_AnimateDead", text = "Your maximum health is increased by 8%." }, { name = "Plagued Flesh", icon = "Interface\\Icons\\Spell_Arcane_Blink", text = "Damage you take is reduced by 5%." }, { name = "Plague Spreads", icon = "Interface\\Icons\\Spell_Shadow_Cripple", text = "Your damaging spells have an 8% chance to Cripple the target. Once every 30 sec.\n\nNoth's plague cripples whoever it touches." }, { name = "Die, Trespasser", icon = "Interface\\Icons\\Spell_Shadow_CurseOfSargeras", text = "Reduces the cooldown of Curse of the Plaguebringer by 8 sec.\n\nThe Plaguebringer curses the quarter with every breath." } }, tips = { [261] = "Rise, my soldiers! Raise two Plagued Warriors to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 8845, soundDeath = 8848, flies = false, wave = 3, instance = "Naxxramas", expansion = 2, order = 534, summons = { [261] = true }, charModel = true, box = { -0.21, -0.01, 2.13 }, voices = { { 8845, 2.3, true, "Glory to the master!" }, { 8846, 2.5, true, "Your life is forfeit!" }, { 8847, 1.6, true, "Die, trespasser!" }, { 8851, 4.5, true, "Rise, my soldiers! Rise and fight once more!" }, { 8849, 2.6, true, "My task is done!" }, { 8850, 3.2, true, "Breathe no more!" }, { 8848, 5.0, true, "I will serve the master... in death!" } }, title = "Former Mage of Dalaran" },
    { id = "heigan", entry = 15936, name = "Heigan the Unclean", label = "Heigan the Unclean", level = 83, display = 16309, height = 7.0, span = 7.0, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_HeiganTheUnclean", profile = "caster", kit = { 55604, 29310, 30122, 29350 }, passives = {}, talentInfo = { { name = "Architect of the Plaguelands", icon = "Interface\\Icons\\Spell_Shadow_PlagueCloud", text = "Your Nature damage is increased by 10%." }, { name = "The End Is Upon You", icon = "Interface\\Icons\\Spell_Shadow_ShadeTrueSight", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Unclean Flesh", icon = "Interface\\Icons\\Spell_Nature_NullifyDisease", text = "Your Nature resistance is increased by 50." }, { name = "Endless Suffering", icon = "Interface\\Icons\\Spell_Shadow_AnimateDead", text = "Your maximum health is increased by 8%." }, { name = "The Dance", icon = "Interface\\Icons\\Spell_Shadow_CreepingPlague", text = "When you are struck, you have a 10% chance to erupt plague around you. Once every 15 sec.\n\nAnyone who stands still near Heigan learns to dance." }, { name = "You Are Mine Now", icon = "Interface\\Icons\\Spell_Shadow_ManaBurn", text = "Reduces the cooldown of Spell Disruption by 10 sec.\n\nHeigan sees every caster in the quarter and breaks their spells again and again." } }, tips = { [29350] = "Channel a plague cloud around you for 45 sec: the ground around you erupts with plague again and again." }, visualKit = 282, soundTransform = 8825, soundDeath = 8828, flies = false, wave = 3, instance = "Naxxramas", expansion = 2, order = 528, box = { -0.21, -0.02, 3.51 }, view = { -2.1527, -0.0149, 0.4235 }, voices = { { 8825, 3.8, true, "You are mine now." }, { 8826, 3.2, true, "I see you!" }, { 8827, 3.8, true, "You... are next." }, { 8829, 5.4, true, "Close your eyes. Sleep." }, { 8830, 7.2, true, "The races of the world will perish. It is only a matter of time." }, { 8831, 14.0, true, "I see endless suffering. I see torment. I see rage. I see everything..." }, { 8832, 5.5, true, "Soon the world will tremble." }, { 8834, 5.7, true, "Hungry worms will feast on your rotting flesh." }, { 8833, 3.5, true, "The end is upon you." } }, title = "Architect of the Plaguelands" },
    { id = "razuvious", entry = 16061, name = "Instructor Razuvious", label = "Instructor Razuvious", level = 83, display = 16582, height = 4.3, span = 4.3, school = "physical", pool = "wotlk", icon = "Interface\\Icons\\INV_Misc_Head_Undead_01", profile = "bruiser", kit = { 55543, 55470, 55550, 29060, 261 }, passives = {}, talentInfo = { { name = "Death Knight Trainer", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "Drill Sergeant", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Frost-Forged Plate", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Stand and Fight", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your Strength is increased by 8%." }, { name = "Sweep the Leg", icon = "Interface\\Icons\\INV_Weapon_ShortBlade_05", text = "Your melee attacks have a 10% chance to throw a Jagged Knife. Once every 15 sec.\n\nSweep the leg... Do you have a problem with that?" }, { name = "You Disappoint Me", icon = "Interface\\Icons\\Ability_Warrior_WarCry", text = "Reduces the cooldown of Disrupting Shout by 5 sec.\n\nYou disappoint me, students! The instructor never stops shouting." } }, tips = { [261] = "Show them no mercy! Call a Death Knight Captain, one of your students, to fight for you for 20 sec." }, visualKit = 437, soundTransform = 8855, soundDeath = 8860, flies = false, wave = 3, instance = "Naxxramas", expansion = 2, order = 529, summons = { [261] = true }, charModel = true, box = { -0.21, -0.01, 2.13 }, voices = { { 8855, 1.3, true, "Do as I taught you!" }, { 8859, 3.6, true, "The time for practice is over! Show me what you have learned!" }, { 8856, 1.5, true, "Show them no mercy!" }, { 8861, 2.6, true, "Sweep the leg... Do you have a problem with that?" }, { 8862, 1.6, true, "You should have stayed home." }, { 8852, 2.9, true, "Hah hah, I'm just getting warmed up!" }, { 8853, 1.4, true, "Stand and fight!" }, { 8854, 1.8, true, "Show me what you've got!" }, { 8858, 2.0, true, "You disappoint me, students!" }, { 8860, 2.9, true, "An honorable... death." } }, title = "Death Knight Trainer" },
    { id = "grobbulus", entry = 15931, name = "Grobbulus", label = "Grobbulus", level = 83, display = 16035, height = 12.0, span = 14.1, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Spell_Shadow_AbominationExplosion", profile = "bruiser", kit = { 28157, 28206, 43581, 261 }, passives = {}, talentInfo = { { name = "First of the Flesh Giants", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Mutagen", icon = "Interface\\Icons\\Spell_Nature_Acid_01", text = "Your Nature damage is increased by 10%." }, { name = "Stitched Hide", icon = "Interface\\Icons\\INV_Misc_Bandage_15", text = "Your armor is increased by 15%." }, { name = "Toxic Blood", icon = "Interface\\Icons\\Spell_Nature_NullifyPoison", text = "Your Nature resistance is increased by 60." }, { name = "Leaking Mutagen", icon = "Interface\\Icons\\Spell_Shadow_CorpseExplode", text = "When you are struck, you have a 10% chance to release a Mutagen Explosion. Once every 20 sec.\n\nPoke the flesh giant and whatever he was injected with leaks out." }, { name = "Bombard Slime", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "Reduces the cooldown of Slime Spray by 5 sec.\n\nGrobbulus has more slime than the plague labs can bottle." } }, tips = { [261] = "Split off two Fallout Slimes to ooze over your foes for 20 sec." }, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Naxxramas", expansion = 2, order = 527, summons = { [261] = true }, box = { -0.41, 0.41, 5.95 }, view = { -8.1136, 0.6918, 2.3016 }, title = "First of the Flesh Giants" },
    { id = "gluth", entry = 15932, name = "Gluth", label = "Gluth", level = 83, display = 16064, height = 13.2, span = 18.8, school = "physical", pool = "wotlk", icon = "Interface\\Icons\\Ability_Hunter_Pet_Hyena", profile = "bruiser", kit = { 29572, 29306, 28371, 31041, 261 }, passives = {}, talentInfo = { { name = "Plague Dog", icon = "Interface\\Icons\\Ability_Hunter_Pet_Wolf", text = "Your attack power is increased by 10%." }, { name = "Rotting Hide", icon = "Interface\\Icons\\INV_Misc_Pelt_Wolf_01", text = "Your armor is increased by 15%." }, { name = "Ravenous", icon = "Interface\\Icons\\Ability_Racial_Cannibalize", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Fed on the Dead", icon = "Interface\\Icons\\Spell_Shadow_AnimateDead", text = "Your maximum health is increased by 10%." }, { name = "Decimate", icon = "Interface\\Icons\\Ability_Druid_Mangle2", text = "Your melee attacks have a 10% chance to Mangle the target. Once every 15 sec.\n\nGluth tears at whatever he bites; nothing he chews on heals clean." }, { name = "Hungry Dog", icon = "Interface\\Icons\\INV_Misc_Food_15", text = "Reduces the cooldown of Enrage by 15 sec.\n\nThe plague dog of Naxxramas is always hungry, and always angry about it." } }, tips = { [261] = "Call three Zombie Chows to shamble at your foes for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Naxxramas", expansion = 2, order = 524, summons = { [261] = true }, box = { -0.83, 0.14, 6.55 }, view = { -11.3182, 0.0000, 1.8260 }, title = "Plague Dog of Naxxramas" },
    { id = "thaddius", entry = 15928, name = "Thaddius", label = "Thaddius", level = 83, display = 16137, height = 14.6, span = 14.6, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Thaddius", profile = "caster", kit = { 28167, 28099, 28135, 28337 }, passives = {}, talentInfo = { { name = "Flesh Titan", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Polarity", icon = "Interface\\Icons\\Spell_ChargePositive", text = "Your Nature damage is increased by 10%." }, { name = "Tesla Coils", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Stitched Frame", icon = "Interface\\Icons\\INV_Misc_Bandage_15", text = "Your armor is increased by 15%." }, { name = "Overcharged Coils", icon = "Interface\\Icons\\Spell_ChargeNegative", text = "When you are struck, you have a 10% chance to crackle a Static Field. Once every 20 sec.\n\nBreak... you!! Thaddius's charge jumps to anything that touches him." }, { name = "Eat Your Bones", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", text = "Your Chain Lightning deals 15% more damage.\n\nStalagg and Feugen's power runs in Thaddius's veins now." } }, tips = { [28337] = "Pull an enemy to you with a magnetic surge." }, visualKit = 282, soundTransform = 8867, soundDeath = 8870, flies = false, wave = 3, instance = "Naxxramas", expansion = 2, order = 538, box = { 0.03, -0.44, 7.29 }, view = { -4.9505, 0.0000, 1.3640 }, voices = { { 8872, 8.7, true, "You are too late!! I... must... obey!!" }, { 8867, 1.5, true, "Kill..." }, { 8868, 3.5, true, "Eat... your... bones..." }, { 8869, 3.6, true, "Break... you!!" }, { 8877, 2.9, true, "You... die now!!" }, { 8871, 3.4, true, "Now you feel pain..." }, { 8870, 2.8, true, "Thank... you..." }, { 8873, 7.5, true, "Hurry! Ple-e-ase hurry!!" }, { 8874, 5.1, true, "Sto-o-op! Make it stop!!" }, { 8875, 7.1, true, "Help me! Save me!" }, { 8876, 5.2, true, "No-o-o-o!!" } }, title = "Flesh Titan of Naxxramas" },
    { id = "sapphiron", entry = 15989, name = "Sapphiron", label = "Sapphiron", level = 83, display = 16033, height = 23.8, span = 49.3, school = "frost", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Sapphiron_01", profile = "caster", kit = { 45065, 28522, 55697, 28547, 16608 }, passives = {}, talentInfo = { { name = "Guardian of Naxxramas", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "Frost Aura", icon = "Interface\\Icons\\Spell_Frost_FrostWard", text = "Your Frost resistance is increased by 60." }, { name = "Bones of the Blue Flight", icon = "Interface\\Icons\\INV_Misc_Bone_ElfSkull_01", text = "Your armor is increased by 20%." }, { name = "Undying Wyrm", icon = "Interface\\Icons\\Spell_Shadow_AnimateDead", text = "Your maximum health is increased by 8%." }, { name = "Chill of the Wyrm", icon = "Interface\\Icons\\INV_Misc_MonsterTail_03", text = "When you are struck, you have a 10% chance to Tail Sweep. Once every 20 sec.\n\nSapphiron's bones still remember how to fight." }, { name = "Breath of the Wyrm", icon = "Interface\\Icons\\Spell_Frost_FreezingBreath", text = "Reduces the cooldown of Frost Breath by 5 sec.\n\nThe frost wyrm breathes the cold of Northrend's grave." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = true, wave = 3, instance = "Naxxramas", expansion = 2, order = 536, box = { -8.59, 0.05, 10.78 }, view = { -12.3936, -0.3155, 22.9553 }, title = "Guardian of Naxxramas" },
    { id = "korthazz", entry = 16064, name = "Thane Korth'azz", label = "Thane Korth'azz", level = 83, display = 16155, height = 4.8, span = 5.8, school = "fire", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_FourHorsemen", profile = "bruiser", kit = { 28884, 28832, 42724, 41196 }, passives = {}, talentInfo = { { name = "Rider of Flame", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "Your Fire damage is increased by 10%." }, { name = "Thane's Deathcharger", icon = "Interface\\Icons\\Ability_Mount_Dreadsteed", text = "Your movement speed is increased by 10%." }, { name = "Death Knight's Plate", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Dwarven Might", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your Strength is increased by 8%." }, { name = "Meteor Shower", icon = "Interface\\Icons\\Spell_Fire_MeteorStorm", text = "Your melee attacks have a 6% chance to call down a Meteor. Once every 30 sec.\n\nKorth'azz never stopped loving a good explosion." }, { name = "To Arms, Ye Roustabouts", icon = "Interface\\Icons\\Ability_Warrior_ShieldWall", text = "Reduces the cooldown of Shield Wall by 20 sec.\n\nThe red-bearded thane never stays behind his shield for long, and never away from it either." } }, tips = {}, visualKit = 286, soundTransform = 8899, soundDeath = 8900, flies = false, wave = 3, instance = "Naxxramas", expansion = 2, order = 539, box = { 0.05, 0.00, 2.40 }, view = { -2.4545, 0.0866, 0.1857 }, voices = { { 8899, 3.0, true, "C'mon an' fight ye wee ninny!" }, { 8903, 3.9, true, "To arms, ye roustabouts! We've got company!" }, { 8904, 6.5, true, "I heard about enough of yer sniveling. Shut yer fly trap 'afore I shut it for ye!" }, { 8905, 4.8, true, "I'm gonna' enjoy killin' these slack-jawed daffodils!" }, { 8902, 3.3, true, "I like my meat extra crispy!" }, { 8901, 3.3, true, "Next time, bring more friends!" }, { 8900, 3.3, true, "What a bloody waste this is!" } }, title = "Rider of the Four Horsemen" },
    { id = "blaumeux", entry = 16065, name = "Lady Blaumeux", label = "Lady Blaumeux", level = 83, display = 16153, height = 5.0, span = 5.8, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_FourHorsemen", profile = "caster", kit = { 57374, 28882, 28833, 30533 }, passives = {}, talentInfo = { { name = "Rider of Shadow", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your Shadow damage is increased by 10%." }, { name = "Lady's Deathcharger", icon = "Interface\\Icons\\Ability_Mount_Dreadsteed", text = "Your movement speed is increased by 10%." }, { name = "Shadow-Forged Plate", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Unholy Focus", icon = "Interface\\Icons\\Spell_Shadow_UnholyStrength", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Your Life Is Mine", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your damaging spells have an 8% chance to open a Void Zone. Once every 20 sec.\n\nLady Blaumeux leaves pools of the void wherever her gaze lands." }, { name = "Defend Yourself", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "Your Unholy Shadow deals 15% more damage.\n\nThe shadow rider's lash cuts deeper each time." } }, tips = {}, visualKit = 7775, soundTransform = 8892, soundDeath = 8893, flies = false, wave = 3, instance = "Naxxramas", expansion = 2, order = 531, box = { 0.05, 0.00, 2.51 }, voices = { { 8892, 1.7, true, "Defend yourself!" }, { 8896, 6.2, true, "Come, Zeliek, do not drive them out. Not before we've had our fun." }, { 8897, 5.9, true, "I do hope they stay alive long enough for me to... introduce myself." }, { 8898, 4.5, true, "The first kill goes to me! Anyone care to wager?" }, { 8895, 2.2, true, "Your life is mine!" }, { 8894, 1.3, true, "Who's next?" }, { 8893, 2.1, true, "Touche..." } }, title = "Rider of the Four Horsemen" },
    { id = "zeliek", entry = 16063, name = "Sir Zeliek", label = "Sir Zeliek", level = 83, display = 16154, height = 5.2, span = 5.8, school = "holy", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_FourHorsemen", profile = "caster", kit = { 57376, 28883, 28835, 57377, 92238 }, passives = {}, talentInfo = { { name = "Burning Light", icon = "Interface\\Icons\\Spell_Holy_HolyBolt", text = "Your Holy damage is increased by 10%." }, { name = "Zeliek's Deathcharger", icon = "Interface\\Icons\\Ability_Mount_Dreadsteed", text = "Your movement speed is increased by 10%." }, { name = "Light-Scarred Plate", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Forgive Me", icon = "Interface\\Icons\\Spell_Holy_Excorcism_02", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Flee Before It's Too Late", icon = "Interface\\Icons\\Spell_Holy_Excorcism", text = "Your damaging spells have an 8% chance to add Holy Wrath. Once every 20 sec.\n\nZeliek still carries the Light he served, and it burns everyone he points it at." }, { name = "Bless You Children", icon = "Interface\\Icons\\Spell_Holy_SearingLight", text = "Reduces the cooldown of Condemnation by 5 sec.\n\nThe white rider condemns the living quickly, as if to spare them." } }, tips = {}, visualKit = 154, soundTransform = 8913, soundDeath = 8914, flies = false, wave = 3, instance = "Naxxramas", expansion = 2, order = 537, box = { 0.05, 0.00, 2.58 }, view = { 0.7935, -0.3465, 1.6086 }, voices = { { 8913, 2.6, true, "Flee, before it's too late!" }, { 8917, 6.9, true, "Invaders, cease this foolish venture at once! Turn away while you still can!" }, { 8918, 6.3, true, "Perhaps they will come to their senses, and run away as fast as they can!" }, { 8919, 4.5, true, "Do not continue! Turn back while there's still time!" }, { 8916, 4.4, true, "I have no choice but to obey!" }, { 8915, 2.1, true, "Forgive me!" }, { 8914, 5.4, true, "It is... as it should be." } }, title = "Rider of the Four Horsemen" },
    { id = "alar", entry = 19514, name = "Al'ar", label = "Al'ar", level = 73, display = 18945, height = 32.3, span = 46.7, school = "fire", pool = "tbc", icon = "Interface\\Icons\\INV_Misc_Summerfest_BrazierOrange", profile = "caster", kit = { 34121, 35181, 35412, 34341, 35369, 261 }, passives = {}, talentInfo = { { name = "Phoenix Fire", icon = "Interface\\Icons\\INV_Elemental_Primal_Fire", text = "Your Fire damage is increased by 10%." }, { name = "Born of Flame", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Your Fire resistance is increased by 60." }, { name = "Blazing Quills", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Endless Rebirth", icon = "Interface\\Icons\\INV_Elemental_Mote_Fire01", text = "Your maximum health is increased by 8%." }, { name = "Flame Quills", icon = "Interface\\Icons\\Spell_Fire_Fireball", text = "Your damaging spells have a 10% chance to add a Flame Buffet. Once every 15 sec.\n\nAl'ar sheds burning quills with every beat of her wings." }, { name = "Phoenix Dive", icon = "Interface\\Icons\\Spell_Fire_Burnout", text = "Reduces the cooldown of Dive Bomb by 10 sec.\n\nEach time the phoenix falls it rises again, and each time it dives it climbs back faster." } }, tips = { [261] = "Shed two Embers of Al'ar from your burning plumage to fight for you for 20 sec." }, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = true, wave = 3, instance = "Tempest Keep", expansion = 1, order = 399, summons = { [261] = true }, box = { -4.01, -0.26, 13.85 }, title = "Phoenix God" },
    { id = "maulgar", entry = 18831, name = "High King Maulgar", label = "High King Maulgar", level = 73, display = 18649, height = 10.9, span = 10.9, school = "physical", pool = "tbc", icon = "Interface\\Icons\\Ability_Warrior_Cleave", profile = "bruiser", kit = { 39144, 33238, 33230, 26561, 17687, 261 }, passives = {}, talentInfo = { { name = "Hand of Gruul", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "High King's Might", icon = "Interface\\Icons\\Ability_Warrior_WarCry", text = "Your Strength is increased by 8%." }, { name = "Thick Ogre Hide", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Brute Endurance", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 8%." }, { name = "Bladespire Arc", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your melee attacks have a 10% chance to add an Arcing Smash. Once every 10 sec.\n\nGronn are big; ogres are many. Maulgar learned to hit all of them at once." }, { name = "Council of Ogres", icon = "Interface\\Icons\\Ability_Whirlwind", text = "Reduces the cooldown of Whirlwind by 8 sec.\n\nThe High King spins again as soon as his council stops shouting advice." } }, tips = { [261] = "Call the Wild Fel Stalker Olm the Summoner keeps on a chain, to hunt at your side for 20 sec." }, visualKit = 437, soundTransform = 11367, soundDeath = 11369, flies = false, wave = 3, instance = "Gruul's Lair", expansion = 1, order = 396, summons = { [261] = true }, box = { -0.39, -0.01, 5.44 }, voices = { { 11367, 5.2, true, "Gronn are the real power in Outland!" }, { 11368, 5.1, true, "You will not defeat the hand of Gruul!" }, { 11369, 4.3, true, "You won't kill next one so easy." }, { 11370, 4.1, true, "Pah! Does not prove anything!" }, { 11371, 3.3, true, "I'm not afraid of you!" }, { 11372, 3.4, true, "Good, now you fight me!" }, { 11373, 3.6, true, "You not so tough after all!" }, { 11374, 3.5, true, "%s laughs." }, { 11375, 3.4, true, "Maulgar is king!" }, { 11376, 5.1, true, "Gruul... will crush you." } }, title = "Lord of the Ogres" },
    { id = "morogrim", entry = 21213, name = "Morogrim Tidewalker", label = "Morogrim Tidewalker", level = 73, display = 20739, height = 19.8, span = 21.6, school = "frost", pool = "tbc", icon = "Interface\\Icons\\Spell_Frost_SummonWaterElemental", profile = "bruiser", kit = { 37730, 37764, 38049, 33970, 261 }, passives = {}, talentInfo = { { name = "Crushing Tide", icon = "Interface\\Icons\\Spell_Frost_SummonWaterElemental", text = "Your Frost damage is increased by 8%." }, { name = "Seabed Tremors", icon = "Interface\\Icons\\Ability_Warstomp", text = "Your attack power is increased by 8%." }, { name = "Tidewalker's Bulk", icon = "Interface\\Icons\\Ability_Hunter_Pet_Turtle", text = "Your maximum health is increased by 10%." }, { name = "Barnacled Hide", icon = "Interface\\Icons\\INV_Misc_Shell_03", text = "Your armor is increased by 20%." }, { name = "Only the Strong Survive", icon = "Interface\\Icons\\Spell_Shaman_TidalWaves", text = "Your melee attacks have an 8% chance to send out a Tidal Wave. Once every 20 sec.\n\nOnly the strong will survive. Every swing of the sea giant stirs the water ahead of it." }, { name = "Struggling Only Makes It Worse", icon = "Interface\\Icons\\Spell_Frost_ManaRecharge", text = "Reduces the cooldown of Watery Grave by 30 sec.\n\nStruggling only makes it worse. The Tidewalker's graves fill faster than prisoners can swim." } }, tips = { [261] = "Destroy them, my subjects! Call three Tidewalker Lurkers out of the water to fight for you for 20 sec." }, visualKit = 4991, soundTransform = 11321, soundDeath = 11329, flies = false, wave = 3, instance = "Coilfang: Serpentshrine Cavern", expansion = 1, order = 376, summons = { [261] = true }, box = { -0.91, 0.27, 9.81 }, voices = { { 11321, 5.2, true, "Flood of the deep, take you!" }, { 11322, 3.3, true, "By the tides!" }, { 11323, 4.7, true, "Destroy them, my subjects!" }, { 11324, 4.1, true, "There is nowhere to hide!" }, { 11325, 4.3, true, "Soon it will be finished!" }, { 11326, 2.9, true, "It is done!" }, { 11327, 4.2, true, "Struggling only makes it worse." }, { 11328, 4.5, true, "Only the strong will survive." }, { 11329, 5.6, true, "Great currents of... Ageon..." } }, title = "Sea Giant of the Coilfang Tribe" },
    { id = "karathress", entry = 21214, name = "Fathom-Lord Karathress", label = "Fathom-Lord Karathress", level = 73, display = 20662, height = 11.4, span = 11.4, school = "frost", pool = "tbc", icon = "Interface\\Icons\\Achievement_Boss_Warlord_Kalithresh", profile = "caster", kit = { 39297, 38445, 38358, 38234, 38335, 38330, 261 }, passives = {}, talentInfo = { { name = "Tidal Healing", icon = "Interface\\Icons\\Spell_Nature_HealingWaveGreater", text = "Your healing is increased by 12%." }, { name = "Fathom-Lord's Command", icon = "Interface\\Icons\\Spell_Frost_IceShock", text = "Your Frost damage is increased by 8%." }, { name = "Strength of the Fallen Guards", icon = "Interface\\Icons\\INV_Misc_Gem_Pearl_04", text = "Your Intellect is increased by 8%." }, { name = "Naga Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_15", text = "Damage you take is reduced by 5%." }, { name = "Power of Tidalvess", icon = "Interface\\Icons\\Spell_Frost_FrostShock", text = "Your damaging spells have a 10% chance to add a Frost Shock. Once every 20 sec.\n\nGo on, kill them! I'll be the better for it! Each fallen advisor leaves Karathress a new trick." }, { name = "Power of Caribdis", icon = "Interface\\Icons\\Spell_Frost_SummonWaterElemental", text = "Reduces the cooldown of Tidal Surge by 8 sec.\n\nI am more powerful than ever! The tides Caribdis commanded now answer the Fathom-Lord." } }, tips = { [261] = "Guards, lend me your strength! Call Sharkkis's Fathom Lurker to hunt at your side for 20 sec." }, visualKit = 4991, soundTransform = 11277, soundDeath = 11285, flies = false, wave = 3, instance = "Coilfang: Serpentshrine Cavern", expansion = 1, order = 371, summons = { [261] = true }, charModel = true, box = { -1.70, 0.02, 5.54 }, voices = { { 11277, 5.0, true, "Guards, attention! We have visitors...." }, { 11278, 6.8, true, "Your overconfidence will be your undoing! Guards, lend me your strength!" }, { 11279, 6.4, true, "Go on, kill them! I'll be the better for it!" }, { 11280, 4.5, true, "I am more powerful than ever!" }, { 11281, 4.6, true, "More knowledge, more power!" }, { 11282, 3.7, true, "Land-dwelling scum!" }, { 11283, 3.5, true, "Alana be'lendor!" }, { 11284, 3.4, true, "I am rid of you." }, { 11285, 5.7, true, "Her... excellency... awaits." } }, title = "Naga of the Coilfang Tribe" },
    { id = "winterchill", entry = 17767, name = "Rage Winterchill", label = "Rage Winterchill", level = 73, display = 17444, height = 14.8, span = 14.8, school = "frost", pool = "tbc", icon = "Interface\\Icons\\Spell_Frost_FrostArmor02", profile = "caster", kit = { 31249, 31250, 39347, 31256, 36990 }, passives = {}, talentInfo = { { name = "Heart of the Frozen Throne", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "Rot of the Scourge", icon = "Interface\\Icons\\Spell_Shadow_DeathAndDecay", text = "Your Shadow damage is increased by 6%." }, { name = "Phylactery Bound", icon = "Interface\\Icons\\Spell_Shadow_ScourgeBuild", text = "Damage you take is reduced by 5%." }, { name = "Icy Chill of Death", icon = "Interface\\Icons\\Spell_Frost_Frost", text = "Your Frost resistance is increased by 50." }, { name = "It Will Be Colder in Your Grave", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "When you are struck, you have an 8% chance to hurl a Frostbolt at your attacker. Once every 30 sec.\n\nWinterchill's cold answers every blow; whoever dares strike him is slowed to a crawl." }, { name = "Ashes to Ashes", icon = "Interface\\Icons\\Spell_Shadow_PlagueCloud", text = "Your Death and Decay lasts 4 sec longer.\n\nAshes to ashes, dust to dust! The lich lets the blight linger over Hyjal's dead." } }, tips = {}, visualKit = 4991, soundTransform = 11022, soundDeath = 11026, flies = false, wave = 3, instance = "The Battle for Mount Hyjal", expansion = 1, order = 363, box = { 0.19, 0.16, 6.05 }, voices = { { 11026, 5.4, true, "You have won this battle, but not... the... war." }, { 11025, 2.2, true, "All life must perish!" }, { 11057, 2.0, true, "Victory to the Legion!" }, { 11023, 2.3, true, "Crumble and rot!" }, { 11055, 3.7, true, "Ashes to ashes, dust to dust!" }, { 11024, 3.6, true, "Succumb to the icy chill... of death." }, { 11058, 3.4, true, "It will be much colder in your grave." }, { 11022, 10.9, true, "The Legion's final conquest has begun! Once again the subjugation of this world is within our grasp. Let none survive!" } }, title = "Commander of the Scourge" },
    { id = "anetheron", entry = 17808, name = "Anetheron", label = "Anetheron", level = 73, display = 21069, height = 18.2, span = 23.1, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Spell_Shadow_CarrionSwarm", profile = "caster", kit = { 31306, 12098, 31302, 16608, 261 }, passives = {}, talentInfo = { { name = "Master of the Swarm", icon = "Interface\\Icons\\Spell_Shadow_CarrionSwarm", text = "Your Shadow damage is increased by 10%." }, { name = "Nathrezim Cunning", icon = "Interface\\Icons\\Spell_Shadow_MindSteal", text = "Your Intellect is increased by 8%." }, { name = "Dreadlord's Wings", icon = "Interface\\Icons\\Spell_Shadow_Possession", text = "Damage you take is reduced by 5%." }, { name = "Lord of Nightmares", icon = "Interface\\Icons\\Spell_Nature_Sleep", text = "Your casting speed is increased by 6%." }, { name = "Vampiric Aura", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Your damaging spells have a 10% chance to Drain Life from the target. Once every 20 sec.\n\nScream for me. The dreadlord drinks from every wound he opens." }, { name = "The Clock Is Ticking", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bat", text = "Reduces the cooldown of Carrion Swarm by 5 sec.\n\nThe clock... is still... ticking. Anetheron never lets the swarm rest for long." } }, tips = { [261] = "Earth and sky shall burn! A Towering Infernal crashes down to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 10977, soundDeath = 10982, flies = false, wave = 3, instance = "The Battle for Mount Hyjal", expansion = 1, order = 359, summons = { [261] = true }, box = { -4.65, -0.26, 8.21 }, voices = { { 10982, 4.4, true, "The clock... is still... ticking." }, { 10981, 2.5, true, "Your hopes are lost!" }, { 11038, 2.2, true, "Scream for me." }, { 11039, 3.8, true, "Pity, no time for a slow death!" }, { 10979, 3.5, true, "The swarm is eager to feed." }, { 11037, 2.2, true, "Pestilence upon you!" }, { 10978, 1.9, true, "You look tired...." }, { 11545, 1.8, true, "Sweet dreams." }, { 10980, 3.2, true, "Let fire rain from above!" }, { 11036, 3.8, true, "Earth and sky shall burn!" }, { 10977, 7.2, true, "You are defenders of a doomed world! Flee here, and perhaps you will prolong your pathetic lives!" } }, title = "Envoy of Archimonde" },
    { id = "kazrogal", entry = 17888, name = "Kaz'rogal", label = "Kaz'rogal", level = 73, display = 17886, height = 25.7, span = 44.2, school = "physical", pool = "tbc", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordDominate", profile = "bruiser", kit = { 31436, 31480, 31477, 31447, 48193 }, passives = {}, talentInfo = { { name = "Doom-Forged Might", icon = "Interface\\Icons\\Spell_Shadow_UnholyStrength", text = "Your attack power is increased by 10%." }, { name = "Mark of the Doomguard", icon = "Interface\\Icons\\Spell_Shadow_ManaBurn", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Fel Iron Carapace", icon = "Interface\\Icons\\INV_Helmet_08", text = "Your armor is increased by 20%." }, { name = "Legion Vitality", icon = "Interface\\Icons\\Spell_Shadow_DemonicTactics", text = "Your Stamina is increased by 8%." }, { name = "Miserable Nuisance", icon = "Interface\\Icons\\Spell_Shadow_Cripple", text = "Your melee attacks have a 10% chance to add a Malevolent Cleave. Once every 15 sec.\n\nMiserable nuisance! The doomguard's blade keeps swinging long after the first victim falls." }, { name = "Shaza-kiel", icon = "Interface\\Icons\\Spell_Shadow_SiphonMana", text = "Your Mark of Kaz'rogal lasts 3 sec longer.\n\nShaza-kiel! Kaz'rogal's mark burns until there is nothing left to drain." } }, tips = {}, visualKit = 437, soundTransform = 11015, soundDeath = 0, flies = false, wave = 3, instance = "The Battle for Mount Hyjal", expansion = 1, order = 362, box = { -2.89, 0.17, 12.87 }, voices = { { 11017, 1.6, true, "Shaza-kiel!" }, { 11053, 2.3, true, "You are nothing!" }, { 11054, 2.3, true, "Miserable nuisance!" }, { 11016, 3.9, true, "Your death will be a painful one." }, { 11052, 2.5, true, "You... are marked." }, { 11015, 6.3, true, "Cry for mercy! Your meaningless lives will soon be forfeit!" } }, title = "Lieutenant of Archimonde" },
    { id = "azgalor", entry = 17842, name = "Azgalor", label = "Azgalor", level = 73, display = 18526, height = 23.3, span = 39.3, school = "fire", pool = "tbc", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", profile = "bruiser", kit = { 31345, 31340, 31344, 48193, 261 }, passives = {}, talentInfo = { { name = "Pit Lord's Fury", icon = "Interface\\Icons\\Spell_Shadow_RainOfFire", text = "Your Fire damage is increased by 10%." }, { name = "Abandon All Hope", icon = "Interface\\Icons\\Spell_Shadow_CurseOfTounges", text = "Your attack power is increased by 8%." }, { name = "Hide of the Pit", icon = "Interface\\Icons\\Ability_Racial_Avatar", text = "Your maximum health is increased by 10%." }, { name = "Doom Lord's Plate", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Reesh, Hokta!", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your melee attacks have a 10% chance to Cleave. Once every 10 sec.\n\nThe pit lord's glaive swings wide whether he means it to or not." }, { name = "Molten Downpour", icon = "Interface\\Icons\\Spell_Fire_MeteorStorm", text = "Your Rain of Fire covers a 20% larger area.\n\nMannoroth's lieutenant never learned to aim; he learned to burn more ground." } }, tips = { [261] = "No one is going to save you. A Lesser Doomguard claws its way out of the Nether to fight for you for 20 sec." }, visualKit = 286, soundTransform = 10999, soundDeath = 11002, flies = false, wave = 3, instance = "The Battle for Mount Hyjal", expansion = 1, order = 361, summons = { [261] = true }, box = { -13.14, 0.32, 11.38 }, voices = { { 11002, 8.4, true, "Your time is almost... up." }, { 11001, 2.3, true, "Reesh, hokta!" }, { 11048, 2.4, true, "Don't fight it." }, { 11047, 3.4, true, "No one is going to save you." }, { 11046, 3.9, true, "Just a taste... of what awaits you." }, { 11000, 3.6, true, "Suffer, you despicable insect!" }, { 10999, 14.3, true, "Abandon all hope! The Legion has returned to finish what was begun so many years ago. This time, there will be no escape!" } }, title = "Lieutenant of Mannoroth" },
    { id = "nalorakk", entry = 23576, name = "Nalorakk", label = "Nalorakk", level = 73, display = 21631, height = 6.8, span = 6.8, school = "physical", pool = "tbc", icon = "Interface\\Icons\\Ability_Racial_BearForm", profile = "bruiser", kit = { 42384, 31429, 42402, 48193, 261 }, passives = {}, talentInfo = { { name = "Amani Axes", icon = "Interface\\Icons\\Ability_Racial_BloodRage", text = "Your attack power is increased by 8%." }, { name = "Troll Berserker", icon = "Interface\\Icons\\Ability_Hunter_Pet_Hyena", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Zul'Aman Steel", icon = "Interface\\Icons\\Ability_Parry", text = "Your chance to parry is increased by 6%." }, { name = "Trollish Regeneration", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Your maximum health is increased by 6%." }, { name = "You Call on da Beast", icon = "Interface\\Icons\\Ability_Druid_Mangle2", text = "Your melee attacks have an 8% chance to add a Brutal Swipe. Once every 20 sec.\n\nYou call on da beast, you gonna get more dan you bargain for!" }, { name = "Killin' Time", icon = "Interface\\Icons\\Ability_Druid_ChallangingRoar", text = "Reduces the cooldown of Surge by 5 sec.\n\nIt be killin' time! Nalorakk never waits long before charging in again." } }, tips = { [261] = "Get da move on, guards! Call two Amani'shi Warbringers to fight for you for 20 sec." }, visualKit = 437, soundTransform = 12070, soundDeath = 12077, flies = false, wave = 3, instance = "Zul'Aman", expansion = 1, order = 413, summons = { [261] = true }, box = { -0.54, 0.10, 3.38 }, voices = { { 12066, 3.5, true, "Get da move on, guards! It be killin' time!" }, { 12067, 5.9, true, "Guards, go already! Who you more afraid of, dem... or me?" }, { 12068, 4.9, true, "Ride now! Ride out dere and bring me back some heads!" }, { 12069, 7.9, true, "I be losin' me patience! Go on: make dem wish dey was never born!" }, { 12070, 1.8, true, "You be dead soon enough!" }, { 12071, 2.3, true, "I bring da pain!" }, { 12072, 4.2, true, "You call on da beast, you gonna get more dan you bargain for!" }, { 12073, 2.4, true, "Make way for da Nalorakk!" }, { 12074, 3.3, true, "You had your chance; now it be too late!" }, { 12075, 3.1, true, "Now whatchoo got to say?" }, { 12076, 3.2, true, "Da Amani gonna rule again!" }, { 12077, 3.6, true, "I... be waitin' on da udda side...." } }, title = "Bear Avatar", visages = { "nalorakk_bear" }, shape = "Troll" },
    { id = "akilzon", entry = 23574, name = "Akil'zon", label = "Akil'zon", level = 73, display = 21630, height = 8.4, span = 8.4, school = "nature", pool = "tbc", icon = "Interface\\Icons\\Ability_Hunter_Pet_Owl", profile = "caster", kit = { 43622, 43661, 43621, 43657, 261 }, passives = {}, talentInfo = { { name = "Eye of the Storm", icon = "Interface\\Icons\\Spell_Nature_EyeOfTheStorm", text = "Your Nature damage is increased by 10%." }, { name = "Eagle's Swiftness", icon = "Interface\\Icons\\Ability_Hunter_EagleEye", text = "Your casting speed is increased by 8%." }, { name = "Predator of the Skies", icon = "Interface\\Icons\\Spell_Nature_StormReach", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Unkillable Spirit", icon = "Interface\\Icons\\Spell_Nature_SpiritWolf", text = "Damage you take is reduced by 5%." }, { name = "I Be da Predator", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your damaging spells have a 10% chance to Call Lightning on the target. Once every 15 sec.\n\nThe eagle avatar is thick with static; lightning finds whatever he looks at." }, { name = "Coming Storm", icon = "Interface\\Icons\\Spell_Nature_CallStorm", text = "Reduces the cooldown of Electrical Storm by 15 sec.\n\nDa storm be comin' faster now. Akil'zon calls it down before the last one has cleared." } }, tips = { [261] = "Call two Amani Eagles down from the peaks to rake your foes for 20 sec." }, visualKit = 282, soundTransform = 12013, soundDeath = 0, flies = false, wave = 3, instance = "Zul'Aman", expansion = 1, order = 408, summons = { [261] = true }, box = { 0.50, 0.12, 4.17 }, voices = { { 12013, 3.6, true, "I be da predator! You da prey..." }, { 12014, 2.2, true, "Feed, me bruddahs!" }, { 12015, 2.2, true, "Your death gonna be quick, strangers. You shoulda never come to this place...." }, { 12016, 2.8, true, "All you be doin' is wastin' me time!" }, { 12017, 1.3, true, "Ya got nothin'!" }, { 12018, 1.3, true, "Stop your cryin'!" }, { 12019, 3.7, true, "You can't... kill... me spirit!" } }, title = "Eagle Avatar" },
    { id = "janalai", entry = 23578, name = "Jan'alai", label = "Jan'alai", level = 73, display = 21633, height = 7.1, span = 7.1, school = "fire", pool = "tbc", icon = "Interface\\Icons\\Ability_Hunter_Pet_DragonHawk", profile = "caster", kit = { 43140, 42630, 43299, 18432, 261 }, passives = {}, talentInfo = { { name = "Dragonhawk Fire", icon = "Interface\\Icons\\Ability_Hunter_Pet_DragonHawk", text = "Your Fire damage is increased by 10%." }, { name = "Hatchery Firebombs", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Frenzied Wings", icon = "Interface\\Icons\\Spell_Fire_BurningSpeed", text = "Your casting speed is increased by 6%." }, { name = "Mother of the Brood", icon = "Interface\\Icons\\INV_Elemental_Mote_Fire01", text = "Your maximum health is increased by 8%." }, { name = "Spirits of da Wind", icon = "Interface\\Icons\\INV_Misc_Bomb_04", text = "When you are struck, you have a 10% chance to drop a Fire Bomb. Once every 20 sec.\n\nSpirits of da wind be your doom! Jan'alai keeps a bomb for anyone who comes too close." }, { name = "Tazaga-choo", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Your Flame Breath deals 15% more damage.\n\nThe spirit of da dragonhawk be hungry, and its breath gets hotter the longer it waits." } }, tips = { [42630] = "Drop a fire bomb at your feet, blasting enemies right beside you with 6125 Fire damage.", [261] = "I show you strength... in numbers. Hatch three Amani Dragonhawk Hatchlings to fight for you for 20 sec." }, visualKit = 286, soundTransform = 12031, soundDeath = 12038, flies = false, wave = 3, instance = "Zul'Aman", expansion = 1, order = 412, summons = { [261] = true }, box = { -0.73, -0.03, 3.55 }, voices = { { 12031, 3.7, true, "Spirits of da wind be your doom!" }, { 12032, 1.3, true, "I burn ya now!" }, { 12033, 3.1, true, "Where ma hatcha? Get to work on dem eggs!" }, { 12034, 3.4, true, "I show you strength... in numbers." }, { 12035, 1.7, true, "You done run outta time!" }, { 12036, 1.9, true, "It all be over now, mon!" }, { 12037, 1.5, true, "Tazaga-choo!" }, { 12038, 4.8, true, "Zul'jin... got a surprise for you...." }, { 12039, 6.1, true, "Come, strangers. The spirit of da dragonhawk be hungry for worthy souls." }, { 12040, 6.0, true, "Come, friends. Your bodies gonna feed ma hatchlings, and your souls gonna fill me with power!" } }, title = "Dragonhawk Avatar" },
    { id = "halazzi", entry = 23577, name = "Halazzi", label = "Halazzi", level = 73, display = 21632, height = 6.4, span = 6.4, school = "nature", pool = "tbc", icon = "Interface\\Icons\\Ability_Mount_JungleTiger", profile = "bruiser", kit = { 43267, 43243, 43139, 43303, 261 }, passives = {}, talentInfo = { { name = "Lynx Flurry", icon = "Interface\\Icons\\Ability_Hunter_Pet_Cat", text = "Your attack speed is increased by 10%." }, { name = "Fang and Claw", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your chance to critically hit with melee attacks is increased by 6%." }, { name = "Untamed Spirit", icon = "Interface\\Icons\\Ability_Mount_JungleTiger", text = "Your Agility is increased by 8%." }, { name = "Pouncing Stride", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Your movement speed is increased by 10%." }, { name = "Get on Ya Knees", icon = "Interface\\Icons\\Ability_Druid_Ravage", text = "Your melee attacks have a 10% chance to add a Saber Lash. Once every 15 sec.\n\nGet on ya knees and bow to da fang and claw!" }, { name = "Loa of the Hunt", icon = "Interface\\Icons\\Ability_Druid_CatForm", text = "Your Saber Lash deals 15% more damage.\n\nThe lynx loa guides every blade to the throat." } }, tips = { [261] = "Split your lynx spirit from your body to hunt at your side for 20 sec." }, visualKit = 282, soundTransform = 12020, soundDeath = 12028, flies = false, wave = 3, instance = "Zul'Aman", expansion = 1, order = 409, summons = { [261] = true }, box = { -0.87, 0.13, 3.10 }, voices = { { 12020, 4.3, true, "Get on ya knees and bow.... to da fang and claw!" }, { 12026, 2.3, true, "You can fight da power!" }, { 12027, 1.7, true, "Ya all gonna fail!" }, { 12023, 2.5, true, "Me gonna carve ya now!" }, { 12024, 2.9, true, "You gonna leave in pieces!" }, { 12021, 3.4, true, "I fight wit untamed spirit...." }, { 12022, 2.3, true, "Spirit, come back to me!" }, { 12028, 3.8, true, "Chaga... chokajinn." } }, title = "Lynx Avatar", visages = { "halazzi_troll" }, shape = "Avatar" },
    { id = "kalecgos", entry = 24850, name = "Kalecgos", label = "Kalecgos", level = 73, display = 23345, height = 25.3, span = 53.0, school = "arcane", pool = "tbc", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Blue", profile = "caster", kit = { 44799, 45122, 44353, 44806 }, passives = {}, talentInfo = { { name = "Breath of the Blue Flight", icon = "Interface\\Icons\\Spell_Frost_ChillingBlast", text = "Your Frost damage is increased by 10%." }, { name = "Arcane Heritage", icon = "Interface\\Icons\\Spell_Arcane_ArcanePotency", text = "Your Arcane damage is increased by 6%." }, { name = "Blue Dragonscale", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Blue", text = "Your armor is increased by 20%." }, { name = "Guardian of Anveena", icon = "Interface\\Icons\\Spell_Arcane_PrismaticCloak", text = "Your maximum health is increased by 8%." }, { name = "You Were Warned", icon = "Interface\\Icons\\INV_Misc_MonsterTail_03", text = "When you are struck, you have a 10% chance to breathe Frost Breath over the enemies before you. Once every 30 sec.\n\nYou were warned! Kalecgos guards Anveena from every side at once." }, { name = "No Longer a Slave", icon = "Interface\\Icons\\Spell_Frost_FreezingBreath", text = "Reduces the cooldown of Frost Breath by 4 sec.\n\nNo longer will I be a slave to Malygos! Kalecgos breathes freely now." } }, tips = {}, visualKit = 1005, soundTransform = 12422, soundDeath = 0, flies = true, wave = 3, instance = "The Sunwell", expansion = 1, order = 420, box = { -8.77, 0.05, 11.43 }, voices = { { 12422, 7.9, true, "Aggh!! No longer will I be a slave to Malygos! Challenge me and you will be destroyed!" }, { 12425, 2.8, true, "In the name of Kil'jaeden!" }, { 12426, 2.0, true, "You were warned!" }, { 12431, 7.8, false, "I am forever in your debt. Once we have triumphed over Kil'jaeden, this entire world will be in your debt as well." }, { 12433, 2.3, true, "Kil'jaeden must be destroyed!" } }, title = "Emissary of the Blue Dragonflight", visages = { "kalec" }, shape = "Dragon" },
    { id = "sathrovarr", entry = 24892, name = "Sathrovarr the Corruptor", label = "Sathrovarr the Corruptor", level = 73, display = 26628, height = 10.9, span = 13.9, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Spell_Shadow_CurseOfAchimonde", profile = "caster", kit = { 45029, 45032, 45031, 12098 }, passives = {}, talentInfo = { { name = "Boundless Agony", icon = "Interface\\Icons\\Spell_Shadow_CurseOfSargeras", text = "Your Shadow damage is increased by 10%." }, { name = "Corruptor's Whispers", icon = "Interface\\Icons\\Spell_Shadow_GatherShadows", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Demon Hide", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Your armor is increased by 15%." }, { name = "Shelter of the Spectral Realm", icon = "Interface\\Icons\\Spell_Shadow_Nethercloak", text = "Damage you take is reduced by 6%." }, { name = "Corruption Spreads", icon = "Interface\\Icons\\Spell_Shadow_CurseOfAchimonde", text = "Your damaging spells have an 8% chance to lay Curse of Boundless Agony. Once every 30 sec.\n\nSathrovarr's corruption was never meant to stay in one dragon." }, { name = "Fed on Misery", icon = "Interface\\Icons\\Spell_Shadow_UnholyStrength", text = "Reduces the cooldown of Corrupting Strike by 10 sec.\n\nThe Corruptor feeds on the torment he spreads and strikes again the sooner for it." } }, tips = {}, visualKit = 7775, soundTransform = 12451, soundDeath = 12452, flies = false, wave = 3, instance = "The Sunwell", expansion = 1, order = 425, box = { -2.79, -0.16, 4.93 }, voices = { { 12451, 8.6, true, "There will be no reprieve! My work here is nearly finished!" }, { 12455, 1.5, true, "Piteous mortal!" }, { 12456, 4.8, true, "Haven't you heard? I always win!" }, { 12452, 4.9, true, "I'm never on the... losing... side!" }, { 12453, 3.5, true, "Your misery is my delight!" }, { 12454, 3.1, true, "I will watch you bleed!" } }, title = "Dreadlord of the Burning Legion" },
    { id = "sacrolash", entry = 25165, name = "Lady Sacrolash", label = "Lady Sacrolash", level = 73, display = 23177, height = 7.2, span = 7.2, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Spell_Shadow_ShadowFury", profile = "bruiser", kit = { 45248, 45256, 45329, 45271 }, passives = {}, talentInfo = { { name = "Shadow Blades", icon = "Interface\\Icons\\Ability_Rogue_ShadowStrikes", text = "Your Shadow damage is increased by 10%." }, { name = "Twin Precision", icon = "Interface\\Icons\\Ability_Rogue_DualWeild", text = "Your chance to critically hit with melee attacks is increased by 6%." }, { name = "Sister's Fury", icon = "Interface\\Icons\\Ability_Warrior_BloodFrenzy", text = "Your attack speed is increased by 8%." }, { name = "Eredar Poise", icon = "Interface\\Icons\\Spell_Shadow_Shadowfury", text = "Your Agility is increased by 6%." }, { name = "Shadow to the Aid of Fire", icon = "Interface\\Icons\\Ability_Rogue_ShadowDance", text = "Your melee attacks have a 10% chance to loose Shadow Blades. Once every 15 sec.\n\nAlythess! Your fire burns within me! The dark twin's blades answer her sister's flame." }, { name = "Ee-nok Kryul", icon = "Interface\\Icons\\Spell_Shadow_Twilight", text = "Reduces the cooldown of Shadow Nova by 5 sec.\n\nEe-nok Kryul! Sacrolash's novas follow each other like steps in a dance." } }, tips = { [45248] = "Slash the enemies around you with shadow blades for 2550 Shadow damage." }, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "The Sunwell", expansion = 1, order = 422, box = { -0.23, 0.05, 3.59 }, voices = { { 12484, 14.6, true, "Misery..." }, { 12488, 4.7, true, "Alythess! Your fire burns within me!" }, { 12486, 2.3, true, "Shadows engulf." }, { 12487, 1.9, true, "Ee-nok Kryul!" }, { 12485, 3.3, true, "Shadow to the aid of fire!" } }, title = "Sister of Alythess" },
    { id = "alythess", entry = 25166, name = "Grand Warlock Alythess", label = "Grand Warlock Alythess", level = 73, display = 23334, height = 7.2, span = 7.2, school = "fire", pool = "tbc", icon = "Interface\\Icons\\Spell_Fire_FelFlameRing", profile = "caster", kit = { 45235, 45232, 45342, 46771, 45230 }, passives = {}, talentInfo = { { name = "Grand Warlock's Flame", icon = "Interface\\Icons\\Spell_Fire_FelFlameStrike", text = "Your Fire damage is increased by 10%." }, { name = "Pillars of Chaos", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Conflagrating Will", icon = "Interface\\Icons\\Spell_Fire_Immolation", text = "Your casting speed is increased by 6%." }, { name = "Bond of the Eredar Twins", icon = "Interface\\Icons\\Spell_Shadow_SealOfKings", text = "Damage you take is reduced by 5%." }, { name = "Fire to the Aid of Shadow", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "Your damaging spells have an 8% chance to add a Flame Sear. Once every 20 sec.\n\nSacrolash! The twins share one fire; Alythess never casts alone." }, { name = "Edir Harach", icon = "Interface\\Icons\\Spell_Fire_BurningSpeed", text = "Your Blaze deals 15% more damage.\n\nEdir harach! The grand warlock's blaze burns hotter with every cast." } }, tips = { [45235] = "Hurl a blaze at an enemy for 5525 Fire damage.", [45230] = "Stoke your pyrogenics, raising your Fire damage by 35% for 15 sec." }, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "The Sunwell", expansion = 1, order = 418, box = { -0.23, 0.05, 3.59 }, voices = { { 12490, 2.7, true, "Fires consume." }, { 12491, 2.1, true, "Edir harach!" }, { 12494, 4.9, true, "Der'ek... manul." }, { 12492, 2.2, true, "Sacrolash!" }, { 12489, 3.3, true, "Fire to the aid of shadow!" }, { 12493, 2.5, true, "Your luck has run its course!" } }, title = "Sister of Sacrolash" },
    { id = "gathios", entry = 22949, name = "Gathios the Shatterer", label = "Gathios the Shatterer", level = 73, display = 21416, height = 4.5, span = 4.5, school = "holy", pool = "tbc", icon = "Interface\\Icons\\Spell_Holy_SealOfMight", profile = "tank", kit = { 41541, 41470, 41468, 41459, 41452, 41450, 37548 }, passives = {}, talentInfo = { { name = "Shatterer's Bulwark", icon = "Interface\\Icons\\Spell_Holy_DevotionAura", text = "Your armor is increased by 25%." }, { name = "Blood Knight's Resolve", icon = "Interface\\Icons\\Spell_Holy_ArdentDefender", text = "Damage you take is reduced by 8%." }, { name = "Seal of the Council", icon = "Interface\\Icons\\Spell_Holy_SealOfFury", text = "The threat you cause is increased by 30%." }, { name = "Hammer of the Blood Knight", icon = "Interface\\Icons\\Spell_Holy_SealOfBlood", text = "Your Holy damage is increased by 8%." }, { name = "Selama Am'oronor", icon = "Interface\\Icons\\Spell_Holy_InnerFire", text = "When you are struck, you have a 10% chance to Consecrate the ground. Once every 30 sec.\n\nSelama am'oronor! Wherever the Shatterer is pressed, the ground under him catches holy fire." }, { name = "Enjoy Your Final Moments", icon = "Interface\\Icons\\Spell_Holy_SealOfMight", text = "Reduces the cooldown of Hammer of Justice by 15 sec.\n\nGathios does not wait to judge; the hammer is already on its way." } }, tips = {}, visualKit = 154, soundTransform = 11422, soundDeath = 11425, flies = false, wave = 3, instance = "Black Temple", expansion = 1, order = 381, charModel = true, box = { -0.27, -0.04, 2.22 }, voices = { { 11422, 2.7, true, "I have better things to do..." }, { 11428, 2.0, true, "Enough games!" }, { 11426, 2.8, true, "Enjoy your final moments." }, { 11427, 2.4, true, "You are MINE!" }, { 11423, 2.4, true, "Selama am'oronor!" }, { 11424, 2.0, true, "Well done!" }, { 11425, 2.6, true, "Lord Illidan, I..." } }, title = "Paladin of the Illidari Council" },
    { id = "zerevor", entry = 22950, name = "High Nethermancer Zerevor", label = "High Nethermancer Zerevor", level = 73, display = 21417, height = 4.5, span = 4.5, school = "arcane", pool = "tbc", icon = "Interface\\Icons\\Spell_Arcane_StarFire", profile = "caster", kit = { 41483, 41481, 41482, 41524, 41478 }, passives = {}, talentInfo = { { name = "High Nethermancy", icon = "Interface\\Icons\\Spell_Arcane_Blast", text = "Your Arcane damage is increased by 10%." }, { name = "Thalassian Arcane Mind", icon = "Interface\\Icons\\Spell_Arcane_MindMastery", text = "Your Intellect is increased by 8%." }, { name = "Nethermancer's Discipline", icon = "Interface\\Icons\\Spell_Arcane_ManaTap", text = "The mana cost of your Arcane spells is reduced by 8%." }, { name = "Quickened Incantations", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", text = "Your casting speed is increased by 5%." }, { name = "Common, Such a Crude Language", icon = "Interface\\Icons\\Spell_Nature_WispSplode", text = "When you are struck, you have a 10% chance to cast Arcane Explosion. Once every 15 sec.\n\nCommon... such a crude language. Bandal! Zerevor answers any brute who gets close with a blast." }, { name = "Shal'mor Sinabanal", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "Reduces the cooldown of Flamestrike by 4 sec.\n\nThe nethermancer weaves fire, frost and arcane in turn, and the fire comes round again quickly." } }, tips = {}, visualKit = 1005, soundTransform = 11440, soundDeath = 11443, flies = false, wave = 3, instance = "Black Temple", expansion = 1, order = 383, charModel = true, box = { -0.27, -0.04, 2.22 }, voices = { { 11440, 5.8, true, "Common... such a crude language. Bandal!" }, { 11446, 2.7, true, "Shal'mor sinabanal!" }, { 11444, 2.2, true, "Diel fin'al." }, { 11445, 2.9, true, "Sha'amoor ara mashal?" }, { 11441, 2.1, true, "Shorel'aran." }, { 11442, 2.1, true, "Belesa menoor!" }, { 11443, 3.1, true, "Diel ma'ahn... orindel'o." } }, title = "Member of the Illidari Council" },
    { id = "malande", entry = 22951, name = "Lady Malande", label = "Lady Malande", level = 73, display = 21419, height = 4.0, span = 4.0, school = "holy", pool = "tbc", icon = "Interface\\Icons\\Spell_Holy_HolySmite", profile = "caster", kit = { 41471, 41472, 41372, 41475, 41451 }, passives = {}, talentInfo = { { name = "Circle of the Sunwell", icon = "Interface\\Icons\\Spell_Holy_CircleOfRenewal", text = "Your healing is increased by 15%." }, { name = "Empowered Smite", icon = "Interface\\Icons\\Spell_Holy_HolySmite", text = "Your Holy damage is increased by 8%." }, { name = "Priestess's Spirit", icon = "Interface\\Icons\\Spell_Holy_DivineSpirit", text = "Your Spirit is increased by 10%." }, { name = "Light of Quel'Thalas", icon = "Interface\\Icons\\Spell_Holy_HolyGuidance", text = "The mana cost of your Holy spells is reduced by 10%." }, { name = "Flee or Die", icon = "Interface\\Icons\\Spell_Holy_SearingLight", text = "Your damaging spells have a 10% chance to add Divine Wrath. Once every 15 sec.\n\nFlee or die! Malande's Light burns as readily as it mends." }, { name = "As It Should Be", icon = "Interface\\Icons\\Spell_Holy_PowerWordShield", text = "Reduces the cooldown of Reflective Shield by 8 sec.\n\nAs it should be. The priestess raises her veil again before the last blow has landed." } }, tips = {}, visualKit = 154, soundTransform = 11482, soundDeath = 11485, flies = false, wave = 3, instance = "Black Temple", expansion = 1, order = 387, charModel = true, box = { -0.15, -0.06, 2.01 }, voices = { { 11482, 3.0, true, "Flee or die!" }, { 11488, 4.0, true, "For Quel'Thalas! For the Sunwell!" }, { 11486, 2.9, true, "No second chances!" }, { 11487, 2.7, true, "I'm full of surprises!" }, { 11483, 2.2, true, "My work is done." }, { 11484, 1.8, true, "As it should be!" }, { 11485, 2.9, true, "Destiny... awaits." } }, title = "Priestess of the Illidari Council" },
