hattered Walkway" },
    { id = "freya", entry = 32906, name = "Freya", label = "Freya", level = 83, display = 28777, height = 19.5, span = 19.5, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Freya_01", profile = "caster", kit = { 62623, 62589, 62325, 43585, 64587, 43421, 261 }, passives = {}, talentInfo = { { name = "Planetary Overseer", icon = "Interface\\Icons\\Spell_Nature_Rejuvenation", text = "Your Nature damage is increased by 10%." }, { name = "Attuned to Nature", icon = "Interface\\Icons\\Spell_Nature_ProtectionformNature", text = "Your healing is increased by 10%." }, { name = "Hardened Bark", icon = "Interface\\Icons\\Spell_Nature_StoneClawTotem", text = "Your armor is increased by 20%." }, { name = "Photosynthesis", icon = "Interface\\Icons\\Spell_Nature_Tranquility", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Seed of the Garden", icon = "Interface\\Icons\\Spell_Nature_StrangleVines", text = "When you are struck, you have a 10% chance to detonate a Nature Bomb. Once every 20 sec.\n\nThe garden answers for its keeper; strike Freya and the ground bursts." }, { name = "Touch of Eonar", icon = "Interface\\Icons\\Ability_Druid_EclipseOrange", text = "Your Sunbeam deals 15% more damage.\n\nEonar's gift lights every beam Freya calls down." } }, tips = { [43421] = "Lay Eonar's bloom on yourself, healing 4713 every 1 sec for 7 sec.", [261] = "Call two treants out of the Conservatory of Life to fight for you for 20 sec." }, visualKit = 282, soundTransform = 15526, soundDeath = 15531, flies = false, wave = 3, instance = "Ulduar", expansion = 2, order = 489, summons = { [261] = true }, box = { -0.09, -0.68, 9.72 }, voices = { { 15526, 3.2, true, "The Conservatory must be protected!" }, { 15527, 3.7, true, "Elders grant me your strength!" }, { 15529, 1.2, true, "Forgive me." }, { 15530, 3.6, true, "From your death springs life anew!" }, { 15531, 10.2, true, "His hold on me dissipates. I can see clearly once more. Thank you, heroes." }, { 15532, 4.1, true, "You have strayed too far. Wasted too much time...." }, { 15528, 3.1, true, "Eonar, your servant requires aid!" }, { 15533, 1.9, true, "Children, assist me!" }, { 15534, 3.3, true, "The swarm of the elements shall overtake you!" } }, title = "Planetary Overseer" },
    { id = "auriaya", entry = 33515, name = "Auriaya", label = "Auriaya", level = 83, display = 28651, height = 18.4, span = 18.4, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Auriaya_01", profile = "bruiser", kit = { 64422, 64386, 39005, 64666, 64375, 261 }, passives = {}, talentInfo = { { name = "Guardian of the Observation Ring", icon = "Interface\\Icons\\Ability_Hunter_Pet_Cat", text = "Your attack power is increased by 10%." }, { name = "Feral Essence", icon = "Interface\\Icons\\Ability_Druid_CatForm", text = "Your attack speed is increased by 8%." }, { name = "Titan's Grace", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your Agility is increased by 8%." }, { name = "Strength of the Pack", icon = "Interface\\Icons\\Ability_Hunter_Pet_Wolf", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Feral Rending", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your melee attacks have a 10% chance to Rip Flesh. Once every 15 sec.\n\nAuriaya's cats taught her to leave no clean wounds." }, { name = "Sentinel's Leap", icon = "Interface\\Icons\\Ability_Druid_SupriseAttack", text = "Reduces the cooldown of Savage Pounce by 5 sec.\n\nThe keeper of the watchers pounces as fast as her sentries." } }, tips = { [261] = "Loose three Swarming Guardians, the sentry cats of the Observation Ring, to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 15473, soundDeath = 15476, flies = false, wave = 3, instance = "Ulduar", expansion = 2, order = 488, summons = { [261] = true }, box = { 0.10, -0.89, 9.15 }, voices = { { 15473, 4.3, true, "Some things are better left alone!" }, { 15474, 3.0, true, "The secret dies with you." }, { 15475, 2.1, true, "There is no escape!" }, { 15477, 2.2, true, "You waste my time!" } }, title = "Guardian of the Observation Ring" },
    { id = "xt002", entry = 33293, name = "XT-002 Deconstructor", label = "XT-002 Deconstructor", level = 83, display = 28611, height = 28.9, span = 28.9, school = "arcane", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_XT002Deconstructor_01", profile = "bruiser", kit = { 39050, 63018, 63024, 261 }, passives = {}, talentInfo = { { name = "Creation of Mimiron", icon = "Interface\\Icons\\INV_Gizmo_02", text = "Your armor is increased by 20%." }, { name = "Heart of the Deconstructor", icon = "Interface\\Icons\\INV_Misc_Gear_01", text = "Your maximum health is increased by 10%." }, { name = "Tantrum", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "New Toys", icon = "Interface\\Icons\\INV_Misc_Bomb_02", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Heartbreak", icon = "Interface\\Icons\\Spell_Holy_SearingLight", text = "When you are struck, you have an 8% chance to charge every enemy near you with Searing Light. Once every 30 sec.\n\nXT wants to play! Break his toys and he breaks yours." }, { name = "So Tired", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Reduces the cooldown of Gravity Bomb by 8 sec.\n\nThe Deconstructor throws bombs faster when he is having fun." } }, tips = { [261] = "I'm tired of these toys! Call three Scrapbots to fight for you for 20 sec." }, visualKit = 1005, soundTransform = 15724, soundDeath = 15731, flies = false, wave = 3, instance = "Ulduar", expansion = 2, order = 500, summons = { [261] = true }, box = { 0.81, -0.04, 14.53 }, voices = { { 15724, 5.8, true, "New toys? For me? I promise I won't break them this time!" }, { 15725, 5.0, true, "So tired. I will rest for just a moment!" }, { 15726, 2.0, true, "I'm ready to play!" }, { 15727, 4.2, true, "NO! NO! NO! NO! NO!" }, { 15728, 3.1, true, "I... I think I broke it." }, { 15729, 2.7, true, "I guess it doesn't bend that way." }, { 15730, 4.4, true, "I'm tired of these toys. I don't want to play anymore!" }, { 15731, 7.5, true, "You are bad... Toys... Very... Baaaaad" }, { 15732, 6.0, true, "Time for a new game! My old toys will fight my new toys!" } }, title = "Creation of Mimiron" },
    { id = "vezax", entry = 33271, name = "General Vezax", label = "General Vezax", level = 83, display = 28548, height = 32.4, span = 37.2, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_GeneralVezax_01", profile = "caster", kit = { 72320, 62661, 16430, 30852 }, passives = {}, talentInfo = { { name = "Commander of the Faceless", icon = "Interface\\Icons\\Spell_Shadow_ShadowFury", text = "Your Shadow damage is increased by 10%." }, { name = "Aura of Despair", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Chitin of the Old God", icon = "Interface\\Icons\\INV_Misc_MonsterSpiderCarapace_01", text = "Your armor is increased by 20%." }, { name = "Saronite Vapors", icon = "Interface\\Icons\\INV_Ore_Saronite_01", text = "Your maximum health is increased by 8%." }, { name = "Profound Darkness", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your damaging spells have an 8% chance to add a Shadow Crash. Once every 20 sec.\n\nYour defeat was inevitable! Vezax's shadow falls where it pleases." }, { name = "The Old God Whispers", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain", text = "Your Mark of the Faceless lasts 3 sec longer.\n\nThe mark of the faceless is slow to fade." } }, tips = {}, visualKit = 7775, soundTransform = 15542, soundDeath = 15546, flies = false, wave = 3, instance = "Ulduar", expansion = 2, order = 490, box = { -10.11, 1.04, 15.99 }, voices = { { 15542, 6.2, true, "Your destruction will herald a new age of suffering!" }, { 15543, 7.3, true, "You thought to stand before the legions of death and survive?" }, { 15544, 6.0, true, "Defiance... a flaw of mortality." }, { 15545, 10.3, true, "The black blood of Yogg-Saron courses through me! I. AM. UNSTOPPABLE!" }, { 15546, 6.0, true, "Oh, what horrors await...." }, { 15547, 4.8, true, "Your defeat was inevitable." }, { 15548, 5.2, true, "Behold now: terror absolute!" } }, title = "Commander of the Faceless Ones" },
