    { id = "acidmaw", entry = 35144, name = "Acidmaw", label = "Acidmaw", level = 83, display = 29815, height = 25.8, span = 25.8, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Spell_Nature_Acid_01", profile = "caster", kit = { 66880, 66901, 66823, 66818, 66794 }, passives = {}, talentInfo = { { name = "Acidic Venom", icon = "Interface\\Icons\\Spell_Nature_Acid_01", text = "Your Nature damage is increased by 10%." }, { name = "Jormungar Hide", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your armor is increased by 20%." }, { name = "Twin Jormungar", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Paralytic Venom", icon = "Interface\\Icons\\Ability_Creature_Poison_03", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Acid Blood", icon = "Interface\\Icons\\Ability_Creature_Poison_01", text = "When you are struck, you have a 10% chance to Acid Spit at the attacker. Once every 15 sec.\n\nStrike the jormungar and it spits back." }, { name = "Out of the Sand", icon = "Interface\\Icons\\Ability_Creature_Poison_05", text = "Reduces the cooldown of Acidic Spew by 5 sec.\n\nAcidmaw's spew comes again before the sand settles." } }, tips = { [66818] = "Spew acid over the enemies before you for 2.5 sec, burning them with Nature damage." }, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Trial of the Crusader", expansion = 2, order = 549, box = { -0.74, -0.22, 9.54 }, title = "Beast of Northrend", visages = { "acidmaw_mobile" }, shape = "Rooted" },
    { id = "jaraxxus", entry = 34780, name = "Lord Jaraxxus", label = "Lord Jaraxxus", level = 83, display = 29615, height = 12.6, span = 12.6, school = "fire", pool = "wotlk", icon = "Interface\\Icons\\Spell_Fire_FelFlameRing", profile = "caster", kit = { 66532, 66528, 41958, 66228, 261 }, passives = {}, talentInfo = { { name = "Eredar Lord of the Burning Legion", icon = "Interface\\Icons\\Spell_Fire_FelFlameRing", text = "Your Fire damage is increased by 10%." }, { name = "Nether Power", icon = "Interface\\Icons\\Spell_Shadow_SealOfKings", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Legion Plate", icon = "Interface\\Icons\\INV_Chest_Plate16", text = "Your armor is increased by 20%." }, { name = "Fel Vigour", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 8%." }, { name = "Nether Portal", icon = "Interface\\Icons\\Spell_Fire_FelFlameBolt", text = "When you are struck, you have a 10% chance to answer with Fel Lightning. Once every 20 sec.\n\nThe Nether stands open behind the Eredar lord; strike him and it strikes back." }, { name = "Incinerate Flesh", icon = "Interface\\Icons\\Spell_Fire_FelImmolation", text = "Reduces the cooldown of Incinerate Flesh by 5 sec.\n\nThe Eredar lord's fire never waits for the last to burn out." } }, tips = { [261] = "Call an infernal down from the Twisting Nether to fight for you for 20 sec." }, visualKit = 286, soundTransform = 16144, soundDeath = 16147, flies = false, wave = 3, instance = "Trial of the Crusader", expansion = 2, order = 555, summons = { [261] = true }, box = { -1.18, -0.31, 6.32 }, voices = { { 16143, 5.0, true, "Trifling gnome! Your arrogance will be your undoing!" }, { 16144, 5.3, true, "You face Jaraxxus, Eredar Lord of the Burning Legion!" }, { 16150, 3.9, true, "Come forth, sister! Your master calls!" }, { 16149, 2.4, true, "FLESH FROM BONE!" }, { 16151, 2.6, true, "IN-FER-NO!" }, { 16145, 1.9, true, "Insignificant gnat!" }, { 16146, 2.0, true, "Banished to the Nether!" }, { 16147, 5.9, true, "Another will take my place. Your world is doomed..." } }, title = "Eredar Lord of the Burning Legion" },
    { id = "halion", entry = 39863, name = "Halion", label = "Halion", level = 83, display = 31952, height = 26.1, span = 55.0, school = "fire", pool = "wotlk", icon = "Interface\\Icons\\Spell_Shadow_Twilight", profile = "bruiser", kit = { 74648, 74525, 74806, 74524, 74531, 74562 }, passives = {}, talentInfo = { { name = "The Twilight Destroyer", icon = "Interface\\Icons\\Spell_Shadow_Twilight", text = "Your Fire damage is increased by 10%." }, { name = "Twilight Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your armor is increased by 20%." }, { name = "Twilight Division", icon = "Interface\\Icons\\Spell_Shadow_GatherShadows", text = "Your Shadow damage is increased by 10%." }, { name = "The Heavens Burn", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "Mark of Combustion", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "When you are struck, you have an 8% chance to engulf the attacker in Fiery Combustion. Once every 30 sec.\n\nCrowd the Twilight Destroyer and the heavens mark you for burning." }, { name = "Realm Rending", icon = "Interface\\Icons\\Spell_Fire_MeteorStorm", text = "Increases the radius of Meteor Strike by 50%.\n\nHalion's meteor tears through both realms at once." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = true, wave = 3, instance = "The Ruby Sanctum", expansion = 2, order = 569, box = { -9.83, -0.12, 12.01 }, voices = { { 17499, 7.1, true, "Meddlesome insects! You are too late. The Ruby Sanctum is lost!" }, { 17500, 8.8, true, "Your world teeters on the brink of annihilation. You will ALL bear witness to the coming of a new age of DESTRUCTION!" }, { 17505, 2.7, true, "The heavens burn!" }, { 17507, 7.9, true, "You will find only suffering within the realm of twilight! Enter if you dare!" }, { 17503, 14.3, true, "Relish this victory, mortals, for it will be your last. This world will burn with the master's return!" }, { 17501, 3.2, true, "Another \"hero\" falls." }, { 17504, 2.0, true, "Not good enough...." } }, title = "The Twilight Destroyer" },
    { id = "skadi", entry = 26693, name = "Skadi the Ruthless", label = "Skadi the Ruthless", level = 80, display = 27418, height = 6.9, span = 6.9, school = "frost", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Skadi", profile = "bruiser", kit = { 58967, 50234, 50228, 47579, 261 }, passives = {}, talentInfo = { { name = "Rider of Grauf", icon = "Interface\\Icons\\Ability_Mount_Drake_Proto", text = "Your movement speed is increased by 10%." }, { name = "The Ruthless", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Ymirjar Might", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your Strength is increased by 8%." }, { name = "Frozen Scales", icon = "Interface\\Icons\\Spell_Frost_FrostWard", text = "Your Frost resistance is increased by 50." }, { name = "Poisoned Tips", icon = "Interface\\Icons\\Ability_Poisons", text = "Your melee attacks have an 8% chance to add a Poisoned Spear. Once every 20 sec.\n\nSkadi keeps a spear in every hand that is not holding the hammer." }, { name = "Grauf's Breath", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "Reduces the cooldown of Freezing Cloud by 5 sec.\n\nGrauf circles the Pinnacle and breathes whenever Skadi points." } }, tips = { [261] = "Call two Ymirjar Harpooners of the Pinnacle to fight for you for 20 sec." }, visualKit = 4991, soundTransform = 13497, soundDeath = 13506, flies = false, wave = 3, instance = "Utgarde Pinnacle", expansion = 2, order = 480, summons = { [261] = true }, box = { -0.46, 0.02, 3.45 }, voices = { { 13497, 7.1, true, "What mongrels dare intrude here? Look alive, my brothers! A feast for the one that brings me their heads!" }, { 13504, 2.9, true, "Not so brash now, are you?" }, { 13505, 3.7, true, "I'll mount your skull from the highest tower!" }, { 13506, 9.3, true, "ARGH! You call that... an attack? I'll... show... aghhhh..." }, { 13507, 6.1, true, "You motherless knaves! Your corpses will make fine morsels for my new drake!" }, { 13498, 2.3, true, "Sear them to the bone!" }, { 13499, 3.6, true, "Go now! Leave nothing but ash in your wake!" }, { 13500, 3.0, true, "Cleanse our sacred halls with flame!" } }, title = "Rider of Grauf" },
    { id = "archavon", entry = 31125, name = "Archavon the Stone Watcher", label = "Archavon the Stone Watcher", level = 83, display = 26967, height = 21.7, span = 21.7, school = "physical", pool = "wotlk", icon = "Interface\\Icons\\Spell_Nature_EarthQuake", profile = "tank", kit = { 58666, 59742, 58663, 58960, 37548 }, passives = {}, talentInfo = { { name = "Stone Watcher", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", text = "Your armor is increased by 25%." }, { name = "Giant Guardian", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 12%." }, { name = "Wintergrasp Sentinel", icon = "Interface\\Icons\\Ability_Warrior_Challange", text = "The threat you cause is increased by 30%." }, { name = "Rock Hard", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your Strength is increased by 8%." }, { name = "Rock Shards", icon = "Interface\\Icons\\Spell_Nature_Earthquake", text = "When you are struck, you have an 8% chance to hurl Rock Shards back. Once every 30 sec.\n\nThe stone watcher answers every chip in his hide with a shower of rock." }, { name = "Unmoving", icon = "Interface\\Icons\\Ability_WarStomp", text = "Reduces the cooldown of Stomp by 10 sec.\n\nArchavon's stomps echo through the vault without rest." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Vault of Archavon", expansion = 2, order = 545, box = { 0.31, -0.31, 10.64 }, title = "Giant Guardian of Wintergrasp" },
    { id = "emalon", entry = 33993, name = "Emalon the Storm Watcher", label = "Emalon the Storm Watcher", level = 83, display = 27108, height = 20.8, span = 20.8, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", profile = "caster", kit = { 64213, 64216, 64219, 261 }, passives = {}, talentInfo = { { name = "Storm Watcher", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 10%." }, { name = "Iron Giant", icon = "Interface\\Icons\\INV_Misc_Gear_01", text = "Your armor is increased by 25%." }, { name = "Overcharged", icon = "Interface\\Icons\\Spell_Nature_LightningOverload", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Grounded", icon = "Interface\\Icons\\Spell_Nature_NatureResistanceTotem", text = "Your Nature resistance is increased by 50." }, { name = "Overcharge", icon = "Interface\\Icons\\Spell_Shaman_StaticShock", text = "When you are struck, you have a 10% chance to burst with an Overcharged Blast. Once every 30 sec.\n\nThe storm watcher crackles with charge; touch it and it bursts." }, { name = "Storm Surge", icon = "Interface\\Icons\\Spell_Shaman_ThunderStorm", text = "Reduces the cooldown of Lightning Nova by 5 sec.\n\nEmalon's nova builds faster the longer the storm rages." } }, tips = { [261] = "Call two Tempest Minions of the vault to fight for you for 20 sec." }, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Vault of Archavon", expansion = 2, order = 546, summons = { [261] = true }, box = { 0.37, 0.40, 10.39 }, title = "Iron Giant of Wintergrasp" },
    { id = "koralon", entry = 35013, name = "Koralon the Flame Watcher", label = "Koralon the Flame Watcher", level = 83, display = 29524, height = 21.4, span = 21.4, school = "fire", pool = "wotlk", icon = "Interface\\Icons\\Spell_Fire_FlameBlades", profile = "bruiser", kit = { 66670, 19717, 28884, 66765 }, passives = {}, talentInfo = { { name = "Flame Watcher", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire damage is increased by 10%." }, { name = "Fire Giant", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Molten Hide", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Your Fire resistance is increased by 60." }, { name = "Burning Fury", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "Meteor Fists", icon = "Interface\\Icons\\Spell_Fire_MeteorStorm", text = "Your melee attacks have a 20% chance to land a Meteor Fist. Once every 6 sec.\n\nEvery blow Koralon lands splits its fire with whoever stands beside the target." }, { name = "Molten Core", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Your Burning Breath deals 15% more damage.\n\nThe flame watcher burns hotter the longer he fights." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Vault of Archavon", expansion = 2, order = 547, box = { -0.29, 0.03, 10.69 }, title = "Fire Giant of Wintergrasp" },
    { id = "toravon", entry = 38433, name = "Toravon the Ice Watcher", label = "Toravon the Ice Watcher", level = 83, display = 31089, height = 21.6, span = 21.6, school = "frost", pool = "wotlk", icon = "Interface\\Icons\\Spell_Frost_FrozenCore", profile = "bruiser", kit = { 72034, 72090, 72004, 16803 }, passives = {}, talentInfo = { { name = "Ice Watcher", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "Frost Giant", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Frozen Hide", icon = "Interface\\Icons\\Spell_Frost_FrostWard", text = "Your Frost resistance is increased by 60." }, { name = "Glacial Bulk", icon = "Interface\\Icons\\Spell_Frost_Glacier", text = "Your armor is increased by 20%." }, { name = "Frozen Mallet", icon = "Interface\\Icons\\Spell_Frost_FrostShock", text = "Your melee attacks have a 10% chance to add Frostbite. Once every 15 sec.\n\nToravon's mallet leaves frostbite wherever it lands." }, { name = "Whiteout", icon = "Interface\\Icons\\Spell_Frost_IceStorm", text = "Reduces the cooldown of Whiteout by 5 sec.\n\nThe ice watcher brings the blizzard with him." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Vault of Archavon", expansion = 2, order = 548, box = { 1.04, 0.52, 10.54 }, title = "Frost Giant of Wintergrasp" },
    { id = "garfrost", entry = 36494, name = "Forgemaster Garfrost", label = "Forgemaster Garfrost", level = 82, display = 30843, height = 22.0, span = 22.0, school = "frost", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Forgemaster", profile = "bruiser", kit = { 68771, 50843, 70381 }, passives = {}, talentInfo = { { name = "Master of Scourge Weaponry", icon = "Interface\\Icons\\Trade_BlackSmithing", text = "Your attack power is increased by 10%." }, { name = "Flesh Giant", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Permafrost", icon = "Interface\\Icons\\Spell_Frost_FrostWard", text = "Your Frost resistance is increased by 50." }, { name = "Throw Saronite", icon = "Interface\\Icons\\INV_Ore_Saronite_01", text = "Your melee attacks have an 8% chance to Throw Saronite. Once every 20 sec.\n\nGarfrost keeps a hunk of ore in his free hand for anyone who steps back." }, { name = "Axe Me Again", icon = "Interface\\Icons\\Spell_Frost_FrostShock", text = "Reduces the cooldown of Deep Freeze by 5 sec.\n\nThe Forgemaster's cold works faster than his hammer." } }, tips = {}, visualKit = 4991, soundTransform = 16912, soundDeath = 16915, flies = false, wave = 3, instance = "Pit of Saron", expansion = 2, order = 518, box = { 2.50, -3.04, 10.99 }, voices = { { 16912, 12.4, true, "Tiny creatures under feet, you bring Garfrost something good to eat!" }, { 16916, 9.1, true, "Axe too weak. Garfrost make better and CRUSH YOU." }, { 16917, 12.3, true, "Garfrost tired of puny mortals. Now your bones will freeze!" }, { 16915, 10.3, true, "Garfrost hope giant underpants clean. Save boss great shame. For later." }, { 16913, 5.9, true, "Will save for snack. For later." }, { 16914, 16.5, true, "That one maybe not so good to eat now. Stupid Garfrost! BAD! BAD!" } }, title = "Master of Scourge Weaponry" },
    { id = "tyrannus", entry = 36658, name = "Scourgelord Tyrannus", label = "Scourgelord Tyrannus", level = 82, display = 30277, height = 4.3, span = 4.3, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_ScourgelordTyrannus", profile = "bruiser", kit = { 69155, 69245, 69167, 69233 }, passives = {}, talentInfo = { { name = "Right Hand of the Lich King", icon = "Interface\\Icons\\Spell_Deathknight_ClassIcon", text = "Your attack power is increased by 10%." }, { name = "Saronite Plate", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Overlord's Might", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your Strength is increased by 8%." }, { name = "Unholy Resolve", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Damage you take is reduced by 5%." }, { name = "Overlord's Brand", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "When you are struck, you have a 10% chance to answer with a Forceful Smash. Once every 20 sec.\n\nStrike the Overlord and his brand strikes back through the mace." }, { name = "Rimefang, Trap Them", icon = "Interface\\Icons\\Spell_Frost_IceStorm", text = "Reduces the cooldown of Icy Blast by 5 sec.\n\nRimefang circles the Pit of Saron and answers her master quickly." } }, tips = {}, visualKit = 7775, soundTransform = 16760, soundDeath = 16763, flies = false, wave = 3, instance = "Pit of Saron", expansion = 2, order = 519, charModel = true, box = { -0.21, -0.01, 2.13 }, voices = { { 16758, 14.8, true, "Alas, brave, brave adventurers, your meddling has reached its end. Do you hear the clatter of bone and steel coming up the tunnel behind you? That is the sound of your impending demise." }, { 16759, 15.4, true, "Ha, such an amusing gesture from the rabble. When I have finished with you, my master's blade will feast upon your souls. Die." }, { 16760, 4.8, true, "I shall not fail the Lich King. Come and meet your end!" }, { 16761, 4.0, true, "Such a shameful display. You are better off dead." }, { 16762, 4.0, true, "Perhaps you should have stayed... in the mountains!" }, { 16763, 6.3, true, "Impossible.... Rimefang.... warn...." }, { 16764, 3.0, true, "Rimefang, destroy this fool!" }, { 16765, 5.2, true, "Power... overwhelming!" } }, title = "Right Hand of the Lich King" },
    { id = "bronjahm", entry = 36497, name = "Bronjahm", label = "Bronjahm", level = 82, display = 30226, height = 3.2, span = 3.2, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_Bronjahm", profile = "caster", kit = { 70043, 68793, 68950, 68921, 68858 }, passives = {}, talentInfo = { { name = "Godfather of Souls", icon = "Interface\\Icons\\Spell_Shadow_SoulGem", text = "Your Shadow damage is increased by 10%." }, { name = "Soul Forge", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_3", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Soul Glutton", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Your maximum health is increased by 8%." }, { name = "Magic's Bane", icon = "Interface\\Icons\\Spell_Arcane_ArcaneResilience", text = "Damage you take is reduced by 5%." }, { name = "Corrupt Soul", icon = "Interface\\Icons\\Spell_Shadow_Haunting", text = "Your damaging spells have a 10% chance to tear a soul loose and Consume Soul. Once every 45 sec.\n\nThe Godfather of Souls wastes nothing; every soul he tears loose ends up in his maw." }, { name = "The Forge Hungers", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_2", text = "Reduces the cooldown of Soulstorm by 8 sec.\n\nThe Forge of Souls is never full, and Bronjahm keeps feeding it." } }, tips = {}, visualKit = 7775, soundTransform = 16595, soundDeath = 16598, flies = false, wave = 3, instance = "The Forge of Souls", expansion = 2, order = 516, charModel = true, box = { -0.16, -0.01, 1.60 }, voices = { { 16595, 3.2, true, "Finally, a captive audience!" }, { 16596, 2.6, true, "Fodder for the engine." }, { 16597, 3.4, true, "Another soul to strengthen the host!" }, { 16598, 2.7, true, "The Devourer awaits..." }, { 16599, 3.6, true, "The vortex of the harvested calls to you!" }, { 16600, 3.8, true, "I will sever your soul from your body!" } }, title = "Godfather of Souls" },
    { id = "devourer", entry = 36502, name = "Devourer of Souls", label = "Devourer of Souls", level = 82, display = 30148, height = 12.6, span = 12.6, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_DevourerOfSouls", profile = "caster", kit = { 68982, 68873, 68863, 261 }, passives = {}, talentInfo = { { name = "Operator of the Soul Grinders", icon = "Interface\\Icons\\Spell_Shadow_SoulGem", text = "Your Shadow damage is increased by 10%." }, { name = "Face of Pain", icon = "Interface\\Icons\\Spell_Shadow_DeathScream", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Engine of Souls", icon = "Interface\\Icons\\INV_Misc_Gem_Stone_01", text = "Your armor is increased by 20%." }, { name = "Fed on Anguish", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Your maximum health is increased by 8%." }, { name = "Mirrored Soul", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_3", text = "When you are struck, you have a 10% chance to open a Well of Souls. Once every 20 sec.\n\nDamnation! Every blow against the Devourer is paid back in souls." }, { name = "Chaos", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Phantom Blast deals 15% more damage.\n\nThe face of pain screams louder than the others." } }, tips = { [261] = "RISE AND FEED! Release two Unleashed Souls to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 16884, soundDeath = 16887, flies = false, wave = 3, instance = "The Forge of Souls", expansion = 2, order = 517, summons = { [261] = true }, box = { -0.33, -0.07, 6.60 }, title = "Operator of the Soul Grinders", visages = { "devourer_sorrow", "devourer_desire" }, shape = "Anger" },
    { id = "falric", entry = 38112, name = "Falric", label = "Falric", level = 82, display = 30972, height = 5.3, span = 5.3, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Spell_Shadow_DeathScream", profile = "bruiser", kit = { 72422, 72426, 72435, 261 }, passives = {}, talentInfo = { { name = "Loyal Captain", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Fear So Exhilarating", icon = "Interface\\Icons\\Spell_Shadow_PsychicScream", text = "Your Shadow damage is increased by 8%." }, { name = "Captain of the Scourge", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "Shield of the Lich King", icon = "Interface\\Icons\\INV_Shield_05", text = "Your chance to block is increased by 5%." }, { name = "Quivering", icon = "Interface\\Icons\\Ability_Warrior_Riposte", text = "Your melee attacks have a 10% chance to add a Quivering Strike. Once every 10 sec.\n\nFear... so exhilarating. Falric's blows shake the nerve as well as the bone." }, { name = "Defiling Horror", icon = "Interface\\Icons\\Spell_Shadow_DeathScream", text = "Reduces the cooldown of Defiling Horror by 10 sec.\n\nThe Halls of Reflection echo with Falric's horror long after it ends." } }, tips = { [261] = "Soldiers of Lordaeron, rise to meet your master's call! Raise two phantom guardsmen to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 16710, soundDeath = 16713, flies = false, wave = 3, instance = "Halls of Reflection", expansion = 2, order = 520, summons = { [261] = true }, charModel = true, box = { -0.26, -0.01, 2.66 }, voices = { { 16710, 11.3, true, "Men, women, and children... None were spared the master's wrath. Your death will be no different." }, { 16711, 2.3, true, "Sniveling maggot!" }, { 16712, 3.8, true, "The children of Stratholme fought with more ferocity!" }, { 16713, 4.6, true, "Marwyn, finish them..." }, { 16715, 3.8, true, "Despair... so delicious..." }, { 16716, 4.3, true, "Fear... so exhilarating..." }, { 16717, 1.4, true, "As you wish, my lord." }, { 16714, 4.6, true, "Soldiers of Lordaeron, rise to meet your master's call!" } }, title = "Loyal Captain of the Lich King" },
    { id = "marwyn", entry = 38113, name = "Marwyn", label = "Marwyn", level = 82, display = 30973, height = 5.3, span = 5.3, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_3", profile = "bruiser", kit = { 72360, 72362, 72368, 70659 }, passives = {}, talentInfo = { { name = "Scourge Commander", icon = "Interface\\Icons\\Spell_Deathknight_ClassIcon", text = "Your attack power is increased by 10%." }, { name = "Corruption of the Flesh", icon = "Interface\\Icons\\Spell_Shadow_CorpseExplode", text = "Your Shadow damage is increased by 8%." }, { name = "Twin Blades", icon = "Interface\\Icons\\Ability_DualWield", text = "Your attack speed is increased by 8%." }, { name = "Unfeeling", icon = "Interface\\Icons\\Spell_Shadow_AnimateDead", text = "Your maximum health is increased by 8%." }, { name = "Shared Suffering", icon = "Interface\\Icons\\Spell_Shadow_UnstableAffliction_3", text = "Your melee attacks have an 8% chance to lay Shared Suffering. Once every 20 sec.\n\nMarwyn's cuts spread their pain to everyone standing close." }, { name = "Spreading Corruption", icon = "Interface\\Icons\\Spell_Shadow_DeathAndDecay", text = "Increases the radius of Well of Corruption by 50%.\n\nThe corruption Marwyn pours out spreads wider with every captain he outlives." } }, tips = {}, visualKit = 7775, soundTransform = 16734, soundDeath = 16737, flies = false, wave = 3, instance = "Halls of Reflection", expansion = 2, order = 521, charModel = true, box = { -0.26, -0.01, 2.66 }, voices = { { 16734, 3.9, true, "Death is all that you will find here!" }, { 16735, 10.3, true, "I saw the same look in his eyes when he died. Terenas could hardly believe it." }, { 16736, 2.1, true, "Choke on your suffering!" }, { 16737, 12.0, true, "Yes... Run... Run to meet your destiny... Its bitter, cold embrace, awaits you." }, { 16739, 3.6, true, "Your flesh shall decay before your very eyes!" }, { 16740, 2.5, true, "Waste away into nothingness!" }, { 16741, 2.7, true, "As you wish, my lord." }, { 16738, 12.9, true, "The master surveyed his kingdom and found it... Lacking. His judgement was swift and without mercy: DEATH TO ALL!" } }, title = "Scourge Commander" },
    { id = "tharonja", entry = 26632, name = "The Prophet Tharon'ja", label = "The Prophet Tharon'ja", level = 76, display = 27072, height = 14.2, span = 21.4, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\INV_Misc_Head_Troll_01", profile = "caster", kit = { 49544, 49537, 49528, 49527, 49548, 261 }, passives = {}, talentInfo = { { name = "The Eternal Dynasty", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", text = "Your maximum health is increased by 8%." }, { name = "Tharon'ja Sees All", icon = "Interface\\Icons\\Spell_Holy_MindVision", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Curse of Unwanted Life", icon = "Interface\\Icons\\Spell_Shadow_CurseOfSargeras", text = "Your Shadow damage is increased by 8%." }, { name = "Bones of the Drakkari", icon = "Interface\\Icons\\INV_Misc_Bone_Skull_01", text = "Damage you take is reduced by 5%." }, { name = "As Tharon'ja Predicted", icon = "Interface\\Icons\\INV_Misc_Eye_01", text = "Your damaging spells have a 10% chance to add an Eye Beam. Once every 15 sec.\n\nAs Tharon'ja predicted! The prophet saw you coming long before you arrived." }, { name = "Tharon'ja Is Eternal", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Reduces the cooldown of Shadow Volley by 4 sec.\n\nThe undying prophet of Drak'Tharon throws shadow as easily as he breathes it." } }, tips = { [261] = "Your flesh serves Tharon'ja now! Raise two Risen Drakkari Warriors to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 13862, soundDeath = 13869, flies = false, wave = 3, instance = "Drak'Tharon Keep", expansion = 2, order = 469, summons = { [261] = true }, box = { -2.01, -0.17, 7.19 }, voices = { { 13862, 9.3, true, "Tharon'ja sees all! The work of mortals shall not end the eternal dynasty!" }, { 13863, 3.2, true, "As Tharon'ja predicted!" }, { 13864, 2.8, true, "As it was written!" }, { 13865, 4.0, true, "Your flesh serves Tharon'ja now!" }, { 13866, 3.6, true, "Tharon'ja has a use for your mortal shell!" }, { 13867, 5.7, true, "No! A taste... all too brief!" }, { 13868, 6.2, true, "Agghh!! Tharon'ja will have more!" }, { 13869, 11.6, true, "Im... impossible! Tharon'ja is eternal! Tharon'ja... is...." } }, title = "Prophet of the Drakkari" },
    { id = "gortok", entry = 26687, name = "Gortok Palehoof", label = "Gortok Palehoof", level = 80, display = 27419, height = 11.2, span = 13.6, school = "physical", pool = "wotlk", icon = "Interface\\Icons\\INV_Misc_Head_Vrykul", profile = "bruiser", kit = { 48260, 48261, 48256, 48131, 261 }, passives = {}, talentInfo = { { name = "Master of the Trophy Hall", icon = "Interface\\Icons\\Ability_Hunter_Pet_Wolf", text = "Your attack power is increased by 10%." }, { name = "Magnataur Hide", icon = "Interface\\Icons\\INV_Misc_Pelt_Bear_03", text = "Your armor is increased by 15%." }, { name = "Pinnacle Strength", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your Strength is increased by 8%." }, { name = "Hunter's Stride", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Your movement speed is increased by 10%." }, { name = "Withering Roar", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "When you are struck, you have a 10% chance to let loose a Withering Roar. Once every 20 sec.\n\nWound the beastmaster and the whole trophy hall hears about it." }, { name = "The Hunt Is On", icon = "Interface\\Icons\\INV_Spear_05", text = "Your Impale deals 15% more damage.\n\nGortok's spears have brought down every beast in his hall." } }, tips = { [261] = "Wake two frenzied worgen from the trophy hall to fight for you for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Utgarde Pinnacle", expansion = 2, order = 479, summons = { [261] = true }, box = { 0.67, 0.09, 5.60 }, title = "Magnataur of the Trophy Hall" },
    { id = "malganis", entry = 26533, name = "Mal'Ganis", label = "Mal'Ganis", level = 82, display = 26582, height = 0.0, span = 0.0, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Spell_Shadow_CarrionSwarm", profile = "caster", kit = { 52720, 52722, 52721, 16608, 261 }, passives = {}, talentInfo = { { name = "The Eternal", icon = "Interface\\Icons\\Spell_Shadow_CarrionSwarm", text = "Your Shadow damage is increased by 10%." }, { name = "Nathrezim Cunning", icon = "Interface\\Icons\\Spell_Shadow_MindSteal", text = "Your Intellect is increased by 8%." }, { name = "Dreadlord's Wings", icon = "Interface\\Icons\\Spell_Shadow_Possession", text = "Damage you take is reduced by 5%." }, { name = "Lord of the Culling", icon = "Interface\\Icons\\Spell_Shadow_AnimateDead", text = "Your casting speed is increased by 6%." }, { name = "Your Journey Has Just Begun", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "Your damaging spells have an 8% chance to add a Mind Blast. Once every 20 sec.\n\nMal'Ganis plays with Arthas's mind as easily as with Stratholme's." }, { name = "Stratholme Burns", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bat", text = "Reduces the cooldown of Carrion Swarm by 5 sec.\n\nThe dreadlord's swarm feeds on a whole city." } }, tips = { [261] = "Call an infernal down from the sky onto your foes; it fights for you for 20 sec." }, visualKit = 7775, soundTransform = 14413, soundDeath = 0, flies = false, wave = 3, instance = "The Culling of Stratholme", expansion = 2, order = 508, summons = { [261] = true }, box = { 0.00, 0.00, 0.00 }, voices = { { 14410, 12.2, true, "Yes, this is the beginning. I've been waiting for you, young prince. I am Mal'Ganis." }, { 14411, 17.8, true, "As you can see, your people are now mine. I will now turn this city household by household, until the flame of life has been snuffed out... forever." }, { 14413, 5.6, true, "This will be a fine test, Prince Arthas." }, { 14416, 3.3, true, "All too easy." }, { 14417, 5.6, true, "The Dark Lord is displeased with your interference." }, { 14418, 5.2, true, "It is Prince Arthas I want, not you!" }, { 14422, 3.4, true, "Anakh kyree!" }, { 14423, 4.9, true, "My Onslaught will wash over the Lich King's forces!" }, { 14424, 4.6, true, "Your death is in vain, tiny mortal." }, { 14425, 4.3, true, "Your time has come to an end." }, { 14414, 2.6, true, "Time out." }, { 14415, 3.5, true, "You seem tired." } }, title = "The Eternal" },
    { id = "voljin", entry = 10540, name = "Vol'jin", label = "Vol'jin", level = 83, display = 31736, height = 3.2, span = 3.2, school = "shadow", pool = "leader", icon = "Interface\\Icons\\INV_Misc_Head_Troll_01", profile = "caster", kit = { 17289, 17146, 11641, 17820, 11986, 261 }, passives = {}, talentInfo = { { name = "Voodoo of the Darkspear", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 10%." }, { name = "Blessing of the Loa", icon = "Interface\\Icons\\Spell_Nature_HealingWaveGreater", text = "Your healing is increased by 10%." }, { name = "Troll Regeneration", icon = "Interface\\Icons\\Spell_Nature_Regenerate", text = "Your maximum health is increased by 6%." }, { name = "Berserking of the Echo Isles", icon = "Interface\\Icons\\Racial_Troll_Berserk", text = "Your casting speed is increased by 8%." }, { name = "Whispers of the Loa", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your damaging spells have a 10% chance to strike the target with Shadow Word: Pain. Once every 15 sec.\n\nThe loa whisper the names of Vol'jin's enemies, and the shadow always finds them." }, { name = "Ya Gonna Make a Fine Frog", icon = "Interface\\Icons\\Spell_Shaman_Hex", text = "Reduces the cooldown of your Hex by 15 sec.\n\nThe shadow hunter has hexed more fools than he can count. Every one of them croaked the same way." } }, tips = { [261] = "The loa send their serpents: two serpents rise to fight for the shadow hunter for 20 sec." }, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Orgrimmar", expansion = 0, order = 15, summons = { [261] = true }, charModel = true, box = { -0.03, 0.04, 1.58 }, title = "Chieftain of the Darkspears" },
    { id = "cairne", entry = 3057, name = "Cairne Bloodhoof", label = "Cairne Bloodhoof", level = 83, display = 4307, height = 2.7, span = 2.7, school = "physical", pool = "leader", icon = "Interface\\Icons\\Achievement_Leader_Cairne_Bloodhoof", profile = "bruiser", kit = { 16856, 16044, 16636, 22916, 23931, 59705, 25425 }, passives = {}, talentInfo = { { name = "Strength of the Earth Mother", icon = "Interface\\Icons\\Spell_Nature_EarthBindTotem", text = "Your Strength is increased by 8%." }, { name = "Endurance of the Bloodhoof", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Thunderhoof", icon = "Interface\\Icons\\Spell_Nature_ThunderClap", text = "Your Nature damage is increased by 8%." }, { name = "Endurance Aura", icon = "Interface\\Icons\\Spell_Nature_BloodLust", text = "Your attack speed is increased by 6%." }, { name = "Earth Mother's Rebuke", icon = "Interface\\Icons\\Ability_ThunderClap", text = "Your melee hits have an 8% chance to Thunderclap. Once every 15 sec.\n\nFeel the might of the Earth Mother! When the High Chieftain swings his totem, the mesa answers." }, { name = "Chieftain's Shockwave", icon = "Interface\\Icons\\Spell_Nature_Earthquake", text = "Reduces the cooldown of your Shockwave by 10 sec.\n\nThe old chieftain led his people across the Barrens on foot. His stride still splits the ground." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Thunder Bluff", expansion = 0, order = 316, charModel = true, box = { -0.05, -0.01, 1.34 }, title = "High Chieftain" },
    { id = "magni", entry = 2784, name = "King Magni Bronzebeard", label = "King Magni Bronzebeard", level = 83, display = 3597, height = 1.9, span = 1.9, school = "physical", pool = "leader", icon = "Interface\\Icons\\Achievement_Leader_King_Magni_Bronzebeard", profile = "bruiser", kit = { 20686, 43612, 22859, 7020, 261 }, passives = {}, talentInfo = { { name = "Might of the Bronzebeard", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", text = "Your attack power is increased by 10%." }, { name = "Stoneskin of Ironforge", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", text = "Your armor is increased by 15%." }, { name = "Dwarven Constitution", icon = "Interface\\Icons\\Spell_Holy_WordFortitude", text = "Your maximum health is increased by 10%." }, { name = "Ironforge Resolve", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Damage you take is reduced by 5%." }, { name = "Hammer of Ironforge", icon = "Interface\\Icons\\INV_Mace_01", text = "Your melee hits have an 8% chance to follow with a Mortal Cleave. Once every 15 sec.\n\nThe Lord of Ironforge fights with two hammers, and the second one is always already swinging." }, { name = "Heart of the Mountain", icon = "Interface\\Icons\\Spell_Shadow_UnholyStrength", text = "Reduces the cooldown of your Stoneform by 15 sec.\n\nThe stone of Khaz Modan answers the king who sits beneath it, and it answers him first." } }, tips = { [261] = "Sound the horn of the mountain halls: two Ironforge Mountaineers march to your side for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Ironforge", expansion = 0, order = 314, summons = { [261] = true }, charModel = true, box = { -0.12, -0.02, 0.95 }, title = "Lord of Ironforge" },
    { id = "muradin", entry = 36948, name = "Muradin Bronzebeard", label = "Muradin Bronzebeard", level = 83, display = 30508, height = 2.4, span = 2.4, school = "physical", pool = "leader", icon = "Interface\\Icons\\INV_Misc_Head_Dwarf_01", profile = "bruiser", kit = { 20685, 69651, 70161, 70309, 15548, 19135, 261 }, passives = { 69637 }, talentInfo = { { name = "Mountain King's Hammer", icon = "Interface\\Icons\\Ability_ThunderClap", text = "Your attack power is increased by 10%." }, { name = "Bash of the Bronzebeard", icon = "Interface\\Icons\\Ability_Warrior_PunishingBlow", text = "Your chance to land a critical strike is increased by 5%." }, { name = "Skybreaker Discipline", icon = "Interface\\Icons\\Ability_Warrior_InnerRage", text = "Your attack speed is increased by 8%." }, { name = "Frozen in the Ice", icon = "Interface\\Icons\\Spell_Frost_FrozenCore", text = "Your Frost resistance is increased by 60." }, { name = "A Taste o' the Hammer", icon = "Interface\\Icons\\INV_Hammer_01", text = "Your melee hits have a 5% chance to Thunderclap. Once every 30 sec.\n\nThe Mountain King never runs out of hammers. Every blow on the deck rings like a thunderclap." }, { name = "Thunder of Khaz Modan", icon = "Interface\\Icons\\Spell_Nature_ThunderClap", text = "Increases the radius of your Thunderclap by 25%.\n\nTen thousand years under the ice did not quiet him. When Muradin strikes the deck, the whole ship shakes." } }, tips = { [261] = "Have a taste o' the Mountain King's hammer! Two Skybreaker Marines leap into the fight beside you for 30 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Icecrown Citadel", expansion = 2, order = 562, summons = { [261] = true }, charModel = true, box = { -0.15, -0.03, 1.18 }, voices = { { 16962, 4.7, true, "Fire up the engines! We got a meetin' with destiny, lads!" }, { 16963, 1.7, true, "Hold on to yer hats!" }, { 16964, 4.0, true, "What in the world is that? Grab me spyglass, crewman!" }, { 16965, 4.6, true, "By me own beard! HORDE SAILIN' IN FAST 'N HOT!" }, { 16966, 3.0, true, "EVASIVE ACTION! MAN THE GUNS!" }, { 16967, 3.2, true, "Cowardly dogs! Ye blindsided us!" }, { 16968, 12.8, true, "Not me battle? I dunnae who ye think ye are, mister, but I got a score to settle with Arthas and yer not gettin' in me way! FIRE ALL GUNS! FIRE! FIRE!" }, { 16969, 6.8, true, "Move yer jalopy or we'll blow it out of the sky, orc! The Horde's got no business here." }, { 16958, 5.5, true, "What's this then?! Ye won't be takin' this son o' Ironforge's vessel without a fight!" }, { 16956, 2.7, true, "Marines, Sergeants, attack!" }, { 16954, 2.5, true, "Riflemen, shoot faster!" }, { 16955, 2.2, true, "Mortar team, reload!" } }, title = "High Thane" },
    { id = "tyrande", entry = 7999, name = "Tyrande Whisperwind", label = "Tyrande Whisperwind", level = 83, display = 7274, height = 2.3, span = 2.3, school = "arcane", pool = "leader", icon = "Interface\\Icons\\Achievement_Leader_Tyrande_Whisperwind", profile = "caster", kit = { 20688, 21669, 20687, 44478, 8362, 34189, 261 }, passives = {}, talentInfo = { { name = "Light of Elune", icon = "Interface\\Icons\\Spell_Arcane_StarFire", text = "Your Arcane damage is increased by 10%." }, { name = "Priestess of the Moon", icon = "Interface\\Icons\\Spell_Nature_StarFall", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Grace of the Nightsaber", icon = "Interface\\Icons\\Ability_Mount_WhiteTiger", text = "You move 10% faster." }, { name = "Trueshot Aura", icon = "Interface\\Icons\\Ability_TrueShot", text = "Your damage is increased by 5%." }, { name = "Moonlit Arrows", icon = "Interface\\Icons\\Spell_Nature_MoonGlow", text = "Your damaging spells and shots have a 10% chance to burn the target with Moonfire. Once every 15 sec.\n\nTen thousand years of Sentinel archery, and every arrow still carries a little of the moon." }, { name = "Let Your Stars Fall", icon = "Interface\\Icons\\Ability_Druid_Starfall", text = "Your Starfall covers a 20% larger area.\n\nWhen the High Priestess calls, Elune does not aim small." } }, tips = { [261] = "Elune's Sentinels answer their High Priestess: two Darnassus Sentinels fight at your side for 20 sec." }, visualKit = 1005, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Darnassus", expansion = 0, order = 284, summons = { [261] = true }, charModel = true, box = { -0.15, 0.10, 1.14 }, title = "High Priestess of Elune" },
    { id = "velen", entry = 17468, name = "Prophet Velen", label = "Prophet Velen", level = 83, display = 17822, height = 3.4, span = 3.4, school = "holy", pool = "leader", icon = "Interface\\Icons\\Achievement_Leader_Prophet_Velen", profile = "caster", kit = { 59703, 59700, 59701, 33542, 22168, 11974 }, passives = {}, talentInfo = { { name = "Light of Argus", icon = "Interface\\Icons\\Spell_Holy_SearingLight", text = "Your Holy damage is increased by 10%." }, { name = "Gift of the Naaru", icon = "Interface\\Icons\\Spell_Holy_HolyProtection", text = "Your healing is increased by 10%." }, { name = "Wisdom of Twenty-Five Millennia", icon = "Interface\\Icons\\Spell_Holy_MagicalSentry", text = "Your Intellect is increased by 8%." }, { name = "Endurance of the Exiles", icon = "Interface\\Icons\\Spell_Holy_WordFortitude", text = "Your maximum health is increased by 8%." }, { name = "Countless Futures", icon = "Interface\\Icons\\Spell_Holy_MindVision", text = "When you are struck you have an 8% chance to answer with a Holy Nova. Once every 30 sec.\n\nVelen has seen this blow in a thousand visions, and in every one of them the Light was already waiting." }, { name = "Prophet of the Naaru", icon = "Interface\\Icons\\Spell_Holy_PowerWordShield", text = "Reduces the cooldown of your Power Word: Shield by 10 sec.\n\nThe Prophet has seen every blow before it falls, and his shield is already there to meet it." } }, tips = {}, visualKit = 154, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "The Exodar", expansion = 1, order = 428, box = { -0.25, -0.03, 1.70 }, title = "Leader of the Draenei" },
    { id = "lorthemar", entry = 16802, name = "Lor'themar Theron", label = "Lor'themar Theron", level = 83, display = 17122, height = 2.7, span = 2.7, school = "arcane", pool = "leader", icon = "Interface\\Icons\\Achievement_Leader_Lorthemar_Theron", profile = "bruiser", kit = { 59715, 33385, 15284, 41180, 31379, 29208, 32908 }, passives = {}, talentInfo = { { name = "Farstrider's Aim", icon = "Interface\\Icons\\Ability_Hunter_SniperShot", text = "Your attack power is increased by 10%." }, { name = "Reflexes of the Farstriders", icon = "Interface\\Icons\\Ability_Hunter_CatlikeReflexes", text = "Your chance to dodge is increased by 5%." }, { name = "Arcane Affinity of Quel'Thalas", icon = "Interface\\Icons\\Spell_Arcane_ArcaneTorrent", text = "Your Arcane damage is increased by 8%." }, { name = "Regent's Composure", icon = "Interface\\Icons\\Spell_Arcane_PortalSilvermoon", text = "Damage you take is reduced by 5%." }, { name = "Spellblade of Quel'Thalas", icon = "Interface\\Icons\\Spell_Nature_WispHeal", text = "Your melee hits have an 8% chance to loose an Arcane Shock at your target. Once every 15 sec.\n\nFarstriders learned the bow; the lords of Silvermoon learned to put the Sunwell's fire behind every blade." }, { name = "Quel'Thalas Stands", icon = "Interface\\Icons\\Ability_Warrior_ShieldBash", text = "Reduces the cooldown of your Shield Bash by 4 sec.\n\nQuel'Thalas has not forgotten how to fight, and its Regent has not forgotten how to silence a Scourge caster." } }, tips = {}, visualKit = 1005, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Silvermoon City", expansion = 1, order = 427, charModel = true, box = { -0.16, -0.03, 1.33 }, title = "Regent Lord of Quel'Thalas" },
    { id = "tirion", entry = 38995, name = "Highlord Tirion Fordring", label = "Highlord Tirion Fordring", level = 83, display = 31286, height = 4.3, span = 4.3, school = "holy", pool = "leader", icon = "Interface\\Icons\\Spell_Holy_SealOfVengeance", profile = "tank", kit = { 29386, 66006, 53638, 69930, 13005, 15493, 13874, 261, 37486 }, passives = {}, talentInfo = { { name = "Fury of the Ashbringer", icon = "Interface\\Icons\\Spell_Holy_AshesToAshes", text = "Your Holy damage is increased by 10%." }, { name = "Argent Bulwark", icon = "Interface\\Icons\\Spell_Holy_DevotionAura", text = "Damage you take is reduced by 10%." }, { name = "Righteous Fury of the Crusade", icon = "Interface\\Icons\\Spell_Holy_SealOfFury", text = "You generate 30% more threat." }, { name = "Crusader's Guard", icon = "Interface\\Icons\\Ability_Parry", text = "Your chance to parry is increased by 5%." }, { name = "The Ashbringer Answers", icon = "Interface\\Icons\\Spell_Holy_Excorcism", text = "Your melee hits have an 8% chance to loose Holy Wrath. Once every 20 sec.\n\nReborn at Light's Hope in Darion's hands, the Ashbringer blazes whenever it bites." }, { name = "Rebirth of the Ashbringer", icon = "Interface\\Icons\\Spell_Holy_CrusaderStrike", text = "Increases the damage of Divine Storm by 15%.\n\nThe corrupted blade came back to the Light and to the Fordring hand. It cuts deeper than it ever did." } }, tips = { [261] = "Light grant me one final blessing! Two Defenders of the Light ride out of Light's Hope and fight at your side for 30 sec." }, visualKit = 154, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Icecrown Citadel", expansion = 2, order = 559, summons = { [261] = true }, charModel = true, box = { -0.21, -0.01, 2.13 }, voices = { { 17390, 6.7, true, "We'll grant you a swift death, Arthas. More than can be said for the thousands you've tortured and slain." }, { 17391, 4.1, true, "So be it. Champions, attack!" }, { 17392, 8.3, true, "LIGHT GRANT ME ONE FINAL BLESSING! GIVE ME THE STRENGTH... TO SHATTER THESE BONDS!" }, { 17393, 5.0, true, "No more, Arthas! No more lives will be consumed by your hatred!" }, { 17389, 3.8, true, "The Lich King must fall!!" } }, title = "Highlord of the Argent Crusade" },
    { id = "darion", entry = 29173, name = "Highlord Darion Mograine", label = "Highlord Darion Mograine", level = 83, display = 25444, height = 2.9, span = 2.9, school = "shadow", pool = "leader", icon = "Interface\\Icons\\Spell_DeathKnight_ClassIcon", profile = "bruiser", kit = { 71488, 56359, 53640, 53635, 31662, 261 }, passives = {}, talentInfo = { { name = "Might of the Ebon Blade", icon = "Interface\\Icons\\Spell_DeathKnight_EmpowerRuneBlade", text = "Your attack power is increased by 10%." }, { name = "Plague of Acherus", icon = "Interface\\Icons\\Spell_DeathKnight_BloodPlague", text = "Your Shadow damage is increased by 8%." }, { name = "Bladed Armor of the Deathlord", icon = "Interface\\Icons\\Spell_DeathKnight_BladedArmor", text = "Your armor is increased by 15%." }, { name = "Will of the Deathlord", icon = "Interface\\Icons\\Spell_DeathKnight_IceBoundFortitude", text = "Damage you take is reduced by 5%." }, { name = "The Might of Mograine", icon = "Interface\\Icons\\Spell_DeathKnight_AntiMagicZone", text = "Your melee hits have a 5% chance to open Death's Embrace around you. Once every 30 sec.\n\nEmpowered by the might of Highlord Darion Mograine, the Ebon Blade is an unstoppable force of darkness." }, { name = "Apocalypse", icon = "Interface\\Icons\\Spell_Shadow_DeathAndDecay", text = "Increases the radius of your Death and Decay by 25%.\n\nSoon, Azeroth's futile tears will rain down upon us. At Light's Hope the heavens themselves came down." } }, tips = { [261] = "The sky weeps! Two Warriors of the Frozen Wastes rise from the Plaguelands and fight for you for 30 sec." }, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Plaguelands: The Scarlet Enclave", expansion = 2, order = 430, summons = { [261] = true }, charModel = true, box = { -0.14, -0.01, 1.44 }, voices = { { 14677, 6.6, true, "Soldiers of the Scourge, stand ready! Prepare to unleash your fury upon the Argent Dawn!" }, { 14678, 8.9, true, "The sky weeps at the glorious devastation of these lands! Soon, Azeroth's futile tears will rain down upon us!" }, { 14681, 4.3, true, "Death knights of Acherus, the death march begins!" }, { 14679, 8.1, true, "Soldiers of the Scourge, death knights of Acherus, minions of the darkness: hear the call of the Highlord!" }, { 14680, 1.7, true, "RISE!" }, { 14682, 11.3, true, "The skies turn red with the blood of the fallen! The Lich King watches over us, minions! Leave only ashes and misery in your destructive wake!" }, { 14683, 2.5, false, "Kneel before the Highlord!" }, { 14684, 2.0, false, "You stand no chance!" }, { 14685, 2.9, false, "The Scourge will destroy this place!" }, { 14686, 1.9, false, "Your life is forfeit." }, { 14687, 2.9, false, "Life is meaningless without suffering!" }, { 14688, 2.9, false, "How much longer will your forces hold out?" } }, title = "Highlord of the Ebon Blade" },
    { id = "medivh", entry = 15608, name = "Medivh", label = "Medivh", level = 73, display = 18718, height = 3.2, span = 3.2, school = "arcane", pool = "leader", icon = "Interface\\Icons\\Ability_Hunter_Pet_Owl", profile = "caster", kit = { 15735, 36277, 31457, 9433, 17740, 29209, 261 }, passives = {}, talentInfo = { { name = "Power of the Guardian", icon = "Interface\\Icons\\Spell_Arcane_ArcanePotency", text = "Your Arcane damage is increased by 10%." }, { name = "Tirisfalen Mastery", icon = "Interface\\Icons\\Spell_Arcane_MindMastery", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Legacy of Aegwynn", icon = "Interface\\Icons\\Spell_Arcane_Arcane03", text = "Your spells are cast 8% faster." }, { name = "Wellspring of Karazhan", icon = "Interface\\Icons\\Spell_Arcane_Arcane02", text = "Your Arcane spells cost 10% less." }, { name = "Feeble Mortal Coil", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "When you are struck you have a 10% chance to unleash an Arcane Explosion around you. Once every 30 sec.\n\nNo! Damn this feeble, mortal coil! The Guardian's body failed him often; his power never did." }, { name = "Tirisfalen Barrage", icon = "Interface\\Icons\\Spell_Nature_StarFall", text = "Reduces the cooldown of your Arcane Missiles by 4 sec.\n\nBehold the power of the last Guardian: the missiles never stop for long." } }, tips = { [261] = "Tear open the way to Draenor: two orcs of the old Horde step through and fight for you for 20 sec." }, visualKit = 1005, soundTransform = 0, soundDeath = 10441, flies = false, wave = 3, instance = "Opening of the Dark Portal", expansion = 1, order = 426, summons = { [261] = true }, box = { -0.10, -0.00, 1.59 }, voices = { { 10435, 13.2, true, "The time has come! Gul'dan, order your warlocks to double their efforts! Moments from now the gateway will open and your Horde will be released upon this ripe, unsuspecting world!" }, { 10436, 11.4, true, "What is this? Champions, coming to my aid? I sense the hand of the dark one in this. Truly this sacred event bears his blessing?" }, { 10439, 5.2, true, "The shield is nearly gone! All that I have worked for is in danger!" }, { 10438, 5.9, true, "My powers must be concentrated on the portal! I do not have time to hold the shield!" }, { 10437, 2.7, true, "Champions! My shield grows weak!" }, { 10441, 4.1, true, "No! Damn this feeble, mortal coil!" }, { 10440, 16.4, true, "I am grateful for your aid, champions. Now, Gul'dan's Horde will sweep across this world like a locust swarm, and all my designs, all my carefully-laid plans will at last fall into place." } }, title = "The Last Guardian" },
    { id = "young_thrall", entry = 17876, name = "Thrall", label = "Thrall (Durnholde)", level = 67, display = 17292, height = 2.8, span = 2.8, school = "nature", pool = "leader", icon = "Interface\\Icons\\Achievement_Leader_Thrall", profile = "bruiser", kit = { 14516, 6730, 22911, 59716, 29667 }, passives = {}, talentInfo = { { name = "Gladiator of Durnholde", icon = "Interface\\Icons\\Ability_Warrior_SavageBlow", text = "Your Strength is increased by 8%." }, { name = "Arena Instinct", icon = "Interface\\Icons\\Ability_Parry", text = "Your chance to parry is increased by 5%." }, { name = "Scars of Blackmoore", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Damage you take is reduced by 5%." }, { name = "Spark of the Elements", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", text = "Your Nature damage is increased by 8%." }, { name = "Arena Footwork", icon = "Interface\\Icons\\Ability_ShockWave", text = "Your melee hits have a 10% chance to follow with a Hamstring. Once every 15 sec.\n\nBlackmoore's crowd paid to see blood. The young gladiator learned to take the legs out first." }, { name = "I Am a Slave No Longer", icon = "Interface\\Icons\\Ability_Warrior_Charge", text = "Reduces the cooldown of your Charge by 8 sec.\n\nNo wall of Durnholde held him. Out of my way!" } }, tips = {}, visualKit = 282, soundTransform = 10448, soundDeath = 0, flies = false, wave = 3, instance = "The Escape From Durnholde", expansion = 1, order = 336, charModel = true, box = { 0.01, -0.01, 1.41 }, voices = { { 10465, 2.6, true, "Very well then. Let's go!" }, { 10466, 1.4, false, "A rider approaches." }, { 10467, 2.4, true, "I'll never be chained again!" }, { 10468, 5.8, true, "Very well. Tarren Mill lies just west of here. Since time is of the essence..." }, { 10469, 1.2, false, "Let's ride!" }, { 10470, 1.8, true, "Who or what was that?" }, { 10471, 0.9, true, "No!" }, { 10472, 4.1, true, "Goodbye, Taretha. I will never forget your kindness." }, { 10458, 1.9, true, "Things are looking grim...." }, { 10459, 1.8, true, "I'll fight... to the last!" }, { 10460, 1.1, true, "Taretha...." }, { 10461, 2.8, true, "A good day... to die." } }, title = "Son of Durotan" },
    { id = "brann", entry = 28070, name = "Brann Bronzebeard", label = "Brann Bronzebeard", level = 80, display = 26353, height = 1.8, span = 1.8, school = "physical", pool = "leader", icon = "Interface\\Icons\\INV_Misc_Head_Dwarf_01", profile = "bruiser", kit = { 6660, 30614, 14443, 7978, 4068, 12024, 34189 }, passives = {}, talentInfo = { { name = "Demolitions Expert", icon = "Interface\\Icons\\INV_Misc_Bomb_05", text = "Your Fire damage is increased by 10%." }, { name = "Bronzebeard Marksmanship", icon = "Interface\\Icons\\INV_Weapon_Rifle_01", text = "Your damage is increased by 5%." }, { name = "Explorer's Stride", icon = "Interface\\Icons\\INV_Misc_Map02", text = "You move 10% faster." }, { name = "Tough as Ironforge Stone", icon = "Interface\\Icons\\Spell_Shadow_UnholyStrength", text = "Damage you take is reduced by 5%." }, { name = "Plenty of Death-Dealing", icon = "Interface\\Icons\\INV_Misc_Bomb_07", text = "Your damaging abilities have an 8% chance to toss a stick of dynamite at the target. Once every 15 sec.\n\nKeep it up now! Brann always has one more stick of dynamite in his pack than anyone thinks is safe." }, { name = "Bronzebeard Rifle", icon = "Interface\\Icons\\INV_Spear_07", text = "Your Aimed Shot deals 15% more damage.\n\nBrann swears the old hand cannon shoots straighter than any rifle in Ironforge. He is usually right." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 14258, flies = false, wave = 3, instance = "Halls of Stone", expansion = 2, order = 477, charModel = true, box = { -0.11, -0.02, 0.87 }, voices = { { 14244, 1.8, true, "Now that's earnin' your supper!" }, { 14245, 1.7, true, "Press on; that's the way!" }, { 14246, 3.5, true, "Keep it up now. Plenty of death-dealing for everyone!" }, { 14257, 4.4, true, "I'm all kinds of busted up... might not... make it." }, { 14258, 4.1, true, "Not yet... not ye--" }, { 14260, 1.6, true, "I'm doin' everything I can!" }, { 14261, 1.8, true, "Light preserve ye!" }, { 14262, 1.7, true, "I hope this is all worth it!" }, { 14259, 4.1, true, "Time to get some answers! Let's get this show on the road!" }, { 14274, 7.4, true, "Don't worry! Ol' Brann's got yer back! Keep that metal monstrosity busy, and I'll see if I can't sweet talk this machine into helping ye!" }, { 14275, 5.2, true, "This is a wee bit trickier than before... Oh, bloody--incomin'!" }, { 14276, 5.3, true, "What in the name o' Madoran did THAT do? Oh! Wait: I just about got it..." } }, title = "Explorers' League" },
    { id = "black_drakonid", entry = 14265, name = "Black Drakonid", label = "Black Drakonid", level = 60, display = 14885, height = 4.4, span = 4.8, school = "fire", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", profile = "bruiser", kit = { 22560, 15284, 22433, 23339, 24375 }, passives = {}, talentInfo = { { name = "Blackwing Brood Fire", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Your Fire damage is increased by 8%." }, { name = "Chromatic Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your armor is increased by 15%." }, { name = "Nefarian's Soldier", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", text = "Your Strength is increased by 6%." }, { name = "Black Flight Blood", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Your Fire resistance is increased by 50." }, { name = "Brood Power", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your melee attacks have a 6% chance to scorch the target with Flame Buffet. Once every 20 sec.\n\nNefarian bred the drakonids to carry their flight's power in the blood; every blow they land smoulders." }, { name = "Wings of the Brood", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", text = "Increases the reach of Wing Buffet by 25%.\n\nA drakonid's wings are too small to fly, but more than big enough to clear a corridor of Blackwing Lair." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, expansion = 0, order = 238, box = { -0.51, 0.82, 2.19 }, skins = { { entry = 14264, name = "Red", creature = "Red Drakonid", display = 14889, height = 4.4, span = 4.8, box = { -0.51, 0.82, 2.19 } }, { entry = 14302, name = "Chromatic", creature = "Chromatic Drakonid", display = 14352, height = 6.5, span = 7.2, box = { -0.76, 1.22, 3.28 } } }, title = "Servant of Nefarian" },
    { id = "dreadlord", entry = 8716, name = "Dreadlord", label = "Dreadlord", level = 62, display = 10543, height = 5.5, span = 6.9, school = "shadow", pool = "archetype", icon = "Interface\\Icons\\Spell_Shadow_Carrionswarm", profile = "caster", kit = { 17287, 16568, 13338, 22687, 13704 }, passives = {}, talentInfo = { { name = "Nathrezim Malice", icon = "Interface\\Icons\\Spell_Shadow_CarrionSwarm", text = "Your Shadow damage is increased by 8%." }, { name = "Master of Deceit", icon = "Interface\\Icons\\Spell_Shadow_MindSteal", text = "Your spell critical strike chance is increased by 5%." }, { name = "Dreadlord's Guile", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Damage you take is reduced by 5%." }, { name = "Nightmare Lord", icon = "Interface\\Icons\\Spell_Shadow_DeathScream", text = "Blows that strike you have a 5% chance to answer with a Mind Blast. Once every 30 sec.\n\nStrike a nathrezim and you strike a lie; the truth waits behind you, and it is already inside your head." }, { name = "Voice in the Dark", icon = "Interface\\Icons\\Spell_Shadow_CurseOfTounges", text = "Your Whispered Doubt deals 15% more damage.\n\nThe dreadlords whispered the plague into Lordaeron one courtier at a time. They never needed to shout." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Blasted Lands", expansion = 0, order = 240, box = { -1.39, -0.08, 2.46 }, title = "Nathrezim of the Burning Legion" },
    { id = "lich", entry = 10508, name = "Ras Frostwhisper", label = "Lich", level = 62, display = 7919, height = 6.4, span = 6.4, school = "frost", pool = "archetype", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", profile = "caster", kit = { 8398, 21369, 18099, 15063, 12096, 60953, 15784 }, passives = {}, talentInfo = { { name = "Frozen Heart of Ras", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "Scholomance Mastery", icon = "Interface\\Icons\\Spell_Frost_IceStorm", text = "Your spell critical strike chance is increased by 5%." }, { name = "Phylactery Bound", icon = "Interface\\Icons\\Spell_Frost_FrostArmor02", text = "Your maximum health is increased by 8%." }, { name = "Cold of the Grave", icon = "Interface\\Icons\\Spell_Frost_FrostWard", text = "Your Frost resistance is increased by 40." }, { name = "Chill of the Crypt", icon = "Interface\\Icons\\Spell_Frost_ChainsOfIce", text = "Blows that strike you have a 6% chance to loose a Chill Nova. Once every 20 sec.\n\nRas Frostwhisper sealed his own soul in ice; warm blood that touches him freezes where it lands." }, { name = "Endless Volley", icon = "Interface\\Icons\\Spell_Frost_Glacier", text = "Reduces the cooldown of Frostbolt Volley by 3 sec.\n\nIn the Scholomance, the students learn the volley first; the lich who teaches it never tires of the lesson." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Scholomance", expansion = 0, order = 230, box = { 0.08, 0.07, 2.59 }, title = "Overseer of the Scholomance" },
    { id = "banshee", entry = 10464, name = "Wailing Banshee", label = "Banshee", level = 59, display = 8782, height = 4.1, span = 4.1, school = "shadow", pool = "archetype", icon = "Interface\\Icons\\Spell_Shadow_PsychicScream", profile = "caster", kit = { 16868, 17105, 16838, 17244, 19645 }, passives = {}, talentInfo = { { name = "Anguish of Quel'Thalas", icon = "Interface\\Icons\\Spell_Shadow_PsychicScream", text = "Your Shadow damage is increased by 10%." }, { name = "Incorporeal Form", icon = "Interface\\Icons\\Spell_Magic_LesserInvisibilty", text = "Damage you take is reduced by 6%." }, { name = "Spectral Drift", icon = "Interface\\Icons\\Spell_Shadow_GhostKey", text = "Your movement speed is increased by 10%." }, { name = "Keening", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_3", text = "Your spells have a 10% chance to lay a Banshee Curse on the target. Once every 15 sec.\n\nA banshee's grief spills into everything she touches; those who hear her once miss their aim for days." }, { name = "Endless Lament", icon = "Interface\\Icons\\Spell_Shadow_Possession", text = "Your Banshee Wail deals 15% more damage.\n\nShe wails for Quel'Thalas, for Silvermoon, for the body she will never wear again. The grief only grows." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Stratholme", expansion = 0, order = 193, box = { -0.50, 0.00, 2.04 }, skins = { { entry = 1804, name = "Green", creature = "Wailing Death", display = 10690, height = 3.2, span = 3.2, box = { -0.39, 0.00, 1.57 } } }, title = "Banshee of Stratholme" },
    { id = "ogre_mauler", entry = 19993, name = "Bloodmaul Mauler", label = "Ogre Mauler", level = 67, display = 17782, height = 7.9, span = 7.9, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Warrior_Cleave", profile = "bruiser", kit = { 37592, 15496, 10966, 2676, 37786 }, passives = {}, talentInfo = { { name = "Bloodmaul Brew", icon = "Interface\\Icons\\INV_Drink_05", text = "Your Physical damage is increased by 8%." }, { name = "Thick Bloodmaul Skull", icon = "Interface\\Icons\\Achievement_Reputation_Ogre", text = "Your maximum health is increased by 10%." }, { name = "Me Smash Good", icon = "Interface\\Icons\\Ability_Warrior_PunishingBlow", text = "Your melee critical strike chance is increased by 5%." }, { name = "Ogre Might", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your Strength is increased by 6%." }, { name = "Smash In Face", icon = "Interface\\Icons\\Ability_Warrior_DecisiveStrike", text = "Your melee hits have an 8% chance to Uppercut the target. Once every 12 sec.\n\nMe mad. You get smash in face! A Bloodmaul does not plan the big punch; it just happens." }, { name = "One More Brew", icon = "Interface\\Icons\\Ability_Racial_BloodRage", text = "Reduces the cooldown of Bloodmaul Rage by 15 sec.\n\nEvery ogre in the Bloodmaul mines knows the last mug is never the last mug." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Blade's Edge Mountains", expansion = 1, order = 333, box = { 0.04, -0.27, 3.90 }, title = "Ogre of Blade's Edge" },
    { id = "centaur", entry = 4636, name = "Kolkar Battle Lord", label = "Centaur", level = 33, display = 9448, height = 3.5, span = 3.5, school = "physical", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Head_Centaur_01", profile = "bruiser", kit = { 55217, 5568, 32023, 6268, 9128, 8258, 261 }, passives = {}, talentInfo = { { name = "Kolkar Hooves", icon = "Interface\\Icons\\Ability_Warstomp", text = "Your Physical damage is increased by 8%." }, { name = "Centaur Stride", icon = "Interface\\Icons\\Spell_Nature_Swiftness", text = "Your movement speed is increased by 10%." }, { name = "Battle Lord's Might", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", text = "Your Strength is increased by 5%." }, { name = "Desolace Endurance", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 6%." }, { name = "Trampling Charge", icon = "Interface\\Icons\\Ability_BullRush", text = "Your melee attacks have an 8% chance to trample everyone around you. Once every 10 sec.\n\nA centaur does not step around the fallen. Every raid on a caravan leaves the road churned under Kolkar hooves." }, { name = "Thunder of Hooves", icon = "Interface\\Icons\\Spell_Nature_Earthquake", text = "Your Hoof Stomp reaches 20% farther.\n\nThe Battle Lord rears again before the dust settles, and the plains shake under him." } }, tips = { [261] = "The Kolkar trample all! Sound the war horn and two Kolkar Marauders gallop in to fight at your side for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Desolace", expansion = 0, order = 107, summons = { [261] = true }, box = { -0.34, -0.01, 1.74 }, view = { -0.8864, 0.9707, 0.7105 }, title = "Centaur of Desolace" },
    { id = "quilboar", entry = 4436, name = "Razorfen Defender", label = "Quilboar", level = 26, display = 6108, height = 3.2, span = 3.2, school = "nature", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Head_Quillboar_01", profile = "tank", kit = { 11972, 54794, 15548, 3385, 8148, 3248, 261 }, passives = {}, talentInfo = { { name = "Bristleback Hide", icon = "Interface\\Icons\\INV_Misc_Pelt_Boar_Ruin_03", text = "Your armor is increased by 20%." }, { name = "Blood of Agamaggan", icon = "Interface\\Icons\\Ability_Hunter_Pet_Boar", text = "Your maximum health is increased by 10%." }, { name = "Razorfen Shieldwall", icon = "Interface\\Icons\\Ability_Defend", text = "Your chance to block is increased by 8%." }, { name = "Defender's Squeal", icon = "Interface\\Icons\\INV_Misc_Head_Quillboar_01", text = "The threat you cause is increased by 30%." }, { name = "Razorfen Thorns", icon = "Interface\\Icons\\Spell_Nature_Thorns", text = "When you are struck, you have a 10% chance to stomp the earth with Thunderclap. Once every 20 sec.\n\nThe Razorfen defenders are raised among thornvines, and they answer a blow the way the thorns do." }, { name = "Stubborn as a Boar", icon = "Interface\\Icons\\INV_Shield_05", text = "Your Improved Blocking lasts 4 sec longer.\n\nA quilboar behind a shield is a boar that has dug in, and nothing short of a kodo will shift it." } }, tips = { [261] = "Touch Razorfen, feel the thorns! Loose two Tamed Battleboars from the Kraul's pens to fight at your side for 20 sec." }, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Razorfen Kraul", expansion = 0, order = 79, as = 4442, summons = { [261] = true }, box = { -0.54, 0.01, 1.58 }, title = "Quilboar of Razorfen Kraul" },
    { id = "trogg", entry = 1167, name = "Stonesplinter Digger", label = "Trogg", level = 19, display = 722, height = 2.2, span = 2.2, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Warrior_Sunder", profile = "bruiser", kit = { 16172, 5164, 4164, 19615, 261 }, passives = {}, talentInfo = { { name = "Trogg Skullcracker", icon = "Interface\\Icons\\Ability_Warrior_Sunder", text = "Your Physical damage is increased by 8%." }, { name = "Stonesplinter Hide", icon = "Interface\\Icons\\INV_Stone_04", text = "Your armor is increased by 15%." }, { name = "Brute of the Deep", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your Strength is increased by 6%." }, { name = "Rock-Hard Skull", icon = "Interface\\Icons\\INV_Stone_01", text = "Your maximum health is increased by 6%." }, { name = "Shovel to the Head", icon = "Interface\\Icons\\INV_Stone_10", text = "Your melee attacks have an 8% chance to follow up with a Throw Rock at the target. Once every 12 sec.\n\nA trogg does not aim. It just keeps swinging the shovel until something breaks, and it is usually a skull." }, { name = "Endless Tunnels", icon = "Interface\\Icons\\Trade_Mining", text = "Reduces the cooldown of Call the Diggers by 30 sec.\n\nWhere there is one trogg there are ten more in the dark behind it, and they all heard you whistle." } }, tips = { [261] = "CRUSH! Whistle two Stonesplinter Troggs up out of the tunnels to fight at your side for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Loch Modan", expansion = 0, order = 41, summons = { [261] = true }, box = { 0.45, 0.01, 1.08 }, title = "Trogg of Loch Modan" },
    { id = "arakkoa", entry = 21644, name = "Skettis Wing Guard", label = "Arakkoa", level = 71, display = 18628, height = 3.8, span = 3.8, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Hunter_Pet_Owl", profile = "bruiser", kit = { 35321, 15496, 30854, 54462, 40546, 8599 }, passives = {}, talentInfo = { { name = "Talons of Terokk", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your Physical damage is increased by 8%." }, { name = "Skettis Wingbeat", icon = "Interface\\Icons\\Ability_Hunter_Pet_Owl", text = "Your attack speed is increased by 8%." }, { name = "Ironfeather Plumage", icon = "Interface\\Icons\\INV_Feather_04", text = "Your armor is increased by 15%." }, { name = "Wing Guard's Vigil", icon = "Interface\\Icons\\Ability_Rogue_Feint", text = "Your chance to dodge is increased by 4%." }, { name = "Vigil of the Spires", icon = "Interface\\Icons\\Ability_Warrior_Revenge", text = "Hits against you have an 8% chance to raise Retaliation. Once every 30 sec.\n\nA Wing Guard sworn to Terokk's spires answers every blow; its oath gives it no other choice." }, { name = "Raven God's Talon", icon = "Interface\\Icons\\Ability_Rogue_Rupture", text = "Your Gushing Wound deals 15% more damage.\n\nThe talons of Skettis find you. Anzu's blessing runs in every cut." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Terokkar Forest", expansion = 1, order = 329, box = { 0.18, -0.02, 1.81 }, skins = { { entry = 18322, name = "Teal", creature = "Sethekk Ravenguard", display = 20573, height = 3.9, span = 3.9, box = { 0.19, -0.02, 1.87 } }, { entry = 18321, name = "Red", creature = "Sethekk Talon Lord", display = 20598, height = 4.4, span = 4.4, box = { 0.21, -0.02, 2.11 } }, { entry = 19944, name = "Purple", creature = "Lashh'an Wing Guard", display = 17858, height = 3.3, span = 3.3, box = { 0.16, -0.02, 1.57 } }, { entry = 18541, name = "Gold", creature = "Urdak", display = 17860, height = 3.3, span = 3.3, box = { 0.16, -0.02, 1.57 } }, { entry = 22388, name = "Green", creature = "Lithic Talonguard", display = 21032, height = 3.6, span = 3.6, box = { 0.18, -0.02, 1.75 } } }, title = "Arakkoa of Skettis" },
    { id = "kodo", entry = 25596, name = "Infected Kodo Beast", label = "Kodo", level = 68, display = 23265, height = 8.1, span = 15.9, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Mount_Kodo_01", profile = "tank", kit = { 6266, 54794, 5568, 45876, 22693, 261 }, passives = {}, talentInfo = { { name = "Ancient Kodo Hide", icon = "Interface\\Icons\\Ability_Mount_Kodo_01", text = "Your armor is increased by 25%." }, { name = "Herd Mother's Bulk", icon = "Interface\\Icons\\Ability_Mount_Kodo_02", text = "Your maximum health is increased by 12%." }, { name = "Plague-Hardened Blood", icon = "Interface\\Icons\\Spell_Nature_NullifyDisease", text = "Your Nature resistance is increased by 40." }, { name = "Thunder of the Herd", icon = "Interface\\Icons\\Ability_Druid_ChallangingRoar", text = "The threat you cause is increased by 30%." }, { name = "Unstoppable Herd", icon = "Interface\\Icons\\Ability_Mount_Kodo_03", text = "Reduces the cooldown of your Stampede by 10 sec.\n\nThe herd tramples all! Once a kodo starts running, the Borean Tundra only gets flatter." }, { name = "Trampling Rage", icon = "Interface\\Icons\\Ability_WarStomp", text = "When you are struck, you have an 8% chance to Trample everything around you. Once every 30 sec.\n\nPlague-sick or not, an old kodo that is poked too often simply walks over the problem." } }, tips = { [261] = "Bellow across the tundra: two Infected Kodo Beasts lumber in to fight beside you for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Borean Tundra", expansion = 2, order = 431, summons = { [261] = true }, box = { -2.95, -0.10, 4.01 }, skinName = "Woolly", skins = { { entry = 2974, name = "Brown", creature = "Kodo Matriarch", display = 10918, height = 6.2, span = 12.2, box = { -2.26, -0.08, 3.07 } }, { entry = 3474, name = "Gray", creature = "Lakota'mani", display = 1241, height = 7.0, span = 13.8, box = { -2.56, -0.09, 3.47 } } }, title = "Kodo of the Borean Tundra" },
    { id = "crocolisk", entry = 15043, name = "Zulian Crocolisk", label = "Crocolisk", level = 60, display = 833, height = 1.6, span = 8.1, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Hunter_Pet_Crocolisk", profile = "bruiser", kit = { 48287, 13445, 3604, 43352, 3391 }, passives = {}, talentInfo = { { name = "Zulian Jaws", icon = "Interface\\Icons\\Ability_Hunter_Pet_Crocolisk", text = "Your Physical damage is increased by 8%." }, { name = "Armored Crocolisk Hide", icon = "Interface\\Icons\\INV_Misc_MonsterScales_03", text = "Your armor is increased by 20%." }, { name = "Cold-Blooded", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your Stamina is increased by 6%." }, { name = "Sacred Pool Swimmer", icon = "Interface\\Icons\\Ability_Druid_AquaticForm", text = "Your movement speed is increased by 8%." }, { name = "Death Roll", icon = "Interface\\Icons\\Ability_Rogue_Rupture", text = "Your melee attacks have an 8% chance to clamp down with a Powerful Bite. Once every 10 sec.\n\nOnce a crocolisk's jaws close, it rolls; whatever is in its mouth rolls with it." }, { name = "Lockjaw", icon = "Interface\\Icons\\Ability_Druid_Mangle2", text = "Increases the damage of Powerful Bite by 15%.\n\nThe crocolisks of Zul'Gurub's sacred pools were fed on Gurubashi sacrifices; their bite has never softened." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Zul'Gurub", expansion = 0, order = 244, box = { -1.24, 0.04, 0.59 }, skins = { { entry = 1082, name = "Swamp", creature = "Sawtooth Crocolisk", display = 807, height = 1.8, span = 9.6, box = { -1.46, 0.05, 0.70 } }, { entry = 1400, name = "Marsh", creature = "Wetlands Crocolisk", display = 1036, height = 1.0, span = 5.3, box = { -0.80, 0.03, 0.38 } } }, title = "Crocolisk of Zul'Gurub" },
    { id = "spider", entry = 5856, name = "Glassweb Spider", label = "Spider", level = 45, display = 4456, height = 1.7, span = 5.2, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Ability_Hunter_Pet_Spider", profile = "bruiser", kit = { 745, 744, 12252, 43356, 17331, 3635 }, passives = { 3616 }, talentInfo = { { name = "Glassweb Venom", icon = "Interface\\Icons\\Ability_Creature_Poison_03", text = "Your Nature damage is increased by 10%." }, { name = "Glassy Carapace", icon = "Interface\\Icons\\Ability_Hunter_Pet_Spider", text = "Your armor is increased by 15%." }, { name = "Skittering Legs", icon = "Interface\\Icons\\Ability_Rogue_Sprint", text = "Your movement speed is increased by 10%." }, { name = "Ambush from the Web", icon = "Interface\\Icons\\Ability_Ambush", text = "Your melee attacks have a 6% chance to web the target in place. Once every 20 sec.\n\nStruggle all you like. A Glassweb spins as it bites, and its prey only notices the web when it tries to run." }, { name = "Searing Gorge Hunger", icon = "Interface\\Icons\\Ability_Racial_BloodRage", text = "Your Pounce deals 15% more damage.\n\nNothing much lives in the scorched canyons, so a Glassweb leaps at anything that moves, and leaps again." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Searing Gorge", expansion = 0, order = 131, box = { 0.71, -0.00, 0.86 }, skinName = "Crystal", variants = { "spider_widow", "spider_plague", "spider_trapper" }, skins = { { entry = 217, name = "Cave", creature = "Venom Web Spider", display = 955, height = 1.4, span = 4.3, box = { 0.59, -0.00, 0.71 } } }, title = "Crystal Spider of Searing Gorge" },
    { id = "bear", entry = 8957, name = "Angerclaw Grizzly", label = "Grizzly", level = 52, display = 9277, height = 3.3, span = 5.8, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bear", profile = "tank", kit = { 15793, 39270, 31279, 8716, 10968, 3427, 19615 }, passives = {}, talentInfo = { { name = "Angerclaw Hide", icon = "Interface\\Icons\\Ability_Racial_BearForm", text = "Your armor is increased by 25%." }, { name = "Grizzly Heart", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bear", text = "Your maximum health is increased by 10%." }, { name = "Felwood Fury", icon = "Interface\\Icons\\Ability_Druid_DemoralizingRoar", text = "The threat you cause is increased by 30%." }, { name = "Thick Grizzly Fur", icon = "Interface\\Icons\\INV_Misc_Pelt_Bear_01", text = "Damage you take is reduced by 5%." }, { name = "Plagued Claws", icon = "Interface\\Icons\\Spell_Nature_NullifyDisease", text = "Your melee attacks have an 8% chance to leave an Infected Wound. Once every 15 sec.\n\nThe Angerclaw grizzlies ate from the fel-poisoned streams of Felwood, and the rot is in their claws now." }, { name = "Out of My Forest", icon = "Interface\\Icons\\Ability_Druid_Maul", text = "Your Demoralizing Roar reaches 20% farther.\n\nRrraaagh! An Angerclaw does not chase intruders out of its forest. It knocks them down and keeps them there." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Felwood", expansion = 0, order = 171, box = { 0.02, -0.05, 1.56 }, view = { -1.9905, -0.7795, 0.4207 }, skinName = "Plagued", variants = { "bear_grizzly", "bear_ice", "bear_war" }, skins = { { entry = 26633, name = "Ursoc", creature = "Ursoc", display = 23964, height = 11.4, span = 20.0, box = { 0.07, -0.17, 5.35 } } }, title = "Plagued Grizzly of Felwood" },
    { id = "wolf", entry = 18476, name = "Timber Worg", label = "Worg", level = 63, display = 11419, height = 2.2, span = 4.5, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Hunter_Pet_Wolf", profile = "bruiser", kit = { 32919, 32918, 13443, 3604, 3149, 261 }, passives = {}, talentInfo = { { name = "Pack Hunter", icon = "Interface\\Icons\\Ability_Hunter_Pet_Wolf", text = "Your Physical damage is increased by 8%." }, { name = "Worg Pelt", icon = "Interface\\Icons\\INV_Misc_Pelt_Wolf_01", text = "Damage you take is reduced by 4%." }, { name = "Timber Stride", icon = "Interface\\Icons\\Spell_Nature_Swiftness", text = "Your movement speed is increased by 12%." }, { name = "Throat Ripper", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your melee critical strike chance is increased by 5%." }, { name = "Hamstring the Straggler", icon = "Interface\\Icons\\Ability_ShockWave", text = "Your melee hits have a 10% chance to Tendon Rip the target. Once every 10 sec.\n\nThe pack never chases the fastest. It cuts down the one that falls behind." }, { name = "Voice of the Pack", icon = "Interface\\Icons\\Spell_Frost_ChillingBlast", text = "Reduces the cooldown of Chilling Howl by 5 sec.\n\nAwoooo! In Terokkar's forests the howling never really stops; it only moves closer." } }, tips = { [261] = "Howl through the Terokkar pines: two Timber Worgs of your pack lope in to hunt beside you for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Terokkar Forest", expansion = 1, order = 328, summons = { [261] = true }, box = { -0.41, -0.02, 1.07 }, skins = { { entry = 10981, name = "Frostwolf", creature = "Frostwolf", display = 10278, height = 2.5, span = 5.1, box = { -0.47, -0.02, 1.21 } }, { entry = 8211, name = "Dark", creature = "Old Cliff Jumper", display = 11414, height = 1.9, span = 3.9, box = { -0.36, -0.01, 0.93 } }, { entry = 17548, name = "Brown", creature = "Tito", display = 17079, height = 1.1, span = 2.3, box = { -0.22, -0.01, 0.56 } } }, title = "Worg of Terokkar Forest" },
    { id = "firelord", entry = 21181, name = "Cyrukh the Firelord", label = "Cyrukh the Firelord", level = 72, display = 20135, height = 38.5, span = 40.8, school = "fire", pool = "archetype", icon = "Interface\\Icons\\Spell_Fire_Elemental_Totem", profile = "caster", kit = { 39429, 36247, 19393, 34660, 7139, 18945 }, passives = {}, talentInfo = { { name = "Fel Inferno", icon = "Interface\\Icons\\Spell_Fire_FelFlameStrike", text = "Your Fire damage is increased by 10%." }, { name = "Molten Body", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Your Fire resistance is increased by 80." }, { name = "Burning Colossus", icon = "Interface\\Icons\\Spell_Fire_Volcano", text = "Your maximum health is increased by 8%." }, { name = "Dirge of Karabor", icon = "Interface\\Icons\\Spell_Fire_FelFlameBolt", text = "Your damaging spells have a 10% chance to hurl a Fel Fireball at the target. Once every 10 sec.\n\nThose that dare play with fire will be incinerated! Cyrukh's burning dirge echoes over Karabor, and every note is fel flame." }, { name = "Colossal Stride", icon = "Interface\\Icons\\Ability_WarStomp", text = "Increases the damage of your Fel Trample by 20%.\n\nEvery step of the Firelord cracks the scorched earth of Shadowmoon Valley a little deeper." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, expansion = 1, order = 378, box = { 0.45, -0.35, 19.14 }, title = "Firelord of Shadowmoon Valley" },
    { id = "siren", entry = 17801, name = "Coilfang Siren", label = "Naga Siren", level = 70, display = 18392, height = 3.7, span = 3.7, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_Lightning", profile = "caster", kit = { 37664, 37856, 38660, 38491, 15063, 17740 }, passives = {}, talentInfo = { { name = "Storm of the Deep", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 8%." }, { name = "Arcana of Nazjatar", icon = "Interface\\Icons\\Spell_Arcane_StarFire", text = "Your Arcane damage is increased by 5%." }, { name = "Siren's Song", icon = "Interface\\Icons\\Spell_Frost_SummonWaterElemental", text = "Your casting speed is increased by 6%." }, { name = "Tidecaller's Focus", icon = "Interface\\Icons\\Spell_Nature_ManaRegenTotem", text = "Your Nature spells cost 8% less." }, { name = "Song of the Deep", icon = "Interface\\Icons\\Spell_Holy_Silence", text = "When you are struck, you have an 8% chance to sear your attacker with Arcane Flare. Once every 30 sec.\n\nStrike a siren and she answers in the old tongue of Nazjatar; the words burn like arcane fire." }, { name = "Stormcaller", icon = "Interface\\Icons\\Spell_Nature_LightningBolt", text = "Increases the damage of Lightning Bolt by 10%.\n\nLady Vashj's sirens pull the storm out of Zangarmarsh's drained waters and throw it back at the thieves." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Coilfang: The Steamvault", expansion = 1, order = 366, charModel = true, box = { -0.78, 0.01, 1.83 }, skins = { { entry = 18087, name = "Darkcrest", creature = "Darkcrest Siren", display = 17952, height = 4.9, span = 4.9, box = { -1.02, 0.01, 2.39 }, charModel = true }, { entry = 20684, name = "Shav'rar", creature = "Lady Shav'rar", display = 19366, height = 5.7, span = 5.7, box = { -1.20, 0.01, 2.81 }, charModel = true }, { entry = 21964, name = "Caribdis", creature = "Fathom-Guard Caribdis", display = 20672, height = 8.6, span = 8.6, box = { -1.81, 0.01, 4.22 }, charModel = true }, { entry = 25073, name = "Darkspine", creature = "Darkspine Siren", display = 22869, height = 3.4, span = 3.4, box = { -0.72, 0.01, 1.69 }, charModel = true }, { entry = 24696, name = "Coilskar", creature = "Coilskar Witch", display = 22590, height = 3.4, span = 3.4, box = { -0.72, 0.01, 1.69 }, charModel = true } }, title = "Naga Sorceress of the Steamvault" },
    { id = "dragonspawn", entry = 9096, name = "Rage Talon Dragonspawn", label = "Dragonspawn", level = 59, display = 2554, height = 3.3, span = 6.5, school = "physical", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", profile = "bruiser", kit = { 9573, 15496, 13737, 15548, 12021, 28371 }, passives = {}, talentInfo = { { name = "Rage Talon Fury", icon = "Interface\\Icons\\Ability_Druid_Enrage", text = "Your Physical damage is increased by 8%." }, { name = "Dragonspawn Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your armor is increased by 15%." }, { name = "Draconic Vigor", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", text = "Your maximum health is increased by 6%." }, { name = "Blood of the Brood", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your melee attacks have a 5% chance to follow up with a Mortal Strike. Once every 30 sec.\n\nDragonspawn were bred for Blackrock's wars; the smell of blood drives them faster than any command." }, { name = "Unyielding Glare", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your Thunderclap reaches 20% farther.\n\nA Rage Talon slams the ground like the wingbeat of its masters, and the whole slope shakes." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, instance = "Blackrock Spire", expansion = 0, order = 181, box = { -0.78, -0.38, 1.59 }, skinName = "Black", variants = { "dragonspawn_blue", "dragonspawn_green", "dragonspawn_bronze" }, skins = { { entry = 1045, name = "Red", creature = "Red Dragonspawn", display = 363, height = 2.6, span = 5.2, box = { -0.62, -0.31, 1.27 } }, { entry = 10447, name = "Chromatic", creature = "Chromatic Dragonspawn", display = 10094, height = 2.6, span = 5.2, box = { -0.62, -0.31, 1.27 } } }, title = "Soldier of the Black Dragonflight" },
    { id = "wyvern", entry = 9297, name = "Enraged Wyvern", label = "Wyvern", level = 65, display = 2157, height = 6.9, span = 11.5, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Ability_Mount_Wyvern_01", profile = "bruiser", kit = { 744, 37319, 24335, 5708, 36589 }, passives = { 3616 }, talentInfo = { { name = "Tempest Wings", icon = "Interface\\Icons\\Ability_Mount_Wyvern_01", text = "Your Physical damage is increased by 8%." }, { name = "Venomed Stinger", icon = "Interface\\Icons\\Ability_Creature_Poison_02", text = "Your Nature damage is increased by 6%." }, { name = "Hunter of the Crags", icon = "Interface\\Icons\\Ability_Hunter_Pet_WindSerpent", text = "Your movement speed is increased by 12%." }, { name = "Leathery Wing Hide", icon = "Interface\\Icons\\Spell_Nature_SpiritArmor", text = "Damage you take is reduced by 4%." }, { name = "Drowsy Venom", icon = "Interface\\Icons\\Spell_Nature_Sleep", text = "Your Wyvern Sting costs 30% less.\n\nHunters took the wyvern's name for their sting. The wyvern had it first, and uses it more." }, { name = "Crag Venom", icon = "Interface\\Icons\\Ability_Creature_Poison_05", text = "Your Poison deals 20% more damage.\n\nWild wyverns of the high crags carry a venom no tamed mount ever keeps." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = true, wave = 3, expansion = 1, order = 331, box = { -0.04, 0.01, 3.94 }, skins = { { entry = 5928, name = "Blue", creature = "Sorrow Wing", display = 11012, height = 9.5, span = 15.7, box = { -0.05, 0.01, 5.37 } }, { entry = 5934, name = "Green", creature = "Heartrazor", display = 11011, height = 9.5, span = 15.7, box = { -0.05, 0.01, 5.37 } } }, title = "Wyvern of the High Crags" },
    { id = "lost_one", entry = 763, name = "Lost One Chieftain", label = "Lost One", level = 39, display = 10921, height = 2.5, span = 2.5, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Gouge", profile = "bruiser", kit = { 11640, 13737, 8255, 6713, 23511, 19615, 261 }, passives = {}, talentInfo = { { name = "Madness of the Exile", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "All damage you deal is increased by 6%." }, { name = "Fel-Sickened Flesh", icon = "Interface\\Icons\\Spell_Fire_FelFire", text = "Your Shadow resistance is increased by 40." }, { name = "Broken But Unbowed", icon = "Interface\\Icons\\Achievement_Character_Draenei_Male", text = "Your maximum health is increased by 6%." }, { name = "Swamp Survivor", icon = "Interface\\Icons\\Ability_Rogue_Feint", text = "Your chance to dodge is increased by 4%." }, { name = "Nothing Left to Lose", icon = "Interface\\Icons\\Ability_Racial_BloodRage", text = "When you are struck, you have an 8% chance to fly into the Madness of the exile. Once every 45 sec.\n\nEvery wound a Lost One takes is one more thing the world has stolen from him, and pain only feeds the madness." }, { name = "Chieftain's Cleaving Arm", icon = "Interface\\Icons\\INV_Sword_48", text = "Your Strong Cleave deals 15% more damage.\n\nThe chieftain's claymore is more rust than steel, but the arm behind it remembers when it was a vindicator's." } }, tips = { [261] = "The Lost Ones have nothing left to lose! Call two Lost One Muckdwellers out of the mire to fight at your side for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Swamp of Sorrows", expansion = 0, order = 113, summons = { [261] = true }, box = { -0.17, 0.01, 1.26 }, skins = { { entry = 7363, name = "White", creature = "Kum'isha the Collector", display = 11653, height = 2.0, span = 2.0, box = { -0.13, 0.01, 0.97 } }, { entry = 18077, name = "Umbrafen", creature = "Umbrafen Oracle", display = 18425, height = 2.2, span = 2.2, box = { -0.15, 0.01, 1.12 } }, { entry = 18113, name = "Feralfen", creature = "Feralfen Hunter", display = 18423, height = 2.2, span = 2.2, box = { -0.15, 0.01, 1.12 } }, { entry = 18116, name = "Daggerfen", creature = "Daggerfen Assassin", display = 18422, height = 2.0, span = 2.0, box = { -0.13, 0.01, 0.97 } }, { entry = 19174, name = "Mummaki", creature = "Chieftain Mummaki", display = 18620, height = 2.5, span = 2.5, box = { -0.17, 0.01, 1.26 } } }, title = "Leader of the Lost Ones" },
    { id = "gnoll_mystic", entry = 1013, name = "Mosshide Mystic", label = "Gnoll Mystic", level = 26, display = 714, height = 2.0, span = 2.0, school = "nature", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Head_Gnoll_01", profile = "caster", kit = { 9532, 11436, 11986, 3288, 12550, 261 }, passives = {}, talentInfo = { { name = "Swamp Lightning", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 8%." }, { name = "Mosshide Mending", icon = "Interface\\Icons\\Spell_Nature_MagicImmunity", text = "Your healing is increased by 12%." }, { name = "Chatter of the Spirits", icon = "Interface\\Icons\\Spell_Nature_ManaRegenTotem", text = "Your Nature spells cost 8% less." }, { name = "Gnoll Cunning", icon = "Interface\\Icons\\INV_Misc_Head_Gnoll_01", text = "Your Intellect is increased by 5%." }, { name = "Spirits of the Fen", icon = "Interface\\Icons\\Spell_Nature_Slow", text = "Your damaging spells have a 10% chance to hex the target with Slow. Once every 15 sec.\n\nThe swamp spirits hear a mystic's begging and clutch at his enemies' ankles with cold, slow hands." }, { name = "Thick Moss", icon = "Interface\\Icons\\Spell_Nature_SpiritArmor", text = "Your Moss Hide lasts 5 sec longer.\n\nWetlands moss grows on anything that stands still long enough, and a mystic stands still a lot." } }, tips = { [3288] = "Cloak yourself in thick moss that absorbs 20 damage for 10 sec.", [261] = "More bones to gnaw on! Howl two Mosshide Gnolls out of the reeds to fight at your side for 20 sec." }, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 3, zone = "Wetlands", expansion = 0, order = 89, summons = { [261] = true }, box = { -0.02, 0.04, 1.01 }, skinName = "Mystic", skinOf = "gnoll", title = "Gnoll Mystic of the Wetlands" },
    { id = "headless_horseman", entry = 23682, name = "Headless Horseman", label = "Headless Horseman", level = 80, display = 22351, height = 4.5, span = 5.1, school = "fire", pool = "wotlk", icon = "Interface\\Icons\\INV_Misc_Bag_28_Halloween", profile = "bruiser", kit = { 42380, 42587, 19196, 42514, 261 }, passives = {}, talentInfo = { { name = "Hallow's End Fire", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire damage is increased by 8%." }, { name = "Rider of the Midnight Steed", icon = "Interface\\Icons\\Ability_Mount_Dreadsteed", text = "Your movement speed is increased by 10%." }, { name = "Headless Fury", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Undying Rider", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", text = "Your maximum health is increased by 8%." }, { name = "Burning Village", icon = "Interface\\Icons\\Spell_Fire_Fireball", text = "Your melee attacks have a 6% chance to Conflagrate the target. Once every 45 sec.\n\nPrepare yourselves, the bells have tolled! The Horseman's blade trails fire." }, { name = "Squashed", icon = "Interface\\Icons\\INV_Misc_Food_59", text = "Your Squash Soul lasts 5 sec longer.\n\nOnce the Horseman has marked a soul, it stays marked." } }, tips = { [261] = "Soldiers arise, stand and fight! Raise three Pumpkin Fiends to burn your foes for 20 sec." }, visualKit = 286, soundTransform = 11961, soundDeath = 11964, flies = true, wave = 4, instance = "Scarlet Monastery", expansion = 2, order = 504, summons = { [261] = true }, box = { 0.45, -0.03, 2.23 }, voices = { { 11961, 8.0, true, "It is over, your search is done. Let fate choose now, the righteous one." }, { 12567, 8.3, true, "Here's my body, fit and pure! Now, your blackened souls I'll cure!" }, { 11963, 8.5, true, "Soldiers arise, stand and fight! Bring victory at last to this fallen knight!" }, { 11964, 8.7, true, "This end have I reached before. What new adventure lies in store?" }, { 11962, 8.6, true, "Your body lies beaten, battered and broken! Let my curse be your own, fate has spoken!" } }, title = "Terror of Hallow's End", visages = { "horseman_unhorsed" }, shape = "Mounted" },
    { id = "coren_direbrew", entry = 23872, name = "Coren Direbrew", label = "Coren Direbrew", level = 80, display = 21824, height = 2.1, span = 2.1, school = "physical", pool = "wotlk", icon = "Interface\\Icons\\INV_Holiday_BrewfestBuff_01", profile = "bruiser", kit = { 22419, 47718, 50276, 47442, 14872 }, passives = {}, talentInfo = { { name = "Dark Iron Brew", icon = "Interface\\Icons\\INV_Drink_05", text = "Your attack power is increased by 10%." }, { name = "Grim Guzzler", icon = "Interface\\Icons\\INV_Misc_Beer_01", text = "Your maximum health is increased by 8%." }, { name = "Brawler's Bulk", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Two-Fisted Drinker", icon = "Interface\\Icons\\Ability_DualWield", text = "Your attack speed is increased by 8%." }, { name = "Next Round's on Me", icon = "Interface\\Icons\\INV_Drink_04", text = "Your melee attacks have a 10% chance to Chuck a Mug. Once every 10 sec.\n\nCoren never runs out of mugs, and never throws one empty." }, { name = "Brewmaiden's Brew", icon = "Interface\\Icons\\Ability_Warrior_Charge", text = "Reduces the cooldown of Direbrew Charge by 5 sec.\n\nA little of the Dark Brewmaiden's brew and the dwarf is off again." } }, tips = { [22419] = "Down a mug and bellow, knocking the enemies close around you back and disarming them for 4 sec." }, visualKit = 437, soundTransform = 1352, soundDeath = 1350, flies = false, wave = 4, instance = "Blackrock Depths", expansion = 2, order = 505, charModel = true, box = { -0.13, -0.02, 1.02 }, title = "Dark Iron Brewmaster" },
    { id = "ahune", entry = 25740, name = "Ahune", label = "Ahune", level = 82, display = 23344, height = 54.9, span = 54.9, school = "frost", pool = "wotlk", icon = "Interface\\Icons\\Spell_Frost_FrozenCore", profile = "caster", kit = { 46406, 50094, 10101, 2676, 46568, 45947, 261 }, passives = {}, talentInfo = { { name = "The Frost Lord", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "Body of Ice", icon = "Interface\\Icons\\Spell_Frost_FrostWard", text = "Your Frost resistance is increased by 60." }, { name = "Slippery Floor", icon = "Interface\\Icons\\Spell_Frost_Glacier", text = "Your chance to dodge is increased by 5%." }, { name = "Frozen Core", icon = "Interface\\Icons\\INV_Misc_Gem_Sapphire_02", text = "Your maximum health is increased by 8%." }, { name = "Chilling Aura", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "When you are struck, you have a 10% chance to raise an Ice Spike under the attacker. Once every 15 sec.\n\nThe cold around the Frost Lord bites back at anyone who gets near." }, { name = "Midsummer's End", icon = "Interface\\Icons\\Spell_Frost_IceShock", text = "Your Bitter Blast deals 15% more damage.\n\nThe bonfires of Midsummer only make Ahune colder." } }, tips = { [45947] = "Freeze the floor under an enemy; it slips and falls, stunned for 2 sec.", [261] = "Call an Ahunite Hailstone out of the ice to fight for you for 20 sec." }, visualKit = 4991, soundTransform = 12286, soundDeath = 12287, flies = false, wave = 4, instance = "Coilfang: The Slave Pens", expansion = 2, order = 513, summons = { [261] = true }, box = { 2.28, -0.27, 21.66 }, title = "The Frost Lord" },
    { id = "rexxar", entry = 21984, name = "Rexxar", label = "Rexxar", level = 72, display = 20918, height = 4.5, span = 4.5, school = "physical", pool = "leader", icon = "Interface\\Icons\\Ability_Hunter_BeastMastery", profile = "bruiser", kit = { 20685, 42332, 67716, 16508, 55220, 261 }, passives = {}, talentInfo = { { name = "Twin Axes", icon = "Interface\\Icons\\Ability_DualWield", text = "Your attack speed is increased by 10%." }, { name = "Beastmaster", icon = "Interface\\Icons\\Ability_Hunter_BeastCall", text = "Your attack power is increased by 8%." }, { name = "Mok'Nathal Blood", icon = "Interface\\Icons\\Ability_Racial_BloodRage", text = "Your maximum health is increased by 8%." }, { name = "Hunter's Instinct", icon = "Interface\\Icons\\Ability_Druid_FerociousBite", text = "Your chance to critically strike with melee attacks is increased by 5%." }, { name = "Wild Axes", icon = "Interface\\Icons\\INV_Weapon_Halberd_03", text = "Your melee hits have an 8% chance to hurl an axe at your target. Once every 12 sec.\n\nRexxar's axes never stay in his hands for long; one is always spinning toward the next foe." }, { name = "Misha's Loyalty", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bear", text = "Reduces the cooldown of Misha by 30 sec.\n\nWherever the Mok'Nathal wanders, Misha is never more than a roar away." } }, tips = { [261] = "Misha! Your great bear comes crashing out of the wilds and fights at your side for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Blade's Edge Mountains", expansion = 1, order = 334, summons = { [261] = true }, box = { -0.03, -0.12, 2.23 }, title = "Champion of the Horde" },
    { id = "maiev_shadowsong", entry = 21699, name = "Maiev Shadowsong", label = "Maiev Shadowsong", level = 72, display = 20628, height = 3.4, span = 3.4, school = "shadow", pool = "leader", icon = "Interface\\Icons\\Achievement_Character_Nightelf_Female", profile = "bruiser", kit = { 16045, 41152, 40685, 39954, 49481, 41176, 261 }, passives = {}, talentInfo = { { name = "Ten Thousand Years", icon = "Interface\\Icons\\Ability_Hunter_SwiftStrike", text = "Your Agility is increased by 6%." }, { name = "Umbra Crescent", icon = "Interface\\Icons\\Ability_Rogue_FanOfKnives", text = "Your chance to critically strike with melee attacks is increased by 5%." }, { name = "Shadow of the Warden", icon = "Interface\\Icons\\Spell_Shadow_ShadowWard", text = "Your Shadow damage is increased by 8%." }, { name = "Elusive Jailer", icon = "Interface\\Icons\\Ability_Rogue_Shadowstep", text = "Your chance to dodge is increased by 5%." }, { name = "Vengeance Incarnate", icon = "Interface\\Icons\\Spell_Shadow_PainSpike", text = "Your melee hits have an 8% chance to lay a Shadow Strike on your target. Once every 15 sec.\n\nTen thousand years as Illidan's jailer left nothing in Maiev but the hunt, and it cuts deep." }, { name = "The Hunt Unending", icon = "Interface\\Icons\\Spell_Arcane_Blink", text = "Reduces the cooldown of your Shadowstep by 8 sec.\n\nThere is nowhere the Betrayer can run that the Warden has not already been." } }, tips = { [41152] = "Throw a dagger at an enemy, dealing 5400 Physical damage.", [40685] = "Strike with a shadow-steeped blade, dealing 4375 Shadow damage every 3 sec for 12 sec.", [39954] = "Loose a fan of blades, dealing Physical damage to every enemy around you.", [261] = "Meet your end! The vengeful dead of Shadowmoon rise at the Warden's call and hunt for her for 20 sec." }, visualKit = 7775, soundTransform = 11492, soundDeath = 0, flies = false, wave = 4, zone = "Shadowmoon Valley", expansion = 1, order = 341, summons = { [261] = true }, box = { -0.21, -0.08, 1.27 }, title = "The Warden" },
    { id = "akama", entry = 21700, name = "Akama", label = "Akama", level = 70, display = 20681, height = 2.9, span = 2.9, school = "nature", pool = "leader", icon = "Interface\\Icons\\Achievement_Reputation_AshtongueDeathsworn", profile = "bruiser", kit = { 40536, 41177, 41978, 15501, 34189, 5200 }, passives = {}, talentInfo = { { name = "Spirit of the Ashtongue", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", text = "Your Nature damage is increased by 8%." }, { name = "Deathsworn Blade", icon = "Interface\\Icons\\Ability_Rogue_Eviscerate", text = "Your chance to critically strike with melee attacks is increased by 5%." }, { name = "Walker in Shadow", icon = "Interface\\Icons\\Ability_Stealth", text = "Your chance to dodge is increased by 5%." }, { name = "Patience of the Broken", icon = "Interface\\Icons\\Ability_Poisons", text = "Your Agility is increased by 6%." }, { name = "Ashtongue Venom", icon = "Interface\\Icons\\Ability_PoisonSting", text = "Your melee hits have an 8% chance to coat your target in Debilitating Poison. Once every 15 sec.\n\nThe Deathsworn waited years in Illidan's shadow, and every blade they carried was already poisoned." }, { name = "The Time Has Come", icon = "Interface\\Icons\\Achievement_Character_Draenei_Male", text = "Reduces the cooldown of Ashtongue Broken by 30 sec.\n\nThe moment is at hand! When the elder calls, the Broken of Karabor come." } }, tips = { [5200] = "The time has come! Two Ashtongue Broken step out of the shadows and fight for their elder for 30 sec." }, visualKit = 282, soundTransform = 11389, soundDeath = 11391, flies = false, wave = 4, zone = "Shadowmoon Valley", expansion = 1, order = 340, summons = { [5200] = true }, box = { -0.31, -0.00, 1.45 }, voices = { { 11600, 4.5, false, "Olum... old friend. It is good to see that you are safe." }, { 11601, 6.5, false, "Illidan will become suspicious... that much is for certain. We will deal with it as we always do." }, { 11602, 5.8, false, "You cannot... be serious, Olum. Your sacrifice has already been too great." }, { 11603, 8.0, false, "It appears your mind is set then. We will guide you to the spirit world with as much kindness as we can." }, { 11604, 6.1, false, "Farewell, dear friend. We shall meet you in the next world when our duties in this one are fulfilled." }, { 11605, 7.4, false, "Master! We've found the traitor who escaped Vashj! His body lies in front of me... lifeless!" }, { 11607, 1.8, false, "It will be done, my lord!" } }, title = "Ashtongue Deathsworn" },
    { id = "khadgar", entry = 18166, name = "Khadgar", label = "Khadgar", level = 71, display = 18921, height = 2.4, span = 2.4, school = "arcane", pool = "leader", icon = "Interface\\Icons\\Spell_Arcane_PortalShattrath", profile = "caster", kit = { 34447, 29885, 33175, 11436, 13323, 14514, 12845 }, passives = {}, talentInfo = { { name = "Medivh's Apprentice", icon = "Interface\\Icons\\Spell_Arcane_ArcanePotency", text = "Your Arcane damage is increased by 10%." }, { name = "Veteran of the Second War", icon = "Interface\\Icons\\Spell_Arcane_MindMastery", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Quickened Casting", icon = "Interface\\Icons\\Spell_Arcane_Blast", text = "Your spells are cast 8% faster." }, { name = "Violet Discipline", icon = "Interface\\Icons\\Spell_Arcane_StarFire", text = "Your Arcane spells cost 10% less." }, { name = "The Guardian's Lessons", icon = "Interface\\Icons\\Spell_Nature_StarFall", text = "Your damaging spells have a 10% chance to loose an extra Arcane Missile at the target. Once every 8 sec.\n\nMedivh taught his apprentice to cast twice before an enemy finished flinching." }, { name = "Walker Between Worlds", icon = "Interface\\Icons\\Spell_Arcane_Blink", text = "Reduces the cooldown of your Blink by 5 sec.\n\nKhadgar crossed the Dark Portal, sealed it behind him and walked Draenor for twenty years." } }, tips = {}, visualKit = 1005, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Shattrath City", expansion = 1, order = 367, box = { 0.04, -0.00, 1.21 }, title = "Sons of Lothar" },
    { id = "rhonin", entry = 16128, name = "Rhonin", label = "Rhonin", level = 83, display = 16024, height = 2.9, span = 2.9, school = "arcane", pool = "leader", icon = "Interface\\Icons\\Achievement_Reputation_KirinTor", profile = "caster", kit = { 50273, 13901, 54202, 29964, 20537, 36109, 71635, 261 }, passives = {}, talentInfo = { { name = "Master of the Violet Eye", icon = "Interface\\Icons\\Spell_Holy_MagicalSentry", text = "Your Arcane damage is increased by 10%." }, { name = "Archmage of Dalaran", icon = "Interface\\Icons\\Spell_Arcane_PortalDalaran", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Discipline of the Six", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "Your Arcane spells cost 10% less." }, { name = "Wards of the Violet Citadel", icon = "Interface\\Icons\\Spell_Holy_PowerWordShield", text = "Damage you take is reduced by 5%." }, { name = "Hero of Grim Batol", icon = "Interface\\Icons\\Spell_Fire_FlameShock", text = "Your damaging spells have an 8% chance to loose an Arcane Barrage at the target. Once every 20 sec.\n\nRhonin freed the Dragon Queen at Grim Batol with a spell no one saw coming, and he has never stopped casting." }, { name = "Leader of the Kirin Tor", icon = "Interface\\Icons\\Achievement_Reputation_KirinTor", text = "Your Aegis of Dalaran lasts 4 sec longer.\n\nThe wards of the Violet Citadel answer first to the one who sits at the head of the Six." } }, tips = { [261] = "Call two Kirin Tor Battle-Mages to your side for 30 sec." }, visualKit = 1005, soundTransform = 15650, soundDeath = 0, flies = false, wave = 4, zone = "Dalaran", expansion = 2, order = 522, summons = { [261] = true }, charModel = true, box = { -0.14, -0.01, 1.44 }, voices = { { 15649, 3.8, false, "We received Brann's message, and we have begun preparations." }, { 15650, 4.8, true, "Citizens of Dalaran! Raise your eyes to the skies and observe!" }, { 15651, 5.3, true, "Today our world's destruction has been averted in defiance of our very makers!" }, { 15652, 8.0, true, "Algalon the Observer, herald of the titans, has been defeated by our brave comrades in the depths of the titan city of Ulduar." }, { 15653, 3.2, true, "Algalon was sent here to judge the fate of our world." }, { 15654, 8.5, true, "He found a planet whose races had deviated from the titans' blueprints. A planet where not everything had gone according to plan." }, { 15655, 12.2, true, "Cold logic deemed our world not worth saving. Cold logic, however, does not account for the power of free will. It's up to each of us to prove this is a world worth saving." }, { 15656, 4.0, true, "That our lives... our lives are worth living." } }, title = "Leader of the Kirin Tor" },
    { id = "high_overlord_saurfang", entry = 14720, name = "High Overlord Saurfang", label = "High Overlord Saurfang", level = 72, display = 14732, height = 2.6, span = 2.6, school = "physical", pool = "leader", icon = "Interface\\Icons\\Achievement_Character_Orc_Male", profile = "bruiser", kit = { 26339, 15284, 19778, 69634, 22120 }, passives = {}, talentInfo = { { name = "Blackrock Veteran", icon = "Interface\\Icons\\Spell_Shadow_UnholyStrength", text = "Your maximum health is increased by 8%." }, { name = "Might of the High Overlord", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your Strength is increased by 8%." }, { name = "Old Horde Fury", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", text = "Your chance to critically strike with melee attacks is increased by 5%." }, { name = "Kor'kron Plate", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Honour Above All", icon = "Interface\\Icons\\Ability_Warrior_WarCry", text = "Your melee hits have an 8% chance to follow with Saurfang's Rage. Once every 20 sec.\n\nEvery foe who stands before the old warrior is paid a round-house kick and the edge of his axe." }, { name = "Blood of the Old Horde", icon = "Interface\\Icons\\Spell_Nature_BloodLust", text = "Reduces the cooldown of your Taste of Blood by 30 sec.\n\nSaurfang has bled on every battlefield since the Dark Portal opened, and it only ever made him angrier." } }, tips = {}, visualKit = 437, soundTransform = 17087, soundDeath = 0, flies = false, wave = 4, expansion = 1, order = 379, charModel = true, box = { 0.01, -0.01, 1.29 }, title = "Commander of the Horde" },
    { id = "adal", entry = 18481, name = "A'dal", label = "A'dal", level = 73, display = 18135, height = 21.8, span = 21.8, school = "holy", pool = "leader", icon = "Interface\\Icons\\Spell_Holy_SurgeOfLight", profile = "caster", kit = { 41394, 40096, 36950, 69963, 65051, 261 }, passives = { 21512 }, talentInfo = { { name = "Light of the Naaru", icon = "Interface\\Icons\\Spell_Holy_HolyBolt", text = "Your Holy damage is increased by 10%." }, { name = "Mender of Shattrath", icon = "Interface\\Icons\\Spell_Holy_GreaterHeal", text = "Your healing is increased by 10%." }, { name = "Radiant Will", icon = "Interface\\Icons\\Spell_Holy_SearingLight", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Being of Light", icon = "Interface\\Icons\\Spell_Holy_BlessingOfProtection", text = "Increases your Shadow resistance by 60." }, { name = "Chime of the Naaru", icon = "Interface\\Icons\\Spell_Holy_HolyNova", text = "Your damaging spells have an 8% chance to ring out a Holy Nova around you. Once every 15 sec.\n\nWhen A'dal speaks, the whole Terrace of Light hears a chime, and every shadow in Shattrath flinches." }, { name = "The Light Endures", icon = "Interface\\Icons\\Spell_Holy_Heal", text = "Reduces the mana cost of your Greater Heal by 20%.\n\nBe still, child of this world. The naaru's light is not spent on the wounded; it is simply given." } }, tips = { [65051] = "Sing a hymn of the Light, healing nearby allies for 2016 and raising the healing they receive by 10% for 8 sec.", [261] = "Be still, child of this world. Two Sha'tar Vindicators answer the naaru and fight at your side for 20 sec." }, visualKit = 154, soundTransform = 0, soundDeath = 0, flies = true, wave = 4, zone = "Shattrath City", expansion = 1, order = 368, summons = { [261] = true }, box = { 0.08, 0.04, 13.30 }, title = "Leader of the Sha'tar" },
    { id = "koltira_deathweaver", entry = 32311, name = "Koltira Deathweaver", label = "Koltira Deathweaver", level = 80, display = 23920, height = 2.8, span = 2.8, school = "shadow", pool = "leader", icon = "Interface\\Icons\\Spell_DeathKnight_AntiMagicZone", profile = "bruiser", kit = { 58843, 30500, 55974, 66018, 53550, 261 }, passives = {}, talentInfo = { { name = "Runeblade of Quel'Thalas", icon = "Interface\\Icons\\Spell_DeathKnight_EmpowerRuneBlade", text = "Your attack power is increased by 10%." }, { name = "Blood Plague", icon = "Interface\\Icons\\spell_deathknight_bloodplague", text = "Your Shadow damage is increased by 8%." }, { name = "Anti-Magic Zone", icon = "Interface\\Icons\\spell_deathknight_antimagiczone", text = "Damage you take is reduced by 5%." }, { name = "Brother in Death", icon = "Interface\\Icons\\Spell_Shadow_DeathPact", text = "Your maximum health is increased by 8%." }, { name = "Deathweaver", icon = "Interface\\Icons\\Spell_Shadow_DeathCoil", text = "Your melee hits have a 6% chance to make the blood of nearby enemies boil. Once every 15 sec.\n\nKoltira weaves death as other elves weave spells: between every swing of the runeblade, the blood around him boils." }, { name = "Plague of the Onslaught", icon = "Interface\\Icons\\Spell_Shadow_DeathAndDecay", text = "Your Blood Boil deals 15% more damage.\n\nThe Scarlet Onslaught learned what the Ebon Blade leaves behind: blood that boils long after the knights ride on." } }, tips = { [261] = "There are none beyond the grasp of the Scourge! An Acherus Ghoul claws out of the ground and fights for you for 20 sec." }, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, expansion = 2, order = 483, summons = { [261] = true }, charModel = true, box = { -0.17, -0.03, 1.39 }, title = "Ebon Blade Emissary to the Horde" },
    { id = "thassarian", entry = 26170, name = "Thassarian", label = "Thassarian", level = 72, display = 23649, height = 2.8, span = 2.8, school = "frost", pool = "leader", icon = "Interface\\Icons\\Spell_DeathKnight_FrostPresence", profile = "bruiser", kit = { 59131, 59130, 66047, 61061, 61094, 29991, 66023 }, passives = {}, talentInfo = { { name = "Twin Runeblades", icon = "Interface\\Icons\\ability_dualwield", text = "Your attack speed is increased by 10%." }, { name = "Frost Fever", icon = "Interface\\Icons\\spell_deathknight_frostfever", text = "Your Frost damage is increased by 10%." }, { name = "Icy Talons", icon = "Interface\\Icons\\Spell_Deathknight_IcyTalons", text = "Your chance to critically strike with melee attacks is increased by 5%." }, { name = "Leryssa's Promise", icon = "Interface\\Icons\\spell_holy_heroism", text = "Damage you take is reduced by 5%." }, { name = "Runeblades of the Borean Front", icon = "Interface\\Icons\\Spell_DeathKnight_IceTouch", text = "Your melee hits have an 8% chance to lay Icy Touch on the target. Once every 10 sec.\n\nTwin runeblades, forged in Acherus and blooded at the Wrathgate. Every cut leaves frost behind." }, { name = "Speak, Lich!", icon = "Interface\\Icons\\Spell_DeathKnight_Strangulate", text = "Reduces the cooldown of Death Grip by 8 sec.\n\nUndeath won't save you from what I'll put you through. Thassarian drags his quarry back, again and again." } }, tips = {}, visualKit = 4991, soundTransform = 14665, soundDeath = 14956, flies = false, wave = 4, zone = "Borean Tundra", expansion = 2, order = 435, charModel = true, box = { -0.14, -0.01, 1.38 }, voices = { { 14664, 0.8, true, "Leryssa!" }, { 14665, 4.5, true, "What have you done to my sister, you motherless elf scum!?" }, { 14666, 8.7, false, "I would sooner slit my own throat. You will pay for what you did to your own men, Arthas... for what you did to me! I swear it." }, { 14667, 2.7, false, "Leryssa... you... you're all right!" }, { 14668, 5.3, false, "I cannot return home with you just yet, Leryssa. I am not quite done with the Scourge." }, { 14669, 8.4, false, "You might be right, sister. My obligations to my land and King have been fulfilled. But there is something that I still owe to myself." }, { 14670, 9.3, false, "Do not worry, Leryssa. I will come back to you when I am done. Nothing in the world will stop me from coming home to the only family that I have left." } }, title = "Ebon Blade Emissary to the Alliance" },
    { id = "lady_deathwhisper", entry = 36855, name = "Lady Deathwhisper", label = "Lady Deathwhisper", level = 83, display = 30893, height = 12.3, span = 12.3, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_LadyDeathwhisper", profile = "caster", kit = { 71254, 71420, 71001, 72905, 71237, 20697, 261 }, passives = {}, talentInfo = { { name = "Leader of the Cult of the Damned", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 10%." }, { name = "Veil of Whispers", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Damage you take is reduced by 5%." }, { name = "Dark Empowerment", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Unholy Fervour", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "Your casting speed is increased by 6%." }, { name = "Embrace the Darkness", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your damaging spells have an 8% chance to loose a free Shadow Bolt. Once every 20 sec.\n\nThe Lady's whispers ride every bolt she throws, and some bolts throw themselves." }, { name = "Dark Martyrdom", icon = "Interface\\Icons\\Spell_Shadow_DeathAndDecay", text = "Reduces the cooldown of Death and Decay by 5 sec.\n\nThe cult gives its lives so the rot spreads sooner." } }, tips = { [261] = "Call two shadowcasters of the Cult of the Damned to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 16868, soundDeath = 16871, flies = false, wave = 4, instance = "Icecrown Citadel", expansion = 2, order = 560, summons = { [261] = true }, box = { 0.23, 0.10, 5.73 }, voices = { { 17272, 10.5, true, "You have found your way here, because you are among the few gifted with true vision in a world cursed with blindness." }, { 17273, 9.9, true, "You can see through the fog that hangs over this world like a shroud, and grasp where true power lies." }, { 16878, 9.7, true, "Fix your eyes upon your crude hands: the sinew, the soft meat, the dark blood coursing within." }, { 17268, 7.6, true, "It is a weakness; a crippling flaw.... A joke played by the Creators upon their own creations." }, { 17269, 8.2, true, "The sooner you come to accept your condition as a defect, the sooner you will find yourselves in a position to transcend it." }, { 17270, 9.8, true, "Through our Master, all things are possible. His power is without limit, and his will unbending." }, { 17271, 17.0, true, "Those who oppose him will be destroyed utterly, and those who serve -- who serve wholly, unquestioningly, with utter devotion of mind and soul -- elevated to heights beyond your ken." }, { 16868, 11.1, true, "What is this disturbance? You dare trespass upon this hallowed ground? This shall be your final resting place!" }, { 16877, 5.4, true, "Enough! I see I must take matters into my own hands!" }, { 16876, 5.4, true, "You are weak, powerless to resist my will!" }, { 16873, 7.8, true, "Take this blessing and show these intruders a taste of the Master's power!" }, { 16874, 4.1, true, "I release you from the curse of flesh!" } }, title = "Leader of the Cult of the Damned" },
    { id = "the_black_knight", entry = 35451, name = "The Black Knight", label = "The Black Knight", level = 80, display = 29837, height = 4.2, span = 4.2, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\GazeOfTheBlackKnight", profile = "bruiser", kit = { 67724, 67718, 67745, 261 }, passives = {}, talentInfo = { { name = "Agent of the Lich King", icon = "Interface\\Icons\\Spell_Deathknight_ClassIcon", text = "Your attack power is increased by 10%." }, { name = "Runeblade Mastery", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Frost Fever", icon = "Interface\\Icons\\Spell_DeathKnight_FrostFever", text = "Your Frost damage is increased by 8%." }, { name = "Death's Plate", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 15%." }, { name = "Unholy Retaliation", icon = "Interface\\Icons\\Spell_DeathKnight_EmpowerRuneBlade", text = "When you are struck, you have an 8% chance to answer with a Plague Strike. Once every 20 sec.\n\nThe Black Knight answers every blow the Crusade lands with plague." }, { name = "No Respite", icon = "Interface\\Icons\\Spell_Shadow_DeathPact", text = "Reduces the cooldown of Death's Respite by 10 sec.\n\nThe Black Knight has died before; he gives the living no respite." } }, tips = { [261] = "Raise a slain champion of the Crusade as a ghoul to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 16259, soundDeath = 16264, flies = false, wave = 4, instance = "Trial of the Champion", expansion = 2, order = 511, summons = { [261] = true }, charModel = true, box = { -0.44, -0.12, 2.09 }, voices = { { 16256, 4.3, false, "You spoiled my grand entrance, rat." }, { 16257, 7.7, false, "Did you honestly think an agent of the Lich King would be bested on the field of your pathetic little tournament?" }, { 16258, 2.5, false, "I've come to finish my task." }, { 16259, 3.0, true, "This farce ends here!" }, { 16262, 3.0, true, "My rotting flesh was just getting in the way!" }, { 16263, 4.7, true, "I have no need for bones to best you!" }, { 16260, 0.9, true, "Pathetic." }, { 16261, 2.1, true, "A waste of flesh." }, { 16264, 4.6, true, "No! I must not fail... again..." } }, title = "Agent of the Lich King", visages = { "black_knight_skeleton", "black_knight_ghost" }, shape = "Knight" },
    { id = "fjola_lightbane", entry = 34497, name = "Fjola Lightbane", label = "Fjola Lightbane", level = 83, display = 29240, height = 9.6, span = 11.7, school = "holy", pool = "wotlk", icon = "Interface\\Icons\\Spell_Holy_DivineProvidence", profile = "bruiser", kit = { 66046, 66075, 67297, 65916, 65858 }, passives = {}, talentInfo = { { name = "Twin Val'kyr of Light", icon = "Interface\\Icons\\Spell_Holy_HolyBolt", text = "Your Fire damage is increased by 10%." }, { name = "Light Essence", icon = "Interface\\Icons\\Spell_Holy_SealOfWrath", text = "Your Fire resistance is increased by 60." }, { name = "Hammer of Light", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Val'kyr Wings", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Your movement speed is increased by 10%." }, { name = "Let the Light Consume You", icon = "Interface\\Icons\\Spell_Holy_SearingLight", text = "Your melee attacks have an 8% chance to lay a Touch of Light. Once every 45 sec.\n\nFjola's hammer leaves the light burning in every wound." }, { name = "Empowered Light", icon = "Interface\\Icons\\Spell_Holy_HolyNova", text = "Your Light Vortex deals 15% more damage.\n\nThe light twin's vortex feeds on her sister's dark." } }, tips = {}, visualKit = 154, soundTransform = 16279, soundDeath = 16275, flies = true, wave = 4, instance = "Trial of the Crusader", expansion = 2, order = 552, box = { -1.27, 0.00, 4.55 }, voices = { { 16272, 10.7, true, "In the name of our dark master. For the Lich King. You. Will. Die." }, { 16279, 3.5, true, "Let the light consume you!" }, { 16278, 4.0, true, "Let the dark consume you!" }, { 16274, 2.3, true, "CHAOS!" }, { 16276, 5.5, true, "You have been measured and found wanting." }, { 16273, 2.9, true, "You are finished!" }, { 16275, 4.1, true, "The Scourge cannot be stopped..." } }, title = "Twin Val'kyr of Light" },
    { id = "eydis_darkbane", entry = 34496, name = "Eydis Darkbane", label = "Eydis Darkbane", level = 83, display = 29267, height = 9.6, span = 11.7, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Spell_Shadow_Shadesofdarkness", profile = "bruiser", kit = { 66058, 66069, 67282, 65828, 38589 }, passives = {}, talentInfo = { { name = "Twin Val'kyr of Darkness", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your Shadow damage is increased by 10%." }, { name = "Dark Essence", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Your Shadow resistance is increased by 60." }, { name = "Dark Vigour", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 8%." }, { name = "Shadow of the Val'kyr", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Let the Dark Consume You", icon = "Interface\\Icons\\Spell_Shadow_PainSpike", text = "Your melee attacks have an 8% chance to add a Twin Spike. Once every 20 sec.\n\nEydis's blade leaves the dark behind in every wound." }, { name = "Dark Pact", icon = "Interface\\Icons\\Spell_Shadow_DarkRitual", text = "Reduces the cooldown of Twin's Pact by 20 sec.\n\nThe dark twin calls on the pact sooner than her sister ever would." } }, tips = {}, visualKit = 7775, soundTransform = 16278, soundDeath = 16275, flies = true, wave = 4, instance = "Trial of the Crusader", expansion = 2, order = 551, box = { -1.27, 0.00, 4.55 }, voices = { { 16272, 10.7, true, "In the name of our dark master. For the Lich King. You. Will. Die." }, { 16279, 3.5, true, "Let the light consume you!" }, { 16278, 4.0, true, "Let the dark consume you!" }, { 16274, 2.3, true, "CHAOS!" }, { 16276, 5.5, true, "You have been measured and found wanting." }, { 16273, 2.9, true, "You are finished!" }, { 16275, 4.1, true, "The Scourge cannot be stopped..." } }, title = "Twin Val'kyr of Darkness" },
    { id = "steelbreaker", entry = 32867, name = "Steelbreaker", label = "Steelbreaker", level = 83, display = 28344, height = 20.8, span = 20.8, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_TheIronCouncil_01", profile = "bruiser", kit = { 61903, 61911, 63525, 37548 }, passives = {}, talentInfo = { { name = "Steelbreaker", icon = "Interface\\Icons\\INV_Misc_Gear_01", text = "Your armor is increased by 25%." }, { name = "Iron Giant", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 10%." }, { name = "Electrical Charge", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 8%." }, { name = "Fusion", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "High Voltage", icon = "Interface\\Icons\\Spell_Nature_LightningOverload", text = "When you are struck, you have a 10% chance to release a High Voltage pulse. Once every 20 sec.\n\nSteelbreaker's plating crackles; strike it and the charge leaps out." }, { name = "So Fragile and Weak", icon = "Interface\\Icons\\INV_Gauntlets_04", text = "Your Fusion Punch deals 15% more damage.\n\nSteelbreaker's fused fists hit harder with every charge he carries." } }, tips = {}, visualKit = 282, soundTransform = 15674, soundDeath = 15678, flies = false, wave = 4, instance = "Ulduar", expansion = 2, order = 497, box = { 0.37, 0.40, 10.39 }, voices = { { 15674, 7.1, true, "You will not defeat the Assembly of Iron so easily, invaders!" }, { 15675, 3.5, true, "So fragile and weak!" }, { 15676, 5.3, true, "Flesh... such a hindrance." }, { 15677, 6.4, true, "You seek the secrets of Ulduar? Then take them!" }, { 15678, 6.5, true, "My death only serves to hasten your demise." }, { 15679, 3.2, true, "Impossible..." }, { 15680, 7.2, true, "This meeting of the Assembly of Iron is adjourned!" } }, title = "The Assembly of Iron" },
    { id = "runemaster_molgeim", entry = 32927, name = "Runemaster Molgeim", label = "Runemaster Molgeim", level = 83, display = 28381, height = 0.0, span = 0.0, school = "arcane", pool = "wotlk", icon = "Interface\\Icons\\INV_Misc_Rune_04", profile = "caster", kit = { 62269, 62274, 64874, 261 }, passives = {}, talentInfo = { { name = "Runemaster", icon = "Interface\\Icons\\INV_Misc_Rune_09", text = "Your Shadow damage is increased by 10%." }, { name = "Assembly of Iron", icon = "Interface\\Icons\\INV_Misc_Gear_01", text = "Your armor is increased by 20%." }, { name = "Rune of Power", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your casting speed is increased by 6%." }, { name = "Iron Vrykul", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 8%." }, { name = "Runed Knuckles", icon = "Interface\\Icons\\INV_Gauntlets_04", text = "When you are struck, you have a 10% chance to answer with a Rune Punch. Once every 20 sec.\n\nNothing short of total decimation will suffice, and Molgeim starts with the nearest face." }, { name = "Decipher This!", icon = "Interface\\Icons\\INV_Misc_Rune_05", text = "Increases the radius of Rune of Death by 30%.\n\nThe runemaster writes his death runes larger than any reader can step out of." } }, tips = { [261] = "Carve a rune of summoning; two storm elementals rise from it to fight for you for 20 sec." }, visualKit = 1005, soundTransform = 15657, soundDeath = 15662, flies = false, wave = 4, instance = "Ulduar", expansion = 2, order = 496, summons = { [261] = true }, box = { 0.00, 0.00, 0.00 }, voices = { { 15657, 4.9, true, "Nothing short of total decimation will suffice." }, { 15658, 4.4, true, "The world suffers yet another insignificant loss." }, { 15659, 3.8, true, "Death is the price of your arrogance." }, { 15660, 2.6, true, "Decipher this!" }, { 15661, 3.7, true, "Face the lightning's surge!" }, { 15662, 6.1, true, "The legacy of storms shall not be undone." }, { 15663, 7.8, true, "What have you gained from my defeat? You are no less doomed, mortals." }, { 15664, 4.9, true, "This meeting of the Assembly of Iron is adjourned!" } }, title = "The Assembly of Iron" },
    { id = "stormcaller_brundir", entry = 32857, name = "Stormcaller Brundir", label = "Stormcaller Brundir", level = 83, display = 28324, height = 4.7, span = 4.7, school = "nature", pool = "wotlk", icon = "Interface\\Icons\\Spell_Nature_LightningOverload", profile = "caster", kit = { 61915, 61879, 28297, 22863 }, passives = {}, talentInfo = { { name = "Stormcaller", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 10%." }, { name = "Iron Dwarf", icon = "Interface\\Icons\\INV_Misc_Gear_01", text = "Your armor is increased by 20%." }, { name = "Supercharge", icon = "Interface\\Icons\\Spell_Nature_LightningOverload", text = "Your casting speed is increased by 6%." }, { name = "Stormshield", icon = "Interface\\Icons\\Spell_Nature_LightningShield", text = "Your Nature resistance is increased by 60." }, { name = "Stormcaller's Reach", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", text = "Your damaging spells have an 8% chance to add a Chain Lightning. Once every 15 sec.\n\nBrundir's tendrils reach for anything his lightning touched." }, { name = "Overload", icon = "Interface\\Icons\\Spell_Shaman_StaticShock", text = "Your Overload deals 15% more damage.\n\nThe stormcaller packs more charge into every ball of lightning." } }, tips = {}, visualKit = 282, soundTransform = 15684, soundDeath = 15689, flies = true, wave = 4, instance = "Ulduar", expansion = 2, order = 498, box = { -0.08, -0.05, 2.29 }, voices = { { 15684, 8.5, true, "Whether the world's greatest gnats or the world's greatest heroes, you are still only mortal." }, { 15685, 1.8, true, "A merciful kill!" }, { 15686, 2.1, true, "HAH!" }, { 15687, 3.8, true, "Stand still and stare into the light!" }, { 15688, 6.3, true, "Let the storm clouds rise and rain down death from above!" }, { 15689, 3.9, true, "The power of the storm lives on." }, { 15690, 4.6, true, "You rush headlong into the maw of madness!" }, { 15691, 3.6, true, "This meeting of the Assembly of Iron is adjourned!" } }, title = "The Assembly of Iron" },
    { id = "alexstrasza", entry = 31333, name = "Alexstrasza the Life-Binder", label = "Alexstrasza", level = 83, display = 27569, height = 43.4, span = 89.7, school = "fire", pool = "leader", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Red", profile = "caster", kit = { 58956, 69293, 58957, 57054, 261, 60003 }, passives = { 9298 }, talentInfo = { { name = "Fire of the Dragon Queen", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "The red flight's fire answers you: your Fire damage is increased by 10%." }, { name = "Gift of the Life-Binder", icon = "Interface\\Icons\\Spell_Nature_Tranquility", text = "All life is yours to mend: your healing is increased by 12%." }, { name = "Aspect's Scales", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Red", text = "Your armor is increased by 20%." }, { name = "Queen of Wyrmrest", icon = "Interface\\Icons\\Achievement_Zone_DragonBlight_09", text = "Your maximum health is increased by 10%." }, { name = "Wrath of the Queen", icon = "Interface\\Icons\\Spell_Fire_Burnout", text = "Your damaging spells have an 8% chance to follow with a Wing Buffet. Once every 30 sec.\n\nThe Life-Binder is gentle until her children are threatened. Then the whole sky beats back." }, { name = "Life-Binder", icon = "Interface\\Icons\\Spell_Holy_Renew", text = "Reduces the cooldown of your Tranquility by 15 sec.\n\nEvery life on Azeroth is hers to mend, and she has never been patient with suffering." } }, tips = { [261] = "Call two Wyrmrest Protectors, dragonspawn of the red flight, to fight at your side for 30 sec." }, visualKit = 286, soundTransform = 14406, soundDeath = 0, flies = true, wave = 4, zone = "Dragonblight", expansion = 2, order = 456, summons = { [261] = true }, box = { -15.56, -0.10, 19.98 }, title = "Queen of the Dragons", visages = { "alexstrasza_visage" }, shape = "Dragon" },
    { id = "alexstrasza_visage", entry = 26917, name = "Alexstrasza the Life-Binder", label = "Alexstrasza", level = 83, display = 28227, height = 0.0, span = 0.0, school = "fire", pool = "leader", icon = "Interface\\Icons\\Spell_Fire_Burnout", profile = "caster", kit = { 64698, 61402, 61362, 60004, 60003, 261 }, passives = {}, talentInfo = { { name = "Mother of All Life", icon = "Interface\\Icons\\Spell_Holy_Renew", text = "Every living thing is your child: your healing is increased by 15%." }, { name = "Kindled Heart", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "Your Fire damage is increased by 8%." }, { name = "Grace of the Queen", icon = "Interface\\Icons\\Spell_Holy_DivineSpirit", text = "Your spells are cast 6% faster." }, { name = "Dragon's Vitality", icon = "Interface\\Icons\\Spell_Holy_WordFortitude", text = "Your maximum health is increased by 8%." }, { name = "Wrath of the Queen", icon = "Interface\\Icons\\Spell_Fire_Burnout", text = "Your damaging spells have an 8% chance to follow with a Blast Wave. Once every 30 sec.\n\nEven in an elf's shape she is the Dragon Queen. When she casts in anger, the air itself catches fire." }, { name = "Kindled Life", icon = "Interface\\Icons\\Spell_Nature_Rejuvenation", text = "Your Renew lasts 3 sec longer.\n\nThe life Alexstrasza kindles does not gutter out quickly. It lingers, as she does." } }, tips = { [261] = "Call two Wyrmrest Protectors, dragonspawn of the red flight, to fight at your side for 30 sec." }, visualKit = 286, soundTransform = 14409, soundDeath = 0, flies = false, wave = 4, zone = "Dragonblight", expansion = 2, order = 457, summons = { [261] = true }, box = { 0.00, 0.00, 0.00 }, title = "Queen of the Dragons", visageOf = "alexstrasza", shape = "High elf" },
    { id = "korialstrasz", entry = 31334, name = "Korialstrasz", label = "Korialstrasz", level = 83, display = 27570, height = 29.3, span = 59.8, school = "fire", pool = "leader", icon = "Interface\\Icons\\Ability_Mount_Drake_Red", profile = "bruiser", kit = { 49110, 19983, 43299, 41572, 36922, 261 }, passives = { 27973 }, talentInfo = { { name = "Wyrmrest Fire", icon = "Interface\\Icons\\Spell_Fire_FlameShock", text = "Your Fire damage is increased by 8%." }, { name = "Red Dragonscale", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your Fire resistance is increased by 60." }, { name = "Consort's Talons", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your chance to critically strike in melee is increased by 5%." }, { name = "Survivor of Grim Batol", icon = "Interface\\Icons\\Spell_Holy_WordFortitude", text = "Your maximum health is increased by 10%." }, { name = "Consort's Fire", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your melee hits have a 10% chance to sear the target with Flame Buffet. Once every 10 sec.\n\nKorialstrasz fights with fire in his claws as much as in his throat." }, { name = "Scorn for the Dragonmaw", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Red", text = "Your Flame Breath deals 15% more damage.\n\nHe remembers every year the Dragonmaw held his queen in chains, and every breath says so." } }, tips = { [261] = "Call two red drakes down from Wyrmrest Temple to fight beside you for 20 sec." }, visualKit = 286, soundTransform = 7274, soundDeath = 0, flies = true, wave = 4, zone = "Dragonblight", expansion = 2, order = 458, summons = { [261] = true }, box = { -10.40, -0.07, 13.51 }, title = "Consort of the Queen", visages = { "krasus" }, shape = "Dragon" },
    { id = "krasus", entry = 27990, name = "Krasus", label = "Krasus", level = 83, display = 24976, height = 4.2, span = 4.2, school = "fire", pool = "leader", icon = "Interface\\Icons\\Spell_Arcane_PortalDalaran", profile = "caster", kit = { 49110, 61909, 16419, 13323, 29211, 261 }, passives = {}, talentInfo = { { name = "Dragonfire in Mortal Hands", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "Your Fire damage is increased by 10%." }, { name = "Council of Six", icon = "Interface\\Icons\\Spell_Arcane_MindMastery", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Kirin Tor Discipline", icon = "Interface\\Icons\\Spell_Arcane_StudentOfMagic", text = "Your spells are cast 6% faster." }, { name = "Hidden Dragonscale", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Damage you take is reduced by 5%." }, { name = "The Dragon Within", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your damaging spells have a 10% chance to loose a gout of Flame Breath at the target. Once every 15 sec.\n\nKrasus wears an elf's face, but now and then the dragon's fire slips through it." }, { name = "Ageless Patience", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "Your Fireball deals 15% more damage.\n\nHe has waited ten thousand years for things to come right. Every Fireball carries a little of that patience." } }, tips = { [261] = "Call a red drake down from Wyrmrest Temple to fight beside you for 20 sec." }, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Dragonblight", expansion = 2, order = 459, summons = { [261] = true }, charModel = true, box = { -0.26, -0.04, 2.11 }, title = "Consort of the Queen", visageOf = "korialstrasz", shape = "High elf" },
    { id = "kalec", entry = 24891, name = "Kalecgos", label = "Kalec", level = 73, display = 23350, height = 4.0, span = 4.0, school = "arcane", pool = "tbc", icon = "Interface\\Icons\\Spell_Arcane_Blink", profile = "caster", kit = { 45026, 45027, 58456, 37132, 15530, 17741 }, passives = {}, talentInfo = { { name = "Spellweaver's Might", icon = "Interface\\Icons\\Spell_Arcane_ArcanePotency", text = "Your Arcane damage is increased by 10%." }, { name = "Frost of the Blue Flight", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 6%." }, { name = "Swordsman of the Sunwell", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Will Against the Corruptor", icon = "Interface\\Icons\\Spell_Arcane_PrismaticCloak", text = "Damage you take is reduced by 5%." }, { name = "Hurry", icon = "Interface\\Icons\\Spell_Arcane_StarFire", text = "Your damaging spells have a 10% chance to add an Arcane Shock. Once every 15 sec.\n\nHurry! There is not much of me left! Kalec fights twice as fast in the spectral realm." }, { name = "Forever in Your Debt", icon = "Interface\\Icons\\Spell_Holy_DivineSpirit", text = "Reduces the cooldown of Revitalize by 10 sec.\n\nI am forever in your debt. Kalec gives back what his allies spend on him." } }, tips = {}, visualKit = 1005, soundTransform = 12439, soundDeath = 0, flies = false, wave = 4, instance = "The Sunwell", expansion = 1, order = 419, box = { -0.24, -0.01, 2.00 }, voices = { { 12428, 7.0, true, "I need... your help! Cannot... resist him much longer!" }, { 12429, 5.0, true, "Agghh!! Help me before I lose my mind!" }, { 12430, 3.9, true, "Hurry! There is not much of me left!" }, { 12439, 8.1, true, "Madrigosa deserved a far better fate. You did what had to be done, but this battle is far from over!" } }, title = "Ambassador of the Blue Dragonflight", visageOf = "kalecgos", shape = "Half-elf" },
    { id = "lady_katrana_prestor", entry = 1749, name = "Lady Katrana Prestor", label = "Lady Katrana Prestor", level = 62, display = 8769, height = 1.9, span = 1.9, school = "shadow", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Shadow_Charm", profile = "caster", kit = { 32860, 17146, 37531, 12098, 18431, 22666 }, passives = {}, talentInfo = { { name = "Whispers at Court", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 10%." }, { name = "Silver Tongue", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "Your chance to land a critical strike with spells is increased by 5%." }, { name = "Daughter of Deathwing", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", text = "Your maximum health is increased by 10%." }, { name = "Court Intrigue", icon = "Interface\\Icons\\Spell_Shadow_MindSteal", text = "Increases your casting speed by 5%." }, { name = "Terror of the Broodmother", icon = "Interface\\Icons\\Spell_Shadow_PsychicScream", text = "Reduces the cooldown of your Bellowing Roar by 10 sec.\n\nKings and raid leaders alike learned it too late: when the Broodmother wants you gone, you run." }, { name = "Poisoned Counsel", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your damaging spells have a 10% chance to whisper a Shadow Word: Pain onto the target. Once every 15 sec.\n\nRun along, little mortal. Lady Prestor's advice always sounds sweet, and it always leaves a wound." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Onyxia's Lair", expansion = 0, order = 318, charModel = true, box = { -0.11, 0.01, 0.96 }, title = "Royal Advisor of Stormwind", visageOf = "onyxia", shape = "Human" },
    { id = "lord_victor_nefarius", entry = 10162, name = "Lord Victor Nefarius", label = "Lord Victor Nefarius", level = 63, display = 9472, height = 3.2, span = 3.2, school = "shadow", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Shadow_Possession", profile = "caster", kit = { 24668, 20741, 22666, 22678, 22687, 29211, 261 }, passives = {}, talentInfo = { { name = "Shadow of Blackrock", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 10%." }, { name = "Deathwing's Heir", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", text = "Your maximum health is increased by 10%." }, { name = "Lord Victor's Guile", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "Your chance to land a critical strike with spells is increased by 5%." }, { name = "Patron of the Dark Horde", icon = "Interface\\Icons\\Spell_Shadow_Possession", text = "Your Shadow spells cost 8% less." }, { name = "Bolts of the Black Flight", icon = "Interface\\Icons\\Spell_Shadow_GatherShadows", text = "Your damaging spells have a 10% chance to hurl a Shadow Bolt at the target as well. Once every 20 sec.\n\nMan or dragon, Deathwing's son never casts one spell of shadow where two will do." }, { name = "Master of the Games", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordDominate", text = "Reduces the cooldown of your Shadowblink by 5 sec.\n\nDo not force my hand, children. Lord Victor is never where his guests expect him to be." } }, tips = { [261] = "Call on the brood of Blackwing Lair: two Chromatic Drakonids answer and fight at your side for 20 sec." }, visualKit = 7775, soundTransform = 8280, soundDeath = 0, flies = false, wave = 4, instance = "Blackwing Lair", expansion = 0, order = 294, summons = { [261] = true }, charModel = true, box = { -0.16, -0.01, 1.60 }, voices = { { 8280, 4.3, true, "Let the games begin!" } }, title = "Lord of Blackrock", visageOf = "nefarian", shape = "Human" },
    { id = "ysera", entry = 27789, name = "Ysera", label = "Ysera", level = 83, display = 24808, height = 51.3, span = 104.6, school = "nature", pool = "leader", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Green", profile = "caster", kit = { 24839, 20669, 24819, 20664, 15847, 13049 }, passives = { 9361 }, talentInfo = { { name = "Breath of the Dream", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 10%." }, { name = "The Dreamer's Grace", icon = "Interface\\Icons\\Spell_Nature_Rejuvenation", text = "Your healing is increased by 10%." }, { name = "Ward of the Emerald Dream", icon = "Interface\\Icons\\Spell_Nature_ResistNature", text = "Your Nature resistance is increased by 50." }, { name = "Scales of the Green Flight", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Green", text = "Your armor is increased by 20%." }, { name = "Storm of the Dream", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", text = "Your damaging spells have a 10% chance to loose a Lightning Wave at the target. Once every 12 sec.\n\nThe Dream's storms answer the Dreamer, arcing from foe to foe as they did for her flight of old." }, { name = "Endless Dream", icon = "Interface\\Icons\\Spell_Nature_Sleep", text = "Your Rejuvenation lasts 3 sec longer.\n\nIn the Emerald Dream nothing truly ends. Ysera's renewal simply forgets to stop." } }, tips = {}, visualKit = 282, soundTransform = 7274, soundDeath = 0, flies = true, wave = 4, zone = "Dragonblight", expansion = 2, order = 460, summons = { [13049] = true }, box = { -18.19, -0.12, 23.64 }, title = "The Dreamer", visages = { "ysera_visage" }, shape = "Dragon" },
    { id = "ysera_visage", entry = 33495, name = "Ysera", label = "Ysera", level = 83, display = 28640, height = 3.4, span = 3.4, school = "nature", pool = "leader", icon = "Interface\\Icons\\Ability_Druid_Dreamstate", profile = "caster", kit = { 20669, 63272, 63242, 261, 29210 }, passives = {}, talentInfo = { { name = "Tranquil Dreams", icon = "Interface\\Icons\\Spell_Nature_Tranquility", text = "Your healing is increased by 12%." }, { name = "Dreamweaver", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 8%." }, { name = "Starlit Vision", icon = "Interface\\Icons\\Spell_Nature_Starfall", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Dreamwalker's Step", icon = "Interface\\Icons\\Ability_Druid_Dreamstate", text = "Your movement speed is increased by 8%." }, { name = "Walker of the Dream", icon = "Interface\\Icons\\Spell_Nature_Sleep", text = "Reduces the cooldown of your Dream Step by 5 sec.\n\nYsera's eyes are closed to the waking world. She walks it the way a dreamer does, a step at a time." }, { name = "Emerald Reverie", icon = "Interface\\Icons\\Ability_Druid_Nourish", text = "Reduces the mana cost of your Nourish by 20%.\n\nThe Dream gives freely to those who sleep in it, and its Aspect gives as freely as it does." } }, tips = { [261] = "Call two wisps of the Emerald Dream to your side for 20 sec." }, visualKit = 282, soundTransform = 15702, soundDeath = 0, flies = false, wave = 4, zone = "Dragonblight", expansion = 2, order = 461, summons = { [261] = true }, charModel = true, box = { -0.23, 0.15, 1.70 }, voices = { { 15702, 3.5, false, "That terrible glow... should that be?" } }, title = "The Dreamer", visageOf = "ysera", shape = "Night elf" },
    { id = "chromie", entry = 27856, name = "Chromie", label = "Chromie", level = 80, display = 24877, height = 1.2, span = 1.2, school = "arcane", pool = "leader", icon = "Interface\\Icons\\Spell_Holy_BorrowedTime", profile = "caster", kit = { 60076, 52657, 38539, 31467, 52737, 52636, 38592 }, passives = {}, talentInfo = { { name = "Timeways Mastery", icon = "Interface\\Icons\\Spell_Arcane_Arcane03", text = "Your Arcane damage is increased by 10%." }, { name = "Borrowed Time", icon = "Interface\\Icons\\Spell_Holy_BorrowedTime", text = "Your spells are cast 8% faster." }, { name = "Out of Sync", icon = "Interface\\Icons\\Spell_Nature_TimeStop", text = "Blows land a moment after you have left: your chance to dodge is increased by 5%." }, { name = "Keeper of the Hourglass", icon = "Interface\\Icons\\Spell_Arcane_StudentOfMagic", text = "Your Arcane spells cost 8% less." }, { name = "Echo of the Timeways", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", text = "Your damaging spells have a 10% chance to strike again a moment later as a Time Shock. Once every 15 sec.\n\nWhat Chronormu has done once, she can always do again. The timeways remember." }, { name = "Right on Time", icon = "Interface\\Icons\\Spell_Arcane_Blink", text = "Reduces the cooldown of your Time Step by 5 sec.\n\nChromie is never late. She arrives precisely when she meant to, which is usually a little early." } }, tips = {}, visualKit = 1005, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Dragonblight", expansion = 2, order = 455, charModel = true, box = { -0.13, -0.00, 0.57 }, title = "Ambassador of the Bronze Dragonflight", visageOf = "chromie_dragon", shape = "Gnome" },
    { id = "chromie_dragon", entry = 30997, name = "Chromie", label = "Chromie", level = 80, display = 27568, height = 11.7, span = 23.9, school = "arcane", pool = "leader", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Bronze", profile = "caster", kit = { 31914, 49840, 58848, 52766, 31475, 52636 }, passives = { 13605 }, talentInfo = { { name = "Sands of Time", icon = "Interface\\Icons\\Spell_Arcane_Arcane03", text = "Your Arcane damage is increased by 8%." }, { name = "Bronze Dragonscale", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Bronze", text = "Your armor is increased by 20%." }, { name = "Timeless", icon = "Interface\\Icons\\Spell_Holy_BorrowedTime", text = "Your spells are cast 6% faster." }, { name = "Brood of Nozdormu", icon = "Interface\\Icons\\Spell_Holy_WordFortitude", text = "Your maximum health is increased by 8%." }, { name = "Echo of the Timeways", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", text = "Your damaging spells have a 10% chance to strike again a moment later as a Shock Lance. Once every 15 sec.\n\nWhat Chronormu has done once, she can always do again. The timeways remember." }, { name = "Guardian of the Hour", icon = "Interface\\Icons\\Spell_Nature_TimeStop", text = "Reduces the cooldown of your Time Stop by 5 sec.\n\nA bronze dragon does not stop time. She simply declines to let it go on, a little more often than most." } }, tips = {}, visualKit = 1005, soundTransform = 7274, soundDeath = 0, flies = true, wave = 4, instance = "The Culling of Stratholme", expansion = 2, order = 506, box = { -4.16, -0.03, 5.40 }, title = "Chronormu of the Bronze Dragonflight", visages = { "chromie" }, shape = "Dragon" },
    { id = "eranikus_tyrant", entry = 15491, name = "Eranikus, Tyrant of the Dream", label = "Eranikus", level = 63, display = 15474, height = 29.3, span = 59.8, school = "nature", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Green", profile = "caster", kit = { 24839, 9591, 24818, 22878, 12890, 15847, 261 }, passives = {}, talentInfo = { { name = "Acid of the Nightmare", icon = "Interface\\Icons\\Spell_Nature_NullifyDisease", text = "Your breath is steeped in the Nightmare: your Nature damage is increased by 10%." }, { name = "Shadow of the Nightmare", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 6%." }, { name = "Twisted Dragonscale", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Your armor is increased by 20%." }, { name = "Lord of the Nightmare", icon = "Interface\\Icons\\Spell_Nature_Sleep", text = "Your spells are cast 6% faster." }, { name = "The Nightmare's Grip", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "Your damaging spells have an 8% chance to spit acid at the target. Once every 15 sec.\n\nThe Nightmare holds him fast. Where Elune's light would one day follow his hand, only acid falls for now." }, { name = "Tyrant's Dominion", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordDominate", text = "Increases the damage of your Acid Breath by 15%.\n\nYsera's consort once watched over the dreamers. Now the Nightmare's acid runs in his breath, and it runs hot." } }, tips = { [261] = "Call two Nightmare Phantasms out of the Dream to fight at your side for 20 sec." }, visualKit = 282, soundTransform = 7274, soundDeath = 0, flies = true, wave = 4, zone = "Moonglade", expansion = 0, order = 287, summons = { [261] = true }, box = { -10.40, -0.07, 13.51 }, view = { -34.4887, 0.0000, 6.3360 }, title = "Tyrant of the Dream", visages = { "eranikus_redeemed" }, shape = "Dragon" },
    { id = "eranikus_redeemed", entry = 15628, name = "Eranikus the Redeemed", label = "Eranikus", level = 63, display = 6984, height = 2.6, span = 2.6, school = "nature", pool = "leader", icon = "Interface\\Icons\\Ability_Druid_Dreamstate", profile = "caster", kit = { 20698, 21668, 20699, 20989, 20665, 17201, 25817 }, passives = {}, talentInfo = { { name = "Touch of Elune", icon = "Interface\\Icons\\Spell_Holy_ElunesGrace", text = "Elune smiles upon you once more: healing you do is increased by 10%." }, { name = "Starlight of the Dream", icon = "Interface\\Icons\\Spell_Arcane_StarFire", text = "Your Arcane damage is increased by 8%." }, { name = "Consort of Ysera", icon = "Interface\\Icons\\Spell_Nature_Tranquility", text = "Your Intellect is increased by 8%." }, { name = "Dreamwalker", icon = "Interface\\Icons\\Ability_Druid_Dreamstate", text = "Your spells are cast 6% faster." }, { name = "Tyrande's Prayer", icon = "Interface\\Icons\\Spell_Nature_StarFall", text = "Your damaging spells have an 8% chance to call Starfire down on the target. Once every 15 sec.\n\nTyrande prayed to Elune and the Nightmare let him go. The goddess's light still follows where he points." }, { name = "Waking from the Nightmare", icon = "Interface\\Icons\\Spell_Nature_Rejuvenation", text = "Reduces the cooldown of Tranquility by 30 sec.\n\nMalfurion, Cenarius, Ysera... they still fight. They need me. The redeemed consort hurries to heal the Dream." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Moonglade", expansion = 0, order = 286, charModel = true, box = { -0.20, 0.01, 1.30 }, title = "Consort of Ysera", visageOf = "eranikus_tyrant", shape = "Night elf" },
    { id = "vaelastrasz_red", entry = 10340, name = "Vaelastrasz the Red", label = "Vaelastrasz", level = 62, display = 9912, height = 3.2, span = 3.2, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Fire_SealOfFire", profile = "caster", kit = { 16319, 25058, 11974, 15242, 16144, 16419, 16396 }, passives = {}, talentInfo = { { name = "Flame of the Red Flight", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire damage is increased by 10%." }, { name = "Heart of the Red", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Red", text = "Your maximum health is increased by 8%." }, { name = "Bones I Shall Mend", icon = "Interface\\Icons\\Spell_Holy_Renew", text = "Your healing is increased by 10%." }, { name = "Wyrmkin Lore", icon = "Interface\\Icons\\Spell_Fire_SealOfFire", text = "Your Fire spells cost 8% less." }, { name = "Be Renewed, Heroes", icon = "Interface\\Icons\\Spell_Holy_HolyNova", text = "Reduces the cooldown of your Touch of Vaelastrasz by 10 sec.\n\nAll is not lost! Alexstrasza's consort mends the wounds of those who fight at his side." }, { name = "Ember of the Consort", icon = "Interface\\Icons\\Spell_Fire_Fireball", text = "Your damaging spells have a 10% chance to follow up with a Fire Blast. Once every 15 sec.\n\nBeneath the mortal guise the red dragon still burns, and now and then the fire slips out." } }, tips = { [16319] = "Pour the life of the red flight into every ally near you, healing each for 5000." }, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Blackwing Lair", expansion = 0, order = 288, charModel = true, box = { -0.16, -0.01, 1.60 }, title = "Consort of Alexstrasza", visageOf = "vaelastrasz", shape = "Human" },
    { id = "keristrasza_visage", entry = 26206, name = "Keristrasza", label = "Keristrasza", level = 80, display = 23686, height = 1.9, span = 1.9, school = "fire", pool = "wotlk", icon = "Interface\\Icons\\Spell_Fire_Fireball02", profile = "caster", kit = { 38641, 16102, 17145, 14145, 23895, 50997 }, passives = {}, talentInfo = { { name = "Fire of the Dragonqueen", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire damage is increased by 8%." }, { name = "Nexus-Tempered", icon = "Interface\\Icons\\Spell_Frost_FrostArmor02", text = "Your Frost resistance is increased by 50." }, { name = "Gift of the Life-Binder", icon = "Interface\\Icons\\Spell_Holy_Heal", text = "Your healing is increased by 8%." }, { name = "Unbroken Will", icon = "Interface\\Icons\\Spell_Arcane_MindMastery", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Brood of Alexstrasza", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "Your damaging spells have a 10% chance to add a Fire Blast. Once every 15 sec.\n\nFree of the Nexus, Keristrasza's fire comes quicker than she can call it." }, { name = "Wave of Crimson", icon = "Interface\\Icons\\Spell_Holy_Excorcism_02", text = "Reduces the cooldown of Blast Wave by 5 sec.\n\nThe red consort answers crowding with fire, again and again." } }, tips = {}, visualKit = 286, soundTransform = 13450, soundDeath = 13454, flies = false, wave = 4, instance = "The Nexus", expansion = 2, order = 448, charModel = true, box = { -0.11, 0.01, 0.96 }, title = "Brood of Alexstrasza", visageOf = "keristrasza", shape = "Human" },
    { id = "saragosa", entry = 27608, name = "Saragosa", label = "Saragosa", level = 73, display = 24140, height = 14.7, span = 29.9, school = "frost", pool = "wotlk", icon = "Interface\\Icons\\Ability_Mount_Drake_Blue", profile = "caster", kit = { 50505, 50804, 65260, 15847 }, passives = {}, talentInfo = { { name = "Breath of Coldarra", icon = "Interface\\Icons\\Spell_Frost_ChillingBlast", text = "Your Frost damage is increased by 8%." }, { name = "Spell-Weaver's Consort", icon = "Interface\\Icons\\Spell_Arcane_ArcanePotency", text = "Your Arcane damage is increased by 8%." }, { name = "Blue Dragonscale", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Blue", text = "Your armor is increased by 20%." }, { name = "Fury of the Nexus", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", text = "Your casting speed is increased by 6%." }, { name = "Guardian of the Ley Lines", icon = "Interface\\Icons\\INV_Misc_MonsterTail_03", text = "When you are struck, you have a 10% chance to Tail Sweep the enemies behind you. Once every 20 sec.\n\nMalygos's consort guards Coldarra from every side; nothing creeps up on her." }, { name = "Consort of Malygos", icon = "Interface\\Icons\\Spell_Frost_FreezingBreath", text = "Reduces the cooldown of Frost Breath by 4 sec.\n\nSaragosa breathes the Nexus's cold as freely as the Spell-Weaver himself." } }, tips = {}, visualKit = 4991, soundTransform = 7274, soundDeath = 0, flies = true, wave = 4, zone = "Dragonblight", expansion = 2, order = 454, as = 26231, box = { -5.20, -0.03, 6.75 }, title = "Consort of Malygos", visages = { "saragosa_visage" }, shape = "Dragon" },
    { id = "saragosa_visage", entry = 26232, name = "Saragosa", label = "Saragosa", level = 73, display = 23713, height = 3.9, span = 3.9, school = "frost", pool = "wotlk", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", profile = "caster", kit = { 51779, 56969, 56776, 15063, 56778 }, passives = {}, talentInfo = { { name = "Frostfire Mastery", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 8%." }, { name = "Arcane Heritage", icon = "Interface\\Icons\\Spell_Arcane_ArcanePotency", text = "Your Arcane damage is increased by 8%." }, { name = "Mana of the Nexus", icon = "Interface\\Icons\\Spell_Frost_ManaRecharge", text = "The mana cost of your Arcane spells is reduced by 8%." }, { name = "Mortal Disguise", icon = "Interface\\Icons\\Spell_Arcane_PrismaticCloak", text = "Damage you take is reduced by 5%." }, { name = "Cold Welcome", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "When you are struck, you have a 10% chance to cast Frost Nova. Once every 30 sec.\n\nSaragosa's mortal guise is thin; strike it and Coldarra's frost answers." }, { name = "Arcane Mastery of the Blue", icon = "Interface\\Icons\\Spell_Arcane_Blast", text = "Your Arcane Shock deals 15% more damage.\n\nEven disguised, the consort spins arcana the way only the blue flight can." } }, tips = {}, visualKit = 4991, soundTransform = 7274, soundDeath = 0, flies = false, wave = 4, zone = "Dragonblight", expansion = 2, order = 451, charModel = true, box = { -0.21, 0.01, 1.92 }, title = "Consort of Malygos", visageOf = "saragosa", shape = "Human" },
    { id = "anachronos", entry = 15192, name = "Anachronos", label = "Anachronos", level = 63, display = 2719, height = 14.7, span = 29.9, school = "arcane", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Bronze", profile = "caster", kit = { 20717, 31743, 58848, 18144, 15847 }, passives = {}, talentInfo = { { name = "Sands of Time", icon = "Interface\\Icons\\Spell_Nature_TimeStop", text = "Your Arcane damage is increased by 10%." }, { name = "Bronze Dragonscale", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Bronze", text = "Your armor is increased by 20%." }, { name = "Walker of the Timeways", icon = "Interface\\Icons\\Spell_Holy_BorrowedTime", text = "Your spells are cast 8% faster." }, { name = "Ancient of the Bronze Flight", icon = "Interface\\Icons\\INV_Misc_PocketWatch_02", text = "Your maximum health is increased by 8%." }, { name = "It Is Not My Time", icon = "Interface\\Icons\\INV_Misc_PocketWatch_01", text = "When you are struck, you have an 8% chance to breathe the sands of time over the enemies before you. Once every 30 sec.\n\nA terrible and costly mistake you have made. It is not my time, mortals." }, { name = "Sands of Nozdormu", icon = "Interface\\Icons\\INV_Misc_Dust_02", text = "Your Sand Breath deals 15% more damage.\n\nAnachronos keeps the Caverns of Time for Nozdormu, and his breath carries the weight of every age he has watched pass." } }, tips = {}, visualKit = 1005, soundTransform = 7274, soundDeath = 0, flies = true, wave = 4, zone = "Tanaris", expansion = 0, order = 134, box = { -5.20, -0.03, 6.75 }, view = { -18.8864, -0.1914, 1.5161 }, title = "Warden of the Caverns of Time", visages = { "anachronos_visage" }, shape = "Dragon" },
    { id = "anachronos_visage", entry = 15381, name = "Anachronos the Ancient", label = "Anachronos", level = 63, display = 15415, height = 2.1, span = 2.1, school = "arcane", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Holy_BorrowedTime", profile = "caster", kit = { 31743, 58848, 11436, 15253, 17741 }, passives = {}, talentInfo = { { name = "Keeper of the Sands", icon = "Interface\\Icons\\Spell_Nature_TimeStop", text = "Your Arcane damage is increased by 10%." }, { name = "Timeless Patience", icon = "Interface\\Icons\\Spell_Holy_BorrowedTime", text = "Your spells are cast 8% faster." }, { name = "Glyphs of Warding", icon = "Interface\\Icons\\Spell_Arcane_Rune", text = "Damage you take is reduced by 5%." }, { name = "Ancient Insight", icon = "Interface\\Icons\\Spell_Arcane_MindMastery", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "It Is Not My Time", icon = "Interface\\Icons\\INV_Misc_PocketWatch_01", text = "When you are struck, you have an 8% chance to Slow your attacker. Once every 30 sec.\n\nA terrible and costly mistake you have made. It is not my time, mortals." }, { name = "Warden of the Scarab Wall", icon = "Interface\\Icons\\Spell_Nature_StarFall", text = "Increases the damage of your Arcane Missile by 15%.\n\nAt the Scarab Wall Anachronos held two whole armies still while the barrier rose; a single foe is no trouble at all." } }, tips = {}, visualKit = 1005, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Tanaris", expansion = 0, order = 135, charModel = true, box = { -0.10, -0.00, 1.06 }, title = "Warden of the Scarab Wall", visageOf = "anachronos", shape = "Human" },
    { id = "caelestrasz", entry = 15412, name = "Caelestrasz Dragon Form", label = "Caelestrasz", level = 60, display = 15414, height = 14.7, span = 29.9, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\Ability_Mount_Drake_Red", profile = "bruiser", kit = { 16396, 19983, 36922, 49241, 69293, 15847 }, passives = {}, talentInfo = { { name = "Fire of the Dragonqueen", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Red", text = "Your Fire damage is increased by 10%." }, { name = "Red Dragonscale", icon = "Interface\\Icons\\INV_Misc_MonsterScales_15", text = "Your armor is increased by 20%." }, { name = "Talons of the Red Flight", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your chance to critically strike in melee is increased by 5%." }, { name = "Defender of the Scarab Wall", icon = "Interface\\Icons\\Spell_Fire_MoltenBlood", text = "Your maximum health is increased by 8%." }, { name = "Resolve of Alexstrasza", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your melee attacks have an 8% chance to blast the area around your target with Ruby Blast. Once every 15 sec.\n\nAlexstrasza grant me the resolve to drive our enemies back! Her fire answers every blow he strikes in her name." }, { name = "Drive Them Back", icon = "Interface\\Icons\\Ability_Mount_Drake_Red", text = "Reduces the cooldown of Wing Buffet by 5 sec.\n\nAt the gates of Ahn'Qiraj the red flight held the line; every beat of Caelestrasz's wings pushed the swarm back a little farther." } }, tips = {}, visualKit = 286, soundTransform = 7274, soundDeath = 0, flies = true, wave = 4, instance = "Ahn'Qiraj Temple", expansion = 0, order = 259, box = { -5.20, -0.03, 6.75 }, view = { -18.8864, 0.3189, 1.5799 }, title = "Champion of the Red Flight", visages = { "caelestrasz_visage" }, shape = "Dragon" },
    { id = "caelestrasz_visage", entry = 15379, name = "Caelestrasz", label = "Caelestrasz", level = 63, display = 15419, height = 2.6, span = 2.6, school = "fire", pool = "classic_raid", icon = "Interface\\Icons\\Spell_Fire_Incinerate", profile = "caster", kit = { 17195, 35250, 17273, 15091, 17843, 35265 }, passives = {}, talentInfo = { { name = "Dragonfire in Mortal Veins", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Your Fire damage is increased by 10%." }, { name = "Envoy's Composure", icon = "Interface\\Icons\\Spell_Arcane_MindMastery", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Kaldorei Guise", icon = "Interface\\Icons\\Spell_Nature_Invisibilty", text = "Increases your casting speed by 5%." }, { name = "Ember Focus", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "Your Fire spells cost 8% less." }, { name = "Resolve of Alexstrasza", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your damaging spells have an 8% chance to loose a Blast Wave around you. Once every 20 sec.\n\nAlexstrasza grant me the resolve to drive our enemies back! Her fire answers every blow he strikes in her name." }, { name = "Remember the Sacrifices", icon = "Interface\\Icons\\Spell_Holy_FlashHeal", text = "Your Flash Heal costs 25% less.\n\nDo not forget the sacrifices made on this day, night elf. Caelestrasz spends his fire freely, and his mending more freely still." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Ahn'Qiraj Temple", expansion = 0, order = 264, charModel = true, box = { -0.20, 0.01, 1.30 }, title = "Envoy of the Dragonqueen", visageOf = "caelestrasz", shape = "Night elf" },
    { id = "tenebron", entry = 30452, name = "Tenebron", label = "Tenebron", level = 83, display = 27082, height = 18.1, span = 30.6, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Ability_Mount_Drake_Twilight", profile = "bruiser", kit = { 57570, 60708, 57728, 261 }, passives = {}, talentInfo = { { name = "Warden of the Eggs", icon = "Interface\\Icons\\INV_Egg_01", text = "Your maximum health is increased by 10%." }, { name = "Twilight Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your armor is increased by 20%." }, { name = "Drake's Fury", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "Twilight Shadow", icon = "Interface\\Icons\\Spell_Shadow_Twilight", text = "Your Shadow damage is increased by 8%." }, { name = "Power of Tenebron", icon = "Interface\\Icons\\spell_fire_twilightflamebreath", text = "Your melee attacks have an 8% chance to add a Shadow Breath. Once every 15 sec.\n\nTenebron's twilight fire comes up whenever he bites." }, { name = "Brood Guardian", icon = "Interface\\Icons\\INV_Misc_MonsterTail_03", text = "Reduces the cooldown of Hatch the Eggs by 20 sec.\n\nThe eggs' warden always has another clutch close to hatching." } }, tips = { [261] = "Hatch two Twilight Whelps from the eggs you guard to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 14122, soundDeath = 14129, flies = true, wave = 4, instance = "The Obsidian Sanctum", expansion = 2, order = 542, summons = { [261] = true }, box = { -2.78, -0.00, 8.22 }, voices = { { 14122, 9.5, true, "You have no place here! Your place... is among the departed!" }, { 14123, 2.7, true, "No contest." }, { 14124, 4.5, true, "Typical. Just as I was having fun..." }, { 14129, 6.4, true, "I should not... have held back..." }, { 14125, 3.6, true, "To darkness I condemn you." }, { 14128, 9.9, true, "It is amusing to watch you struggle. Very well, witness how it is done!" }, { 14126, 7.6, true, "Arrogant little creatures, to challenge powers you do not yet understand." }, { 14127, 7.7, true, "I am no mere dragon. You will find that I am much, much more." } }, title = "Warden of the Twilight Eggs" },
    { id = "shadron", entry = 30451, name = "Shadron", label = "Shadron", level = 83, display = 27421, height = 18.1, span = 30.6, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Spell_Shadow_Twilight", profile = "bruiser", kit = { 67107, 55847, 57757, 261 }, passives = {}, talentInfo = { { name = "Lord of the Twilight Portal", icon = "Interface\\Icons\\Spell_Shadow_Twilight", text = "Your Shadow damage is increased by 10%." }, { name = "Lava-Tempered Hide", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your Fire resistance is increased by 50." }, { name = "Portal Fury", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your attack power is increased by 10%." }, { name = "Twilight Wings", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Your movement speed is increased by 10%." }, { name = "Power of Shadron", icon = "Interface\\Icons\\Spell_Shadow_Shadowfury", text = "Your melee attacks have an 8% chance to tear open a Shadow Fissure. Once every 20 sec.\n\nWherever Shadron bites, the twilight portal leaks through." }, { name = "Portal Fire", icon = "Interface\\Icons\\Spell_Fire_Volcano", text = "Your Rain of Fire lasts 2 sec longer.\n\nThe drake's lava lingers as long as the twilight portal stays open." } }, tips = { [261] = "Call an Acolyte of Shadron out of the twilight to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 14111, soundDeath = 14118, flies = true, wave = 4, instance = "The Obsidian Sanctum", expansion = 2, order = 541, summons = { [261] = true }, box = { -2.78, -0.00, 8.22 }, voices = { { 14111, 4.2, true, "I fear nothing! Least of all you!" }, { 14112, 2.2, true, "You are insignificant." }, { 14113, 3.2, true, "Such mediocre resistance..." }, { 14118, 7.5, true, "We... are superior! How could this... be?" }, { 14114, 2.9, true, "You are easily bested!" }, { 14117, 5.4, true, "I will take pity on you, Sartharion, just this once." }, { 14115, 2.0, true, "Father taught me well." }, { 14116, 2.2, true, "On your knees!" } }, title = "Lord of the Twilight Portal" },
    { id = "vesperon", entry = 30449, name = "Vesperon", label = "Vesperon", level = 83, display = 27039, height = 18.1, span = 30.6, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", profile = "bruiser", kit = { 37275, 56909, 56910, 261 }, passives = {}, talentInfo = { { name = "Tormentor of the Twilight Realm", icon = "Interface\\Icons\\Spell_Shadow_Twilight", text = "Your Shadow damage is increased by 10%." }, { name = "Tormentor's Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your armor is increased by 15%." }, { name = "Tormentor's Fangs", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Twilight Wings", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Your movement speed is increased by 10%." }, { name = "Tormentor's Due", icon = "Interface\\Icons\\Spell_Shadow_CurseOfSargeras", text = "When you are struck, you have a 10% chance to lay Twilight Torment on the attacker. Once every 20 sec.\n\nVesperon torments whoever reaches him with the twilight he carries." }, { name = "Power of Vesperon", icon = "Interface\\Icons\\INV_Misc_MonsterTail_03", text = "Increases the radius of Tail Lash by 30%.\n\nThe drake's tail sweeps wider while the portal is open." } }, tips = { [261] = "Call an Acolyte of Vesperon out of the twilight to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 14133, soundDeath = 14140, flies = true, wave = 4, instance = "The Obsidian Sanctum", expansion = 2, order = 543, summons = { [261] = true }, box = { -2.78, -0.00, 8.22 }, voices = { { 14133, 6.9, true, "You pose no threat, lesser beings! Give me your worst!" }, { 14134, 3.8, true, "The least you could do is put up a fight!" }, { 14135, 3.5, true, "Was that the best you can do?" }, { 14140, 6.2, true, "I still have some... fight... in me-e-e..." }, { 14136, 4.6, true, "I will pick my teeth with your bones!" }, { 14139, 6.7, true, "Father was right about you, Sartharion. You ARE a weakling." }, { 14137, 6.7, true, "Aren't you tricky? I have a few tricks of my own..." }, { 14138, 4.3, true, "Unlike you, I have many talents!" } }, title = "Tormentor of the Twilight Realm" },
    { id = "lethon", entry = 14888, name = "Lethon", label = "Lethon", level = 63, display = 15365, height = 21.7, span = 44.9, school = "shadow", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Green", profile = "caster", kit = { 24811, 12739, 24820, 24585, 24818, 15847 }, passives = {}, talentInfo = { { name = "Shadow of the Nightmare", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 10%." }, { name = "Feast of Souls", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Your maximum health is increased by 8%." }, { name = "Scales of the Corrupted", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Damage you take is reduced by 5%." }, { name = "Waking Nightmare", icon = "Interface\\Icons\\Spell_Nature_Sleep", text = "Your casting speed is increased by 6%." }, { name = "The Endless Whirl", icon = "Interface\\Icons\\Spell_Shadow_Shadowfury", text = "Your damaging spells have a 10% chance to loose a Shadow Bolt Whirl around you. Once every 15 sec.\n\nLethon never stops turning. Bolts of shadow spin off him for the whole fight, whether he aims them or not." }, { name = "Your Wicked Souls", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_3", text = "Reduces the cooldown of Draw Spirit by 15 sec.\n\nYour wicked souls shall feed my power! Each time Lethon bleeds, he tears more spirits loose to feed on." } }, tips = {}, visualKit = 7775, soundTransform = 3525, soundDeath = 3523, flies = true, wave = 4, zone = "The Hinterlands", expansion = 0, order = 120, box = { -7.75, 0.04, 9.80 }, title = "Dragon of Nightmare" },
    { id = "emeriss", entry = 14889, name = "Emeriss", label = "Emeriss", level = 63, display = 15366, height = 20.5, span = 41.8, school = "nature", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Green", profile = "caster", kit = { 24928, 24840, 24818, 15847, 48291, 12098 }, passives = {}, talentInfo = { { name = "Blight of the Nightmare", icon = "Interface\\Icons\\Spell_Nature_NatureTouchDecay", text = "Your Nature damage is increased by 10%." }, { name = "Contagion of the Dream", icon = "Interface\\Icons\\Spell_Holy_HarmUndeadAura", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Rotting Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Damage you take is reduced by 5%." }, { name = "Corrupted Guardian", icon = "Interface\\Icons\\Spell_Nature_EarthBind", text = "Your Intellect is increased by 8%." }, { name = "Hope Is a Disease", icon = "Interface\\Icons\\Spell_Nature_NullifyDisease", text = "Your damaging spells have a 10% chance to infect the target with Volatile Infection. Once every 20 sec.\n\nHope is a disease of the soul, Emeriss says, and she spreads her cure with every spell." }, { name = "Withering Land", icon = "Interface\\Icons\\Spell_Shadow_PlagueCloud", text = "Your Poison Cloud covers 25% more ground.\n\nThis land shall wither and die! Where Emeriss's rot seeps into the earth, it keeps on spreading." } }, tips = {}, visualKit = 282, soundTransform = 3525, soundDeath = 3523, flies = true, wave = 4, zone = "Feralas", expansion = 0, order = 152, box = { -7.28, -0.05, 9.46 }, view = { -23.6560, 0.0000, 4.3560 }, title = "Dragon of Nightmare" },
    { id = "taerar", entry = 14890, name = "Taerar", label = "Taerar", level = 63, display = 15363, height = 20.2, span = 41.9, school = "arcane", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Green", profile = "caster", kit = { 24857, 15124, 22686, 24818, 15847, 24841 }, passives = {}, talentInfo = { { name = "Nightmare Reign", icon = "Interface\\Icons\\Spell_Shadow_DeathPact", text = "Your Arcane damage is increased by 10%." }, { name = "Children of Madness", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Scales of the Dreamer", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Damage you take is reduced by 5%." }, { name = "Fleeting Dream", icon = "Interface\\Icons\\Spell_Nature_Sleep", text = "Your casting speed is increased by 6%." }, { name = "Peace Is a Fleeting Dream", icon = "Interface\\Icons\\Spell_Shadow_PsychicScream", text = "When you are struck, you have a 6% chance to blast your attacker with Arcane Blast, hurling it back. Once every 45 sec.\n\nPeace is but a fleeting dream! Wound Taerar and his madness answers, flinging the brave away from him." }, { name = "Split Mind", icon = "Interface\\Icons\\Spell_Shadow_GatherShadows", text = "Your Arcane Blast deals 15% more damage.\n\nTaerar's mind broke into shades long ago, and every shard of it hurls the same arcane fury." } }, tips = { [24841] = "Split your mind into two Shades of Taerar that fight at your side for 20 sec." }, visualKit = 1005, soundTransform = 3525, soundDeath = 3523, flies = true, wave = 4, zone = "Duskwood", expansion = 0, order = 93, summons = { [24841] = true }, box = { -7.23, 0.04, 9.14 }, view = { -23.7162, 0.0000, 4.3670 }, title = "Dragon of Nightmare" },
    { id = "balnazzar", entry = 10813, name = "Balnazzar", label = "Balnazzar", level = 62, display = 10691, height = 9.1, span = 11.6, school = "shadow", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", profile = "caster", kit = { 17399, 17287, 33678, 13704, 13338, 261 }, passives = {}, talentInfo = { { name = "Might of the Nathrezim", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 10%." }, { name = "Unmasked", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "All damage you deal is increased by 5%." }, { name = "Usurper of the Crusade", icon = "Interface\\Icons\\Spell_Shadow_MindSteal", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Dreadlord's Vigor", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain", text = "Your maximum health is increased by 8%." }, { name = "Nightmare's Grasp", icon = "Interface\\Icons\\Spell_Nature_Sleep", text = "When you are struck, you have an 8% chance to lash out with Shadow Shock. Once every 20 sec.\n\nThe Nathrezim do not fight fair. Strike one, and the shadows strike back." }, { name = "Face of the Nathrezim", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "Increases the damage of Mind Blast by 15%.\n\nWith the mask of Dathrohan cast off, Balnazzar's hatred has nothing left to hold it back." } }, tips = { [261] = "Call two Skeletal Berserkers up from the streets of Stratholme to fight for the Nathrezim for 20 sec." }, visualKit = 7775, soundTransform = 1095, soundDeath = 1094, flies = false, wave = 4, instance = "Stratholme", expansion = 0, order = 200, summons = { [261] = true }, box = { -2.32, -0.13, 4.11 }, title = "Agent of the Burning Legion", visages = { "dathrohan" }, shape = "Dreadlord" },
    { id = "arcanist_doan", entry = 6487, name = "Arcanist Doan", label = "Arcanist Doan", level = 35, display = 5266, height = 2.7, span = 2.7, school = "arcane", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Nature_WispSplode", profile = "caster", kit = { 9487, 9433, 8988, 13323, 9438, 9435 }, passives = {}, talentInfo = { { name = "Keeper of Mysteries", icon = "Interface\\Icons\\Spell_Nature_WispSplode", text = "Your Arcane damage is increased by 10%." }, { name = "Righteous Fire", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "Your Fire damage is increased by 10%." }, { name = "Studies of the Library", icon = "Interface\\Icons\\INV_Misc_Book_06", text = "Your Intellect is increased by 8%." }, { name = "Scarlet Arcana", icon = "Interface\\Icons\\Spell_Holy_Silence", text = "Your Arcane spells and abilities cost 8% less." }, { name = "Burn in Righteous Fire", icon = "Interface\\Icons\\Spell_Fire_SealOfFire", text = "Increases the damage of Detonation by 20%.\n\nBurn in righteous fire! Doan hoards the library's fury inside his bubble, then spends it all at once." }, { name = "Abjurer's Ward", icon = "Interface\\Icons\\Spell_Holy_DivineIntervention", text = "Reduces the cooldown of Arcane Explosion by 3 sec.\n\nYou will not defile these mysteries! The library's wards pulse outward at every step the keeper takes." } }, tips = { [9435] = "Loose the fury gathered in your bubble, dealing 460 Fire damage to every enemy around you." }, visualKit = 1005, soundTransform = 5842, soundDeath = 0, flies = false, wave = 4, instance = "Scarlet Monastery", expansion = 0, order = 102, charModel = true, box = { -0.13, -0.01, 1.33 }, voices = { { 5842, 2.8, true, "You will not defile these mysteries!" }, { 5843, 2.0, true, "Burn in righteous fire!" } }, title = "Keeper of the Monastery Library" },
    { id = "amnennar", entry = 7358, name = "Amnennar the Coldbringer", label = "Amnennar the Coldbringer", level = 37, display = 7971, height = 5.3, span = 5.3, school = "frost", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Frost_FrostNova", profile = "caster", kit = { 13009, 15530, 15531, 8398, 17204 }, passives = { 12556 }, talentInfo = { { name = "Hand of the Lich King", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "The Coldbringer", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Heart of the Coldbringer", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", text = "Your maximum health is increased by 8%." }, { name = "Master of the Downs", icon = "Interface\\Icons\\Spell_Shadow_SummonVoidWalker", text = "Your casting speed is increased by 6%." }, { name = "Grave Chill", icon = "Interface\\Icons\\Spell_Frost_Frostbolt", text = "When you are struck, you have a 10% chance to answer with a Frostbolt. Once every 15 sec.\n\nWhoever lays hands on the Coldbringer feels the grave-cold of the Downs creep into their bones." }, { name = "Wrath of the Coldbringer", icon = "Interface\\Icons\\Spell_Frost_ChainsOfIce", text = "Reduces the cooldown of Amnennar's Wrath by 8 sec.\n\nThe hand of the Lich King sweeps the unworthy from his throne room, and never tires of it." } }, tips = {}, visualKit = 4991, soundTransform = 5825, soundDeath = 5796, flies = false, wave = 4, instance = "Razorfen Downs", expansion = 0, order = 110, summons = { [17204] = true }, box = { 0.07, 0.06, 2.16 }, voices = { { 5825, 3.6, true, "You'll never leave this place alive." }, { 5828, 2.7, true, "To me, my servants!" }, { 5829, 4.1, true, "Come, spirits - attend your master!" }, { 5827, 3.6, true, "I am the hand of the Lich King!" }, { 5826, 2.1, false, "Too easy." } }, title = "Ruler of Razorfen Downs" },
    { id = "baron_silverlaine", entry = 3887, name = "Baron Silverlaine", label = "Baron Silverlaine", level = 20, display = 3222, height = 2.6, span = 2.6, school = "shadow", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Shadow_GatherShadows", profile = "bruiser", kit = { 7068, 15496, 9080, 7074, 7295, 41176 }, passives = {}, talentInfo = { { name = "Accursed Place", icon = "Interface\\Icons\\Spell_Shadow_GatherShadows", text = "Your Shadow damage is increased by 8%." }, { name = "Baron's Blade Work", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your chance to critically strike in melee is increased by 5%." }, { name = "Restless Spirit", icon = "Interface\\Icons\\Spell_Shadow_ImpPhaseShift", text = "Damage you take is reduced by 5%." }, { name = "Lord of the Keep", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", text = "Your maximum health is increased by 8%." }, { name = "Echoes of the Keep", icon = "Interface\\Icons\\Ability_ShockWave", text = "When you are struck, you have an 8% chance to Hamstring your attacker. Once every 30 sec.\n\nStrike the Baron and the keep answers: its murdered dead drag at your legs." }, { name = "Leave This Place", icon = "Interface\\Icons\\Spell_Shadow_NetherCloak", text = "Reduces the cooldown of your Veil of Shadow by 5 sec.\n\nLeave this accursed place at once! The Baron's veil falls again before the last one lifts." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Shadowfang Keep", expansion = 0, order = 43, charModel = true, box = { -0.13, -0.01, 1.28 }, title = "Ghost of Shadowfang Keep" },
    { id = "general_angerforge", entry = 9033, name = "General Angerforge", label = "General Angerforge", level = 55, display = 8756, height = 2.0, span = 2.0, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", profile = "bruiser", kit = { 14099, 20691, 9080, 13730, 22911, 261, 17204 }, passives = { 9128 }, talentInfo = { { name = "Veteran of the Dark Iron", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", text = "All damage you deal is increased by 5%." }, { name = "Military Historian", icon = "Interface\\Icons\\INV_Misc_Book_06", text = "Your chance to critically strike in melee is increased by 5%." }, { name = "Shadowforge Plate", icon = "Interface\\Icons\\INV_Chest_Plate04", text = "Your armor is increased by 10%." }, { name = "Anvilrage Reserves", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your maximum health is increased by 8%." }, { name = "Form Ranks", icon = "Interface\\Icons\\Ability_Rogue_SliceDice", text = "Cleave strikes 1 more target.\n\nHe has read every battle the dwarves ever fought, and knows exactly where the line is thinnest." }, { name = "Lessons of History", icon = "Interface\\Icons\\Ability_ShockWave", text = "Your melee attacks have an 8% chance to Hamstring the target. Once every 12 sec.\n\nA foe who cannot run is a foe who cannot regroup: chapter one of the General's treatise." } }, tips = { [261] = "Sound the call: three Anvilrage Reservists rush in to fight for you for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Blackrock Depths", expansion = 0, order = 163, summons = { [261] = true, [17204] = true }, charModel = true, box = { -0.12, -0.02, 0.99 }, title = "General of the Dark Iron Armies" },
    { id = "lord_incendius", entry = 9017, name = "Lord Incendius", label = "Lord Incendius", level = 53, display = 1204, height = 5.0, span = 5.0, school = "fire", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", profile = "caster", kit = { 13899, 13900, 13880, 26977, 9163 }, passives = {}, talentInfo = { { name = "Will of Ragnaros", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "Your Fire damage is increased by 10%." }, { name = "Reborn in Flame", icon = "Interface\\Icons\\Spell_Fire_LavaSpawn", text = "Damage you take is reduced by 5%." }, { name = "Elemental Lord", icon = "Interface\\Icons\\Spell_Fire_FireBolt", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "Molten Bulk", icon = "Interface\\Icons\\Spell_Fire_Immolation", text = "Your maximum health is increased by 8%." }, { name = "Molten Blood", icon = "Interface\\Icons\\Spell_Fire_FlameShock", text = "When you are struck, you have a 10% chance to hit the attacker with a Magma Splash. Once every 15 sec.\n\nCut the guardian of the Black Anvil and he bleeds magma." }, { name = "Heat of the Black Anvil", icon = "Interface\\Icons\\Spell_Fire_Volcano", text = "Increases the damage of Fire Storm by 15%.\n\nBy the will of Ragnaros, the forge-fire beneath Shadowforge City burns wider each time he calls it." } }, tips = {}, visualKit = 286, soundTransform = 1288, soundDeath = 1286, flies = false, wave = 4, instance = "Blackrock Depths", expansion = 0, order = 159, box = { 0.08, -0.05, 2.65 }, title = "Guardian of the Black Anvil" },
    { id = "pyroguard_emberseer", entry = 9816, name = "Pyroguard Emberseer", label = "Pyroguard Emberseer", level = 60, display = 2172, height = 2.5, span = 2.5, school = "fire", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Fire_SealOfFire", profile = "caster", kit = { 23462, 23341, 17274, 15744 }, passives = { 13377 }, talentInfo = { { name = "Unbound Fury", icon = "Interface\\Icons\\Spell_Fire_SealOfFire", text = "Your Fire damage is increased by 10%." }, { name = "Regained Strength", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "Your maximum health is increased by 8%." }, { name = "Charring Heat", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Your casting speed is increased by 6%." }, { name = "Kindled by Blows", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "When you are struck, you have a 10% chance to erupt in a Fire Nova. Once every 15 sec.\n\nThe Incarcerators learned too late: every blow against the Emberseer only feeds the flame." }, { name = "Full Strength", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Increases the radius of Break the Bonds by 30%.\n\nFully grown, the Emberseer's release fills the whole Hall of Binding." } }, tips = {}, visualKit = 286, soundTransform = 1288, soundDeath = 1286, flies = false, wave = 4, instance = "Blackrock Spire", expansion = 0, order = 185, box = { 0.04, -0.03, 1.32 }, title = "Captive of the Blackhand Legion" },
    { id = "darkmaster_gandling", entry = 1853, name = "Darkmaster Gandling", label = "Darkmaster Gandling", level = 61, display = 11070, height = 3.2, span = 3.2, school = "shadow", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", profile = "caster", kit = { 30830, 15790, 12040, 14887, 12739, 14514, 17490 }, passives = {}, talentInfo = { { name = "Darkmaster", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Shadow damage is increased by 10%." }, { name = "Headmaster's Lessons", icon = "Interface\\Icons\\INV_Misc_Book_06", text = "Your Intellect is increased by 8%." }, { name = "Cult of the Damned", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", text = "Your chance to critically strike with spells is increased by 5%." }, { name = "School Is in Session", icon = "Interface\\Icons\\Spell_Nature_StarFall", text = "Your casting speed is increased by 6%." }, { name = "Hall Monitor", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "When you are struck, you have a 10% chance to raise a Shadow Shield. Once every 30 sec.\n\nNobody lays a hand on the Headmaster. The shield is up before the student has finished the swing." }, { name = "Mandatory Attendance", icon = "Interface\\Icons\\Spell_Shadow_Shadowfury", text = "Increases the damage of Shadow Bolt Volley by 15%.\n\nEvery student of the Scholomance attends the Headmaster's lecture, whether they meant to or not." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Scholomance", expansion = 0, order = 227, summons = { [17490] = true }, charModel = true, box = { -0.16, -0.01, 1.60 }, title = "Headmaster of Scholomance" },
    { id = "the_beast", entry = 10430, name = "The Beast", label = "The Beast", level = 62, display = 10193, height = 13.1, span = 23.4, school = "fire", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Shadow_SummonFelHunter", profile = "bruiser", kit = { 16785, 16788, 16144, 15570, 16636, 14100 }, passives = {}, talentInfo = { { name = "Fires of the Spire", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "Your Fire damage is increased by 10%." }, { name = "Scorched Hide", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Your Fire resistance is increased by 60." }, { name = "Beast of the Spire", icon = "Interface\\Icons\\Ability_Hunter_Pet_CoreHound", text = "Your maximum health is increased by 10%." }, { name = "Savage Maw", icon = "Interface\\Icons\\INV_Misc_MonsterFang_01", text = "Your chance to land a critical strike in melee is increased by 5%." }, { name = "Burning Maw", icon = "Interface\\Icons\\Spell_Fire_Immolation", text = "Your melee attacks have a 10% chance to set the target ablaze with Immolate. Once every 8 sec.\n\nWhatever the Beast bites, it sets alight; the Blackhand Elites know to run." }, { name = "Off the Chain", icon = "Interface\\Icons\\Ability_Racial_BloodRage", text = "Reduces the cooldown of Berserker Charge by 5 sec.\n\nKept on a chain for years in the depths of the Spire, the Beast never waits once it is loose." } }, tips = {}, visualKit = 286, soundTransform = 6819, soundDeath = 6817, flies = false, wave = 4, instance = "Blackrock Spire", expansion = 0, order = 188, box = { -0.86, -0.02, 6.49 }, title = "Terror of Blackrock Spire" },
    { id = "shade_of_eranikus", entry = 5709, name = "Shade of Eranikus", label = "Shade of Eranikus", level = 50, display = 7806, height = 11.7, span = 23.9, school = "nature", pool = "classic_dungeon", icon = "Interface\\Icons\\Achievement_Boss_ShadeOfEranikus", profile = "bruiser", kit = { 12891, 12890, 11876, 12882, 17204 }, passives = { 12535 }, talentInfo = { { name = "Acid of the Nightmare", icon = "Interface\\Icons\\Spell_Nature_Acid_01", text = "Your Nature damage is increased by 10%." }, { name = "Scales of the Consort", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Your armor is increased by 15%." }, { name = "Tormented Shade", icon = "Interface\\Icons\\Spell_Shadow_Shadesofdarkness", text = "Damage you take is reduced by 5%." }, { name = "Dreamer's Slumber", icon = "Interface\\Icons\\Spell_Nature_Sleep", text = "Your maximum health is increased by 8%." }, { name = "Bile of the Nightmare", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "Acid Breath deals 20% more damage.\n\nThe Nightmare that twisted the consort of Ysera burns in every breath he takes." }, { name = "Beat Back the Dreamers", icon = "Interface\\Icons\\Ability_Hunter_Pet_Dragonhawk", text = "When you are struck, you have a 10% chance to beat your wings and hurl back the enemies before you. Once every 20 sec.\n\nBound in the Sunken Temple, the shade suffers no one to come close." } }, tips = {}, visualKit = 282, soundTransform = 3525, soundDeath = 3523, flies = true, wave = 4, instance = "Sunken Temple", expansion = 0, order = 148, summons = { [17204] = true }, box = { -4.16, -0.03, 5.40 }, title = "Fallen Consort of Ysera" },
    { id = "talon_king_ikiss", entry = 18473, name = "Talon King Ikiss", label = "Talon King Ikiss", level = 68, display = 18636, height = 4.9, span = 4.9, school = "arcane", pool = "tbc", icon = "Interface\\Icons\\Achievement_Boss_TalonKingIkiss", profile = "caster", kit = { 35059, 38197, 29211, 35032, 38245, 9438 }, passives = {}, talentInfo = { { name = "Power in Trinkets", icon = "Interface\\Icons\\Spell_Arcane_StarFire", text = "Your Arcane damage is increased by 10%." }, { name = "Sethekk Wisdom", icon = "Interface\\Icons\\Spell_Holy_MagicalSentry", text = "Your Intellect is increased by 8%." }, { name = "Favor of Anzu", icon = "Interface\\Icons\\Spell_Arcane_Blast", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Hoarded Power", icon = "Interface\\Icons\\INV_Misc_Gem_Variety_01", text = "The mana cost of your Arcane spells is reduced by 8%." }, { name = "No Escape", icon = "Interface\\Icons\\Spell_Nature_Slow", text = "Your damaging spells have a 10% chance to Slow the enemies around you. Once every 30 sec.\n\nAk-a-ra-k! No escape for -- caw -- you! Ikiss's magic clings to whoever runs from it." }, { name = "Blink and Burn", icon = "Interface\\Icons\\Spell_Arcane_Blink", text = "Reduces the cooldown of Blink by 5 sec.\n\nIkiss never walks where he can blink, and never blinks without something to explode at the other end." } }, tips = {}, visualKit = 1005, soundTransform = 10554, soundDeath = 10560, flies = false, wave = 4, instance = "Auchindoun: Sethekk Halls", expansion = 1, order = 337, box = { 0.24, -0.06, 2.35 }, voices = { { 10557, 17.2, true, "Ra-ak! Trinkets, yes. Pretty trinkets! Ak! Power, great power. Ra-kaw! Power in trinkets! Ak-caw!" }, { 10554, 6.5, true, "Mmm, you make war on Ikiss? Aa-ak!" }, { 10555, 8.8, true, "Ikiss cut you, pretty -- ak-a-ak -- slice you, yes!" }, { 10556, 5.4, true, "Ak-a-ra-k! No escape for -- caw -- you!" }, { 10558, 6.3, true, "You die -- ka! Stay away from trinkets!" }, { 10559, 2.6, true, "Mmmmmm..." }, { 10560, 8.3, true, "Ikiss will not -- rak, rak -- die..." } }, title = "Master of the Sethekk" },
    { id = "harbinger_skyriss", entry = 20912, name = "Harbinger Skyriss", label = "Harbinger Skyriss", level = 72, display = 19943, height = 20.3, span = 20.3, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Achievement_Boss_Harbinger_Skyriss", profile = "caster", kit = { 36924, 36929, 39020, 39415, 261 }, passives = {}, talentInfo = { { name = "Agent of Your Demise", icon = "Interface\\Icons\\Spell_Shadow_MindRot", text = "Your Shadow damage is increased by 10%." }, { name = "Powers Untouched by Time", icon = "Interface\\Icons\\Spell_Arcane_MindMastery", text = "Your casting speed is increased by 6%." }, { name = "Infinite Multitudes", icon = "Interface\\Icons\\Spell_Shadow_Possession", text = "Your maximum health is increased by 8%." }, { name = "Will of the Harbinger", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordDominate", text = "Your Intellect is increased by 8%." }, { name = "Horrors Undreamed Of", icon = "Interface\\Icons\\Spell_Shadow_PsychicScream", text = "When you are struck, you have an 8% chance to lay Void Rend on the attacker. Once every 45 sec.\n\nI will show you horrors undreamed of. Those who touch the Harbinger see what he serves." }, { name = "Your Fate Is Written", icon = "Interface\\Icons\\Spell_Shadow_Twilight", text = "Your Void Rend lasts 3 sec longer.\n\nYour fate is written. Skyriss lets the rend linger, as the void would." } }, tips = { [36929] = "Rend an enemy's mind for 1800 Shadow damage over 3 sec.", [261] = "I am merely one of infinite multitudes. Split off an illusion of yourself to fight for 20 sec." }, visualKit = 7775, soundTransform = 11123, soundDeath = 11126, flies = false, wave = 4, instance = "Tempest Keep: The Arcatraz", expansion = 1, order = 393, summons = { [261] = true }, box = { 0.11, 0.05, 9.78 }, voices = { { 11123, 4.3, true, "Bear witness to the agent of your demise!" }, { 11124, 2.2, true, "Your fate is written." }, { 11125, 4.7, true, "The chaos I have sown here is but a taste...." }, { 11127, 3.8, true, "You will do my bidding, weakling." }, { 11128, 4.9, true, "Your will is no longer your own." }, { 11129, 2.5, true, "Flee in terror." }, { 11130, 4.3, true, "I will show you horrors undreamed of." }, { 11131, 5.6, true, "We span the universe, as countless as the stars!" }, { 11126, 7.4, true, "I am merely one of... infinite multitudes." } }, title = "Prisoner of the Arcatraz" },
    { id = "exarch_maladaar", entry = 18373, name = "Exarch Maladaar", label = "Exarch Maladaar", level = 67, display = 17715, height = 5.4, span = 5.4, school = "shadow", pool = "tbc", icon = "Interface\\Icons\\Achievement_Boss_Exarch_Maladaar", profile = "caster", kit = { 32422, 32346, 37330, 32421, 37369, 261 }, passives = {}, talentInfo = { { name = "Keeper of the Crypts", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your Shadow damage is increased by 10%." }, { name = "Stolen Souls", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_3", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Exarch's Resolve", icon = "Interface\\Icons\\Spell_Holy_DevotionAura", text = "Your maximum health is increased by 8%." }, { name = "Auchenai Devotion", icon = "Interface\\Icons\\Spell_Holy_MindVision", text = "Your Intellect is increased by 8%." }, { name = "Clouded Minds", icon = "Interface\\Icons\\Spell_Shadow_PsychicScream", text = "When you are struck, you have a 10% chance to lash the attacker with a Ribbon of Souls. Once every 30 sec.\n\nLet your mind be clouded. The crypt's dead lash out through Maladaar whenever he is touched." }, { name = "Room for One More", icon = "Interface\\Icons\\Spell_Shadow_SoulGem", text = "Reduces the cooldown of Stolen Soul by 10 sec.\n\nStare into the darkness of your soul. The exarch keeps a crypt of them, and always has room for one more." } }, tips = { [261] = "Rise, my fallen brothers! Call the Avatar of the Martyred, a draenei spirit of the crypts, to fight beside you for 20 sec." }, visualKit = 7775, soundTransform = 10513, soundDeath = 10518, flies = false, wave = 4, instance = "Auchindoun: Auchenai Crypts", expansion = 1, order = 335, summons = { [261] = true }, charModel = true, box = { -0.65, -0.05, 2.70 }, voices = { { 10509, 15.7, true, "You have defiled the resting place of our ancestors. For this offense, there can be but one punishment. It is fitting that you have come to a place of the dead... for you will soon be joining them." }, { 10512, 5.9, true, "Rise, my fallen brothers! Take form and fight!" }, { 10513, 2.0, true, "You will pay with your life!" }, { 10514, 2.2, true, "There is no turning back now!" }, { 10515, 2.7, true, "Serve your penitence!" }, { 10510, 2.2, true, "Let your mind be clouded." }, { 10511, 3.0, true, "Stare into the darkness of your soul." }, { 10516, 3.8, true, "These walls will be your tomb!" }, { 10517, 7.2, true, "Now you'll stay... for eternity." }, { 10518, 5.6, true, "This is... where I belong." } }, title = "Exarch of the Auchenai" },
    { id = "herald_volazj", entry = 29311, name = "Herald Volazj", label = "Herald Volazj", level = 75, display = 27408, height = 18.6, span = 21.8, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_HeraldVolazj", profile = "caster", kit = { 57949, 57941, 57942, 60845, 34322 }, passives = {}, talentInfo = { { name = "Whisper of the Old God", icon = "Interface\\Icons\\Spell_Shadow_MindFlay", text = "Your Shadow damage is increased by 10%." }, { name = "Outside the Cycle", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "Damage you take is reduced by 5%." }, { name = "Perpetuity of the Void", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your maximum health is increased by 10%." }, { name = "Herald of Yogg-Saron", icon = "Interface\\Icons\\Spell_Shadow_ShadowBolt", text = "Your Intellect is increased by 8%." }, { name = "Madness Unending", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "When you are struck, you have a 10% chance to burst in a Shadow Nova. Once every 20 sec.\n\nTouch the Herald and the whispers get out." }, { name = "Insanity", icon = "Interface\\Icons\\Spell_Shadow_Possession", text = "Reduces the cooldown of Shiver by 5 sec.\n\nVolazj spreads the shiver faster than any mind can shake it." } }, tips = {}, visualKit = 7775, soundTransform = 14043, soundDeath = 14048, flies = false, wave = 4, instance = "Ahn'kahet: The Old Kingdom", expansion = 2, order = 467, box = { 0.60, 0.87, 8.74 }, voices = { { 14043, 2.8, true, "Shgla'yos plahf mh'naus." }, { 14044, 4.4, true, "Gul'kafh an'shel. Yoq'al shn ky ywaq nuul." }, { 14045, 2.3, true, "Ywaq ma phgwa'cul hnakf." }, { 14046, 2.4, true, "Uulwi gag erh'ongg w'ssh." }, { 14047, 4.0, true, "Ywaq puul skshgn: on'ma yeh'glu zuq." }, { 14048, 4.9, true, "Iilth vwah, uhn'agth fhssh za." }, { 14049, 6.8, true, "Ywaq maq oou; ywaq maq ssaggh. Ywaq ma shg'fhn." } }, title = "Herald of the Old Gods" },
    { id = "cyanigosa", entry = 29317, name = "Cyanigosa (Dragon)", label = "Cyanigosa", level = 77, display = 27340, height = 20.2, span = 42.8, school = "arcane", pool = "wotlk", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Blue", profile = "caster", kit = { 58688, 58690, 59374, 11264 }, passives = {}, talentInfo = { { name = "Breath of the Nexus", icon = "Interface\\Icons\\Spell_Frost_ChillingBlast", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Arcane Assault", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", text = "Your Arcane damage is increased by 8%." }, { name = "Azure Scales", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Blue", text = "Your armor is increased by 20%." }, { name = "Lieutenant of Malygos", icon = "Interface\\Icons\\Spell_Arcane_PrismaticCloak", text = "Your maximum health is increased by 8%." }, { name = "Am I Interrupting?", icon = "Interface\\Icons\\INV_Misc_MonsterTail_03", text = "When you are struck, you have a 10% chance to Tail Sweep the enemies behind you. Once every 20 sec.\n\nAm I interrupting? Cyanigosa never is; she just ends conversations." }, { name = "Violet Hold Breach", icon = "Interface\\Icons\\Spell_Frost_IceStorm", text = "Increases the reach of Uncontrollable Energy by 30%.\n\nThe torrent Cyanigosa looses on the Violet Hold spills over every ward." } }, tips = {}, visualKit = 1005, soundTransform = 13947, soundDeath = 13955, flies = true, wave = 4, instance = "Violet Hold", expansion = 2, order = 474, box = { -6.78, 0.00, 9.15 }, title = "Lieutenant of Malygos", visages = { "cyanigosa_elf" }, shape = "Dragon" },
    { id = "prince_taldaram", entry = 29308, name = "Prince Taldaram", label = "Prince Taldaram", level = 75, display = 27406, height = 4.7, span = 4.7, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_PrinceTaldaram", profile = "bruiser", kit = { 16608, 55968, 55927, 55966, 55964 }, passives = {}, talentInfo = { { name = "Thirst of the San'layn", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain", text = "Your Shadow damage is increased by 10%." }, { name = "The Watcher Unseen", icon = "Interface\\Icons\\Ability_Rogue_Shadowstep", text = "Your chance to dodge is increased by 5%." }, { name = "Grace of the Blood Prince", icon = "Interface\\Icons\\Spell_Shadow_BloodBoil", text = "Your Agility is increased by 8%." }, { name = "Fangs of Ahn'kahet", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Still I Thirst", icon = "Interface\\Icons\\Spell_Nature_BloodLust", text = "Your melee attacks have a 10% chance to add a Bloodthirst. Once every 15 sec.\n\nStill I hunger. Still... I... thirst." }, { name = "One Final Embrace", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Your Embrace of the Vampyr lasts 2 sec longer.\n\nOne final... embrace. The prince never lets go quickly." } }, tips = { [55966] = "Step through the shadows to an enemy." }, visualKit = 7775, soundTransform = 14360, soundDeath = 14368, flies = false, wave = 4, instance = "Ahn'kahet: The Old Kingdom", expansion = 2, order = 468, box = { -0.53, -0.26, 2.27 }, voices = { { 14360, 5.0, true, "I will feast on your remains!" }, { 14366, 3.8, true, "I will drink no blood before its time." }, { 14367, 3.8, true, "One final... embrace." }, { 14368, 9.0, true, "Still I hunger. Still... I... thirst." }, { 14363, 2.8, true, "So... appetizing." }, { 14364, 6.0, true, "Fresh, warm blood... it has been too long." }, { 14361, 5.7, true, "Your heartbeat is... music to my ears." }, { 14362, 10.2, true, "I am nowhere.... I am everywhere. I am the watcher unseen." } }, title = "Prince of the San'layn" },
    { id = "galdarah", entry = 29306, name = "Gal'darah", label = "Gal'darah", level = 78, display = 27061, height = 3.1, span = 3.1, school = "physical", pool = "wotlk", icon = "Interface\\Icons\\Achievement_Boss_GalDarah", profile = "bruiser", kit = { 55220, 55250, 55276, 55285 }, passives = {}, talentInfo = { { name = "Prophet of Akali", icon = "Interface\\Icons\\Ability_Hunter_Pet_Rhino", text = "Your attack power is increased by 10%." }, { name = "Drakkari Fury", icon = "Interface\\Icons\\Ability_Warrior_Rampage", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Hide of Akali", icon = "Interface\\Icons\\INV_Misc_Pelt_Bear_03", text = "Your armor is increased by 15%." }, { name = "Gundrak's Strength", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your Strength is increased by 8%." }, { name = "Akali's Spear", icon = "Interface\\Icons\\Ability_Warrior_Charge", text = "Your melee attacks have an 8% chance to add a Puncture. Once every 20 sec.\n\nThe High Prophet's spear goes where the rhino's horn would have." }, { name = "Stampede", icon = "Interface\\Icons\\Ability_BullRush", text = "Reduces the cooldown of Stampede by 6 sec.\n\nAkali's spirits run for Gal'darah again and again." } }, tips = {}, visualKit = 437, soundTransform = 14430, soundDeath = 14439, flies = false, wave = 4, instance = "Gundrak", expansion = 2, order = 472, charModel = true, box = { 0.00, 0.00, 1.56 }, voices = { { 14430, 3.9, true, "I'm gonna spill your guts, mon!" }, { 14436, 2.5, true, "What a rush!" }, { 14437, 5.9, true, "Who needs gods when we ARE gods?" }, { 14438, 2.8, true, "I told ya so!" }, { 14439, 5.4, true, "Even the mighty... can fall." }, { 14433, 4.9, true, "Gut them! Impale them!" }, { 14434, 3.3, true, "KILL THEM ALL!" }, { 14435, 5.2, true, "Say hello to my BIG friend!" }, { 14431, 5.2, true, "Ain't gonna be nothin' left after this!" }, { 14432, 5.9, true, "You wanna see power? I'm gonna show you power!" } }, title = "High Prophet of Akali", visages = { "galdarah_rhino" }, shape = "Troll" },
    { id = "krikthir", entry = 28684, name = "Krik'thir the Gatewatcher", label = "Krik'thir the Gatewatcher", level = 74, display = 27394, height = 13.0, span = 13.0, school = "shadow", pool = "wotlk", icon = "Interface\\Icons\\INV_Misc_Head_Nerubian_01", profile = "caster", kit = { 52592, 52586, 52469, 52524, 261, 17204 }, passives = {}, talentInfo = { { name = "Curse of the Gate", icon = "Interface\\Icons\\Spell_Shadow_CurseOfTounges", text = "Your Shadow damage is increased by 10%." }, { name = "Chitinous Plating", icon = "Interface\\Icons\\INV_Misc_NerubianChitin_01", text = "Your armor is increased by 20%." }, { name = "Hold the Gate", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Your maximum health is increased by 8%." }, { name = "As Anub'arak Commands", icon = "Interface\\Icons\\Spell_Nature_Web", text = "Your casting speed is increased by 6%." }, { name = "Gatewatcher", icon = "Interface\\Icons\\Ability_Hunter_Pet_Spider", text = "Increases the radius of Blinding Webs by 30%.\n\nKrik'thir webs the whole gate, not just the ones who reach him." }, { name = "Keep Them Out", icon = "Interface\\Icons\\Spell_Shadow_CurseOfMannoroth", text = "Reduces the cooldown of Curse of Fatigue by 5 sec.\n\nKrik'thir curses whatever stands at his gate, and he watches it constantly." } }, tips = { [261] = "Call Watcher Gashra down from the gate to fight beside you for 20 sec." }, visualKit = 7775, soundTransform = 14075, soundDeath = 14087, flies = false, wave = 4, instance = "Azjol-Nerub", expansion = 2, order = 465, summons = { [261] = true, [17204] = true }, box = { 0.06, -0.10, 6.38 }, voices = { { 14075, 6.7, true, "This kingdom belongs to the Scourge. Only the dead may enter!" }, { 14077, 3.3, true, "You were foolish to come." }, { 14078, 3.2, true, "As Anub'arak commands!" }, { 14087, 8.7, true, "I should be grateful... but I long ago lost the capacity...." }, { 14085, 2.3, true, "They hunger...." }, { 14086, 2.9, true, "Dinner time, my pets!" }, { 14082, 5.9, true, "Keep an eye on that tunnel. We must not let anyone through!" }, { 14083, 4.9, true, "I hear footsteps. Be on your guard." }, { 14084, 4.0, true, "I sense the living. Be ready." }, { 14079, 6.6, true, "We are besieged! Strike out and bring back their corpses!" }, { 14080, 6.3, true, "We must hold the gate. Attack! Tear them limb from limb!" }, { 14081, 7.3, true, "The gate must be protected at all costs. Rip them to shreds!" } }, title = "Gatewatcher of Azjol-Nerub" },
    { id = "succubus", entry = 22956, name = "Sister of Pain", label = "Succubus", level = 72, display = 21456, height = 4.1, span = 4.1, school = "shadow", pool = "archetype", icon = "Interface\\Icons\\Spell_Shadow_SummonSuccubus", profile = "caster", kit = { 41353, 41355, 30638, 44547, 41371, 12845 }, passives = {}, talentInfo = { { name = "Mistress of Pain", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your Shadow damage is increased by 10%." }, { name = "Cruel Precision", icon = "Interface\\Icons\\Spell_Shadow_CurseOfSargeras", text = "Your spell critical strike chance is increased by 5%." }, { name = "Child of the Nether", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Your Shadow resistance is increased by 40." }, { name = "Irresistible", icon = "Interface\\Icons\\Spell_Shadow_MindSteal", text = "Your Lash of Pain deals 15% more damage.\n\nInteresting... Now this is more than I expected. No one turns down a sayaad twice." }, { name = "Pain Returned", icon = "Interface\\Icons\\Spell_Shadow_Curse", text = "When you are struck, you have a 10% chance to answer with a Lash of Pain. Once every 20 sec.\n\nStrike a Sister of Pain and she only smiles; her whip has already answered for her." } }, tips = { [30638] = "Crack your whip around a distant enemy and drag it to you, dealing 175 Shadow damage." }, visualKit = 7775, soundTransform = 1122, soundDeath = 1120, flies = false, wave = 4, instance = "Black Temple", expansion = 1, order = 380, box = { -1.38, 0.71, 2.05 }, skinName = "Blue", skins = { { entry = 1863, name = "Red", creature = "Succubus", display = 4162, height = 2.1, span = 2.1, box = { -0.69, 0.36, 1.02 } }, { entry = 1864, name = "Purple", creature = "Greater Succubus", display = 159, height = 2.1, span = 2.1, box = { -0.69, 0.36, 1.02 } } }, title = "Sayaad of the Burning Legion" },
    { id = "felhunter", entry = 8718, name = "Manahound", label = "Felhunter", level = 60, display = 6173, height = 3.7, span = 7.6, school = "shadow", pool = "archetype", icon = "Interface\\Icons\\Spell_Shadow_SummonFelHunter", profile = "bruiser", kit = { 30849, 17012, 20817, 33086, 14331, 3604 }, passives = {}, talentInfo = { { name = "Magic Eater", icon = "Interface\\Icons\\Spell_Nature_Purge", text = "Your maximum health is increased by 8%." }, { name = "Hunter of Mages", icon = "Interface\\Icons\\Spell_Shadow_MindRot", text = "Your attack power is increased by 8%." }, { name = "Relentless Pursuit", icon = "Interface\\Icons\\Ability_Hunter_Pet_Wolf", text = "Your movement speed is increased by 8%." }, { name = "Warded Against Sorcery", icon = "Interface\\Icons\\Spell_Shadow_AntiMagicShell", text = "Your Arcane resistance is increased by 40." }, { name = "Scent of Magic", icon = "Interface\\Icons\\Ability_Druid_FerociousBite", text = "Your melee attacks have an 8% chance to follow up with a Wild Bite. Once every 12 sec.\n\nA felhunter smells magic the way a wolf smells blood; when it finds the scent it bites deep." }, { name = "Mana Glutton", icon = "Interface\\Icons\\Spell_Shadow_ManaBurn", text = "Reduces the cooldown of Mana Burn by 5 sec.\n\nThe Legion starves its manahounds between hunts, so they bolt the magic of a whole camp at once." } }, tips = {}, visualKit = 7775, soundTransform = 1249, soundDeath = 1250, flies = false, wave = 4, zone = "Blasted Lands", expansion = 0, order = 239, box = { -1.13, -0.46, 1.74 }, title = "Mana Hunter of the Burning Legion" },
    { id = "pit_lord", entry = 18945, name = "Pit Commander", label = "Pit Lord", level = 72, display = 18622, height = 34.9, span = 58.9, school = "fire", pool = "archetype", icon = "Interface\\Icons\\Spell_Shadow_RainOfFire", profile = "bruiser", kit = { 33627, 30619, 38750, 11443, 39048, 261 }, passives = {}, talentInfo = { { name = "Rain of Fel Fire", icon = "Interface\\Icons\\Spell_Shadow_RainOfFire", text = "Your Fire damage is increased by 10%." }, { name = "Annihilan Hide", icon = "Interface\\Icons\\Spell_Shadow_FelArmour", text = "Your armor is increased by 20%." }, { name = "Bulk of the Pit", icon = "Interface\\Icons\\Spell_Shadow_DemonicTactics", text = "Your maximum health is increased by 10%." }, { name = "Born of Fel Flame", icon = "Interface\\Icons\\Spell_Fire_FelFire", text = "Your Fire resistance is increased by 40." }, { name = "Siege-Lord's Barrage", icon = "Interface\\Icons\\Spell_Fire_FelRainOfFire", text = "Your Rain of Fire covers an area 30% wider.\n\nJust a taste of what awaits you. The annihilan break whole cities, not single foes." }, { name = "Crushing Contempt", icon = "Interface\\Icons\\Spell_Shadow_Cripple", text = "Your melee hits have an 8% chance to Cripple the target. Once every 12 sec.\n\nTo a pit lord every mortal is already beaten; its blows only remind them of it." } }, tips = { [261] = "Rain two Infernal Siegebreakers down from the sky. They crash to the ground beside you and fight for 20 sec." }, visualKit = 286, soundTransform = 10101, soundDeath = 10100, flies = false, wave = 4, zone = "Hellfire Peninsula", expansion = 1, order = 326, summons = { [261] = true }, box = { -19.71, 0.48, 17.06 }, title = "Commander of the Burning Legion" },
    { id = "nether_drake", entry = 22106, name = "Ruul's Netherdrake", label = "Nether Drake", level = 70, display = 20809, height = 8.6, span = 22.9, school = "arcane", pool = "archetype", icon = "Interface\\Icons\\Ability_Mount_NetherdrakePurple", profile = "caster", kit = { 36631, 16067, 38265, 38884, 36513 }, passives = {}, talentInfo = { { name = "Nether-Charged Breath", icon = "Interface\\Icons\\Spell_Arcane_StarFire", text = "Your Arcane damage is increased by 10%." }, { name = "Phasing Scales", icon = "Interface\\Icons\\Spell_Arcane_Blink", text = "Damage you take is reduced by 5%." }, { name = "Raw Nether", icon = "Interface\\Icons\\Spell_Arcane_ArcanePotency", text = "Your spell critical strike chance is increased by 5%." }, { name = "Nether-Warped Hide", icon = "Interface\\Icons\\Spell_Nature_StarFall", text = "Your Arcane resistance is increased by 40." }, { name = "Slip Into the Nether", icon = "Interface\\Icons\\Spell_Holy_SenseUndead", text = "When you are struck, you have a 10% chance to phase into Intangible Presence. Once every 30 sec.\n\nA netherdrake is never wholly in this world; strike one hard and your blade finds only the Twisting Nether." }, { name = "Breath of the Nether", icon = "Interface\\Icons\\Spell_Arcane_MassDispel", text = "Your Netherbreath's cooldown is 2 sec. shorter.\n\nThe nether sings through its scales, and it never runs out of breath to sing with." } }, tips = { [38265] = "Blast an enemy with nether fire for 463 Arcane damage, knock it away and burn it for 250 more every 3 sec. for 15 sec." }, visualKit = 1005, soundTransform = 9003, soundDeath = 10784, flies = true, wave = 4, expansion = 1, order = 338, box = { -4.09, -0.22, 3.50 }, skins = { { entry = 27637, name = "Silver", creature = "Vengeful Nether Drake", display = 24725, height = 3.9, span = 10.3, box = { -1.84, -0.10, 1.57 } }, { entry = 24743, name = "Red", creature = "Merciless Nether Drake", display = 22620, height = 3.9, span = 10.3, box = { -1.84, -0.10, 1.57 } }, { entry = 31124, name = "Green", creature = "Brutal Nether Drake", display = 27507, height = 3.9, span = 10.3, box = { -1.84, -0.10, 1.57 } } }, title = "Nether Drake of Outland" },
    { id = "proto_drake", entry = 24083, name = "Enslaved Proto-Drake", label = "Proto-Drake", level = 70, display = 24874, height = 5.9, span = 18.0, school = "fire", pool = "archetype", icon = "Interface\\Icons\\Ability_Mount_Drake_Proto", profile = "bruiser", kit = { 50653, 43931, 61554, 49722, 41572, 42771 }, passives = {}, talentInfo = { { name = "Primal Fire", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire damage is increased by 10%." }, { name = "Talons of the Wild", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your melee critical strike chance is increased by 5%." }, { name = "Primal Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your armor is increased by 20%." }, { name = "Unbroken Will", icon = "Interface\\Icons\\Spell_Nature_Rejuvenation", text = "When you are struck, you have a 10% chance to catch your Second Wind. Once every 45 sec.\n\nChains will not hold me. The Dragonflayer learned it every time: stun a proto-drake and it only comes back angrier." }, { name = "Searing Breath", icon = "Interface\\Icons\\Spell_Fire_Incinerate", text = "Increases the damage of your Flame Breath by 15%.\n\nThe fire of the primal drakes is older than any flight, and it burns hotter than Utgarde's forges." } }, tips = {}, visualKit = 286, soundTransform = 13753, soundDeath = 13751, flies = true, wave = 4, instance = "Utgarde Keep", expansion = 2, order = 442, box = { -2.53, 0.13, 2.67 }, skins = { { entry = 26893, name = "Blue", creature = "Grauf", display = 27043, height = 5.9, span = 18.0, box = { -2.53, 0.13, 2.67 } }, { entry = 31265, name = "White", creature = "Savage Proto-Drake", display = 26715, height = 7.9, span = 24.0, box = { -3.37, 0.17, 3.56 } }, { entry = 32491, name = "Time-Lost", creature = "Time-Lost Proto Drake", display = 26711, height = 7.9, span = 24.0, box = { -3.37, 0.17, 3.56 } }, { entry = 28467, name = "Black", creature = "Broodmother Slivina", display = 26709, height = 7.9, span = 24.0, box = { -3.37, 0.17, 3.56 } }, { entry = 29756, name = "Violet", creature = "Veranus", display = 26727, height = 27.7, span = 84.0, box = { -11.81, 0.61, 12.48 } } }, title = "Captive of the Dragonflayer Vrykul" },
    { id = "sporebat", entry = 21246, name = "Serpentshrine Sporebat", label = "Sporebat", level = 71, display = 18030, height = 3.6, span = 3.6, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Ability_Hunter_Pet_Sporebat", profile = "bruiser", kit = { 35394, 38575, 38461, 34171, 7145 }, passives = { 38471 }, talentInfo = { { name = "Choking Spores", icon = "Interface\\Icons\\Spell_Nature_AbolishMagic", text = "Your Nature damage is increased by 10%." }, { name = "Spongy Hide", icon = "Interface\\Icons\\Spell_Nature_SpiritArmor", text = "Your maximum health is increased by 8%." }, { name = "Marsh-Born", icon = "Interface\\Icons\\Spell_Nature_ProtectionformNature", text = "Your Nature resistance is increased by 40." }, { name = "Puff of Spores", icon = "Interface\\Icons\\Ability_Hunter_Pet_Sporebat", text = "When you are struck, you have a 10% chance to release a Spore Cloud on your attacker. Once every 20 sec.\n\nSqueeze a sporebat and it answers the only way it knows: a choking green puff right in your face." }, { name = "Sporewind", icon = "Interface\\Icons\\Spell_Nature_Cyclone", text = "Your Toxic Spores cover an area 30% wider.\n\nOver the open water of Zangarmarsh the spores drift farther than any hunter expects." } }, tips = {}, visualKit = 282, soundTransform = 9883, soundDeath = 9881, flies = true, wave = 4, instance = "Coilfang: Serpentshrine Cavern", expansion = 1, order = 370, box = { -0.28, -0.04, 1.99 }, skins = { { entry = 18129, name = "Green", creature = "Greater Sporebat", display = 17752, height = 6.2, span = 6.2, box = { -0.49, -0.06, 3.47 } }, { entry = 18280, name = "Yellow", creature = "Sporewing", display = 18029, height = 8.9, span = 8.9, box = { -0.70, -0.09, 4.96 } } }, title = "Sporebat of Zangarmarsh" },
    { id = "clefthoof", entry = 17132, name = "Clefthoof Bull", label = "Clefthoof", level = 66, display = 19583, height = 10.1, span = 21.2, school = "physical", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Pelt_Bear_03", profile = "tank", kit = { 32023, 32021, 15588, 12612, 54794, 50502, 13446 }, passives = {}, talentInfo = { { name = "Thick Hide", icon = "Interface\\Icons\\INV_Misc_LeatherScrap_08", text = "Your armor is increased by 25%." }, { name = "Bulk of the Herd", icon = "Interface\\Icons\\Ability_Druid_Enrage", text = "Your maximum health is increased by 10%." }, { name = "Herd Guardian", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "The threat you cause is increased by 30%." }, { name = "Shaggy Coat", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", text = "Damage you take is reduced by 5%." }, { name = "Shake Them Off", icon = "Interface\\Icons\\Ability_WarStomp", text = "Hits against you have an 8% chance to set off a Stomp that knocks nearby enemies back. Once every 15 sec.\n\nOgre and orc hunt the clefthoof for its hide. Few who crowd a bull live to skin it." }, { name = "Stampede", icon = "Interface\\Icons\\Ability_Mount_Kodo_01", text = "Reduces the cooldown of Rushing Charge by 5 sec.\n\nHrrrmmph! Once the herd is moving on Nagrand's plains, nothing turns it." } }, tips = {}, visualKit = 437, soundTransform = 771, soundDeath = 775, flies = false, wave = 4, zone = "Nagrand", expansion = 1, order = 332, box = { -3.65, -0.13, 4.75 }, skins = { { entry = 18398, name = "Red", creature = "Brokentoe", display = 19797, height = 12.6, span = 26.5, box = { -4.56, -0.16, 5.94 } }, { entry = 18259, name = "Terokkar", creature = "Banthar", display = 19585, height = 17.6, span = 37.0, box = { -6.39, -0.23, 8.31 } }, { entry = 17133, name = "Black", creature = "Aged Clefthoof", display = 19581, height = 12.6, span = 26.5, box = { -4.56, -0.16, 5.94 } } }, title = "Clefthoof of Nagrand" },
    { id = "nightsaber", entry = 2034, name = "Feral Nightsaber", label = "Nightsaber", level = 11, display = 3030, height = 1.3, span = 3.5, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Mount_WhiteTiger", profile = "glass_cannon", kit = { 8152, 24333, 24332, 12166, 3604, 14100 }, passives = {}, talentInfo = { { name = "Feline Grace", icon = "Interface\\Icons\\Ability_Druid_CatForm", text = "Your Agility is increased by 8%." }, { name = "Savage Claws", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your melee critical strike chance is increased by 5%." }, { name = "Night Stalker", icon = "Interface\\Icons\\Ability_Stealth", text = "Your chance to dodge is increased by 5%." }, { name = "Claws of the Night Hunt", icon = "Interface\\Icons\\Ability_Druid_Disembowel", text = "Your melee attacks have an 8% chance to Rake your target. Once every 20 sec.\n\nA nightsaber never strikes once. The first swipe opens the hide; the second, the one you never see, opens the rest." }, { name = "Sentinel's Pounce", icon = "Interface\\Icons\\Ability_GhoulFrenzy", text = "Your Ravage deals 15% more damage.\n\nThe Sentinels ride the fastest of the sabers. From the branches of Teldrassil they drop, and drop again." } }, tips = {}, visualKit = 437, soundTransform = 648, soundDeath = 646, flies = false, wave = 4, zone = "Teldrassil", expansion = 0, order = 11, box = { -0.70, -0.06, 0.63 }, view = { 1.0736, 0.0000, 0.1430 }, skins = { { entry = 729, name = "Tiger", creature = "Sin'Dall", display = 471, height = 1.9, span = 5.2, box = { -1.05, -0.09, 0.95 } }, { entry = 2850, name = "Cougar", creature = "Broken Tooth", display = 6082, height = 1.9, span = 5.2, box = { -1.05, -0.09, 0.95 } }, { entry = 1201, name = "Snow", creature = "Snow Leopard", display = 954, height = 1.1, span = 2.9, box = { -0.59, -0.05, 0.54 } }, { entry = 731, name = "White", creature = "King Bangalash", display = 616, height = 1.9, span = 5.2, box = { -1.05, -0.09, 0.95 } }, { entry = 767, name = "Jaguar", creature = "Swamp Jaguar", display = 632, height = 1.5, span = 4.0, box = { -0.80, -0.07, 0.73 } } }, title = "Nightsaber of Teldrassil" },
    { id = "dryad", entry = 17944, name = "Dryad", label = "Dryad", level = 70, display = 17340, height = 3.6, span = 3.6, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_Tranquility", profile = "glass_cannon", kit = { 15795, 14516, 7992, 17201, 24021 }, passives = {}, talentInfo = { { name = "Fleet of Hoof", icon = "Interface\\Icons\\Spell_Nature_Swiftness", text = "Your movement speed is increased by 12%." }, { name = "Poisoned Spears", icon = "Interface\\Icons\\Ability_Poisons", text = "Your Physical damage is increased by 10%." }, { name = "Grove-Trained Aim", icon = "Interface\\Icons\\INV_Spear_05", text = "Your melee critical strike chance is increased by 5%." }, { name = "Child of the Forest", icon = "Interface\\Icons\\Spell_Nature_ProtectionformNature", text = "Your Nature resistance is increased by 40." }, { name = "Venomed Tips", icon = "Interface\\Icons\\Spell_Nature_SlowPoison", text = "Your melee hits have an 8% chance to apply Slowing Poison. Once every 10 sec.\n\nEvery dryad's spear is dipped in the grove's slow venom before she leaves Moonglade." }, { name = "Swift as the Hind", icon = "Interface\\Icons\\Ability_PoisonArrow", text = "Increases the damage of Spear Throw by 15%.\n\nShe throws on the run, and a spear from a running dryad lands with all her speed behind it." } }, tips = {}, visualKit = 282, soundTransform = 1134, soundDeath = 1133, flies = false, wave = 4, instance = "The Battle for Mount Hyjal", expansion = 1, order = 355, box = { 0.06, -0.07, 1.78 }, skinName = "Dryad", variants = { "dryad_nymph" }, skins = { { entry = 1992, name = "Purple", creature = "Tarindrella", display = 10034, height = 2.4, span = 2.4, box = { 0.04, -0.04, 1.19 } }, { entry = 3916, name = "Frost", creature = "Shael'dryn", display = 2721, height = 2.4, span = 2.4, box = { 0.04, -0.04, 1.19 } }, { entry = 3585, name = "Tan", creature = "Therysil", display = 876, height = 2.4, span = 2.4, box = { 0.04, -0.04, 1.19 } } }, title = "Daughter of Cenarius" },
    { id = "moonkin", entry = 10157, name = "Moonkin Oracle", label = "Moonkin", level = 14, display = 12236, height = 4.2, span = 4.2, school = "arcane", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_ForceOfNature", profile = "caster", kit = { 15798, 9739, 21668, 16561, 12747, 27530, 65855 }, passives = {}, talentInfo = { { name = "Moonfury", icon = "Interface\\Icons\\Spell_Nature_MoonGlow", text = "Your Arcane damage is increased by 10%." }, { name = "Moonkin Aura", icon = "Interface\\Icons\\Spell_Nature_ForceOfNature", text = "Your spell critical strike chance is increased by 5%." }, { name = "Owlbeast Hide", icon = "Interface\\Icons\\Spell_Nature_StoneClawTotem", text = "Your armor is increased by 20%." }, { name = "Eclipse of the Oracle", icon = "Interface\\Icons\\Spell_Nature_StarFall", text = "Your harmful spells have a 10% chance to call a Moonfire down on the target. Once every 20 sec.\n\nThe oracles watch the sky, not the fight. When Elune's eye opens, her light falls wherever their gaze does." }, { name = "Wrath of the Night Sky", icon = "Interface\\Icons\\Spell_Arcane_StarFire", text = "Your Starfire deals 15% more damage.\n\nMoonkin were made to keep the balance. Tip it, and the stars themselves come down to set it right." } }, tips = {}, visualKit = 1005, soundTransform = 5361, soundDeath = 5359, flies = false, wave = 4, zone = "Darkshore", expansion = 0, order = 17, box = { 0.13, 0.02, 2.11 }, view = { -0.3556, 0.0090, -0.0757 }, skinName = "Moonkin", variants = { "moonkin_owlbeast", "moonkin_wildkin" }, skins = { { entry = 10158, name = "Brown", creature = "Moonkin", display = 5927, height = 4.2, span = 4.2, box = { 0.13, 0.02, 2.11 } }, { entry = 7450, name = "White", creature = "Ragged Owlbeast", display = 12235, height = 4.2, span = 4.2, box = { 0.13, 0.02, 2.11 } } }, title = "Moonkin of Darkshore" },
    { id = "wisp", entry = 17946, name = "Ancient Wisp", label = "Wisp", level = 70, display = 17607, height = 9.6, span = 9.6, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_WispSplode", profile = "caster", kit = { 39349, 15798, 12160, 16561, 6726, 20789 }, passives = {}, talentInfo = { { name = "Spark of Life", icon = "Interface\\Icons\\Spell_Nature_WispSplode", text = "Your Nature damage is increased by 10%." }, { name = "Light of the Glade", icon = "Interface\\Icons\\Spell_Nature_Rejuvenation", text = "Your healing done is increased by 12%." }, { name = "Drifting Spirit", icon = "Interface\\Icons\\Spell_Nature_Invisibilty", text = "Your movement speed is increased by 10%." }, { name = "Insubstantial", icon = "Interface\\Icons\\Spell_Magic_LesserInvisibilty", text = "Damage you take is reduced by 5%." }, { name = "Sparks of Nordrassil", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your spells have a 10% chance to loose an extra Ancient Spark. Once every 8 sec.\n\nThousands of wisps rose at the World Tree, and every one of them carried a spark for Archimonde." }, { name = "Denouement", icon = "Interface\\Icons\\Spell_Nature_WispSplodeGreen", text = "Your Detonate reaches 30% farther.\n\nA wisp's last light is its brightest. At Nordrassil they burned out all at once, and the Burning One fell." } }, tips = {}, visualKit = 282, soundTransform = 6339, soundDeath = 0, flies = false, wave = 4, instance = "The Battle for Mount Hyjal", expansion = 1, order = 358, box = { 1.10, 0.02, 5.30 }, skins = { { entry = 16701, name = "Red", creature = "Spirit of Summer", display = 16587, height = 1.6, span = 1.6, box = { 0.18, 0.00, 0.88 } } }, title = "Spirit of Nordrassil" },
    { id = "iron_dwarf", entry = 27963, name = "Dark Rune Theurgist", label = "Iron Dwarf", level = 78, display = 25990, height = 2.3, span = 2.3, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", profile = "caster", kit = { 53167, 35010, 12734, 49753, 52651, 51484, 51475 }, passives = {}, talentInfo = { { name = "Storm-Forged", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 10%." }, { name = "Iron Skin", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", text = "Your armor is increased by 20%." }, { name = "Runic Focus", icon = "Interface\\Icons\\Spell_Shadow_Teleport", text = "Your casting speed is increased by 6%." }, { name = "Rune-Etched", icon = "Interface\\Icons\\Spell_Fire_Rune", text = "Your damaging spells have a 10% chance to brand the target with a Rune of Destruction. Once every 15 sec.\n\nYou dare to defy the sons of iron? Every bolt a theurgist throws carries a rune cut in the forges of Ulduar." }, { name = "Might of Loken", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", text = "Increases the damage of your Forked Lightning by 15%.\n\nLoken's lightning runs in the iron dwarves' stone veins, and his servants throw it gladly." } }, tips = {}, visualKit = 282, soundTransform = 13780, soundDeath = 13783, flies = false, wave = 4, instance = "Halls of Stone", expansion = 2, order = 476, summons = { [51475] = true }, box = { -0.04, -0.03, 1.15 }, skins = { { entry = 23675, name = "Dark", creature = "Iron Rune Runemaster", display = 25748, height = 2.3, span = 2.3, box = { -0.04, -0.03, 1.15 } }, { entry = 26348, name = "Red", creature = "Iron Thane Argrum", display = 25793, height = 2.7, span = 2.7, box = { -0.04, -0.03, 1.32 } }, { entry = 24212, name = "Silver", creature = "Iron Rune Guardian", display = 25755, height = 2.3, span = 2.3, box = { -0.04, -0.03, 1.15 } }, { entry = 29368, name = "Gold", creature = "Valduran the Stormborn", display = 26218, height = 2.9, span = 2.9, box = { -0.05, -0.03, 1.43 } } }, title = "Servant of Loken" },
    { id = "ancient_protector", entry = 11459, name = "Ironbark Protector", label = "Ancient Protector", level = 59, display = 13489, height = 9.5, span = 9.5, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Ability_Druid_ForceofNature", profile = "tank", kit = { 28858, 70428, 5568, 18670, 63169, 63149, 20655 }, passives = {}, talentInfo = { { name = "Ironbark", icon = "Interface\\Icons\\Spell_Nature_StoneClawTotem", text = "Your armor is increased by 20%." }, { name = "Ancient Heartwood", icon = "Interface\\Icons\\Spell_Nature_Regeneration", text = "Your maximum health is increased by 10%." }, { name = "Warden of Eldre'Thalas", icon = "Interface\\Icons\\Ability_Druid_ForceofNature", text = "The threat you cause is increased by 30%." }, { name = "Living Heartwood", icon = "Interface\\Icons\\Spell_Nature_StrangleVines", text = "Damage you take is reduced by 5%." }, { name = "Tangled Bark", icon = "Interface\\Icons\\inv_misc_root_01", text = "Blows that strike you have a 6% chance to root the attacker in Entangling Roots. Once every 20 sec.\n\nThe protectors of Dire Maul have stood so long that their roots run under every flagstone. Stand too close and they take hold." }, { name = "Wrath of the Grove", icon = "Interface\\Icons\\Spell_Nature_ResistNature", text = "Your Violent Earth deals 15% more damage.\n\nEldre'Thalas fell long ago; its ancient still tears the ground open under anyone who walks its courts." } }, tips = {}, visualKit = 282, soundTransform = 15500, soundDeath = 300, flies = false, wave = 4, instance = "Dire Maul", expansion = 0, order = 209, box = { 0.62, 0.12, 4.69 }, skinName = "Ancient", variants = { "ancient_protector_stonebark", "ancient_protector_brightleaf", "ancient_protector_ironbranch" }, skins = { { entry = 22053, name = "Moss", creature = "Mosswood the Ancient", display = 20249, height = 12.6, span = 12.6, box = { 0.83, 0.16, 6.25 } }, { entry = 12836, name = "Gray", creature = "Wandering Protector", display = 12750, height = 12.6, span = 12.6, box = { 0.83, 0.16, 6.25 } } }, title = "Guardian of Eldre'Thalas" },
    { id = "jeklik_bat", entry = 14941, name = "High Priestess Jeklik", label = "High Priestess Jeklik", level = 63, display = 15191, height = 6.4, span = 13.4, school = "physical", pool = "classic_raid", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bat", profile = "bruiser", kit = { 23919, 23918, 2100405, 6016, 22911, 261 }, passives = {}, talentInfo = { { name = "Wings of Hir'eek", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bat", text = "Your movement speed is increased by 10%." }, { name = "Swooping Strikes", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your chance to land a critical strike is increased by 6%." }, { name = "Leathery Wings", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Damage you take is reduced by 5%." }, { name = "Frenzy of the Bat God", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "Your attack speed is increased by 8%." }, { name = "Wings of Vengeance", icon = "Interface\\Icons\\Ability_Hunter_SwiftStrike", text = "Increases the damage of your Swoop by 15%.\n\nLord Hir'eek, grant me wings of vengeance! The bat god's priestess strikes hardest out of the sky." }, { name = "Bloodseeker's Hunger", icon = "Interface\\Icons\\Ability_Racial_Cannibalize", text = "Your melee hits have an 8% chance to set off a Blood Leech around you. Once every 15 sec.\n\nHir'eek's brood feed as they fight, and so does the priestess who wears his wings." } }, tips = { [261] = "Shriek for your brood: two Bloodseeker Bats flock to you and fight for 15 sec." }, visualKit = 437, soundTransform = 8417, soundDeath = 8422, flies = true, wave = 4, instance = "Zul'Gurub", expansion = 0, order = 248, as = 14517, summons = { [261] = true }, box = { -0.33, -0.00, 4.38 }, voices = { { 8417, 3.8, true, "Lord Hir'eek, grant me wings of vengeance!" }, { 8422, 5.3, true, "Finally...death! Curse you, Hakkar! Curse you!" } }, title = "Priestess of Hir'eek", visageOf = "jeklik", shape = "Bat" },
    { id = "venoxis_serpent", entry = 14877, name = "High Priest Venoxis", label = "High Priest Venoxis", level = 63, display = 15102, height = 4.4, span = 4.9, school = "nature", pool = "classic_raid", icon = "Interface\\Icons\\Ability_Hunter_CobraStrikes", profile = "bruiser", kit = { 23862, 23861, 3391, 8269, 261 }, passives = {}, talentInfo = { { name = "Venom of Hethiss", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "Your Nature damage is increased by 10%." }, { name = "Serpent Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Your armor is increased by 15%." }, { name = "Venom Blood", icon = "Interface\\Icons\\Spell_Nature_ResistNature", text = "Your Nature resistance is increased by 40." }, { name = "Coils of Hate", icon = "Interface\\Icons\\Ability_Hunter_Pet_WindSerpent", text = "Your attack speed is increased by 8%." }, { name = "Fangs of Hethiss", icon = "Interface\\Icons\\Ability_Creature_Poison_05", text = "Your melee hits have a 10% chance to spit Venom Spit at the target. Once every 8 sec.\n\nThe serpent god's venom wells in every bite; Venoxis hardly needs to aim." }, { name = "Let the Coils Unfurl", icon = "Interface\\Icons\\Spell_Nature_NatureTouchDecay", text = "Your Poison Cloud covers a 20% wider area.\n\nLet the coils of hate unfurl! The cloud spreads through the temple pool like the god's own breath." } }, tips = { [261] = "Loose the parasites of Hethiss: two Parasitic Serpents slither out to fight for 20 sec." }, visualKit = 282, soundTransform = 8421, soundDeath = 0, flies = false, wave = 4, instance = "Zul'Gurub", expansion = 0, order = 246, as = 14507, summons = { [261] = true }, box = { -0.84, 0.01, 2.12 }, view = { 0.9031, 0.0418, 0.2134 }, voices = { { 8421, 3.5, true, "Let the coils of hate unfurl!" } }, title = "Priest of Hethiss", visageOf = "venoxis", shape = "Serpent" },
    { id = "marli_spider", entry = 14967, name = "High Priestess Mar'li", label = "High Priestess Mar'li", level = 63, display = 15226, height = 7.0, span = 9.8, school = "nature", pool = "classic_raid", icon = "Interface\\Icons\\Ability_Hunter_Pet_Spider", profile = "bruiser", kit = { 24111, 24110, 24112, 22911, 3391 }, passives = {}, talentInfo = { { name = "Venom of Shadra", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "Your Nature damage is increased by 10%." }, { name = "Spider Aspect Carapace", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Your armor is increased by 15%." }, { name = "Skittering Legs", icon = "Interface\\Icons\\Ability_Hunter_Pet_Spider", text = "Your movement speed is increased by 10%." }, { name = "Brood of Mar'li", icon = "Interface\\Icons\\Spell_Shadow_ImpPhaseShift", text = "Your maximum health is increased by 8%." }, { name = "Venom Sacs", icon = "Interface\\Icons\\Spell_Nature_Acid_01", text = "Your melee hits have a 10% chance to set off a Poison Shock on the target. Once every 10 sec.\n\nShadra, make of me your avatar! Every bite of the spider priestess bursts with the loa's venom." }, { name = "Leap from the Web", icon = "Interface\\Icons\\Ability_Warrior_Charge", text = "Increases the damage of your Corrosive Poison by 15%.\n\nThe web holds them still; the spider does the rest. Mar'li's venom eats deepest into prey that cannot move." } }, tips = { [24112] = "Shock an enemy with venom, dealing 875 Nature damage to it and to enemies close by." }, visualKit = 282, soundTransform = 8418, soundDeath = 8423, flies = false, wave = 4, instance = "Zul'Gurub", expansion = 0, order = 249, as = 14510, box = { -0.29, -0.00, 3.12 }, voices = { { 8418, 5.3, true, "Draw me to your web mistress Shadra. Unleash your venom!" }, { 8423, 7.7, true, "Bless you, mortals, for this release...Hakkar controls me no longer!" } }, title = "Priestess of Shadra", visageOf = "marli", shape = "Spider" },
    { id = "thekal_tiger", entry = 14966, name = "High Priest Thekal", label = "High Priest Thekal", level = 63, display = 14792, height = 5.7, span = 6.0, school = "physical", pool = "classic_raid", icon = "Interface\\Icons\\INV_Misc_Head_Tiger_01", profile = "bruiser", kit = { 24189, 24193, 24187, 24332, 8269, 24183 }, passives = {}, talentInfo = { { name = "Claws of Shirvallah", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your chance to land a critical strike is increased by 6%." }, { name = "Swiftness of the Tiger", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Your attack speed is increased by 8%." }, { name = "Zulian Tigerhide", icon = "Interface\\Icons\\INV_Misc_Head_Tiger_01", text = "Your chance to dodge is increased by 5%." }, { name = "Undying Avatar", icon = "Interface\\Icons\\Ability_Mount_JungleTiger", text = "Your maximum health is increased by 8%." }, { name = "Pounce of Shirvallah", icon = "Interface\\Icons\\Ability_Warrior_Charge", text = "Increases the damage of your Charge by 15%.\n\nThe tiger avatar picks its prey across the temple floor and hits it with the whole weight of the loa." }, { name = "Tiger God's Wrath", icon = "Interface\\Icons\\INV_Gauntlets_31", text = "Blows against you have a 10% chance to set off a Force Punch around you. Once every 20 sec.\n\nCrowd the risen priest and Shirvallah answers for him, flinging the whole pack back across the steps." } }, tips = {}, visualKit = 437, soundTransform = 8419, soundDeath = 8424, flies = false, wave = 4, instance = "Zul'Gurub", expansion = 0, order = 245, as = 14509, summons = { [24183] = true }, box = { -0.59, -0.07, 2.82 }, voices = { { 8419, 3.8, true, "Shirvallah, fill me with your RAGE!" }, { 8424, 5.3, true, "Hakkar binds me no more! Peace at last!" } }, title = "Priest of Shirvallah", visageOf = "thekal", shape = "Tiger" },
    { id = "arlokk_panther", entry = 14968, name = "High Priestess Arlokk", label = "High Priestess Arlokk", level = 63, display = 15013, height = 9.9, span = 10.0, school = "physical", pool = "classic_raid", icon = "Interface\\Icons\\INV_Jewelcrafting_BlackPearlPanther", profile = "bruiser", kit = { 24213, 24332, 24016, 39669, 34189 }, passives = {}, talentInfo = { { name = "Panther's Pounce", icon = "Interface\\Icons\\INV_Jewelcrafting_BlackPearlPanther", text = "Your chance to land a critical strike is increased by 6%." }, { name = "Shadow of the Jungle", icon = "Interface\\Icons\\Ability_Stealth", text = "Your chance to dodge is increased by 6%." }, { name = "Jungle Stalker", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Your movement speed is increased by 10%." }, { name = "Bethekk's Speed", icon = "Interface\\Icons\\Ability_Mount_BlackPanther", text = "Your attack speed is increased by 8%." }, { name = "Ravager of Bethekk", icon = "Interface\\Icons\\Ability_GhoulFrenzy", text = "Your Ravage deals 15% more damage.\n\nThe prey that hears the gong has already been chosen. Bethekk's avatar only ever pounces once." }, { name = "Bleeding Prey", icon = "Interface\\Icons\\Ability_Druid_Disembowel", text = "Your melee hits have an 8% chance to Rake the target. Once every 12 sec.\n\nFeast on them, my pretties! The panther priestess leaves a trail her pack can follow." } }, tips = {}, visualKit = 437, soundTransform = 8416, soundDeath = 8412, flies = false, wave = 4, instance = "Zul'Gurub", expansion = 0, order = 247, as = 14515, box = { 0.24, -0.86, 4.51 }, voices = { { 8416, 3.6, true, "Bethekk, your priestess calls upon your might!" }, { 8412, 4.3, true, "At last, I am free of the Soulflayer!" } }, title = "Priestess of Bethekk", visageOf = "arlokk", shape = "Panther" },
    { id = "galdarah_rhino", entry = 29681, name = "Gal'darah", label = "Gal'darah", level = 78, display = 26278, height = 5.8, span = 10.5, school = "physical", pool = "wotlk", icon = "Interface\\Icons\\Ability_Hunter_Pet_Rhino", profile = "bruiser", kit = { 55292, 55530, 55663, 55285 }, passives = {}, talentInfo = { { name = "Horn of Akali", icon = "Interface\\Icons\\Ability_Hunter_Pet_Rhino", text = "Your attack power is increased by 10%." }, { name = "Thick Hide", icon = "Interface\\Icons\\INV_Misc_Pelt_Bear_03", text = "Your armor is increased by 20%." }, { name = "Stampeding Hooves", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your movement speed is increased by 10%." }, { name = "Rhino God's Might", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your Strength is increased by 8%." }, { name = "Trampling Hooves", icon = "Interface\\Icons\\Ability_Warstomp", text = "When you are struck, you have a 10% chance to Stomp. Once every 20 sec.\n\nCrowd the rhino and you learn why the Drakkari worship it." }, { name = "Charging Rhino", icon = "Interface\\Icons\\Ability_Warrior_Charge", text = "Reduces the cooldown of Charge by 5 sec.\n\nOnce Akali's spirit is loose, it rarely stops charging." } }, tips = {}, visualKit = 437, soundTransform = 14432, soundDeath = 14439, flies = false, wave = 4, instance = "Gundrak", expansion = 2, order = 470, as = 29306, box = { -0.75, -0.06, 2.79 }, voices = { { 14430, 3.9, true, "I'm gonna spill your guts, mon!" }, { 14436, 2.5, true, "What a rush!" }, { 14437, 5.9, true, "Who needs gods when we ARE gods?" }, { 14438, 2.8, true, "I told ya so!" }, { 14439, 5.4, true, "Even the mighty... can fall." }, { 14433, 4.9, true, "Gut them! Impale them!" }, { 14434, 3.3, true, "KILL THEM ALL!" }, { 14435, 5.2, true, "Say hello to my BIG friend!" }, { 14431, 5.2, true, "Ain't gonna be nothin' left after this!" }, { 14432, 5.9, true, "You wanna see power? I'm gonna show you power!" } }, title = "High Prophet of Akali", visageOf = "galdarah", shape = "Rhino" },
    { id = "nalorakk_bear", entry = 23759, name = "Nalorakk", label = "Nalorakk", level = 73, display = 21736, height = 7.6, span = 13.4, school = "physical", pool = "tbc", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bear", profile = "tank", kit = { 42395, 42397, 42389, 42398, 29390, 37548 }, passives = {}, talentInfo = { { name = "Thick Bear Hide", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bear", text = "Your armor is increased by 25%." }, { name = "Avatar of the Bear", icon = "Interface\\Icons\\Ability_Racial_BearForm", text = "Your maximum health is increased by 12%." }, { name = "I Bring Da Pain", icon = "Interface\\Icons\\Ability_Druid_DemoralizingRoar", text = "The threat you cause is increased by 30%." }, { name = "Bear God's Strength", icon = "Interface\\Icons\\Ability_Druid_Maul", text = "Your Strength is increased by 8%." }, { name = "Rend Flesh", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your melee attacks have a 10% chance to Rend Flesh. Once every 15 sec.\n\nDa bear spirit tears deeper every time it lands a blow." }, { name = "Now Whatchoo Got to Say", icon = "Interface\\Icons\\Ability_Druid_ChallangingRoar", text = "Reduces the cooldown of Deafening Roar by 8 sec.\n\nNow whatchoo got to say? The bear roars again before the casters can finish a sentence." } }, tips = {}, visualKit = 437, soundTransform = 12072, soundDeath = 12077, flies = false, wave = 4, instance = "Zul'Aman", expansion = 1, order = 403, as = 23576, box = { 0.05, -0.12, 3.57 }, voices = { { 12066, 3.5, true, "Get da move on, guards! It be killin' time!" }, { 12067, 5.9, true, "Guards, go already! Who you more afraid of, dem... or me?" }, { 12068, 4.9, true, "Ride now! Ride out dere and bring me back some heads!" }, { 12069, 7.9, true, "I be losin' me patience! Go on: make dem wish dey was never born!" }, { 12070, 1.8, true, "You be dead soon enough!" }, { 12071, 2.3, true, "I bring da pain!" }, { 12072, 4.2, true, "You call on da beast, you gonna get more dan you bargain for!" }, { 12073, 2.4, true, "Make way for da Nalorakk!" }, { 12074, 3.3, true, "You had your chance; now it be too late!" }, { 12075, 3.1, true, "Now whatchoo got to say?" }, { 12076, 3.2, true, "Da Amani gonna rule again!" }, { 12077, 3.6, true, "I... be waitin' on da udda side...." } }, title = "Bear Avatar", visageOf = "nalorakk", shape = "Bear" },
    { id = "halazzi_troll", entry = 24144, name = "Halazzi", label = "Halazzi", level = 73, display = 22348, height = 6.4, span = 6.4, school = "fire", pool = "tbc", icon = "Interface\\Icons\\Spell_Fire_FlameShock", profile = "caster", kit = { 43303, 43305, 43526, 44033, 43527, 261 }, passives = {}, talentInfo = { { name = "Searing Totems", icon = "Interface\\Icons\\Spell_Fire_FlameShock", text = "Your Fire damage is increased by 10%." }, { name = "Earthen Shocks", icon = "Interface\\Icons\\Spell_Nature_EarthShock", text = "Your Nature damage is increased by 8%." }, { name = "Amani Chain Healing", icon = "Interface\\Icons\\Spell_Nature_HealingWaveGreater", text = "Your healing is increased by 10%." }, { name = "Shocking Focus", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Split Spirit", icon = "Interface\\Icons\\Spell_Nature_Earthquake", text = "When you are struck, you have a 10% chance to Earth Shock the attacker. Once every 20 sec.\n\nHalazzi and his lynx spirit fight as one; hit the troll and the spirit hits back." }, { name = "Thunder of the Amani", icon = "Interface\\Icons\\Spell_Nature_ThunderClap", text = "Reduces the cooldown of Thunderclap by 4 sec.\n\nThe Amani shaman keeps the storm close and calls it often." } }, tips = { [261] = "Split your lynx spirit from your body to hunt at your side for 20 sec." }, visualKit = 286, soundTransform = 12021, soundDeath = 12028, flies = false, wave = 4, instance = "Zul'Aman", expansion = 1, order = 410, summons = { [261] = true }, charModel = true, box = { -0.09, 0.07, 3.08 }, voices = { { 12020, 4.3, true, "Get on ya knees and bow.... to da fang and claw!" }, { 12026, 2.3, true, "You can fight da power!" }, { 12027, 1.7, true, "Ya all gonna fail!" }, { 12023, 2.5, true, "Me gonna carve ya now!" }, { 12024, 2.9, true, "You gonna leave in pieces!" }, { 12021, 3.4, true, "I fight wit untamed spirit...." }, { 12022, 2.3, true, "Spirit, come back to me!" }, { 12028, 3.8, true, "Chaga... chokajinn." } }, title = "Lynx Avatar", visageOf = "halazzi", shape = "Troll" },
    { id = "zuljin_bear", entry = 23759, name = "Zul'jin", label = "Zul'jin", level = 73, display = 21736, height = 7.6, span = 13.4, school = "physical", pool = "tbc", icon = "Interface\\Icons\\Ability_Racial_BearForm", profile = "bruiser", kit = { 43095, 43456, 7092, 48193 }, passives = {}, talentInfo = { { name = "Shape of the Bear", icon = "Interface\\Icons\\Ability_Racial_BearForm", text = "All damage you deal is increased by 8%." }, { name = "Bear Loa's Hide", icon = "Interface\\Icons\\Ability_Hunter_Pet_Bear", text = "Your armor is increased by 20%." }, { name = "Brudda Bear's Might", icon = "Interface\\Icons\\Ability_Druid_Maul", text = "Your Strength is increased by 8%." }, { name = "Grievous Wounds", icon = "Interface\\Icons\\Ability_Warrior_BloodFrenzy", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Bear Loa's Fury", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your melee attacks have a 10% chance to add an Overpower. Once every 15 sec.\n\nThe bear loa lends Zul'jin its claws, and it never learned to hold back." }, { name = "Creeping Paralysis", icon = "Interface\\Icons\\Spell_Nature_TimeStop", text = "Reduces the cooldown of Creeping Paralysis by 15 sec.\n\nThe paralysis spreads through the Amani ring faster each time the bear stamps." } }, tips = {}, visualKit = 437, soundTransform = 12092, soundDeath = 12100, flies = false, wave = 4, instance = "Zul'Aman", expansion = 1, order = 404, as = 23863, box = { 0.05, -0.12, 3.57 }, voices = { { 12091, 2.8, true, "Nobody badduh dan me!" }, { 12092, 4.9, true, "Got me some new tricks... like me brudda bear...." }, { 12093, 3.8, true, "Dere be no hidin' from da eagle!" }, { 12094, 6.5, true, "Let me introduce you to me new bruddas: fang and claw!" }, { 12095, 5.1, true, "Ya don' have to look to da sky to see da dragonhawk!" }, { 12096, 3.7, true, "Fire kill you just as quick!" }, { 12097, 4.1, true, "You too slow! Me too strong!" }, { 12098, 2.8, true, "Da Amani di chuka!" }, { 12099, 2.8, true, "Lot more going to fall like you." }, { 12100, 8.6, true, "Mebbe me fall... but da Amani empire... never going to die." } }, title = "Warlord of Zul'Aman", visageOf = "zuljin", shape = "Bear" },
    { id = "zuljin_eagle", entry = 23913, name = "Zul'jin", label = "Zul'jin", level = 73, display = 22257, height = 14.1, span = 24.2, school = "nature", pool = "tbc", icon = "Interface\\Icons\\Spell_Nature_RavenForm", profile = "glass_cannon", kit = { 43137, 43731, 43121, 43517 }, passives = {}, talentInfo = { { name = "Shape of the Eagle", icon = "Interface\\Icons\\Spell_Nature_RavenForm", text = "Your movement speed is increased by 12%." }, { name = "Energy Storm", icon = "Interface\\Icons\\Spell_Nature_CallStorm", text = "Your Nature damage is increased by 12%." }, { name = "Eagle Eye", icon = "Interface\\Icons\\Ability_Hunter_EagleEye", text = "Your chance to critically hit with spells is increased by 6%." }, { name = "Rending Talons", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Crackling Storm", icon = "Interface\\Icons\\Spell_Nature_StormReach", text = "When you are struck, you have a 10% chance to Zap the attacker. Once every 15 sec.\n\nThe eagle loa's storm crackles around Zul'jin and lashes anyone who reaches for him." }, { name = "Eye of the Eagle", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Reduces the cooldown of Zap by 3 sec.\n\nDere be no hidin' from da eagle. Its lightning finds you quicker every time." } }, tips = { [43137] = "Dere be no hidin' from da eagle! Zap an enemy for 1250 Nature damage.", [43731] = "Dere be no hidin' from da eagle! Call the energy storm down around you for 660 Nature damage to every enemy within 15 yards." }, visualKit = 282, soundTransform = 12093, soundDeath = 12100, flies = true, wave = 4, instance = "Zul'Aman", expansion = 1, order = 405, as = 23863, box = { 1.13, 0.06, 8.66 }, voices = { { 12091, 2.8, true, "Nobody badduh dan me!" }, { 12092, 4.9, true, "Got me some new tricks... like me brudda bear...." }, { 12093, 3.8, true, "Dere be no hidin' from da eagle!" }, { 12094, 6.5, true, "Let me introduce you to me new bruddas: fang and claw!" }, { 12095, 5.1, true, "Ya don' have to look to da sky to see da dragonhawk!" }, { 12096, 3.7, true, "Fire kill you just as quick!" }, { 12097, 4.1, true, "You too slow! Me too strong!" }, { 12098, 2.8, true, "Da Amani di chuka!" }, { 12099, 2.8, true, "Lot more going to fall like you." }, { 12100, 8.6, true, "Mebbe me fall... but da Amani empire... never going to die." } }, title = "Warlord of Zul'Aman", visageOf = "zuljin", shape = "Eagle" },
