    { id = "hydromancer_velratha", entry = 7795, name = "Hydromancer Velratha", label = "Hydromancer Velratha", level = 46, display = 6685, height = 2.7, span = 2.7, school = "frost", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Frost_SummonWaterElemental", profile = "caster", kit = { 15530, 488, 37730, 11831, 12491 }, passives = {}, talentInfo = { { name = "Waters of Zul'Farrak", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "Tidecaller", icon = "Interface\\Icons\\Spell_Frost_SummonWaterElemental", text = "Your casting speed is increased by 6%." }, { name = "Pool Blessing", icon = "Interface\\Icons\\Spell_Nature_HealingWaveGreater", text = "Your healing is increased by 10%." }, { name = "Cool Head", icon = "Interface\\Icons\\Spell_Frost_FrostArmor02", text = "Your Fire resistance is increased by 30." }, { name = "Undertow", icon = "Interface\\Icons\\Spell_Frost_FrostBolt", text = "Your damaging spells have a 10% chance to lash the target with a Water Bolt. Once every 10 sec.\n\nThe sacred pool never stops moving. Neither do its waters, once Velratha has called them." }, { name = "Gahz'rilla Stirs", icon = "Interface\\Icons\\Spell_Frost_IceShock", text = "Reduces the cooldown of your Tidal Wave by 5 sec.\n\nStrike the gong and the pool rises. Velratha knows how to raise it without one." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Zul'Farrak", expansion = 0, order = 139, charModel = true, box = { -0.22, -0.07, 1.34 }, title = "Keeper of the Sacred Pool" },
    { id = "antusul", entry = 8127, name = "Antu'sul", label = "Antu'sul", level = 46, display = 7353, height = 2.6, span = 2.6, school = "nature", pool = "classic_dungeon", icon = "Interface\\Icons\\Ability_Hunter_Pet_Crocolisk", profile = "caster", kit = { 11894, 16006, 15501, 8376, 11899, 11895 }, passives = {}, talentInfo = { { name = "Voice of the Storm", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", text = "Your Nature damage is increased by 8%." }, { name = "Brood Keeper", icon = "Interface\\Icons\\Spell_Nature_HealingWaveGreater", text = "Your healing is increased by 10%." }, { name = "Basilisk Hide", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your armor is increased by 12%." }, { name = "Totemic Focus", icon = "Interface\\Icons\\Spell_Nature_StrengthOfEarthTotem02", text = "The mana cost of your Nature spells is reduced by 8%." }, { name = "My Beautiful Children", icon = "Interface\\Icons\\Ability_Hunter_Pet_Crocolisk", text = "Reduces the cooldown of Children of Sul by 20 sec.\n\nThe children of Sul will protect their master. They hatch faster when he calls." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Zul'Farrak", expansion = 0, order = 136, summons = { [11894] = true }, charModel = true, box = { -0.03, 0.03, 1.32 }, title = "Overseer of Sul" },
    { id = "baelog", entry = 6906, name = "Baelog", label = "Baelog", level = 39, display = 5710, height = 1.6, span = 1.6, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Weapon_Bow_02", profile = "bruiser", kit = { 15620, 14443, 17174, 14516, 261, 5200 }, passives = {}, talentInfo = { { name = "Steady Aim", icon = "Interface\\Icons\\Ability_Marksmanship", text = "Your chance to critically hit with melee and ranged attacks is increased by 5%." }, { name = "Explorer's Stride", icon = "Interface\\Icons\\Ability_Rogue_Sprint", text = "Your movement speed is increased by 8%." }, { name = "Dwarven Grit", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your maximum health is increased by 6%." }, { name = "Treasure Hunter's Edge", icon = "Interface\\Icons\\INV_Weapon_Bow_02", text = "Your attack power is increased by 8%." }, { name = "Three Lost Dwarves", icon = "Interface\\Icons\\INV_Shield_05", text = "Reduces the cooldown of Olaf, Hold the Line by 20 sec.\n\nBaelog shoots, Eric runs and Olaf blocks. They have been doing it together for a very long time." } }, tips = { [261] = "Shout for Olaf: your shield-bearing kinsman charges in and fights beside you for 20 sec.", [5200] = "Whistle for Eric \"The Swift\": he dashes in and fights beside you for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Uldaman", expansion = 0, order = 61, summons = { [261] = true, [5200] = true }, charModel = true, box = { -0.10, -0.02, 0.79 }, title = "Lost Dwarf of Uldaman" },
    { id = "revelosh", entry = 2160, name = "Revelosh", label = "Revelosh", level = 39, display = 976, height = 1.9, span = 1.9, school = "nature", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", profile = "caster", kit = { 15801, 15117, 12548, 11986 }, passives = {}, talentInfo = { { name = "Stormcaller", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your Nature damage is increased by 10%." }, { name = "Deep Stone Hide", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your armor is increased by 12%." }, { name = "Crackling Focus", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Trogg Vigour", icon = "Interface\\Icons\\Ability_Racial_Cannibalize", text = "Your maximum health is increased by 6%." }, { name = "Static in the Stone", icon = "Interface\\Icons\\Spell_Nature_LightningBolt", text = "Your damaging spells have a 10% chance to loose a Lightning Bolt. Once every 8 sec.\n\nThe excavation hums with the old titans' power, and Revelosh has learned to drink from it." }, { name = "Arcing Storm", icon = "Interface\\Icons\\Spell_Nature_CallStorm", text = "Reduces the cooldown of your Chain Lightning by 3 sec.\n\nDwarven wires still run through Uldaman's walls. Revelosh lets the lightning ride them." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Uldaman", expansion = 0, order = 60, as = 6910, box = { 0.39, 0.01, 0.94 }, title = "Stonevault Stormcaller" },
    { id = "ironaya", entry = 7228, name = "Ironaya", label = "Ironaya", level = 39, display = 6089, height = 8.8, span = 8.8, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Hammer_09", profile = "tank", kit = { 37548, 8374, 10101, 11876, 15062 }, passives = {}, talentInfo = { { name = "Titan Stone Body", icon = "Interface\\Icons\\INV_Misc_ArmorKit_14", text = "Your armor is increased by 20%." }, { name = "Watcher's Endurance", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", text = "Your maximum health is increased by 10%." }, { name = "Keeper's Guard", icon = "Interface\\Icons\\Ability_Parry", text = "Your chance to parry is increased by 5%." }, { name = "Unyielding", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Damage you take is reduced by 4%." }, { name = "Secrets of the Makers", icon = "Interface\\Icons\\Ability_WarStomp", text = "Reduces the cooldown of your War Stomp by 10 sec.\n\nIronaya was made to guard, not to rest. The vault floor remembers each of her steps." } }, tips = {}, visualKit = 437, soundTransform = 5851, soundDeath = 0, flies = false, wave = 4, instance = "Uldaman", expansion = 0, order = 62, box = { 0.05, -0.43, 4.39 }, view = { -2.3880, 0.0000, 0.7260 }, voices = { { 5851, 3.5, true, "None may steal the secrets of the Makers!" } }, title = "Guardian of the Makers" },
    { id = "archaedas", entry = 2748, name = "Archaedas", label = "Archaedas", level = 40, display = 5988, height = 11.1, span = 11.1, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Hammer_04", profile = "bruiser", kit = { 6524, 18944, 13737, 261, 5200 }, passives = {}, talentInfo = { { name = "Stone of the Makers", icon = "Interface\\Icons\\INV_Misc_ArmorKit_14", text = "Your armor is increased by 15%." }, { name = "Titan's Hammer", icon = "Interface\\Icons\\INV_Hammer_04", text = "Your attack power is increased by 8%." }, { name = "Ancient Endurance", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", text = "Your maximum health is increased by 8%." }, { name = "Watcher's Vigil", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Damage you take is reduced by 4%." }, { name = "Reckless Mortal", icon = "Interface\\Icons\\Ability_Warrior_SavageBlow", text = "Your melee hits have an 8% chance to deal a Mortal Strike. Once every 12 sec.\n\nReckless mortal! The watcher answers every blow the way the Makers built him to." }, { name = "Defend the Discs", icon = "Interface\\Icons\\Spell_Nature_EarthBindTotem", text = "Reduces the cooldown of Awake, Ye Servants by 20 sec.\n\nUldaman's halls are lined with sleeping earthen. Archaedas needs only to call." } }, tips = { [261] = "Awake, ye servants! Two Earthen Guardians shake off their stone and fight for you for 20 sec.", [5200] = "To my side, brothers! A Vault Warder wakes and fights for you for 20 sec." }, visualKit = 437, soundTransform = 5855, soundDeath = 5858, flies = false, wave = 4, instance = "Uldaman", expansion = 0, order = 64, summons = { [261] = true, [5200] = true }, box = { -0.10, -0.29, 5.55 }, voices = { { 5855, 7.8, true, "Who dares awaken Archaedas? Who dares the wrath of the Makers?" }, { 5856, 4.5, true, "Awake, ye servants! Defend the Disks!" }, { 5857, 5.2, true, "To my side, brothers! For the Makers!" }, { 5858, 2.6, true, "Reckless mortal!" } }, title = "Ancient Stone Watcher" },
