    { id = "tinkerer_gizlock", entry = 13601, name = "Tinkerer Gizlock", label = "Tinkerer Gizlock", level = 48, display = 7125, height = 1.4, span = 1.4, school = "fire", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Misc_Bomb_08", profile = "glass_cannon", kit = { 16100, 7978, 21833, 29419, 11972 }, passives = {}, talentInfo = { { name = "Explosive Expertise", icon = "Interface\\Icons\\INV_Misc_Bomb_08", text = "Your Fire damage is increased by 10%." }, { name = "Steady Barrel", icon = "Interface\\Icons\\INV_Weapon_Rifle_01", text = "Your chance to critically hit with melee and ranged attacks is increased by 5%." }, { name = "Goblin Hustle", icon = "Interface\\Icons\\Ability_Rogue_Sprint", text = "Your movement speed is increased by 8%." }, { name = "Gear Shield", icon = "Interface\\Icons\\INV_Shield_05", text = "Your chance to block is increased by 5%." }, { name = "Mine! Mine! Mine!", icon = "Interface\\Icons\\INV_Misc_Bomb_05", text = "Your melee and ranged hits have an 8% chance to lob Gizlock's Bomb. Once every 12 sec.\n\nGizlock is the ruler of this domain. He has a bomb for anyone who disagrees." }, { name = "That Is Unless It Explodes", icon = "Interface\\Icons\\INV_Misc_Bomb_02", text = "Reduces the cooldown of your Goblin Dragon Gun by 8 sec.\n\nGoblin engineering: faster, hotter and only occasionally fatal to the goblin." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Maraudon", expansion = 0, order = 130, charModel = true, box = { 0.01, -0.02, 0.69 }, title = "Goblin of the Earth Song Falls" },
