    { id = "mother_smolderweb", entry = 11370, name = "Mother Smolderweb", label = "Mother Smolderweb", level = 59, display = 963, height = 2.1, span = 6.1, school = "nature", pool = "classic_dungeon", icon = "Interface\\Icons\\Ability_Hunter_Pet_Spider", profile = "bruiser", kit = { 16104, 745, 21067, 7992, 261 }, passives = {}, talentInfo = { { name = "Crystal Carapace", icon = "Interface\\Icons\\INV_Misc_Gem_Crystal_02", text = "Your armor is increased by 15%." }, { name = "Brood Venom", icon = "Interface\\Icons\\Spell_Nature_NullifyPoison", text = "Your Nature damage is increased by 10%." }, { name = "Eight Swift Legs", icon = "Interface\\Icons\\Ability_Hunter_Pet_Spider", text = "Your movement speed is increased by 8%." }, { name = "Mother's Bulk", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your maximum health is increased by 8%." }, { name = "Mother's Milk", icon = "Interface\\Icons\\Ability_Creature_Poison_06", text = "Your melee hits have an 8% chance to inject Slowing Poison. Once every 12 sec.\n\nHer venom was meant for her young. Whatever she bites grows slow and heavy with it." } }, tips = { [261] = "Your egg sacs split: three Spire Spiderlings hatch and fight for you for 20 sec." }, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Zul'Gurub", expansion = 0, order = 250, as = 10596, summons = { [261] = true }, box = { 0.84, -0.00, 1.01 }, title = "Brood Mother of the Spire" },
    { id = "overlord_wyrmthalak", entry = 9568, name = "Overlord Wyrmthalak", label = "Overlord Wyrmthalak", level = 60, display = 8711, height = 6.6, span = 10.4, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", profile = "bruiser", kit = { 20691, 11130, 23511, 261, 5200 }, passives = {}, talentInfo = { { name = "Black Dragonspawn Might", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Black", text = "Your attack power is increased by 8%." }, { name = "Scales of Blackrock", icon = "Interface\\Icons\\INV_Misc_MonsterScales_07", text = "Your armor is increased by 15%." }, { name = "Fireblooded", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Your Fire resistance is increased by 30." }, { name = "Reach of the Polearm", icon = "Interface\\Icons\\INV_Spear_06", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Overlord's Command", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your melee hits have a 10% chance to Cleave. Once every 8 sec.\n\nWyrmthalak commands the spire's legions by example: nothing in reach of his polearm stays standing." } }, tips = { [261] = "Call for help: a Spirestone Warlord answers and fights for you for 20 sec.", [5200] = "Call for help: a Smolderthorn Berserker answers and fights for you for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Blackrock Spire", expansion = 0, order = 184, summons = { [261] = true, [5200] = true }, box = { -1.25, -0.61, 3.25 }, title = "Overlord of the Lower Spire" },
    { id = "the_unforgiven", entry = 10516, name = "The Unforgiven", label = "The Unforgiven", level = 57, display = 10771, height = 6.9, span = 6.9, school = "frost", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Frost_FrostNova", profile = "bruiser", kit = { 14907, 50349, 50577, 261 }, passives = { 12529 }, talentInfo = { { name = "Cold of the Grave", icon = "Interface\\Icons\\Spell_Frost_FrostArmor02", text = "Your Frost damage is increased by 8%." }, { name = "Incorporeal", icon = "Interface\\Icons\\Spell_Shadow_GhostKey", text = "Your chance to dodge is increased by 6%." }, { name = "Endless Grudge", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Your maximum health is increased by 8%." }, { name = "Culled Strength", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your Physical damage is increased by 6%." }, { name = "None Forgiven", icon = "Interface\\Icons\\Spell_Shadow_PsychicScream", text = "Reduces the cooldown of your Unforgiving Wail by 15 sec.\n\nArthas gave the city no mercy. Its dead return the favour to every living thing that walks its streets." } }, tips = { [261] = "The dead of Stratholme answer you: two Vengeful Phantoms rise from the ashes and fight at your side for 20 sec." }, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Stratholme", expansion = 0, order = 190, summons = { [261] = true }, box = { -0.48, -0.38, 2.78 }, view = { -1.5485, 0.0000, 0.5170 }, title = "Shade of the Culling" },
    { id = "hearthsinger_forresten", entry = 10558, name = "Hearthsinger Forresten", label = "Hearthsinger Forresten", level = 57, display = 10482, height = 2.1, span = 2.1, school = "shadow", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Weapon_Bow_07", profile = "glass_cannon", kit = { 16100, 14443, 16798, 16244, 16331 }, passives = {}, talentInfo = { { name = "Hearthsinger's Aim", icon = "Interface\\Icons\\Ability_TrueShot", text = "Your chance to critically strike with physical attacks is increased by 5%." }, { name = "Arrows of the Dead", icon = "Interface\\Icons\\Ability_SearingArrow", text = "Your Physical damage is increased by 8%." }, { name = "Spectral Step", icon = "Interface\\Icons\\Spell_Shadow_GhostKey", text = "Your movement speed is increased by 10%." }, { name = "Half in the World", icon = "Interface\\Icons\\Spell_Magic_LesserInvisibilty", text = "Your chance to dodge is increased by 5%." }, { name = "Encore", icon = "Interface\\Icons\\Ability_UpgradeMoonGlaive", text = "Your shots have an 8% chance to loose a free Multi-Shot. Once every 12 sec.\n\nThe crowd in the square is long dead. Forresten plays for them anyway, and always gives an encore." }, { name = "Last Lullaby", icon = "Interface\\Icons\\Spell_Holy_Silence", text = "Reduces the cooldown of your Enchanting Lullaby by 15 sec.\n\nThe last song he sang before the Culling was a lullaby. He has been singing it ever since." } }, tips = { [16331] = "Fade half out of the world: your chance to dodge rises by 50% until cancelled." }, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Stratholme", expansion = 0, order = 189, charModel = true, box = { -0.10, -0.00, 1.06 }, title = "Lost Bard of Stratholme" },
    { id = "magistrate_barthilas", entry = 10435, name = "Magistrate Barthilas", label = "Magistrate Barthilas", level = 58, display = 10433, height = 2.8, span = 4.6, school = "shadow", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", profile = "bruiser", kit = { 16793, 12795, 20578, 13704 }, passives = { 16791 }, talentInfo = { { name = "Swollen with Plague", icon = "Interface\\Icons\\Spell_Shadow_CallofBone", text = "Your maximum health is increased by 10%." }, { name = "Grip of the Grave", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain", text = "Your Shadow damage is increased by 8%." }, { name = "Dead Weight", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your Physical damage is increased by 6%." }, { name = "Rotted Hide", icon = "Interface\\Icons\\INV_Misc_Pelt_Bear_Ruin_02", text = "Your armor is increased by 10%." }, { name = "Hungering Grip", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Your melee hits have a 6% chance to set off a Draining Blow. Once every 12 sec.\n\nThe magistrate always took his due. The thing he became takes it in blood." } }, tips = { [20578] = "Feast on the fallen, restoring 8% of your health every 2 sec. for 10 sec." }, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Stratholme", expansion = 0, order = 191, box = { 0.55, -0.22, 1.42 }, view = { -8.6284, 0.3925, -0.5309 }, title = "Magistrate of Stratholme", visages = { "magistrate_barthilas_human" }, shape = "Risen" },
    { id = "magistrate_barthilas_human", entry = 2335, name = "Magistrate Burnside", label = "Magistrate Barthilas", level = 30, display = 3637, height = 2.1, span = 2.1, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Misc_Note_02", profile = "bruiser", kit = { 10887, 14099, 16793, 36589 }, passives = { 16791 }, talentInfo = { { name = "Weight of the Law", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your Physical damage is increased by 8%." }, { name = "Swollen with Plague", icon = "Interface\\Icons\\Spell_Shadow_CallofBone", text = "Your maximum health is increased by 8%." }, { name = "Official Business", icon = "Interface\\Icons\\Ability_Rogue_Sprint", text = "Your movement speed is increased by 8%." }, { name = "Robes over Rot", icon = "Interface\\Icons\\INV_Chest_Cloth_21", text = "Your armor is increased by 10%." }, { name = "Through the Service Gate", icon = "Interface\\Icons\\INV_Misc_Horn_01", text = "Reduces the cooldown of your Warn the Baron by 20 sec.\n\nEvery time the Service Gate is breached, the magistrate runs the same road to the Baron. He knows it well by now." }, { name = "Order Must Be Kept", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Your melee hits have a 6% chance to set off a Draining Blow. Once every 12 sec.\n\nThe magistrate always took his due. Now he takes it in blood." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Hillsbrad Foothills", expansion = 0, order = 98, charModel = true, box = { -0.10, -0.00, 1.06 }, title = "Magistrate of Stratholme", visageOf = "magistrate_barthilas", shape = "Magistrate" },
    { id = "timmy_the_cruel", entry = 10808, name = "Timmy the Cruel", label = "Timmy the Cruel", level = 58, display = 571, height = 3.0, span = 4.3, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Shadow_AnimateDead", profile = "bruiser", kit = { 17470, 67749, 43356, 16458, 8599 }, passives = { 3417 }, talentInfo = { { name = "Cruelty", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your Physical damage is increased by 8%." }, { name = "Bloated on the Dead", icon = "Interface\\Icons\\Spell_Shadow_CallofBone", text = "Your maximum health is increased by 10%." }, { name = "Ghoul's Hunger", icon = "Interface\\Icons\\Ability_Racial_Cannibalize", text = "Your attack speed is increased by 8%." }, { name = "Tough Hide", icon = "Interface\\Icons\\INV_Misc_Pelt_Bear_Ruin_02", text = "Your armor is increased by 10%." }, { name = "Ravenous", icon = "Interface\\Icons\\Ability_GhoulFrenzy", text = "Your melee hits have an 8% chance to set off a Ravenous Claw. Once every 10 sec.\n\nTimmy is always hungry. Timmy is always Timmy." }, { name = "TIMMY!", icon = "Interface\\Icons\\Ability_Druid_ChallangingRoar", text = "Reduces the cooldown of your Enrage by 15 sec.\n\nHe only knows the one word, and he shouts it every time he gets angry. He gets angry often." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Stratholme", expansion = 0, order = 192, box = { 0.44, 0.12, 1.43 }, title = "Terror of Crusaders' Square" },
    { id = "baroness_anastari", entry = 10436, name = "Baroness Anastari", label = "Baroness Anastari", level = 59, display = 10698, height = 4.8, span = 4.8, school = "shadow", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Shadow_Possession", profile = "caster", kit = { 16565, 16867, 18327, 17244, 12845 }, passives = {}, talentInfo = { { name = "Grief of the Baroness", icon = "Interface\\Icons\\Spell_Shadow_PsychicScream", text = "Your Shadow damage is increased by 10%." }, { name = "Incorporeal", icon = "Interface\\Icons\\Spell_Magic_LesserInvisibilty", text = "Damage you take is reduced by 5%." }, { name = "Noble Poise", icon = "Interface\\Icons\\Spell_Shadow_SoulLeech_3", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Spectral Drift", icon = "Interface\\Icons\\Spell_Shadow_GhostKey", text = "Your movement speed is increased by 8%." }, { name = "Anguish of the Anastari", icon = "Interface\\Icons\\Spell_Shadow_DeathScream", text = "Increases the damage of your Banshee Wail by 15%.\n\nThe Anastari line ended in Stratholme's fall. Its last baroness never stopped mourning it." }, { name = "Curse of the Ziggurat", icon = "Interface\\Icons\\Spell_Shadow_CurseOfTounges", text = "Reduces the cooldown of your Banshee Curse by 5 sec.\n\nThose who climb the first ziggurat feel her curse long before they see her." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Stratholme", expansion = 0, order = 194, box = { -0.58, 0.00, 2.36 }, title = "Keeper of the First Ziggurat" },
    { id = "nerubenkan", entry = 10437, name = "Nerub'enkan", label = "Nerub'enkan", level = 60, display = 9793, height = 4.6, span = 6.1, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\Ability_Hunter_Pet_Spider", profile = "bruiser", kit = { 31602, 4962, 6016, 17235 }, passives = {}, talentInfo = { { name = "Chitin Blades", icon = "Interface\\Icons\\Ability_Hunter_Pet_Spider", text = "Your Physical damage is increased by 8%." }, { name = "Carapace", icon = "Interface\\Icons\\INV_Misc_AhnQirajTrinket_05", text = "Your armor is increased by 15%." }, { name = "Many-Legged", icon = "Interface\\Icons\\Ability_Rogue_SliceDice", text = "Your attack speed is increased by 6%." }, { name = "Nerubian Resolve", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Your maximum health is increased by 8%." }, { name = "Strands of the Ziggurat", icon = "Interface\\Icons\\Spell_Nature_EarthBind", text = "Your melee hits have a 5% chance to encase the enemy in webs. Once every 20 sec.\n\nThe halls of the second ziggurat are hung with webs. Few who walk into them walk out." }, { name = "Endless Swarm", icon = "Interface\\Icons\\Spell_Nature_InsectSwarm", text = "Reduces the cooldown of your Crypt Scarabs by 2 sec.\n\nKill one scarab and ten more crawl out of the dead. Nerub'enkan never runs out." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Stratholme", expansion = 0, order = 198, summons = { [17235] = true }, box = { -0.44, -0.00, 2.07 }, title = "Keeper of the Second Ziggurat" },
    { id = "archivist_galford", entry = 10811, name = "Archivist Galford", label = "Archivist Galford", level = 60, display = 10544, height = 2.1, span = 2.1, school = "fire", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Misc_Book_07", profile = "caster", kit = { 17274, 17366, 17293, 8814 }, passives = {}, talentInfo = { { name = "Burning Pages", icon = "Interface\\Icons\\Spell_Fire_FlameBolt", text = "Your Fire damage is increased by 10%." }, { name = "Archivist's Eye", icon = "Interface\\Icons\\INV_Misc_Book_07", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Careful Hand", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Reduces the mana cost of your Fire spells by 8%." }, { name = "Scarlet Conviction", icon = "Interface\\Icons\\Spell_Holy_SealOfFury", text = "Your maximum health is increased by 6%." }, { name = "Kindling of Records", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "Reduces the cooldown of your Pyroblast by 3 sec.\n\nEvery heresy the Crusade ever recorded is in his archive. He knows which pages burn hottest." }, { name = "Ashes of the Archive", icon = "Interface\\Icons\\Spell_Fire_SealOfFire", text = "Your spells have a 10% chance to set off a Fire Nova around you. Once every 12 sec.\n\nThe archive was meant to be burned. Galford would rather burn whoever came to do it." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Stratholme", expansion = 0, order = 195, charModel = true, box = { -0.10, -0.00, 1.06 }, title = "Keeper of the Scarlet Archive" },
    { id = "cannon_master_willey", entry = 10997, name = "Cannon Master Willey", label = "Cannon Master Willey", level = 60, display = 10674, height = 2.1, span = 2.1, school = "fire", pool = "classic_dungeon", icon = "Interface\\Icons\\INV_Weapon_Rifle_01", profile = "bruiser", kit = { 10101, 15615, 22334, 17279 }, passives = { 16615 }, talentInfo = { { name = "Gunpowder Drill", icon = "Interface\\Icons\\INV_Ammo_Bullet_02", text = "Your Physical damage is increased by 8%." }, { name = "Twin Hatchets", icon = "Interface\\Icons\\Ability_DualWield", text = "Your attack speed is increased by 8%." }, { name = "Powder-Burned", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire resistance is increased by 40." }, { name = "Scarlet Plate", icon = "Interface\\Icons\\INV_Chest_Plate16", text = "Your armor is increased by 10%." }, { name = "Reload!", icon = "Interface\\Icons\\INV_Misc_Bomb_05", text = "Reduces the cooldown of your Cannon Blast by 5 sec.\n\nA cannon master who reloads slowly is soon a dead cannon master." }, { name = "Point Blank", icon = "Interface\\Icons\\INV_Weapon_Rifle_01", text = "Your melee hits have a 6% chance to set off a Cannon Blast. Once every 15 sec.\n\nClose enough to swing a hatchet is close enough to fire the rifle, as far as Willey is concerned." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Stratholme", expansion = 0, order = 196, summons = { [17279] = true }, charModel = true, box = { -0.10, -0.00, 1.06 }, title = "Master of the Scarlet Guns" },
    { id = "malor_the_zealous", entry = 11032, name = "Malor the Zealous", label = "Malor the Zealous", level = 60, display = 10458, height = 2.1, span = 2.1, school = "holy", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Holy_HolyBolt", profile = "bruiser", kit = { 17281, 12734, 16172, 15493, 17233 }, passives = {}, talentInfo = { { name = "Zeal of the Crusade", icon = "Interface\\Icons\\Spell_Holy_HolyBolt", text = "Your Holy damage is increased by 10%." }, { name = "Scarlet Devotion", icon = "Interface\\Icons\\Spell_Holy_FlashHeal", text = "Your healing done is increased by 10%." }, { name = "Bastion Plate", icon = "Interface\\Icons\\INV_Chest_Plate16", text = "Your armor is increased by 10%." }, { name = "Heavy Hammer", icon = "Interface\\Icons\\INV_Hammer_04", text = "Your Physical damage is increased by 6%." }, { name = "Zealot's Devotion", icon = "Interface\\Icons\\Spell_Holy_Heal02", text = "Reduces the mana cost of your Holy Light by 20%.\n\nMalor prays as hard as he hits. The Light, he believes, has never once refused him." }, { name = "Righteous Zeal", icon = "Interface\\Icons\\Spell_Holy_SealOfMight", text = "Your melee hits have an 8% chance to set off a Zealous Strike. Once every 10 sec.\n\nThe zealous do not stop to wonder whether their foe deserves the hammer." } }, tips = {}, visualKit = 154, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Stratholme", expansion = 0, order = 197, charModel = true, box = { -0.10, -0.00, 1.06 }, title = "Zealot of the Scarlet Bastion" },
    { id = "maleki_the_pallid", entry = 10438, name = "Maleki the Pallid", label = "Maleki the Pallid", level = 61, display = 10546, height = 2.1, span = 2.1, school = "frost", pool = "classic_dungeon", icon = "Interface\\Icons\\Spell_Frost_Glacier", profile = "caster", kit = { 17503, 16869, 17238, 17243 }, passives = { 12544 }, talentInfo = { { name = "Pallid Chill", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "Hunger of the Grave", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain02", text = "Your Shadow damage is increased by 8%." }, { name = "Cold Focus", icon = "Interface\\Icons\\Spell_Frost_IceShock", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Ziggurat Ward", icon = "Interface\\Icons\\Spell_Frost_FrostArmor02", text = "Damage you take is reduced by 5%." }, { name = "Tomb Keeper", icon = "Interface\\Icons\\Spell_Frost_Glacier", text = "Reduces the cooldown of your Ice Tomb by 15 sec.\n\nThe third ziggurat is a tomb already. Maleki only adds to its occupants." }, { name = "Rime of the Ziggurat", icon = "Interface\\Icons\\Spell_Frost_Frostbolt", text = "Your spells have a 10% chance to loose a free Frostbolt. Once every 10 sec.\n\nCold follows Maleki through the ziggurat's halls like a faithful hound." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Stratholme", expansion = 0, order = 199, charModel = true, box = { -0.10, -0.00, 1.06 }, title = "Keeper of the Third Ziggurat" },
    { id = "emogg_the_crusher", entry = 14267, name = "Emogg the Crusher", label = "Emogg the Crusher", level = 19, display = 3189, height = 2.5, span = 2.5, school = "physical", pool = "rare", icon = "Interface\\Icons\\Ability_Warrior_PunishingBlow", profile = "bruiser", kit = { 33661, 8078, 5164, 28371 }, passives = {}, talentInfo = { { name = "Crusher", icon = "Interface\\Icons\\Ability_Warrior_PunishingBlow", text = "Your Physical damage is increased by 8%." }, { name = "Ogre Hide", icon = "Interface\\Icons\\INV_Misc_Pelt_Bear_Ruin_02", text = "Your armor is increased by 10%." }, { name = "Big Emogg", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your maximum health is increased by 8%." }, { name = "Heavy Hand", icon = "Interface\\Icons\\INV_Axe_03", text = "Your chance to critically strike with melee attacks is increased by 4%." }, { name = "Smash Again!", icon = "Interface\\Icons\\Spell_Nature_ThunderClap", text = "Your melee hits have a 6% chance to stomp the ground again. Once every 15 sec.\n\nEmogg does not know when a fight is over. He just keeps smashing until nothing moves." }, { name = "You Die!", icon = "Interface\\Icons\\Ability_Druid_ChallangingRoar", text = "Reduces the cooldown of your Enrage by 15 sec.\n\nIt takes very little to make Emogg angry. A dwarf walking past will do." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Loch Modan", expansion = 0, order = 40, box = { -0.02, -0.00, 1.22 }, view = { -0.2045, 0.0000, 0.0330 }, title = "Ogre of Loch Modan" },
    { id = "siege_golem", entry = 2749, name = "Siege Golem", label = "Siege Golem", level = 40, display = 13869, height = 5.0, span = 5.3, school = "fire", pool = "rare", icon = "Interface\\Icons\\INV_Gizmo_02", profile = "bruiser", kit = { 9576, 24611, 17501, 12612 }, passives = {}, talentInfo = { { name = "Obsidian Plating", icon = "Interface\\Icons\\INV_Misc_Orb_05", text = "Your armor is increased by 15%." }, { name = "Powder Charges", icon = "Interface\\Icons\\Spell_Fire_Fireball", text = "Your Fire damage is increased by 8%." }, { name = "Iron Frame", icon = "Interface\\Icons\\INV_Gizmo_02", text = "Your maximum health is increased by 8%." }, { name = "Fireproof Hull", icon = "Interface\\Icons\\Spell_Fire_FireArmor", text = "Your Fire resistance is increased by 40." }, { name = "Siege Engineering", icon = "Interface\\Icons\\INV_Misc_Bomb_04", text = "Reduces the cooldown of your Mortar Round by 5 sec.\n\nDark Iron engineers built it to flatten walls from afar. It reloads faster than any crew could." }, { name = "Loaded Chamber", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "Your melee hits have a 6% chance to fire a free Siege Shell. Once every 12 sec.\n\nIts cannon arm is never quite empty. Stand too close and you find out." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Badlands", expansion = 0, order = 115, box = { 0.79, -0.20, 2.48 }, view = { -1.2656, 0.0000, 0.3410 }, title = "Dark Iron War Machine" },
    { id = "narillasanz", entry = 2447, name = "Narillasanz", label = "Narillasanz", level = 44, display = 6371, height = 12.1, span = 20.4, school = "fire", pool = "rare", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Red", profile = "caster", kit = { 18435, 9574, 13374, 8362 }, passives = {}, talentInfo = { { name = "Red Flame", icon = "Interface\\Icons\\Spell_Fire_Fire", text = "Your Fire damage is increased by 10%." }, { name = "Life-Binder's Brood", icon = "Interface\\Icons\\Spell_Holy_Renew", text = "Your healing done is increased by 10%." }, { name = "Drake Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_15", text = "Your armor is increased by 12%." }, { name = "Dragonfire Focus", icon = "Interface\\Icons\\Spell_Fire_FlameBolt", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Deep Breath", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Red", text = "Reduces the cooldown of your Flame Breath by 5 sec.\n\nA drake that lives alone learns to breathe fire often. There is no one else to do it." }, { name = "Kindled Scales", icon = "Interface\\Icons\\Spell_Fire_Fireball02", text = "Your spells have a 10% chance to spit a free Dragonfire. Once every 8 sec.\n\nRed dragonfire does not go out easily, and neither does Narillasanz's temper." } }, tips = {}, visualKit = 286, soundTransform = 0, soundDeath = 0, flies = true, wave = 4, zone = "Alterac Mountains", expansion = 0, order = 121, box = { -1.85, -0.00, 5.48 }, title = "Red Drake of Alterac" },
    { id = "anathemus", entry = 2754, name = "Anathemus", label = "Anathemus", level = 45, display = 10040, height = 10.0, span = 10.6, school = "nature", pool = "rare", icon = "Interface\\Icons\\INV_Stone_10", profile = "tank", kit = { 37548, 23392, 25056, 21909, 18376 }, passives = {}, talentInfo = { { name = "Stone Skin", icon = "Interface\\Icons\\INV_Stone_10", text = "Your armor is increased by 20%." }, { name = "Giant's Bulk", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your maximum health is increased by 10%." }, { name = "Curse Given Flesh", icon = "Interface\\Icons\\Spell_Shadow_AbominationExplosion", text = "Your Shadow damage is increased by 10%." }, { name = "Unmoved", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Damage you take is reduced by 5%." }, { name = "Long Arm", icon = "Interface\\Icons\\INV_Stone_15", text = "Reduces the cooldown of your Boulder by 3 sec.\n\nThe Badlands are full of rocks, and Anathemus has an arm for every one of them." }, { name = "Spreading Anathema", icon = "Interface\\Icons\\Spell_Shadow_CurseOfTounges", text = "When you are hit, you have a 5% chance to lay your Anathema on the enemies around you. Once every 20 sec.\n\nStrike the cursed giant and the curse spreads to you. The Badlands learned that long ago." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Badlands", expansion = 0, order = 116, box = { 0.12, -0.09, 4.98 }, title = "Cursed Giant of the Badlands" },
    { id = "lord_captain_wyrmak", entry = 14445, name = "Lord Captain Wyrmak", label = "Lord Captain Wyrmak", level = 45, display = 7976, height = 5.8, span = 9.1, school = "nature", pool = "rare", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Green", profile = "tank", kit = { 37548, 15589, 15572, 12884, 12098 }, passives = {}, talentInfo = { { name = "Dragonscale Plate", icon = "Interface\\Icons\\INV_Chest_Plate16", text = "Your armor is increased by 15%." }, { name = "Green Flight's Resolve", icon = "Interface\\Icons\\Spell_Nature_Regeneration", text = "Your maximum health is increased by 8%." }, { name = "Swamp Venom", icon = "Interface\\Icons\\Spell_Nature_Acid_01", text = "Your Nature damage is increased by 10%." }, { name = "Polearm Drill", icon = "Interface\\Icons\\INV_Spear_06", text = "Your chance to parry is increased by 5%." }, { name = "Wide Sweep", icon = "Interface\\Icons\\INV_Weapon_Halberd_02", text = "Increases the radius of your Polearm Sweep by 20%.\n\nA halberd in a dragonspawn's hands reaches farther than any soldier expects." }, { name = "Acid Blood", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "When you are hit, you have a 4% chance to breathe Swamp Breath at your foes. Once every 20 sec.\n\nWound a green wyrmkin and the swamp answers for it." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Swamp of Sorrows", expansion = 0, order = 114, box = { -1.09, -0.54, 2.85 }, view = { -3.2485, 0.0000, 0.7590 }, title = "Lord Captain of the Green Wyrmkin" },
    { id = "mithrethis_the_enchanter", entry = 8217, name = "Mith'rethis the Enchanter", label = "Mith'rethis the Enchanter", level = 52, display = 28248, height = 3.0, span = 3.0, school = "arcane", pool = "rare", icon = "Interface\\Icons\\Spell_Holy_MagicalSentry", profile = "caster", kit = { 15254, 11436, 13745, 17740 }, passives = {}, talentInfo = { { name = "Enchanter's Craft", icon = "Interface\\Icons\\Spell_Holy_MagicalSentry", text = "Your Arcane damage is increased by 10%." }, { name = "Quickened Mind", icon = "Interface\\Icons\\Spell_Nature_Invisibilty", text = "Your casting speed is increased by 6%." }, { name = "Warded Hide", icon = "Interface\\Icons\\Spell_Shadow_DetectLesserInvisibility", text = "Damage you take is reduced by 5%." }, { name = "Arcane Thrift", icon = "Interface\\Icons\\Spell_Arcane_ArcaneResilience", text = "Reduces the mana cost of your Arcane spells by 8%." }, { name = "Lingering Sloth", icon = "Interface\\Icons\\Spell_Nature_Slow", text = "Reduces the cooldown of your Slow by 5 sec.\n\nMith'rethis weaves sloth into everything he touches. His enemies rarely notice until it is too late to run." }, { name = "Arcane Echo", icon = "Interface\\Icons\\Spell_Nature_WispSplode", text = "Your spells have a 10% chance to release a free Arcane Explosion. Once every 10 sec.\n\nAn enchanter's power leaks. His leaks hurt." } }, tips = {}, visualKit = 1005, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "The Hinterlands", expansion = 0, order = 119, charModel = true, box = { -0.04, 0.03, 1.44 }, title = "Troll Enchanter of the Hinterlands" },
    { id = "zaricotl", entry = 2931, name = "Zaricotl", label = "Zaricotl", level = 55, display = 1210, height = 11.4, span = 11.4, school = "physical", pool = "rare", icon = "Interface\\Icons\\Ability_Hunter_Pet_Vulture", profile = "glass_cannon", kit = { 18144, 13445, 31273, 44531, 20578 }, passives = {}, talentInfo = { { name = "Hooked Beak", icon = "Interface\\Icons\\Ability_Hunter_Pet_Vulture", text = "Your Physical damage is increased by 8%." }, { name = "Circling", icon = "Interface\\Icons\\Ability_Druid_Dash", text = "Your movement speed is increased by 10%." }, { name = "Scavenger's Instinct", icon = "Interface\\Icons\\Ability_Hunter_EagleEye", text = "Your chance to critically strike with melee attacks is increased by 5%." }, { name = "Ragged Feathers", icon = "Interface\\Icons\\INV_Feather_05", text = "Your chance to dodge is increased by 5%." }, { name = "Next Meal", icon = "Interface\\Icons\\Ability_Racial_Cannibalize", text = "Reduces the cooldown of your Feast on the Fallen by 20 sec.\n\nZaricotl seems much calmer once it has eaten. It is never calm for long." }, { name = "Open Wounds", icon = "Interface\\Icons\\Ability_Druid_Rake", text = "Your melee hits have an 8% chance to Tear Flesh. Once every 10 sec.\n\nA carrion bird does not need its prey dead yet. It only needs it bleeding." } }, tips = { [20578] = "Feed on the remains of the fallen, restoring 8% of your health every 2 sec. for 10 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = true, wave = 4, zone = "Badlands", expansion = 0, order = 117, box = { -0.49, 0.17, 6.77 }, title = "Carrion Lord of the Badlands" },
