    { id = "skarr_the_unbreakable", entry = 11498, name = "Skarr the Unbreakable", label = "Skarr the Unbreakable", level = 58, display = 10169, height = 7.2, span = 7.2, school = "physical", pool = "rare", icon = "Interface\\Icons\\Ability_Warrior_Sunder", profile = "bruiser", kit = { 15708, 15496, 11428, 22857, 41104 }, passives = {}, talentInfo = { { name = "Arena Veteran", icon = "Interface\\Icons\\Ability_Warrior_Sunder", text = "Your Physical damage is increased by 8%." }, { name = "Unbroken Bones", icon = "Interface\\Icons\\Spell_Nature_Strength", text = "Your maximum health is increased by 10%." }, { name = "Crowd Favourite", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", text = "Your chance to critically strike with melee attacks is increased by 5%." }, { name = "Ring-Hardened", icon = "Interface\\Icons\\INV_Misc_Pelt_Bear_Ruin_02", text = "Your armor is increased by 10%." }, { name = "Never Broken", icon = "Interface\\Icons\\Ability_Warrior_ShieldWall", text = "Reduces the cooldown of your Unbreakable by 30 sec.\n\nThey named him the Unbreakable after his hundredth fight. Nobody has kept count since." }, { name = "Crowd Pleaser", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your melee hits have an 8% chance to follow through with a Cleave. Once every 10 sec.\n\nThe Gordok crowd wants blood, and Skarr always gives them two helpings." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Dire Maul", expansion = 0, order = 176, box = { 0.04, -0.24, 3.55 }, title = "Champion of the Gordok Arena" },
    { id = "azurous", entry = 10202, name = "Azurous", label = "Azurous", level = 59, display = 6373, height = 15.7, span = 26.5, school = "frost", pool = "rare", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Blue", profile = "caster", kit = { 16099, 22271, 14033, 29991, 14514 }, passives = {}, talentInfo = { { name = "Arcane Immunity", icon = "Interface\\Icons\\Spell_Nature_WispSplode", text = "Your Arcane resistance is increased by 100." }, { name = "Winter's Breath", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "Your Frost damage is increased by 10%." }, { name = "Blue Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_14", text = "Your armor is increased by 12%." }, { name = "Spellweaver's Brood", icon = "Interface\\Icons\\Spell_Arcane_ArcaneResilience", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Frozen Lair", icon = "Interface\\Icons\\Spell_Frost_FreezingBreath", text = "Reduces the cooldown of your Frost Breath by 5 sec.\n\nWinterspring's caves are cold enough. Azurous makes them colder." }, { name = "Arcane Surge", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", text = "Your spells have a 10% chance to release a free Arcane Explosion. Once every 10 sec.\n\nThe magic of the blue flight runs through its scales, and sometimes spills out." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = true, wave = 4, zone = "Winterspring", expansion = 0, order = 236, box = { -2.41, -0.00, 7.12 }, title = "Blue Drake of Winterspring" },
    { id = "lady_hederine", entry = 10201, name = "Lady Hederine", label = "Lady Hederine", level = 61, display = 10925, height = 3.1, span = 3.1, school = "shadow", pool = "rare", icon = "Interface\\Icons\\Spell_Shadow_MindSteal", profile = "caster", kit = { 15968, 17146, 30850, 14033, 261 }, passives = {}, talentInfo = { { name = "Mistress of Pain", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your Shadow damage is increased by 10%." }, { name = "Darkwhisper", icon = "Interface\\Icons\\Spell_Shadow_MindSteal", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Demon Hide", icon = "Interface\\Icons\\Spell_Shadow_RagingScream", text = "Damage you take is reduced by 5%." }, { name = "Nether Grace", icon = "Interface\\Icons\\Spell_Shadow_GhostKey", text = "Your movement speed is increased by 8%." }, { name = "Irresistible", icon = "Interface\\Icons\\Spell_Shadow_Charm", text = "Reduces the cooldown of your Seduction by 10 sec.\n\nFew who come to Darkwhisper Gorge leave it. Fewer leave it by choice." }, { name = "Lingering Pain", icon = "Interface\\Icons\\Spell_Shadow_CurseOfSargeras", text = "Your spells have a 10% chance to lay a free Shadow Word: Pain on the target. Once every 12 sec.\n\nHer pain is a gift, and she gives it freely." } }, tips = { [261] = "Call your initiates out of Darkwhisper Gorge: two Hederine Initiates fight for you for 20 sec." }, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Winterspring", expansion = 0, order = 237, summons = { [261] = true }, box = { -1.03, 0.54, 1.54 }, title = "Mistress of the Hederine" },
    { id = "sneeds_shredder", entry = 642, name = "Sneed's Shredder", label = "Sneed", level = 20, display = 1269, height = 4.8, span = 5.6, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\Ability_Mount_ShredderMount", profile = "bruiser", kit = { 43410, 37123, 54904, 52318, 7399, 3603 }, passives = {}, talentInfo = { { name = "Riveted Hull", icon = "Interface\\Icons\\INV_Misc_ArmorKit_14", text = "Your armor is increased by 15%." }, { name = "Goblin Chassis", icon = "Interface\\Icons\\INV_Gizmo_04", text = "Your maximum health is increased by 8%." }, { name = "Lumber Mill Engine", icon = "Interface\\Icons\\Trade_Engineering", text = "Your attack power is increased by 8%." }, { name = "Honed Teeth", icon = "Interface\\Icons\\INV_Misc_SawBlade_01", text = "Your Physical damage is increased by 8%." }, { name = "Thrown Teeth", icon = "Interface\\Icons\\Ability_Warrior_SavageBlow", text = "Your melee hits have a 10% chance to fling a Saw Blade. Once every 10 sec.\n\nA shredder chews through blades faster than timber. The spent ones have to go somewhere." }, { name = "Overclocked Saws", icon = "Interface\\Icons\\Ability_Whirlwind", text = "Reduces the cooldown of your Whirling Saws by 4 sec.\n\nSneed never did read the safety plate. The saws spin up quicker without it." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Deadmines", expansion = 0, order = 39, box = { 1.08, -0.14, 2.26 }, title = "Lumbermaster", visages = { "sneed" }, shape = "Shredder" },
    { id = "sneed", entry = 643, name = "Sneed", label = "Sneed", level = 20, display = 7125, height = 1.4, span = 1.4, school = "physical", pool = "classic_dungeon", icon = "Interface\\Icons\\Achievement_GoblinHead", profile = "glass_cannon", kit = { 15667, 6713, 13445, 7978, 15087, 261 }, passives = {}, talentInfo = { { name = "Goblin Reflexes", icon = "Interface\\Icons\\Ability_Rogue_Feint", text = "Your chance to dodge is increased by 4%." }, { name = "Sharpened Claws", icon = "Interface\\Icons\\Ability_CriticalStrike", text = "Your chance to critically hit with melee attacks is increased by 4%." }, { name = "Blasting Powder", icon = "Interface\\Icons\\INV_Misc_Bomb_05", text = "Your Fire damage is increased by 10%." }, { name = "Quick Little Legs", icon = "Interface\\Icons\\Ability_Rogue_Sprint", text = "Your movement speed is increased by 8%." }, { name = "Tearing Claws", icon = "Interface\\Icons\\Ability_Gouge", text = "Your melee hits have a 10% chance to inflict Rending Claws. Once every 10 sec.\n\nSneed files his claws on the mill's grindstone between shifts." }, { name = "Foreman's Whistle", icon = "Interface\\Icons\\INV_ThrowingAxe_03", text = "Reduces the cooldown of Back to Work by 20 sec.\n\nThe Woodcarvers know that whistle. The last one to down tools gets fed to the shredder." } }, tips = { [261] = "Whistle up the mill crew: two Goblin Woodcarvers drop their tools and fight for you for 20 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Deadmines", expansion = 0, order = 38, summons = { [261] = true }, charModel = true, box = { 0.01, -0.02, 0.69 }, title = "Lumbermaster", visageOf = "sneeds_shredder", shape = "On Foot" },
    { id = "necromancer_frost", entry = 27539, name = "Frigid Necromancer", label = "Frigid Necromancer", level = 74, display = 24692, height = 2.1, span = 2.1, school = "frost", pool = "archetype", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", profile = "caster", kit = { 20822, 48400, 12674, 20828, 44178, 50324 }, passives = {}, talentInfo = { { name = "Rime of the Damned", icon = "Interface\\Icons\\Spell_Frost_FrostBolt", text = "Your Frost damage is increased by 10%." }, { name = "Frozen Heart", icon = "Interface\\Icons\\Spell_Frost_FrozenCore", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Cold Discipline", icon = "Interface\\Icons\\Spell_Frost_WindWalkOn", text = "Your casting speed is increased by 6%." }, { name = "Icebound Flesh", icon = "Interface\\Icons\\Spell_Frost_Wisp", text = "Your maximum health is increased by 8%." }, { name = "Frozen Echo", icon = "Interface\\Icons\\Spell_Frost_FrostShock", text = "Your damaging spells have a 10% chance to loose a free Frostbolt at the target. Once every 12 sec.\n\nIn Icecrown the cold does not wait to be called. A frigid necromancer's every spell leaves a second, colder one behind." }, { name = "Tomb-Keeper", icon = "Interface\\Icons\\Spell_Frost_Glacier", text = "Reduces the cooldown of Frost Tomb by 10 sec.\n\nThe Cult keeps its prisoners on ice until the Lich King has a use for them. There is always another block ready." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Dragonblight", expansion = 2, order = 452, charModel = true, box = { -0.10, -0.00, 1.06 }, skinName = "Frost", skinOf = "necromancer", title = "Cult of the Damned" },
    { id = "necromancer_plague", entry = 24957, name = "Cult Plaguebringer", label = "Cult Plaguebringer", level = 71, display = 23294, height = 2.1, span = 2.1, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Spell_Shadow_PlagueCloud", profile = "caster", kit = { 50356, 25811, 16345, 7102, 261 }, passives = {}, talentInfo = { { name = "Cauldron Brew", icon = "Interface\\Icons\\Spell_Shadow_CallofBone", text = "Your Shadow damage is increased by 8%." }, { name = "Plague Apothecary", icon = "Interface\\Icons\\Spell_Nature_NullifyDisease", text = "Your casting speed is increased by 6%." }, { name = "Rotten Constitution", icon = "Interface\\Icons\\Ability_Creature_Disease_03", text = "Your maximum health is increased by 8%." }, { name = "Carrier's Immunity", icon = "Interface\\Icons\\Spell_Nature_ResistNature", text = "Your Nature resistance is increased by 40." }, { name = "Seeping Plague", icon = "Interface\\Icons\\Ability_Creature_Disease_02", text = "Your damaging spells have a 10% chance to Inject Plague into the target. Once every 15 sec.\n\nA Plaguebringer's hands are never clean. Everything it touches carries a little of the cauldron away with it." }, { name = "Bring Out Your Dead", icon = "Interface\\Icons\\Spell_Shadow_RaiseDead", text = "Reduces the cooldown of Ghoul Summons by 15 sec.\n\nWhere the plague has passed, the dead are already waiting. A Plaguebringer only has to ask." } }, tips = { [261] = "Call the plague's harvest: two Plague Ghouls claw their way up to fight for you for 20 sec." }, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Borean Tundra", expansion = 2, order = 434, summons = { [261] = true }, charModel = true, box = { -0.10, -0.00, 1.06 }, skinName = "Plague", skinOf = "necromancer", title = "Cult of the Damned" },
    { id = "necromancer_shadow", entry = 8550, name = "Shadowmage", label = "Shadowmage", level = 60, display = 10421, height = 2.1, span = 2.1, school = "shadow", pool = "archetype", icon = "Interface\\Icons\\Spell_Shadow_Shadowform", profile = "glass_cannon", kit = { 20825, 17238, 17243, 14868, 13338, 32711 }, passives = { 22917 }, talentInfo = { { name = "Umbral Mastery", icon = "Interface\\Icons\\Spell_Shadow_ShadowWordPain", text = "Your Shadow damage is increased by 8%." }, { name = "Void Focus", icon = "Interface\\Icons\\Spell_Shadow_Twilight", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Siphoned Vigour", icon = "Interface\\Icons\\Spell_Shadow_SiphonMana", text = "Your Shadow spells cost 10% less mana." }, { name = "Shadowmage's Ward", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Damage you take is reduced by 4%." }, { name = "Lingering Agony", icon = "Interface\\Icons\\Spell_Shadow_CurseOfSargeras", text = "Your damaging spells have an 8% chance to lay Curse of Agony on the target. Once every 15 sec.\n\nThe Shadowmages of the Plaguelands curse as easily as they breathe, and rarely only once." }, { name = "Grave Hunger", icon = "Interface\\Icons\\Spell_Shadow_LifeDrain", text = "Increases the damage of Drain Life by 15%.\n\nThe Cult teaches that life is a debt owed to the Lich King, and its Shadowmages collect with interest." } }, tips = {}, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Eastern Plaguelands", expansion = 0, order = 234, charModel = true, box = { -0.10, -0.00, 1.06 }, skinName = "Shadow", skinOf = "necromancer", title = "Cult of the Damned" },
    { id = "bear_grizzly", entry = 27131, name = "Grizzly Bear", label = "Grizzly Bear", level = 74, display = 21635, height = 3.3, span = 5.8, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Druid_Maul", profile = "tank", kit = { 52506, 58855, 15727, 53498, 38324 }, passives = {}, talentInfo = { { name = "Thick Hide", icon = "Interface\\Icons\\INV_Misc_Pelt_Bear_03", text = "Your armor is increased by 20%." }, { name = "Grizzled Endurance", icon = "Interface\\Icons\\Spell_Nature_Regeneration", text = "Your maximum health is increased by 10%." }, { name = "Den Guardian", icon = "Interface\\Icons\\Ability_Physical_Taunt", text = "The threat you cause is increased by 30%." }, { name = "Winter Fat", icon = "Interface\\Icons\\Ability_Racial_BearForm", text = "Damage you take is reduced by 5%." }, { name = "Cornered Grizzly", icon = "Interface\\Icons\\Ability_Druid_Swipe", text = "When you are struck you have a 10% chance to lash out with a free Swipe. Once every 10 sec.\n\nA grizzly backed against a cliff does not retreat. It simply starts swinging at everything in reach." }, { name = "Long Winter's Sleep", icon = "Interface\\Icons\\Ability_Druid_TigersRoar", text = "Reduces the cooldown of Frenzied Regeneration by 20 sec.\n\nEvery grizzly has slept off worse. A winter under the snow mends wounds no hunter's arrow ever made." } }, tips = { [38324] = "Let the wild fury knit your wounds, healing you for 125 every 3 sec. for 12 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Grizzly Hills", expansion = 2, order = 462, box = { 0.02, -0.05, 1.56 }, skinName = "Grizzly", skinOf = "bear", title = "Grizzly of the Grizzly Hills" },
    { id = "bear_ice", entry = 1196, name = "Ice Claw Bear", label = "Ice Claw Bear", level = 8, display = 8840, height = 1.6, span = 2.8, school = "frost", pool = "archetype", icon = "Interface\\Icons\\Spell_Frost_FrostArmor02", profile = "bruiser", kit = { 3130, 22479, 3143, 61186, 31256 }, passives = {}, talentInfo = { { name = "Frost-Rimed Hide", icon = "Interface\\Icons\\Spell_Frost_FrostWard", text = "Your Frost resistance is increased by 50." }, { name = "Winter Coat", icon = "Interface\\Icons\\INV_Misc_Pelt_Bear_01", text = "Your armor is increased by 15%." }, { name = "Glacier-Fed", icon = "Interface\\Icons\\Spell_Frost_Glacier", text = "Your maximum health is increased by 8%." }, { name = "Frozen Ferocity", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "Numbing Cold", icon = "Interface\\Icons\\Spell_Frost_FrozenCore", text = "Your melee attacks have an 8% chance to leave a Frozen Bite. Once every 12 sec.\n\nAn Ice Claw's fangs are always cold. Whatever it bites keeps shivering long after it has let go." }, { name = "Voice of the Blizzard", icon = "Interface\\Icons\\Spell_Frost_ArcticWinds", text = "Reduces the cooldown of Glacial Roar by 10 sec.\n\nWhen an Ice Claw roars in Dun Morogh, the mountain answers, and the snow comes down with it." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Dun Morogh", expansion = 0, order = 5, box = { 0.01, -0.02, 0.76 }, skinName = "Ice", skinOf = "bear", title = "Ice Claw Bear of Dun Morogh" },
    { id = "bear_war", entry = 32207, name = "Armored Brown Bear", label = "Armored Brown Bear", level = 70, display = 27821, height = 2.7, span = 4.6, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Mount_PolarBear_Brown", profile = "bruiser", kit = { 22911, 27553, 15550, 9080, 50502 }, passives = {}, talentInfo = { { name = "Riveted Plate", icon = "Interface\\Icons\\Ability_Warrior_DefensiveStance", text = "Your armor is increased by 25%." }, { name = "Trained for War", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", text = "Your Strength is increased by 6%." }, { name = "Drilled Footwork", icon = "Interface\\Icons\\Ability_Parry", text = "Your chance to parry is increased by 5%." }, { name = "Warbear's Stride", icon = "Interface\\Icons\\Ability_Warrior_Charge", text = "Your attack speed is increased by 6%." }, { name = "Heavy Footfalls", icon = "Interface\\Icons\\Ability_ThunderClap", text = "Your melee attacks have an 8% chance to Trample the enemies around you. Once every 15 sec.\n\nA war bear in full plate does not need to aim. Everything beneath its feet is already losing." }, { name = "Unstoppable Momentum", icon = "Interface\\Icons\\Ability_Rogue_Sprint", text = "Reduces the cooldown of Armored Charge by 5 sec.\n\nIts riders learn to hold on. Once a Northrend war bear has started running, only the enemy line stops it." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Crystalsong Forest", expansion = 2, order = 441, box = { -0.02, -0.03, 1.27 }, skinName = "War Bear", skinOf = "bear", title = "Armored Battle Bear of Northrend" },
    { id = "spider_widow", entry = 1688, name = "Night Web Matriarch", label = "Night Web Matriarch", level = 5, display = 368, height = 1.1, span = 3.3, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Ability_Creature_Poison_05", profile = "glass_cannon", kit = { 54470, 2818, 25809, 17158, 25991 }, passives = {}, talentInfo = { { name = "Matriarch's Venom", icon = "Interface\\Icons\\Ability_Creature_Poison_03", text = "Your Nature damage is increased by 10%." }, { name = "Killing Instinct", icon = "Interface\\Icons\\Ability_CriticalStrike", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Night Web Stride", icon = "Interface\\Icons\\Ability_Rogue_Sprint", text = "Your movement speed is increased by 8%." }, { name = "Brood Mother's Vigour", icon = "Interface\\Icons\\Ability_Hunter_Pet_Spider", text = "Your maximum health is increased by 6%." }, { name = "Tangled in Venom", icon = "Interface\\Icons\\Spell_Nature_SlowPoison", text = "Your melee attacks have a 10% chance to leave Crippling Venom in the wound. Once every 10 sec.\n\nThe Matriarch never chases. One bite and her prey stumbles, and then it is only a matter of patience." }, { name = "Web of Venom", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "Your Venom Nova reaches 20% farther.\n\nThe Night Web Hollow drips with the Matriarch's venom from floor to ceiling. There is no safe corner." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Tirisfal Glades", expansion = 0, order = 3, box = { 0.46, -0.00, 0.56 }, skinName = "Widow", skinOf = "spider", title = "Matriarch of the Night Web" },
    { id = "spider_plague", entry = 15974, name = "Dread Creeper", label = "Dread Creeper", level = 81, display = 15937, height = 2.1, span = 6.1, school = "shadow", pool = "archetype", icon = "Interface\\Icons\\Ability_Creature_Disease_02", profile = "bruiser", kit = { 60678, 53803, 25198, 28431, 261 }, passives = {}, talentInfo = { { name = "Scourge-Hardened Chitin", icon = "Interface\\Icons\\Spell_Shadow_AntiShadow", text = "Your armor is increased by 15%." }, { name = "Undying Hunger", icon = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy", text = "Your maximum health is increased by 10%." }, { name = "Plague-Soaked Fangs", icon = "Interface\\Icons\\Ability_Creature_Disease_05", text = "Your Nature damage is increased by 8%." }, { name = "Death's Patience", icon = "Interface\\Icons\\Spell_Shadow_DeathScream", text = "Damage you take is reduced by 5%." }, { name = "Festering Fangs", icon = "Interface\\Icons\\Ability_Creature_Disease_01", text = "Your melee attacks have an 8% chance to leave a Plague Bite. Once every 15 sec.\n\nNothing in the Arachnid Quarter is clean. A Dread Creeper's every bite carries a little of Naxxramas with it." }, { name = "Endless Brood", icon = "Interface\\Icons\\INV_Misc_MonsterSpiderCarapace_01", text = "Reduces the cooldown of Spiderling Swarm by 15 sec.\n\nMaexxna's brood hatches faster than any adventurer can crush it." } }, tips = { [261] = "Shake loose the brood clinging to your back: three spiderlings swarm out to fight for you for 20 sec." }, visualKit = 7775, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Naxxramas", expansion = 0, order = 312, summons = { [261] = true }, box = { 0.84, -0.00, 1.01 }, skinName = "Plague", skinOf = "spider", title = "Crawler of the Arachnid Quarter" },
    { id = "spider_trapper", entry = 15975, name = "Carrion Spinner", label = "Carrion Spinner", level = 81, display = 15938, height = 2.7, span = 7.9, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_Web", profile = "bruiser", kit = { 28434, 54453, 29484, 30831, 41390, 30043 }, passives = {}, talentInfo = { { name = "Silken Carapace", icon = "Interface\\Icons\\INV_Misc_Web_01", text = "Your armor is increased by 15%." }, { name = "Patient Spinner", icon = "Interface\\Icons\\Ability_Rogue_Feint", text = "Your chance to dodge is increased by 5%." }, { name = "Carrion Feast", icon = "Interface\\Icons\\Ability_Creature_Disease_03", text = "Your maximum health is increased by 8%." }, { name = "From the Rafters", icon = "Interface\\Icons\\Ability_Ambush", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Sticky Silk", icon = "Interface\\Icons\\Ability_Ensnare", text = "Your melee attacks have a 6% chance to bind the enemy in Web Wrap. Once every 20 sec.\n\nEvery strand a Carrion Spinner touches stays sticky. Its prey finds that out one leg at a time." }, { name = "Silk to Spare", icon = "Interface\\Icons\\Spell_Nature_EarthBind", text = "Reduces the cooldown of Web Burst by 15 sec.\n\nThe Spinner's lair is more web than stone. There is always more silk to throw." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Naxxramas", expansion = 0, order = 311, box = { 1.09, -0.00, 1.31 }, skinName = "Trapper", skinOf = "spider", title = "Spinner of Naxxramas" },
    { id = "moonkin_owlbeast", entry = 2927, name = "Vicious Owlbeast", label = "Vicious Owlbeast", level = 43, display = 12238, height = 4.2, span = 4.2, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Druid_Rake", profile = "bruiser", kit = { 7938, 13738, 3252, 5164, 34971 }, passives = {}, talentInfo = { { name = "Matted Plumage", icon = "Interface\\Icons\\INV_Feather_03", text = "Your armor is increased by 15%." }, { name = "Hunger of the Wild", icon = "Interface\\Icons\\Ability_Druid_FerociousBite", text = "Your Physical damage is increased by 8%." }, { name = "Ruffled Fury", icon = "Interface\\Icons\\Ability_Hunter_Pet_Owl", text = "Your attack speed is increased by 6%." }, { name = "Thick Down", icon = "Interface\\Icons\\Spell_Nature_Regeneration", text = "Your maximum health is increased by 8%." }, { name = "Rending Talons", icon = "Interface\\Icons\\Ability_Druid_Disembowel", text = "Your melee attacks have a 10% chance to rake your target with Rend. Once every 10 sec.\n\nAn owlbeast does not strike once. The first blow is only the beak; the talons come after." }, { name = "Gorge", icon = "Interface\\Icons\\Ability_Druid_Mangle", text = "Your Fatal Bite deals 15% more damage.\n\nIt eats while it fights, and it fights better for eating." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "The Hinterlands", expansion = 0, order = 118, box = { 0.13, 0.02, 2.11 }, skinName = "Owlbeast", skinOf = "moonkin", title = "Owlbeast of the Hinterlands" },
    { id = "moonkin_wildkin", entry = 17323, name = "Contaminated Wildkin", label = "Contaminated Wildkin", level = 16, display = 17056, height = 5.3, span = 5.3, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_NullifyDisease", profile = "bruiser", kit = { 6917, 24097, 31282, 15848, 13443, 8599 }, passives = {}, talentInfo = { { name = "Crystal Rot", icon = "Interface\\Icons\\Spell_Nature_CorrosiveBreath", text = "Your Nature damage is increased by 10%." }, { name = "Mutated Hide", icon = "Interface\\Icons\\Ability_Creature_Disease_03", text = "Your armor is increased by 15%." }, { name = "Feverish Vigour", icon = "Interface\\Icons\\Spell_Nature_Rejuvenation", text = "Your maximum health is increased by 8%." }, { name = "Tainted Blood", icon = "Interface\\Icons\\Spell_Nature_PoisonCleansingTotem", text = "Your Nature resistance is increased by 40." }, { name = "Radiant Taint", icon = "Interface\\Icons\\Spell_Nature_AbolishMagic", text = "When you are struck you have a 10% chance to taint your attacker with Tainted Claws. Once every 12 sec.\n\nStrike a wildkin of Bloodmyst and the crystal dust on its feathers comes away on your hands." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Bloodmyst Isle", expansion = 1, order = 322, box = { 0.16, 0.02, 2.64 }, skinName = "Wildkin", skinOf = "moonkin", title = "Contaminated Wildkin of Bloodmyst" },
    { id = "dragonspawn_blue", entry = 26716, name = "Azure Warder", label = "Azure Warder", level = 71, display = 25251, height = 5.2, span = 10.4, school = "arcane", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Blue", profile = "bruiser", kit = { 22460, 35871, 17630, 16094, 56777, 56778 }, passives = {}, talentInfo = { { name = "Nexus-Tempered", icon = "Interface\\Icons\\Spell_Arcane_StarFire", text = "Your Arcane damage is increased by 10%." }, { name = "Azure Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_05", text = "Your Arcane resistance is increased by 40." }, { name = "Spellhunter's Eye", icon = "Interface\\Icons\\Spell_Arcane_ArcanePotency", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Warder's Vigil", icon = "Interface\\Icons\\Spell_Holy_MagicalSentry", text = "Your maximum health is increased by 8%." }, { name = "Mana Siphon", icon = "Interface\\Icons\\Spell_Shadow_ManaBurn", text = "Your melee attacks have a 10% chance to loose a free Mana Burn at the target. Once every 15 sec.\n\nAn azure warder's axe is etched with runes that drink magic. Every blow tastes the mana of the one it strikes." }, { name = "Malygos's Decree", icon = "Interface\\Icons\\Spell_Holy_Silence", text = "Reduces the cooldown of Silence by 10 sec.\n\nThe Spell-Weaver decreed that no mortal would work magic again. His warders take the decree personally." } }, tips = {}, visualKit = 1005, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "The Nexus", expansion = 2, order = 445, box = { -1.25, -0.61, 2.54 }, skinName = "Blue", skinOf = "dragonspawn", title = "Warder of the Blue Dragonflight" },
    { id = "dragonspawn_green", entry = 5319, name = "Jademir Tree Warder", label = "Jademir Tree Warder", level = 60, display = 625, height = 3.9, span = 7.8, school = "nature", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Green", profile = "caster", kit = { 20663, 21667, 16359, 20654, 22695, 20656 }, passives = {}, talentInfo = { { name = "Emerald Resilience", icon = "Interface\\Icons\\Spell_Nature_ResistNature", text = "Your Nature resistance is increased by 40." }, { name = "Dreamer's Grace", icon = "Interface\\Icons\\Spell_Nature_HealingTouch", text = "Your healing is increased by 10%." }, { name = "Verdant Mind", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your casting speed is increased by 6%." }, { name = "Jademir Hide", icon = "Interface\\Icons\\INV_Misc_MonsterScales_09", text = "Your maximum health is increased by 8%." }, { name = "Stinging Motes", icon = "Interface\\Icons\\Spell_Nature_StarFall", text = "Your damaging spells have an 8% chance to loose a free Wrath at the target. Once every 12 sec.\n\nWhere a Jademir walks, the Dream's motes swarm after it. They sting anyone the warder is angry with." }, { name = "Keeper of the Gates", icon = "Interface\\Icons\\Spell_Nature_ProtectionformNature", text = "Reduces the mana cost of Waking Dream by 20%.\n\nThe Dream is patient and deep. A warder who guards its gates never runs short of the light that mends." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Feralas", expansion = 0, order = 151, box = { -0.94, -0.46, 1.91 }, skinName = "Green", skinOf = "dragonspawn", title = "Warder of the Green Dragonflight" },
    { id = "dragonspawn_bronze", entry = 32281, name = "Guardian of Time", label = "Guardian of Time", level = 80, display = 17555, height = 3.3, span = 6.5, school = "arcane", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Head_Dragon_Bronze", profile = "bruiser", kit = { 35351, 58829, 31741, 31422, 66045, 23381 }, passives = {}, talentInfo = { { name = "Sands of Eternity", icon = "Interface\\Icons\\Spell_Arcane_Arcane04", text = "Your Arcane damage is increased by 8%." }, { name = "Borrowed Seconds", icon = "Interface\\Icons\\Ability_Rogue_Sprint", text = "Your attack speed is increased by 6%." }, { name = "Timeless Scales", icon = "Interface\\Icons\\INV_Misc_MonsterScales_13", text = "Your armor is increased by 15%." }, { name = "Glimpse Ahead", icon = "Interface\\Icons\\Spell_Nature_TimeStop", text = "Your chance to dodge is increased by 5%." }, { name = "Temporal Drag", icon = "Interface\\Icons\\Spell_Nature_Slow", text = "Your melee attacks have an 8% chance to Slow the target. Once every 15 sec.\n\nA guardian of time strikes a little ahead of the moment. What it hits falls a little behind." }, { name = "The Hourglass Turns", icon = "Interface\\Icons\\INV_Misc_PocketWatch_02", text = "Reduces the cooldown of Rewind Time by 10 sec.\n\nNozdormu forbids his flight to meddle with time. His guardians count a few seconds of their own wounds as exempt." } }, tips = {}, visualKit = 1005, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, expansion = 2, order = 482, box = { -0.78, -0.38, 1.59 }, skinName = "Bronze", skinOf = "dragonspawn", title = "Guardian of the Timeways" },
    { id = "ancient_protector_stonebark", entry = 18487, name = "Night Elf Ancient Protector", label = "Elder Stonebark", level = 70, display = 17846, height = 18.9, span = 18.9, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_StoneSkinTotem", profile = "bruiser", kit = { 62932, 49639, 54427, 65860, 43592 }, passives = {}, talentInfo = { { name = "Petrified Heartwood", icon = "Interface\\Icons\\Spell_Nature_StoneClawTotem", text = "Your armor is increased by 20%." }, { name = "Granite Grip", icon = "Interface\\Icons\\INV_Stone_10", text = "Your Strength is increased by 6%." }, { name = "Deep Roots of Ulduar", icon = "Interface\\Icons\\Spell_Nature_EarthBindTotem", text = "Your maximum health is increased by 10%." }, { name = "Stone Patience", icon = "Interface\\Icons\\INV_Stone_15", text = "Damage you take is reduced by 4%." }, { name = "Broken Bones", icon = "Interface\\Icons\\Ability_Warrior_Trauma", text = "Your melee attacks have an 8% chance to follow with a free Stone Fist. Once every 12 sec.\n\nThe stone fists of Stonebark do not glance off. What they strike, they break, and then they strike it again." }, { name = "Heart of the Mountain", icon = "Interface\\Icons\\Spell_Nature_EarthQuake", text = "Reduces the cooldown of Fists of Stone by 20 sec.\n\nStonebark drank from the stone of Ulduar for an age. The strength comes back to its limbs faster than any mortal's." } }, tips = {}, visualKit = 437, soundTransform = 15501, soundDeath = 15503, flies = false, wave = 4, instance = "The Battle for Mount Hyjal", expansion = 1, order = 356, box = { 1.24, 0.25, 9.37 }, skinName = "Stonebark", skinOf = "ancient_protector", title = "Elder of the Conservatory" },
    { id = "ancient_protector_brightleaf", entry = 2041, name = "Ancient Protector", label = "Elder Brightleaf", level = 60, display = 2429, height = 12.6, span = 12.6, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_Sentinal", profile = "caster", kit = { 62872, 62240, 62451, 16561, 62251 }, passives = {}, talentInfo = { { name = "Sunlit Canopy", icon = "Interface\\Icons\\Spell_Nature_WispSplode", text = "Your Nature damage is increased by 10%." }, { name = "Solar Attunement", icon = "Interface\\Icons\\Spell_Holy_SearingLight", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Photosynthetic Sap", icon = "Interface\\Icons\\Spell_Nature_Rejuvenation", text = "Your healing is increased by 10%." }, { name = "Brightleaf Vigour", icon = "Interface\\Icons\\Spell_Nature_AbolishMagic", text = "Your maximum health is increased by 8%." }, { name = "Sunflare Echo", icon = "Interface\\Icons\\Spell_Fire_SelfDestruct", text = "Your damaging spells have an 8% chance to call a free Sunbeam on the target. Once every 12 sec.\n\nThe Conservatory was built to catch the sun. Brightleaf still catches it, and lets a little fall on its foes." }, { name = "Unstable Radiance", icon = "Interface\\Icons\\Spell_Holy_SurgeOfLight", text = "Your Unstable Sun Beam reaches 20% farther.\n\nBrightleaf's sun beams were never steady. The elder learned long ago to let them spill wide." } }, tips = {}, visualKit = 282, soundTransform = 15483, soundDeath = 15487, flies = false, wave = 4, zone = "Teldrassil", expansion = 0, order = 12, box = { 0.83, 0.16, 6.25 }, skinName = "Bright", skinOf = "ancient_protector", title = "Elder of the Conservatory" },
    { id = "ancient_protector_ironbranch", entry = 3468, name = "Ancient of Lore", label = "Elder Ironbranch", level = 62, display = 1460, height = 27.5, span = 27.5, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_Thorns", profile = "bruiser", kit = { 62310, 22800, 63239, 65062, 21749 }, passives = {}, talentInfo = { { name = "Ironwood Hide", icon = "Interface\\Icons\\INV_Misc_Root_02", text = "Your armor is increased by 20%." }, { name = "Keen Thorns", icon = "Interface\\Icons\\Ability_Hunter_Pet_Crab", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Old Growth", icon = "Interface\\Icons\\Spell_Nature_ProtectionformNature", text = "Your maximum health is increased by 8%." }, { name = "Barbed Heartwood", icon = "Interface\\Icons\\Spell_Nature_NatureTouchDecay", text = "Your Nature damage is increased by 8%." }, { name = "Thorny Retort", icon = "Interface\\Icons\\Spell_Nature_Thorns", text = "Your melee attacks have an 8% chance to loose a free Thorn Swarm at the target. Once every 15 sec.\n\nEvery blow Ironbranch lands leaves a few thorns behind. Given a moment, they become a swarm." }, { name = "Iron Grip", icon = "Interface\\Icons\\Spell_Nature_StrangleVines", text = "Reduces the cooldown of Iron Roots by 5 sec.\n\nMortals have no place in the Conservatory. Ironbranch's roots are already moving before they arrive." } }, tips = { [22800] = "Wrap an enemy in iron-hard roots: it is held in place for 8 sec and takes 225 Nature damage every 2 sec." }, visualKit = 282, soundTransform = 15493, soundDeath = 15496, flies = false, wave = 4, zone = "Darnassus", expansion = 0, order = 283, box = { 1.30, -0.01, 13.42 }, skinName = "Iron", skinOf = "ancient_protector", title = "Elder of the Conservatory" },
    { id = "giant_frost", entry = 10985, name = "Ice Giant", label = "Ice Giant", level = 63, display = 10041, height = 10.0, span = 10.6, school = "frost", pool = "archetype", icon = "Interface\\Icons\\Spell_Frost_Glacier", profile = "bruiser", kit = { 54673, 51857, 57668, 55216, 12544 }, passives = {}, talentInfo = { { name = "Glacier Hide", icon = "Interface\\Icons\\Spell_Frost_FrostArmor02", text = "Your armor is increased by 20%." }, { name = "Winter's Might", icon = "Interface\\Icons\\Spell_Frost_WizardMark", text = "Your Strength is increased by 6%." }, { name = "Frozen Endurance", icon = "Interface\\Icons\\Spell_Frost_Wisp", text = "Your maximum health is increased by 10%." }, { name = "Heart of Winter", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", text = "Your Frost damage is increased by 10%." }, { name = "Shedding Ice", icon = "Interface\\Icons\\Spell_Frost_IceShard", text = "Your melee attacks have a 6% chance to heave a free Ice Boulder at the target. Once every 15 sec.\n\nAn ice giant never runs short of stones. Every swing of its maul breaks another boulder loose from its hide." }, { name = "Frozen Passes", icon = "Interface\\Icons\\Spell_Frost_FreezingBreath", text = "Reduces the cooldown of Frost Stomp by 5 sec.\n\nIn the high passes of Winterspring the ground is always frozen. An ice giant barely has to stamp to lock it." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, expansion = 0, order = 285, box = { 0.12, -0.09, 4.98 }, skinName = "Frost", skinOf = "giant", title = "Ice Giant of Winterspring" },
    { id = "dryad_nymph", entry = 33355, name = "Misguided Nymph", label = "Misguided Nymph", level = 81, display = 28724, height = 6.1, span = 6.1, school = "frost", pool = "archetype", icon = "Interface\\Icons\\Spell_Frost_FrostBolt02", profile = "caster", kit = { 63111, 9739, 63082, 12747, 63136 }, passives = {}, talentInfo = { { name = "Frost of the Garden", icon = "Interface\\Icons\\Spell_Frost_ChillingBlast", text = "Your Frost damage is increased by 10%." }, { name = "Freya's Grace", icon = "Interface\\Icons\\Spell_Nature_HealingTouch", text = "Your healing is increased by 10%." }, { name = "Clarity of Winter", icon = "Interface\\Icons\\Spell_Frost_WizardMark", text = "Your spell critical strike chance is increased by 3%." }, { name = "Evergreen", icon = "Interface\\Icons\\Spell_Nature_ResistNature", text = "Your maximum health is increased by 8%." }, { name = "Hoarfrost", icon = "Interface\\Icons\\Spell_Frost_IceShard", text = "Your spells have a 10% chance to hurl a free Frost Spear. Once every 10 sec.\n\nWhere a nymph's spell lands, the frost is already waiting." }, { name = "Bound in Spring", icon = "Interface\\Icons\\Spell_Nature_Rejuvenation", text = "Reduces the cooldown of Bind Life by 5 sec.\n\nFreya's garden never lets a bond wither for long." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Ulduar", expansion = 2, order = 486, box = { 0.02, 0.08, 3.00 }, skinName = "Nymph", skinOf = "dryad", title = "Nymph of Freya's Grove" },
