    { id = "air_elemental_storm", entry = 32958, name = "Lightning Elemental", label = "Lightning Elemental", level = 80, display = 28418, height = 1.5, span = 1.5, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_ChainLightning", profile = "glass_cannon", kit = { 12553, 43435, 31715, 50841, 61902, 64187 }, passives = {}, talentInfo = { { name = "Conductive Core", icon = "Interface\\Icons\\Spell_Nature_LightningShield", text = "Your Nature damage is increased by 8%." }, { name = "Arc Focus", icon = "Interface\\Icons\\Spell_Nature_StormReach", text = "Your chance to critically hit with spells is increased by 6%." }, { name = "Riding the Front", icon = "Interface\\Icons\\Spell_Nature_Invisibilty", text = "Your movement speed is increased by 8%." }, { name = "Thunderhead", icon = "Interface\\Icons\\Spell_Nature_CallStorm", text = "Your maximum health is increased by 6%." }, { name = "Forked Current", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your damaging spells have a 10% chance to snap a free Shock at the target. Once every 8 sec.\n\nA storm never strikes only once. When the air is charged, the next bolt is already looking for somewhere to land." }, { name = "Chain Reaction", icon = "Interface\\Icons\\Spell_Nature_ThunderClap", text = "Your Chain Lightning arcs to 1 more enemy.\n\nThe Iron Council's sparks were bred to leap from one armoured body to the next. Crowds only feed them." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Ulduar", expansion = 2, order = 485, box = { -0.06, -0.01, 0.95 }, skinName = "Storm", skinOf = "air_elemental", title = "Spark of the Iron Council" },
    { id = "air_elemental_dust", entry = 832, name = "Dust Devil", label = "Dust Devil", level = 19, display = 5327, height = 2.2, span = 2.3, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Ability_Whirlwind", profile = "bruiser", kit = { 29673, 56855, 70302, 7272, 33709, 31379 }, passives = {}, talentInfo = { { name = "Grit and Gale", icon = "Interface\\Icons\\Ability_Rogue_Sprint", text = "Your Agility is increased by 6%." }, { name = "Formless Grit", icon = "Interface\\Icons\\Spell_Nature_Cyclone", text = "Your chance to dodge is increased by 5%." }, { name = "Endless Spin", icon = "Interface\\Icons\\Ability_Warrior_Bladestorm", text = "Your attack speed is increased by 6%." }, { name = "Prairie Wind", icon = "Interface\\Icons\\Spell_Nature_EarthBind", text = "Your movement speed is increased by 10%." }, { name = "Scouring Wind", icon = "Interface\\Icons\\Spell_Nature_Tranquility", text = "Your melee attacks have a 10% chance to loose a free Sand Lash at the target. Once every 10 sec.\n\nA dust devil does not strike; it scours. Every pass leaves a little more grit in the joints of whatever it touches." }, { name = "Widening Funnel", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "The radius of your Cyclone Strike is increased by 20%.\n\nOver open plains a whirlwind grows as it spins, dragging in dirt, chaff and anyone standing too close." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Westfall", expansion = 0, order = 19, box = { -0.09, -0.02, 1.42 }, skinName = "Dust", skinOf = "air_elemental", title = "Whirlwind of the Westfall Plains" },
    { id = "earth_elemental_ice", entry = 23919, name = "Ice Elemental", label = "Ice Elemental", level = 69, display = 21910, height = 2.6, span = 3.4, school = "frost", pool = "archetype", icon = "Interface\\Icons\\Spell_Frost_Glacier", profile = "caster", kit = { 50578, 69184, 36989, 29670, 8369, 41590 }, passives = {}, talentInfo = { { name = "Heart of Permafrost", icon = "Interface\\Icons\\Spell_Frost_FrostArmor02", text = "Your Frost damage is increased by 10%." }, { name = "Brittle Edges", icon = "Interface\\Icons\\Spell_Frost_FrostShock", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Glacier Hide", icon = "Interface\\Icons\\Spell_Frost_FrostWard", text = "Your armor is increased by 15%." }, { name = "Born of Winter", icon = "Interface\\Icons\\Spell_Frost_WizardMark", text = "Your Frost resistance is increased by 40." }, { name = "Splintering Cold", icon = "Interface\\Icons\\Spell_Frost_IceShard", text = "Your damaging spells have a 10% chance to hurl a free Ice Shard at the target. Once every 10 sec.\n\nIce under strain does not bend. It cracks, and the splinters fly at whoever made it crack." }, { name = "Creeping Rime", icon = "Interface\\Icons\\Spell_Frost_FrostNova", text = "Reduces the cooldown of your Freeze by 5 sec.\n\nThe cold that holds an ice elemental together seeps into the ground around it, faster every time it spreads." } }, tips = {}, visualKit = 4991, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Howling Fjord", expansion = 2, order = 438, box = { -0.01, -0.04, 1.20 }, skinName = "Ice", skinOf = "earth_elemental", title = "Frozen Earth of Northrend" },
    { id = "earth_elemental_crystal", entry = 11778, name = "Shadowshard Smasher", label = "Shadowshard Smasher", level = 42, display = 11710, height = 3.5, span = 4.5, school = "arcane", pool = "archetype", icon = "Interface\\Icons\\INV_Misc_Gem_Amethyst_02", profile = "bruiser", kit = { 33688, 50302, 36179, 11428, 31534, 40898 }, passives = {}, talentInfo = { { name = "Shadowshard Core", icon = "Interface\\Icons\\INV_Misc_Gem_Amethyst_01", text = "Your Arcane damage is increased by 10%." }, { name = "Faceted Hide", icon = "Interface\\Icons\\INV_Misc_Gem_Diamond_02", text = "Your armor is increased by 15%." }, { name = "Keen Edges", icon = "Interface\\Icons\\INV_Misc_Gem_Crystal_02", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Deep Crystal", icon = "Interface\\Icons\\INV_Stone_15", text = "Your maximum health is increased by 8%." }, { name = "Splinters", icon = "Interface\\Icons\\INV_Misc_Gem_Variety_02", text = "Blows that strike you have a 10% chance to answer with a free Crystal Strike. Once every 12 sec.\n\nStrike a crystal and it chips. Strike a Shadowshard and the chips come back at you, sharp side first." }, { name = "Mirrored Facets", icon = "Interface\\Icons\\Spell_Arcane_ArcaneResilience", text = "Reduces the cooldown of your Prismatic Facets by 20 sec.\n\nEvery shard a Shadowshard grows is another mirror. The older ones catch spells almost without trying." } }, tips = { [40898] = "Crack your crystal body open in a burst of shards, dealing 1600 Physical damage to every enemy around you." }, visualKit = 1005, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Desolace", expansion = 0, order = 108, box = { -0.02, -0.06, 1.60 }, skinName = "Crystal", skinOf = "earth_elemental", title = "Shadowshard of Maraudon" },
