    { id = "defias_footpad", entry = 38, name = "Defias Thug", label = "Defias Thug", level = 4, display = 5035, height = 2.1, span = 2.1, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Stealth", profile = "bruiser", kit = { 15581, 15582, 8822, 30980, 15614, 11201, 37683 }, passives = {}, talentInfo = { { name = "Light Fingers", icon = "Interface\\Icons\\Ability_Rogue_Disguise", text = "Your Agility is increased by 6%." }, { name = "Ducking the Watch", icon = "Interface\\Icons\\Ability_Rogue_Feint", text = "Your chance to dodge is increased by 4%." }, { name = "Cutpurse's Edge", icon = "Interface\\Icons\\Ability_CriticalStrike", text = "Your chance to critically hit with melee attacks is increased by 5%." }, { name = "Fleet of Foot", icon = "Interface\\Icons\\Ability_Rogue_Sprint", text = "Your movement speed is increased by 8%." }, { name = "Tainted Blades", icon = "Interface\\Icons\\Ability_Poisons", text = "Your melee attacks have a 10% chance to flick a free Crippling Poison onto the target. Once every 12 sec.\n\nA footpad's blade is never clean. Whoever gives chase finds their legs going heavy long before they catch up." }, { name = "Practiced Ambush", icon = "Interface\\Icons\\Ability_Rogue_Ambush", text = "Reduces the cooldown of your Sap by 10 sec.\n\nOn the Westfall roads the same lonely stretch sees a new traveller every hour. The cosh is always ready." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Northshire Valley", expansion = 0, order = 2, charModel = true, box = { -0.10, -0.00, 1.06 }, skinName = "Footpad", skinOf = "defias", title = "Cutpurse of the Defias Brotherhood" },
    { id = "defias_pirate", entry = 657, name = "Defias Pirate", label = "Defias Pirate", level = 20, display = 2347, height = 2.1, span = 2.1, school = "physical", pool = "archetype", icon = "Interface\\Icons\\INV_Sword_30", profile = "bruiser", kit = { 14516, 15589, 92895, 29690, 14822, 6713 }, passives = {}, talentInfo = { { name = "Sea Legs", icon = "Interface\\Icons\\INV_Misc_Bandana_03", text = "Your attack speed is increased by 6%." }, { name = "Salt-Hardened", icon = "Interface\\Icons\\Spell_Nature_UnyeildingStamina", text = "Your maximum health is increased by 6%." }, { name = "Rigging Hauler", icon = "Interface\\Icons\\Ability_Warrior_Cleave", text = "Your Strength is increased by 6%." }, { name = "Two Blades, No Mercy", icon = "Interface\\Icons\\Ability_DualWield", text = "Your chance to critically hit with melee attacks is increased by 4%." }, { name = "Second Blade", icon = "Interface\\Icons\\Ability_Warrior_Riposte", text = "Your melee attacks have a 10% chance to follow up with a free Cutlass Hack. Once every 10 sec.\n\nA deckhand never trusts one blade. When the cutlass is caught, the dirk is already coming." }, { name = "Bottomless Tankard", icon = "Interface\\Icons\\INV_Drink_04", text = "Reduces the cooldown of your Swig of Grog by 15 sec.\n\nThere is always more grog below decks, and a Defias pirate always knows where the barrel is." } }, tips = { [14822] = "Take a long swig of grog: your attack speed rises by 50% for 15 sec." }, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Deadmines", expansion = 0, order = 34, charModel = true, box = { -0.10, -0.00, 1.06 }, skinName = "Pirate", skinOf = "defias", title = "Deckhand of VanCleef's Juggernaut" },
    { id = "defias_overseer", entry = 634, name = "Defias Overseer", label = "Defias Overseer", level = 18, display = 2316, height = 2.1, span = 2.1, school = "physical", pool = "archetype", icon = "Interface\\Icons\\Ability_Warrior_BattleShout", profile = "tank", kit = { 11976, 21008, 6016, 15615, 5115, 13730 }, passives = {}, talentInfo = { { name = "Mail of the Mines", icon = "Interface\\Icons\\INV_Chest_Chain_05", text = "Your armor is increased by 10%." }, { name = "Overseer's Bulk", icon = "Interface\\Icons\\Spell_Holy_Devotion", text = "Your maximum health is increased by 8%." }, { name = "Turn the Pick", icon = "Interface\\Icons\\Ability_Parry", text = "Your chance to parry is increased by 4%." }, { name = "Eyes on Me", icon = "Interface\\Icons\\Ability_Warrior_Sunder", text = "The threat you cause is increased by 20%." }, { name = "Keep Them Working", icon = "Interface\\Icons\\Ability_Warrior_PunishingBlow", text = "Your melee attacks have a 10% chance to follow up with a free Strike. Once every 10 sec.\n\nAn overseer's second blow always lands on whoever stopped digging to watch the first." }, { name = "Rally the Crew", icon = "Interface\\Icons\\Ability_Warrior_RallyingCry", text = "Reduces the cooldown of your Battle Command by 15 sec.\n\nThe Brotherhood's crews answer the overseer's voice faster than any Stormwind drill sergeant could hope for." } }, tips = {}, visualKit = 437, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, instance = "Deadmines", expansion = 0, order = 30, charModel = true, box = { -0.10, -0.00, 1.06 }, skinName = "Overseer", skinOf = "defias", title = "Slave-Driver of the Deadmines" },
    { id = "vrykul_runeseer", entry = 23656, name = "Dragonflayer Rune-Seer", label = "Dragonflayer Rune-Seer", level = 69, display = 21966, height = 5.2, span = 5.2, school = "nature", pool = "archetype", icon = "Interface\\Icons\\Spell_Nature_StormReach", profile = "caster", kit = { 9532, 12058, 42740, 51612, 19136, 49753 }, passives = {}, talentInfo = { { name = "Storm-Read Runes", icon = "Interface\\Icons\\Spell_Nature_CallStorm", text = "Your Nature damage is increased by 8%." }, { name = "Seer's Sight", icon = "Interface\\Icons\\Spell_Holy_MagicalSentry", text = "Your chance to critically hit with spells is increased by 5%." }, { name = "Quick Carving", icon = "Interface\\Icons\\Spell_Nature_WispSplode", text = "Your casting speed is increased by 5%." }, { name = "Rune-Warded Flesh", icon = "Interface\\Icons\\Spell_Holy_Devotion", text = "Your maximum health is increased by 6%." }, { name = "The Storm Answers", icon = "Interface\\Icons\\Spell_Nature_Lightning", text = "Your damaging spells have a 10% chance to call down a free Lightning Bolt on the target. Once every 10 sec.\n\nA seer who reads the runes rightly never has to ask the sky twice." }, { name = "Njord's Teaching", icon = "Interface\\Icons\\Spell_Holy_SealOfProtection", text = "Reduces the cooldown of your Rune Shield by 8 sec.\n\nNjord of Utgarde carved his runes of protection in the heat of battle. His seers learned to carve as fast." } }, tips = {}, visualKit = 282, soundTransform = 0, soundDeath = 0, flies = false, wave = 4, zone = "Howling Fjord", expansion = 2, order = 437, charModel = true, box = { -0.31, -0.02, 2.48 }, skinName = "Rune-Seer", skinOf = "vrykul", title = "Seer of the Dragonflayer Runes" },
